    // la boucle requestAnimationFrame.
    const frame = Math.floor(performance.now() / 1000 * LIFE_STEAL_FPS) % LIFE_STEAL_FRAMES + 1;
    const img = getCachedImage(`ASSETS/LIFE_STEAL/${frame}.png`);
