  try {
    t.rocketSlowPct = Math.max(Number(t.rocketSlowPct || 0), SAP_SLOW_PCT);
    t.rocketSlowT = Math.max(Number(t.rocketSlowT || 0), SAP_DURATION);

  } catch {}
