  pulseCd = Math.max(Number(pulseCd || 0), persistedCdLeft("pulse"));
  ishCd = Math.max(Number(ishCd || 0), persistedCdLeft("ish"));
  smbCd = Math.max(Number(smbCd || 0), persistedCdLeft("smb"));
