// ============================================================
// ✅ Fenêtre Boosters en jeu : stock, activation, compte à rebours
// ============================================================
function boosterCatalogId(def) {
  return `booster_${def?.id || ""}`;
}

// Ordre des familles dans la fenêtre.
const BOOSTER_FAMILY_ORDER = ["dmgPct", "shieldPct", "hpPct", "expPct", "honorPct", "repairPct", "resPct", "sregPct", "boxPct", "questPct", "petXpPct"];

// Couleurs officielles lexique FR (cf. screenshot) : rouge = dégâts,
// cyan = bouclier, vert = PV, orange = exp, rose = honneur, etc.
const BOOSTER_FAMILY_COLORS = Object.freeze({
  dmgPct: "#ff2222",
  shieldPct: "#4dd2ff",
  hpPct: "#33ff66",
  expPct: "#ffa028",
  honorPct: "#ffc2d1",
  repairPct: "#c061ff",
  resPct: "#e6c200",
  sregPct: "#6b7cff",
  boxPct: "#f5e0a0",
  questPct: "#ffffff",
  petXpPct: "#e5a055",
});

// Petite icône de catégorie (pour les multi-effets : MUL-B03, EPHON-1).
const BOOSTER_FAMILY_ICONS = Object.freeze({
  dmgPct: "/ASSETS/BOOSTERS/CAT/dmg.png",
  shieldPct: "/ASSETS/BOOSTERS/CAT/shd.png",
  hpPct: "/ASSETS/BOOSTERS/CAT/hp.png",
  expPct: "/ASSETS/BOOSTERS/CAT/ep.png",
  honorPct: "/ASSETS/BOOSTERS/CAT/hon.png",
  repairPct: "/ASSETS/BOOSTERS/CAT/rep.png",
  resPct: "/ASSETS/BOOSTERS/CAT/res.png",
  sregPct: "/ASSETS/BOOSTERS/CAT/sreg.png",
  boxPct: "/ASSETS/BOOSTERS/CAT/bb.png",
  questPct: "/ASSETS/BOOSTERS/MINI/qr.png",
  petXpPct: "/ASSETS/BOOSTERS/CAT/pep.png",
});

function boosterFacetIcon(facet) {
  const keys = Object.keys(facet?.def?.effect || {}).filter(
    (k) => k !== "hitPct" && BOOSTER_FAMILY_ORDER.includes(k)
  );
  // Multi-effets : icône de la catégorie, pas celle du booster.
  if (keys.length > 1) return BOOSTER_FAMILY_ICONS[facet.key] || facet.def.iconMini || facet.def.icon;
  return facet.def.iconMini || facet.def.icon;
}

// Ids des boosters B02 actifs (bonus de groupe), pour la synchro réseau.
function activeGroupBoosterIds() {
  try {
    const now = Date.now();
    const out = [];
    for (const id of GROUP_BOOSTER_IDS) {
      if (boosterTimeLeftMs(account.user?.boosters, id, now) > 0) out.push(id);
    }
    return out;
  } catch { return []; }
}

// B02 actifs des AUTRES membres du groupe : { boosterId: nbMembres }.
// Moi exclu (mon B02 s'affiche déjà en propre). Uniquement les membres
// sur la MÊME carte que moi.
function groupBoosterCounts() {
  const counts = {};
  try {
    const me = String(netMyId());
    const here = String(window.__CURRENT_MAP_ID__ || "").toLowerCase();
    for (const m of getNetGroup()?.members || []) {
      if (!m || String(m.id) === me) continue;
      if (m.online === false) continue;
      if (String(m.map || "").toLowerCase() !== here) continue;
      for (const id of (Array.isArray(m.b2) ? m.b2 : [])) {
        if (!GROUP_BOOSTER_IDS.includes(String(id))) continue;
        counts[String(id)] = Math.max(0, Number(counts[String(id)]) || 0) + 1;
      }
    }
  } catch {}
  return counts;
}

function renderBoosterWindow() {
  if (!shouldRefreshWindow("boosterWindow")) return;
  const list = document.getElementById("boosterList");
  if (!list) return;
  const user = account.user || getCurrentUserFull();
  const now = Date.now();
  // On n'affiche que les boosters ACTIFS (tout achat prolonge le timer).
  const owned = BOOSTERS.filter((def) => boosterTimeLeftMs(user?.boosters, def.id, now) > 0);
  if (!owned.length) {
    list.innerHTML = `<div class="boosterEmpty">Aucun booster actif — achète-les en boutique (onglet BOOSTERS).</div>`;
    return;
  }
  // Une ligne par effet : les multi-effets (MUL-B03, EPHON-1) apparaissent
  // dans chaque famille avec le combiné actualisé.
  const facets = [];
  for (const def of owned) {
    for (const [key, value] of Object.entries(def.effect || {})) {
      if (key === "hitPct") continue; // précision : appliquée, non affichée en famille
      if (!BOOSTER_FAMILY_ORDER.includes(key)) continue;
      facets.push({ def, key, pct: Number(value) || 0 });
    }
  }
  // B02 du groupe (autres membres) : une carte GROUPE par booster, sans
  // timer, au % proportionnel au nombre de membres (GROUPE X5...).
  try {
    for (const [bid, n] of Object.entries(groupBoosterCounts())) {
      if (!(Number(n) > 0)) continue;
      const bonus = GROUP_BOOSTER_BONUS[bid];
      const def = BOOSTERS.find((b) => b.id === bid);
      if (!bonus || !def) continue;
      const key = Object.keys(bonus)[0];
      if (!BOOSTER_FAMILY_ORDER.includes(key)) continue;
      facets.push({ def, key, pct: (Number(Object.values(bonus)[0]) || 0) * Number(n), group: Number(n) });
    }
  } catch {}
  // Bases du clan avec modules DMG/HON/EXP/REP : une carte BASE <MAP> sans
  // timer par famille (+2 % dégâts, +10 % honneur, +10 % exp, +2 % réparation).
  // HON/EXP : appliqué plafonné à +50 % au total (voir stationClanHonMult).
  try {
    for (const b of stationClanBaseBonuses()) {
      const pushBaseFacet = (key, pct, icon, short) => {
        if (!(Number(pct) > 0)) return;
        const capTxt = key === "honorPct" || key === "expPct" ? " (plafond +50 % au total)"
          : key === "dmgPct" || key === "repairPct" ? " (plafond +10 % au total)" : "";
        facets.push({
          def: {
            id: `station-base-${String(b.map || "").toLowerCase()}-${key}`,
            code: `BASE ${b.map}`,
            name: `Base ${b.map} — module ${short}`,
            desc: `Module ${short} de la base de combat : +${pct} %${capTxt}, cumulé aux boosters.`,
            iconMini: icon,
            effect: { [key]: Number(pct) || 0 },
          },
          key,
          pct: Number(pct) || 0,
          base: String(b.map || "").toUpperCase(),
        });
      };
      pushBaseFacet("dmgPct", b.dmg, "/ASSETS/BOOSTERS/CAT/dmg.png", "DMG");
      pushBaseFacet("honorPct", b.hon, "/ASSETS/BOOSTERS/CAT/hon.png", "HON");
      pushBaseFacet("expPct", b.exp, "/ASSETS/BOOSTERS/CAT/ep.png", "EXP");
      pushBaseFacet("repairPct", b.rep, "/ASSETS/BOOSTERS/CAT/rep.png", "REP");
    }
  } catch {}
  const rowHtml = (facet) => {
    const color = BOOSTER_FAMILY_COLORS[facet.key] || "#effbff";
    const icon = boosterFacetIcon(facet);
    if (facet.base) {
      const label = `BASE ${facet.base}`;
      return `<div class="boosterRow compact" data-booster="${facet.def.id}" data-family="${facet.key}" data-base="${facet.base}" style="--boost:${color}" title="${facet.def.name} — ${facet.def.desc}">`
        + `<img src="${icon}" alt="${facet.def.code}">`
        + `<strong class="boosterCode">${label}</strong>`
        + `</div>`;
    }
    if (facet.group) {
      const label = facet.group > 1 ? `GROUPE X${facet.group}` : "GROUPE";
      return `<div class="boosterRow compact" data-booster="${facet.def.id}" data-family="${facet.key}" data-group="${facet.group}" style="--boost:${color}" title="${facet.def.name} — bonus de groupe (${facet.group} membre${facet.group > 1 ? "s" : ""})">`
      + `<img src="${icon}" alt="${facet.def.code}">`
      + `<strong class="boosterCode">${label}</strong>`
      + `</div>`;
    }
    const leftMs = boosterTimeLeftMs(user?.boosters, facet.def.id, now);
    return `<div class="boosterRow compact" data-booster="${facet.def.id}" data-family="${facet.key}" style="--boost:${color}" title="${facet.def.name} — ${facet.def.desc}">
      <img src="${icon}" alt="${facet.def.code}">
      <strong class="boosterCode">${facet.def.code}</strong>
      <span class="boosterStatus" data-booster-countdown="${facet.def.id}">${formatBoosterCountdown(leftMs)}</span>
    </div>`;
  };
  let html = "";
  for (const key of BOOSTER_FAMILY_ORDER) {
    const rows = facets.filter((f) => f.key === key && !f.base);
    const baseRows = facets.filter((f) => f.key === key && f.base);
    if (!rows.length && !baseRows.length) continue;
    const color = BOOSTER_FAMILY_COLORS[key] || "#ffc85a";
    if (rows.length === 1) {
      const pct = rows[0].pct;
      html += `<div class="boosterSingle" data-family="${key}" style="--boost:${color}"><span class="singleRail"><span class="boosterPct">${pct}%</span><span class="singleBar" aria-hidden="true"></span></span>${rowHtml(rows[0])}</div>`;
    } else if (rows.length > 1) {
      const total = Math.round(rows.reduce((sum, f) => sum + f.pct, 0));
      html += `<div class="boosterGroup" data-family="${key}" style="--boost:${color}"><div class="boosterGroupRail"><span class="boosterCombined">${total}%</span><span class="bracket" aria-hidden="true"></span></div><div class="boosterGroupCards">`;
      for (const f of rows) html += rowHtml(f);
      html += `</div></div>`;
    }
    // Bases : lignes unitaires par base (une +X % chacune) avec accolade +
    // total combiné comme les boosters classiques. HON/EXP : total appliqué
    // plafonné à +50 %.
    if (baseRows.length === 1) {
      const b = baseRows[0];
      html += `<div class="boosterSingle" data-family="${key}" data-base="${b.base}" style="--boost:${color}"><span class="singleRail"><span class="boosterPct">+${b.pct}%</span><span class="singleBar" aria-hidden="true"></span></span>${rowHtml(b)}</div>`;
    } else if (baseRows.length > 1) {
      const rawTotal = Math.round(baseRows.reduce((sum, f) => sum + (Number(f.pct) || 0), 0));
      const cap50 = key === "honorPct" || key === "expPct";
      const cap10 = key === "dmgPct" || key === "repairPct";
      const cap = cap50 ? 50 : cap10 ? 10 : Infinity;
      const shownTotal = Math.min(rawTotal, cap);
      const capNote = rawTotal > cap ? ` title="Total appliqué (plafond +${cap} %)"` : "";
      html += `<div class="boosterGroup" data-family="${key}" style="--boost:${color}"><div class="boosterGroupRail"><span class="boosterCombined"${capNote}>+${shownTotal}%</span><span class="bracket" aria-hidden="true"></span></div><div class="boosterGroupCards">`;
      for (const b of baseRows) {
        html += `<div class="boosterSingle" data-family="${key}" data-base="${b.base}" style="--boost:${color}"><span class="singleRail"><span class="boosterPct">+${b.pct}%</span><span class="singleBar" aria-hidden="true"></span></span>${rowHtml(b)}</div>`;
      }
      html += `</div></div>`;
    }
  }
  list.innerHTML = html;
}

function refreshBoosterCountdowns() {
  const list = document.getElementById("boosterList");
  if (!list || list.style.display === "none") return;
  const card = document.getElementById("boosterWindow");
  if (!card || card.style.display === "none" || card.classList.contains("gameWinMinimized")) return;
  const now = Date.now();
  const user = account.user || getCurrentUserFull();
  let changed = false;
  // B02 du groupe : tout changement (activation, expiration, arrivée,
  // départ) re-rend les cartes GROUPE. Idem pour les cartes BASE (DMG
  // posé/retiré/détruit sur une base du clan).
  try {
    const sig = JSON.stringify(groupBoosterCounts());
    if (sig !== refreshBoosterCountdowns._groupSig) {
      refreshBoosterCountdowns._groupSig = sig;
      changed = true;
    }
    const stationSig = JSON.stringify(stationClanBaseBonuses());
    if (stationSig !== refreshBoosterCountdowns._stationSig) {
      refreshBoosterCountdowns._stationSig = stationSig;
      changed = true;
    }
  } catch {}
  for (const def of BOOSTERS) {
    const el = list.querySelector(`[data-booster-countdown="${def.id}"]`);
    if (!el) continue;
    const leftMs = boosterTimeLeftMs(user?.boosters, def.id, now);
    const next = formatBoosterCountdown(leftMs);
    if (el.textContent !== next) {
      // Fin d'effet : re-rendu complet (la ligne disparaît).
      if (leftMs <= 0) { changed = true; break; }
      el.textContent = next;
    }
  }
  if (changed) renderBoosterWindow();
}

window.addEventListener("orbit:window-restoring", (event) => {
  if (event.detail?.id === "boosterWindow") renderBoosterWindow();
});

function wireBoosterWindow() {
  queueMicrotask(() => renderBoosterWindow());
}

