// Skin de portail par map de destination (ASSETS/PORTAL : NORMAUX / BATTLE / BL / QZ).
// Les vieux PVP_PORTAL (rouge) et PORTAL_JUMP_RED sont supprimés : les battle
// 4-1..4-4 utilisent BATTLE/4-x, comme chaque map utilise son propre skin.
function getPortalSpriteSet(ptl = null) {
  const gateId = String(window.__CURRENT_MAP_ID__ || rules?.mapLabel || "").toLowerCase();
  const isGalaxyGate = ["alpha", "beta", "gamma", "delta", "epsilon", "zeta", "kappa", "lambda", "kronos", "awakened", "eternal"].includes(gateId);
  const destination = isGalaxyGate && ptl === portal ? gateId
    : isGalaxyGate && ptl === gateReturnPortal
      ? getFactionHomeMap((account.user || getCurrentUserFull())?.faction)
      : ptl?.toMap;
  const skin = getPortalSkinForMap(destination);
  return {
    idle: ptl?.sprites?.idle || skin?.idle || PORTAL_IDLE_SPR,
    open: ptl?.sprites?.open || skin?.open || PORTAL_OPEN_SPR,

    jump: {
      ...DEFAULT_PORTAL_JUMP_SPR,
      ...(PORTAL_JUMP_SPR || {}),
      ...(!ptl?.sprites?.jump && skin?.jump ? skin.jump : {}),
      ...(ptl?.sprites?.jump || {}),
    },

    jumpFx: {
      ...DEFAULT_PORTAL_JUMP_FX,
      // Animation de saut de la catégorie (25 frames 320x320).
      ...(!ptl?.sprites?.jumpFx && skin?.jumpFxPath ? { path: skin.jumpFxPath } : {}),
      // ✅ nombre/frames/taille/forcage propres au skin (ex. Kronos : 18/6 frames, tailles réelles).
      ...(!ptl?.sprites?.jumpFx && Number(skin?.jumpFxFrames) > 0 ? { frames: Math.floor(Number(skin.jumpFxFrames)) } : {}),
      ...(!ptl?.sprites?.jumpFx && Number(skin?.jumpFxFps) > 0 ? { fps: Math.floor(Number(skin.jumpFxFps)) } : {}),
      ...(!ptl?.sprites?.jumpFx && Number(skin?.jumpFxW) > 0 ? { w: Math.floor(Number(skin?.jumpFxW)) } : {}),
      ...(!ptl?.sprites?.jumpFx && Number(skin?.jumpFxH) > 0 ? { h: Math.floor(Number(skin?.jumpFxH)) } : {}),
      ...(ptl?.sprites?.jumpFx || {}),
    },

    jumpButton: {
      ...DEFAULT_PORTAL_JUMP_BUTTON,
      ...(ptl?.jumpButton || {}),

      idle: {
        ...DEFAULT_PORTAL_JUMP_BUTTON.idle,
        ...(ptl?.jumpButton?.idle || {}),
      },

      mouse: {
        ...DEFAULT_PORTAL_JUMP_BUTTON.mouse,
        ...(ptl?.jumpButton?.mouse || {}),
      },

        click: {
          ...DEFAULT_PORTAL_JUMP_BUTTON.click,
          ...(ptl?.jumpButton?.click || {}),
        },
      },

      portalPreview: ptl?.sprites?.portalPreview || skin?.portalPreview || null,
    };
  }

function getPortalFrameSrc(pack, index) {
  if (!pack) return null;

  const first = Number(pack.firstNumber ?? 1);
  const ext = pack.ext || ".png";
  // Some portal sequences (Kronos) have fewer than ten frames. The fixed
  // frame used with animations disabled must stay inside the actual pack.
  const last = Math.max(0, Math.floor(Number(pack.frames) || 1) - 1);
  const n = first + Math.max(0, Math.min(last, Math.floor(Number(index) || 0)));

  // Exemple : ASSETS/PORTAL_JUMP_FX/1.png
  return `${pack.path}${n}${ext}`;
}

function preloadPortalJumpSequence(ptl = null) {
  const jobs = [];
  try {
    const spr = getPortalSpriteSet(ptl);
    const fx = spr?.jumpFx;
    if (fx?.path) {
      const frames = Math.max(1, Number(fx.frames || 1));
      for (let i = 0; i < frames; i++) {
        const src = getPortalFrameSrc(fx, i);
        if (src) jobs.push(loadImage(src, { priority: true }));
      }
    }
  } catch {}
  return jobs;
}

function preloadPortalSprites(ptl = null) {
  const spr = getPortalSpriteSet(ptl);
  const jobs = [];

  if (spr.idle?.src) jobs.push(loadImage(spr.idle.src, { priority: true }));
  // ✅ aperçu destination (ex. Saturne Kronos).
  if (spr.portalPreview?.image) jobs.push(loadImage(spr.portalPreview.image, { priority: true }));
  // ✅ open animé : précharge toutes les frames (sinon seule la 1re s'affiche).
  if (spr.open && Number(spr.open.frames) > 1 && spr.open.path) {
    const frames = Math.max(1, Number(spr.open.frames));
    for (let i = 0; i < frames; i++) {
      jobs.push(loadImage(getPortalFrameSrc(spr.open, i), { priority: true }));
    }
  } else if (spr.open?.src) jobs.push(loadImage(spr.open.src, { priority: true }));
  if (spr.jump?.src) jobs.push(loadImage(spr.jump.src, { priority: true }));

  const btn = spr.jumpButton;

if (btn?.idle?.src) {
  jobs.push(loadImage(btn.idle.src, { priority: true }));
}

if (btn?.mouse?.src) {
  jobs.push(loadImage(btn.mouse.src, { priority: true }));
}

if (btn?.click?.src) {
  jobs.push(loadImage(btn.click.src, { priority: true }));
}

  // ✅ précharge la séquence de saut quand les anims sont ON
  // (sinon seule la frame 10 figée est affichée).
  const fx = spr.jumpFx;
  let portalAnimsPreloadOn = false;
  try { portalAnimsPreloadOn = GAME_SETTINGS.portalAnims === true; } catch {}
  if (fx?.path) {
    if (portalAnimsPreloadOn) {
      jobs.push(...preloadPortalJumpSequence(ptl));
    } else {
      const src = getPortalFrameSrc(fx, 9);
      if (src) jobs.push(loadImage(src, { priority: true }));
    }
  }
  return jobs;
}

const SHORTCUT_TAX_CONFIRMATION_KEY = "orbit_shortcut_tax_confirmation_hidden_v1";

function isShortcutTaxConfirmationHidden() {
  try {
    return localStorage.getItem(SHORTCUT_TAX_CONFIRMATION_KEY) === "1";
  } catch {
    return false;
  }
}

function hideShortcutTaxConfirmation() {
  try {
    localStorage.setItem(SHORTCUT_TAX_CONFIRMATION_KEY, "1");
  } catch {}
}

function requestShortcutTaxConfirmation(ptl, shortcutCost) {
  if (!ptl || ptl.entryConfirmationOpen) return false;
  const overlay = document.getElementById("confirmOverlay");
  const title = document.getElementById("confirmTitle");
  const message = document.getElementById("confirmMessage");
  const cancel = document.getElementById("confirmCancel");
  const confirm = document.getElementById("confirmOk");
  if (!overlay || !title || !message || !cancel || !confirm) return false;

  const destination = String(ptl.toMap || "secteur inconnu").toUpperCase();
  const enough = player.credits >= shortcutCost;
  const remainingCredits = Math.max(0, player.credits - shortcutCost);

  ptl.entryConfirmationOpen = true;
  title.textContent = `Raccourci vers ${destination}`;
  message.innerHTML = `Ce portail est un raccourci intersectoriel.<br><strong>${formatInteger(shortcutCost)} crédits</strong> seront débités à chaque passage.<br><br>Tu possèdes <strong>${formatInteger(player.credits)}</strong> crédits.<br>Après le passage : <strong>${formatInteger(remainingCredits)}</strong> crédits.<label style="display:flex;align-items:center;gap:9px;margin-top:16px;color:#b9dce8;font-weight:800;cursor:pointer"><input id="shortcutTaxDontAskAgain" type="checkbox" style="width:17px;height:17px;accent-color:#26c3e4"> Ne plus afficher cette confirmation</label>`;
  cancel.style.display = "";
  cancel.textContent = "Annuler";
  confirm.disabled = !enough;
  confirm.textContent = enough ? "Payer et utiliser" : "Crédits insuffisants";
  overlay.style.display = "grid";

  const cleanup = () => {
    ptl.entryConfirmationOpen = false;
    overlay.style.display = "none";
    overlay.onclick = null;
    cancel.onclick = null;
    confirm.onclick = null;
    confirm.disabled = false;
  };

  cancel.onclick = cleanup;
  overlay.onclick = event => { if (event.target === overlay) cleanup(); };
  confirm.onclick = () => {
    if (player.credits < shortcutCost) return;
    if (document.getElementById("shortcutTaxDontAskAgain")?.checked) {
      hideShortcutTaxConfirmation();
    }
    cleanup();
    startZonePortalJump(ptl, true);
  };
  return true;
}

function requestPortalEntryConfirmation(ptl, entryCost) {
  if (!ptl || ptl.entryConfirmationOpen) return false;
  const overlay = document.getElementById("confirmOverlay");
  const title = document.getElementById("confirmTitle");
  const message = document.getElementById("confirmMessage");
  const cancel = document.getElementById("confirmCancel");
  const confirm = document.getElementById("confirmOk");
  if (!overlay || !title || !message || !cancel || !confirm) return false;

  ptl.entryConfirmationOpen = true;
  title.textContent = "Entrer dans la gate LOW";
  message.innerHTML = `<span id="creditGateEntrySummary"></span>`;
  cancel.textContent = "Annuler";
  confirm.textContent = "Confirmer";
  overlay.style.display = "grid";

  const summary = document.getElementById("creditGateEntrySummary");
  const refresh = () => {
    const total = entryCost;
    const enough = player.credits >= total;
    if (summary) summary.innerHTML = `Tu possèdes <strong>${formatInteger(player.credits)}</strong> crédits.<br><strong>${formatInteger(total)}</strong> nécessaires (${formatInteger(entryCost)} d'entrée).<br>Après paiement : <strong>${formatInteger(Math.max(0, player.credits - total))}</strong> crédits.`;
    confirm.disabled = !enough;
    confirm.textContent = enough ? "Confirmer l'entrée" : "Crédits insuffisants";
  };
  refresh();

  const cleanup = () => {
    ptl.entryConfirmationOpen = false;
    overlay.style.display = "none";
    overlay.onclick = null;
    cancel.onclick = null;
    confirm.onclick = null;
    confirm.disabled = false;
  };
  cancel.onclick = cleanup;
  overlay.onclick = event => {
    if (event.target === overlay) cleanup();
  };
  confirm.onclick = () => {
    const total = entryCost;
    if (player.credits < total) return;
    ptl.pendingEntryCost = total;
    cleanup();
    startZonePortalJump(ptl, true);
  };
  return true;
}

function requestResourceGateConfirmation(ptl) {
  if (!ptl || ptl.entryConfirmationOpen) return false;
  const overlay = document.getElementById("confirmOverlay");
  const title = document.getElementById("confirmTitle");
  const message = document.getElementById("confirmMessage");
  const cancel = document.getElementById("confirmCancel");
  const confirm = document.getElementById("confirmOk");
  if (!overlay || !title || !message || !cancel || !confirm) return false;

  if (!account.user) loadAccountUser();
  const resourceId = String(ptl.entryResource || "hybrid_alloy");
  const owned = Math.max(0, Math.floor(Number(account.user?.inventory?.resources?.[resourceId]) || 0));
  const baseCost = Math.max(0, Math.floor(Number(ptl.entryResourceCost) || 0));
  const resourceName = getResourceName(resourceId, owned);
  ptl.entryConfirmationOpen = true;
  title.textContent = "Entrer dans la gate QZ";
  cancel.textContent = "Annuler";
  confirm.textContent = owned >= baseCost ? "Confirmer l'entrée" : "Fermer";

  if (owned < baseCost) {
    message.innerHTML = `Accès impossible : tu possèdes <strong>${formatInteger(owned)}</strong> ${escapeHtml(resourceName)}, mais <strong>${formatInteger(baseCost)}</strong> sont nécessaires.<br><br>Élimine des <strong>Blighted Kristallon</strong> : ils font apparaître des <strong>Blighted Gygerthrall</strong>, dont les cargaisons contiennent les Alliages hybrides.`;
    cancel.style.display = "none";
  } else {
    message.innerHTML = `<span id="qzEntrySummary"></span>`;
    const summary = document.getElementById("qzEntrySummary");
    const refresh = () => {
      const total = baseCost;
      const enough = owned >= total;
      if (summary) summary.innerHTML = `Tu possèdes <strong>${formatInteger(owned)}</strong> Alliages hybrides.<br><strong>${formatInteger(total)}</strong> nécessaires (${formatInteger(baseCost)} d'entrée).<br>Après paiement : <strong>${formatInteger(Math.max(0, owned - total))}</strong> restants.`;
      confirm.disabled = !enough;
      confirm.textContent = enough ? "Confirmer l'entrée" : "Alliages insuffisants";
    };
    refresh();
  }
  overlay.style.display = "grid";

  const cleanup = () => {
    ptl.entryConfirmationOpen = false;
    overlay.style.display = "none";
    overlay.onclick = null;
    cancel.onclick = null;
    confirm.onclick = null;
    cancel.style.display = "";
    confirm.disabled = false;
  };
  cancel.onclick = cleanup;
  overlay.onclick = event => { if (event.target === overlay) cleanup(); };
  confirm.onclick = () => {
    if (owned < baseCost) return cleanup();
    const total = baseCost;
    if (owned < total) return;
    ptl.pendingResourceCost = total;
    cleanup();
    startZonePortalJump(ptl, true);
  };
  return true;
}

// Purge d'avant-saut : les NPC de l'ancienne carte sont retirés dès le
// départ du saut (plus de fuite visuelle de l'autre côté, plus de
// disparition brutale à l'arrivée — la nouvelle carte respawn les siens).
// Les tirs ennemis en vol partent aussi, et un verrou NPC est libéré.
function purgeNpcsForJump() {
  try {
    const locked = Target.get();
    if (locked && enemies.includes(locked) && !locked._netPlayer && !locked._netPet && !locked.isPetTarget) {
      try { Target.clear(); } catch {}
    }
  } catch {}
  try {
    for (const e of enemies) {
      try { if (e && e.id != null) enemiesById.delete(e.id); } catch {}
    }
  } catch {}
  try { enemies.length = 0; } catch {}
  try { enemyBullets.length = 0; } catch {}
}

function isPortalJumpInProgress() {
  return portalJumpActive || mapSwitchInProgress;
}

function lockPortalJump() {
  portalJumpActive = true;
  phoneControls?.cancel();
  cancelCollectableTarget();
  moveTarget.active = false;
  player.vx = 0;
  player.vy = 0;
  pointer.dragArmed = false;
  pointer.dragging = false;
  pointer.followWhileDown = false;
  for (const ptl of getInteractivePortals()) {
    ptl.buttonHovered = false;
    ptl.buttonPressed = false;
  }
}

function startZonePortalJump(ptl, entryConfirmed = false) {
  if (!ptl || ptl.jumping || isPortalJumpInProgress()) return false;
  // ✅ portail caché = marqueur d'arrivée d'un aller simple, jamais un départ.
  if (ptl.hidden === true) return false;
  // Raid Low : pas de sortie pendant une vague (le portail est masqué,
  // ceci est le garde-fou pour les déclenchements directs comme le bot).
  if (ptl.factionReturn === true && isLowRaidRunning()) {
    SFX.play("swDeny");
    showToast("Retour bloqué — vague en cours", 1.6);
    return false;
  }
  if (!isPlayerNearPortal(ptl)) {
    showToast("Approche-toi du portail", 1.2);
    return false;
  }

  if ((player.portalLockT || 0) > 0) {
    SFX.play("swDeny");
    showToast(`Portail bloqué — attends ${Math.ceil(player.portalLockT)} s après ta mort`, 1.4);
    return false;
  }

  const mapId = String(window.__CURRENT_MAP_ID__ || rules?.mapLabel || "").trim().toLowerCase();
  const combatRestrictedMap = /^4-[123]$/.test(mapId) || mapId === "4-4" || mapId === "4-5";
  // Battle 4-x : les NPC ne bloquent jamais le saut, seul un joueur qui nous
  // attaque verrouille (pvpAttackT, posé par hurtPlayer avec source.byPlayer).
  const pvpCooldown = Number(player.pvpAttackT) || 0;
  if (combatRestrictedMap && pvpCooldown > 0) {
    SFX.play("swDeny");
    showToast(`Portail verrouillé — attaqué par un joueur, attends ${Math.ceil(pvpCooldown)} s`, 1.4);
    return false;
  }

  // Niveau requis façon DarkOrbit officiel (voir SRC/CORE/MAP_ACCESS.js).
  // Vérifié avant les coûts : inutile de payer si le niveau bloque.
  const targetMapId = String(ptl.toMap || "").toLowerCase();
  if (targetMapId) {
    const user = account.user || getCurrentUserFull();
    const playerLevel = getLevelInfo(Number(user?.stats?.exp || 0)).level;
    const access = checkMapAccess(targetMapId, playerLevel, getFaction(user?.faction).sector);
    if (!access.ok) {
      SFX.play("swDeny");
      showToast(`Accès refusé — niveau ${access.required} requis pour ${targetMapId.toUpperCase()} (niveau ${access.level})`, 2.4);
      return false;
    }
  }

  // Raid Low : entrée gratuite mais groupe de 2 à 10 exigé.
  if (targetMapId === "low") {
    let groupSize = 0;
    try { groupSize = Number(getNetGroup()?.members?.length) || 0; } catch { groupSize = 0; }
    if (groupSize < 2) {
      SFX.play("swDeny");
      showToast("Raid Low — groupe de 2 joueurs minimum requis", 2.4);
      return false;
    }
    if (groupSize > 10) {
      SFX.play("swDeny");
      showToast("Raid Low — groupe de 10 joueurs maximum", 2.4);
      return false;
    }
  }

  const entryCost = Math.max(0, Math.floor(Number(ptl.entryCost) || 0));
  const shortcutCreditCost = Math.max(0, Math.floor(Number(ptl.shortcutCreditCost) || 0));
  const confirmedEntryCost = entryConfirmed
    ? Math.max(entryCost, Math.floor(Number(ptl.pendingEntryCost) || entryCost))
    : entryCost;
  const resourceEntryCost = Math.max(0, Math.floor(Number(ptl.entryResourceCost) || 0));
  if (resourceEntryCost > 0 && !entryConfirmed) return requestResourceGateConfirmation(ptl);
  if (resourceEntryCost > 0 && entryConfirmed) {
    if (!account.user) loadAccountUser();
    const resourceId = String(ptl.entryResource || "hybrid_alloy");
    const totalCost = Math.max(resourceEntryCost, Math.floor(Number(ptl.pendingResourceCost) || resourceEntryCost));
    const owned = Math.max(0, Math.floor(Number(account.user?.inventory?.resources?.[resourceId]) || 0));
    if (owned < totalCost) {
      showToast(`Entrée refusée — ${formatInteger(totalCost)} ${getResourceName(resourceId, totalCost)} requis`, 2.2);
      return false;
    }
    account.user.inventory.resources[resourceId] = owned - totalCost;
    markProgressDirty();
    saveProgressNow();
    showNotification(`Accès QZ payé : ${formatInteger(totalCost)} Alliages hybrides`, 3, "info");
    addGameLog(`Entrée QZ · -${formatInteger(totalCost)} Alliages hybrides`, "info");
    ptl.pendingResourceCost = 0;
  }
  const totalPortalCreditCost = confirmedEntryCost + shortcutCreditCost;
  if (totalPortalCreditCost > 0 && player.credits < totalPortalCreditCost) {
    showToast(`Passage refusé — ${formatInteger(totalPortalCreditCost)} crédits requis`, 1.8);
    return false;
  }
  if (shortcutCreditCost > 0 && !entryConfirmed && !isShortcutTaxConfirmationHidden()) {
    return requestShortcutTaxConfirmation(ptl, shortcutCreditCost);
  }
  if (entryCost > 0 && !entryConfirmed) {
    return requestPortalEntryConfirmation(ptl, entryCost);
  }

  const gateId = String(ptl.toMap || "").toLowerCase();
  if (GALAXY_GATE_DEFINITIONS[gateId]) {
    const user = account.user || getCurrentUserFull();
    const factionHomeMap = getFactionHomeMap(user?.faction);
    if (String(window.__CURRENT_MAP_ID__ || "").toLowerCase() !== factionHomeMap) {
      showToast(`Cette Galaxy Gate est uniquement accessible depuis ta base mère ${factionHomeMap}`, 1.8);
      return false;
    }
    const access = consumeCurrentUserGalaxyGate(gateId);
    if (!access.ok) {
      showToast("Cette Galaxy Gate doit d'abord être construite dans le Spinner", 1.8);
      return false;
    }
    account.user = access.user;
    renderGalaxyGateWindow(`${GALAXY_GATE_DEFINITIONS[gateId].name} activée`);
    // ✅ pas de camouflage dans la gate (restauré après récompense/échec).
    try { suspendCloakForGate(); } catch {}
    // ✅ arrivée de l'autre côté = son "saut terminée" (comme les portails de zone).
    try { sessionStorage.setItem("orbit_gate_jump", "1"); } catch {}
  }

  // ✅ Gate Eternal : la gate reste posée pendant le run (elle ne
  // disparaît qu'à la mort). L'entrée est juste vérifiée ici, et la
  // vague repart de 1 (le refresh, lui, reprend la vague sauvée).
  if (targetMapId === "eternal") {
    if (!isEternalGateDeployed()) {
      showToast("Gate Eternal non posée — utilise un CPU depuis le panneau Galaxy Gate", 1.8);
      return false;
    }
    try {
      const rst = resetEternalGateWaveProgress();
      if (rst.ok) account.user = rst.user;
      if (netActive()) flushNetUser().catch(() => {});
    } catch {}
    renderGalaxyGateWindow("Eternal activée");
    try { sessionStorage.setItem("orbit_gate_jump", "1"); } catch {}
  }

  if (entryCost > 0) {
    player.credits -= confirmedEntryCost;
    if (account.user) account.user.credits = player.credits;
    try { noteNetPurchase(confirmedEntryCost); } catch {}
    markProgressDirty();
    saveProgressNow();
    showNotification(`Droit d'entrée acquitté : ${formatInteger(confirmedEntryCost)} crédits`, 3, "info");
    addGameLog(`Entrée ${String(ptl.toMap || "Gate").toUpperCase()} · -${formatInteger(confirmedEntryCost)} crédits`, "info");
    ptl.pendingEntryCost = 0;
  }

  if (shortcutCreditCost > 0) {
    player.credits -= shortcutCreditCost;
    if (account.user) account.user.credits = player.credits;
    try { noteNetPurchase(shortcutCreditCost); } catch {}
    markProgressDirty();
    saveProgressNow();
    showNotification(`Taxe du raccourci acquittée : ${formatInteger(shortcutCreditCost)} crédits`, 3, "info");
    addGameLog(`Raccourci vers ${String(ptl.toMap || "secteur").toUpperCase()} · -${formatInteger(shortcutCreditCost)} crédits`, "info");
  }

  // ✅ on mémorise l'état visuel actuel du portail
  // comme ça le jump part de l'état open sans cassure
  ptl.jumpBaseFade = Math.max(0, getPortalOpenFade(ptl));

  // ✅ PAS de purge d'avant-saut ici : vider `enemies` au clic puis les
  // recréer via syncNetNpcs / zoneController pendant les ~2 s d'animation
  // produisait le freeze puis le dash collectif des NPC. Les NPC de
  // l'ancienne carte restent visibles et continuent leur IA pendant le
  // saut ; la vraie purge a lieu dans switchMapConfig (début + fin du
  // préchargement). On libère juste le lock NPC et les tirs en vol, et on
  // protège le joueur pendant l'animation (iFrames) puisqu'il peut encore
  // être touché.
  try {
    const locked = Target.get();
    if (locked && enemies.includes(locked) && !locked._netPlayer && !locked._netPet && !locked.isPetTarget) {
      try { Target.clear(); } catch {}
    }
  } catch {}
  try { enemyBullets.length = 0; } catch {}

  lockPortalJump();
  ptl.jumping = true;
  ptl.jumpT = 0;
  ptl.jumpDur = Math.max(0.1, Number(ptl.jumpDur ?? 2));

  // ✅ Si les anims portails sont ON, on précharge toute la séquence
  // de saut en priorité pour que le sprite joue en entier dès le début.
  try {
    if (GAME_SETTINGS.portalAnims === true) preloadPortalJumpSequence(ptl);
  } catch {}

  // ✅ invulnérable pendant l'animation : les NPC restent visibles et
  // peuvent encore tirer, mais le saut ne doit jamais tuer.
  try { player.iFrames = Math.max(Number(player.iFrames) || 0, ptl.jumpDur + 0.3); } catch {}

  // ✅ verrouille le robot réparateur pendant le saut : cooldown à 0
  player.repairJumpLock = true;
  player.repairT = 0;
  player.repairTickT = 0;
  stopRepairSound({ fadeOut: 0 });

  ptl.jumpMap = ptl.toMap;
  ptl.jumpPortal = ptl.toPortal;
  // Portail retour Low : renvoie chacun vers sa map d'origine (firme).
  if (ptl.factionReturn === true) {
    const sector = String(getFaction((account.user || getCurrentUserFull())?.faction)?.sector || "1");
    const mapBySector = { 1: "1-3", 2: "2-3", 3: "3-3" };
    const portalBySector = { 1: "p_13_to_low", 2: "p_23_to_low", 3: "p_33_to_low" };
    ptl.jumpMap = mapBySector[sector] || "1-3";
    ptl.jumpPortal = portalBySector[sector] || "p_13_to_low";
  }
  ptl.jumpTargetReady = false;
  ptl.jumpTargetPromise = Promise.resolve(
    window.__PRELOAD_MAP__?.(ptl.jumpMap, ptl.jumpPortal)
  ).catch((error) => {
    console.warn("Préchargement de la prochaine carte incomplet:", error);
  }).finally(() => {
    ptl.jumpTargetReady = true;
  });

  // ✅ transition open -> jump
  ptl.jumpSwitching = true;
  ptl.jumpSwitchT = 0;
  ptl.jumpSwitchDur = Math.max(0.1, Number(ptl.jumpSwitchDur || portal.switchDur || 1));

  // ✅ surtout on coupe la fermeture / ouverture normale
  ptl.open = true;
  ptl.switching = false;
  ptl.holding = false;
  ptl.closing = false;
  ptl.switchT = 0;
  ptl.holdT = 0;
  ptl.closeT = 0;

  // Le verrou du saut reste actif jusqu'a l'arrivee sur la prochaine carte.
  mapPortalLock = Math.max(mapPortalLock, ptl.jumpDur + 0.25);

  const destinationMap = String(ptl.jumpMap || ptl.toMap || "inconnue");
  showNotification(`Saut en cours vers la carte ${destinationMap}`, ptl.jumpDur, "info", { goldTerms: [destinationMap] });

  // ✅ "Saut possible" puis 500 ms après → "saut en cours"
  SFX.play("swReady");
  window.setTimeout(() => {
    SFX.play("swJump");
  }, 500);

  return true;
}

function finishZonePortalJump(ptl) {
  if (!ptl || ptl.jumpSwitchPending) return;

  const toMap = ptl.jumpMap ?? ptl.toMap;
  const toPortal = ptl.jumpPortal ?? ptl.toPortal;
  ptl.jumpSwitchPending = true;

  if (typeof window.__SWITCH_MAP__ === "function") {
    window.__SWITCH_MAP__(toMap, toPortal).then(() => {
      portalJumpActive = false;
    }).catch((error) => {
      console.error("Changement interne impossible:", error);
      ptl.jumpSwitchPending = false;
      window.__GO_TO_MAP__?.(toMap, toPortal);
    });
    return;
  }

  ptl.jumpSwitchPending = false;
  window.__GO_TO_MAP__?.(toMap, toPortal);
}

function tickZonePortalJumps(dt) {
  if (!isZoneMap || !started || player.dead || !zonePortals.length) return false;

  for (const ptl of zonePortals) {
    if (!ptl.jumping) continue;

    ptl.jumpT += dt;

    if (ptl.jumpT >= Math.max(0.1, Number(ptl.jumpDur || 2))) {
      if (!ptl.jumpTargetReady) continue;
      finishZonePortalJump(ptl);
      return true;
    }
  }

  return false;
}

// ============================================================
// State
// ============================================================
let started = false;
let betweenWaves = false;
// Compteur de sauvegarde du temps joué (toutes les 60 s de jeu).
let playtimeSaveAcc = 0;

// ✅ Idle sway (balancement à l'arrêt)
let idleSway = 0;

// ============================================================
// ✅ Account / Progress
// ============================================================
const account = {
  user: null,
  dirty: false,
  saveCd: 0,
};
let questState = normalizeQuestState(getCurrentUserFull()?.quests);

function mergeQuestProgress(localState, persistedState) {
  const local = normalizeQuestState(localState);
  const persisted = normalizeQuestState(persistedState);
  const completed = new Set([...persisted.completed, ...local.completed]);
  // Un abandon explicite bat les fusions max-gagnant : la progression
  // abandonnée ne doit jamais ressusciter (reprise = zéro).
  const abandoned = { ...(persisted.abandoned || {}), ...(local.abandoned || {}) };
  for (const id of completed) delete abandoned[id];
  const active = { ...persisted.active };
  for (const [questId, localProgress] of Object.entries(local.active)) {
    if (completed.has(questId)) { delete active[questId]; continue; }
    const target = active[questId] || (active[questId] = {});
    for (const [objectiveId, count] of Object.entries(localProgress || {})) {
      target[objectiveId] = Math.max(Number(target[objectiveId]) || 0, Number(count) || 0);
    }
  }
  for (const questId of completed) delete active[questId];
  for (const questId of Object.keys(abandoned)) delete active[questId];
  return normalizeQuestState({ active, completed: [...completed], abandoned });
}

function preserveLivePetVitals(previous, next) {
  if (!previous || !next || previous.id !== next.id) return next;
  const live = previous.pet, incoming = next.pet;
  // Une réparation manuelle désactive le REX : adopter alors le nouvel état.
  if (live?.owned !== true || incoming?.owned !== true
      || live.active !== true || incoming.active !== true) return next;
  for (const key of ["hp", "sh"]) {
    if (Number.isFinite(Number(live[key]))) incoming[key] = Math.max(0, Number(live[key]));
  }
  return next;
}

function loadAccountUser() {
  const previousId = account.user?.id || null;
  account.user = preserveLivePetVitals(account.user, getCurrentUserFull());

  // Le module est initialisé avant la connexion. Dans ce cas, questState
  // contient encore l'état vide issu de l'utilisateur anonyme : resynchronise
  // une seule fois avec l'état réellement persisté du compte connecté.
  const currentId = account.user?.id || null;
  if (currentId && currentId !== previousId) {
    questState = normalizeQuestState(account.user.quests);
    selectedQuestId = null;
    selectedQuestOfferId = null;
  }
  return account.user;
}

function markProgressDirty() {
  if (!account.dirty) account.saveCd = 15.0;
  account.dirty = true;
  // Le premier changement arme le filet de securite periodique. Les tirs
  // suivants ne repoussent pas ce delai ; portail/quitter sauvent aussitot.
}

let progressSaveIdleHandle = 0;
function scheduleProgressSave() {
  if (progressSaveIdleHandle) return;
  const persist = () => {
    progressSaveIdleHandle = 0;
    if (account.user && account.dirty) saveProgressNow();
  };
  if (typeof requestIdleCallback === "function") {
    progressSaveIdleHandle = requestIdleCallback(persist, { timeout: 1200 });
  } else {
    progressSaveIdleHandle = setTimeout(persist, 0);
  }
}

// Snapshot léger de position toutes les 3 s. Il met à jour le hangar en
// mémoire + sessionStorage, puis la sauvegarde complète l'absorbe plus tard.
let positionSaveCd = 0;
const lastPositionSave = { x: NaN, y: NaN, map: "" };

function awardExperience(amount, source = "") {
  if (!account.user) loadAccountUser();
  if (!account.user) return null;
  account.user.stats ||= { honor: 0, exp: 0, rankPoints: 0 };
  const moduleBonus = Number(player?.expBonusPct || 0);
  const raw = Number(amount || 0) * Math.max(0, 1 + moduleBonus / 100) * playerBoosterMults().exp * playerPilotMults().exp * shipPassiveXpMult();
  const result = grantExperience(account.user.stats, Math.max(0, Math.ceil(raw - Number.EPSILON)));
  if (result.gained <= 0) return result;
  for (const drone of account.user.drones?.items || []) {
    const previousLevel = Math.max(1, Number(drone.level) || getDroneLevel(drone.exp));
    drone.exp = Math.max(0, Number(drone.exp) || 0) + result.gained * DRONE_XP_SHARE;
    drone.level = getDroneLevel(drone.exp);
    if (drone.level > previousLevel) queueDroneLevelTransition(drone.id, previousLevel, drone.level);
  }
  // P.E.T / REX officiel : +5 % de l'XP du vaisseau quand il est possédé
  // ET activé (bouton play de la fenêtre P.E.T).
  if (account.user.pet?.owned === true && account.user.pet.active === true) {
    const previousPetLevel = Math.max(0, Number(account.user.pet.level) || getPetLevel(account.user.pet.exp));
    account.user.pet.exp = Math.max(0, Number(account.user.pet.exp) || 0) + result.gained * PET_XP_SHARE * playerBoosterMults().petXp;
    account.user.pet.level = getPetLevel(account.user.pet.exp);
    if (account.user.pet.level > previousPetLevel) {
      showToast(`P.E.T niveau ${account.user.pet.level} atteint !`, 2.6);
    }
  }
  markProgressDirty();
  if (result.leveledUp) {
    showToast(`Niveau ${result.after.level} atteint !`, 2.6);
  } else if (source === "quest") {
    showToast(`+${formatInteger(result.gained)} XP`, 1.8);
  }
  return result;
}

function awardHonor(amount) {
  if (!account.user) loadAccountUser();
  if (!account.user) return null;
  account.user.stats ||= { honor: 0, exp: 0, rankPoints: 0, lifetimeKills: 0 };
  const previousRank = getRankInfo(account.user.stats.rankPoints, account.user.stats.honor);
  const moduleBonus = Number(player?.honorBonusPct || 0);
  const zeroHonorFormation = String(getActiveDroneFormation(account.user)?.id || "").toLowerCase() === "x";
  const raw = zeroHonorFormation
    ? 0
    : Number(amount || 0) * Math.max(0, 1 + moduleBonus / 100) * playerBoosterMults().honor * playerPilotMults().honor;
  const result = grantHonor(account.user.stats, Math.max(0, Math.ceil(raw - Number.EPSILON)));
  account.user.stats.rankPoints = calculateRankPoints(account.user.stats);
  const nextRank = getRankInfo(account.user.stats.rankPoints, account.user.stats.honor);
  if (result.gained > 0) markProgressDirty();
  if (nextRank.index > previousRank.index) showToast(`Nouveau grade : ${nextRank.name}`, 2.6);
  return result;
}

let selectedQuestId = null;
let lastQuestTerminalAccess = null;
let lastDpsHudAt = 0;

function hasQuestTerminalAccess() {
  return (zoneSafe?.modules || []).some(module =>
    isQuestModule(module) && canUseStation(module) && isPlayerNearQuestModule(module)
  );
}

let questJournalRenderPending = false;
let questTerminalRenderPending = false;

function renderQuestWindow() {
  if (!shouldRefreshWindow("questWindow")) { questJournalRenderPending = true; return; }
  if (!ui.questList) return;
  questJournalRenderPending = false;
  // Rattrape le cas où le moteur a été instancié avant la session utilisateur
  // (refresh/login) et aurait conservé un journal vide en mémoire.
  // Fusionne aussi le stockage frais : progression externe (ou autre onglet)
  // adoptée sans jamais perdre la progression mémoire (on garde le max).
  {
    const persisted = normalizeQuestState(getCurrentUserFull()?.quests);
    if (persisted) {
      for (const [id, prog] of Object.entries(persisted.active)) {
        if (questState.completed.includes(id)) continue;
        const mem = questState.active[id];
        if (!mem) {
          if (Object.keys(questState.active).length < MAX_ACTIVE_QUESTS) questState.active[id] = { ...prog };
          continue;
        }
        for (const [oid, val] of Object.entries(prog)) {
          if (Number(val) > Number(mem[oid] || 0)) mem[oid] = Number(val);
        }
      }
      for (const id of persisted.completed) {
        if (!questState.completed.includes(id)) questState.completed.push(id);
        if (questState.active[id]) delete questState.active[id];
      }
      // Abandons : union des tombstones, purge des progressions abandonnées
      // (sinon le stockage les réinjecte et la reprise ne repart pas de zéro).
      const tombstones = { ...(persisted.abandoned || {}), ...(questState.abandoned || {}) };
      for (const id of questState.completed) delete tombstones[id];
      for (const id of Object.keys(tombstones)) delete questState.active[id];
      questState.abandoned = tombstones;
    }
  }
  const view = buildQuestJournalView(questState, selectedQuestId, { collectables: COLLECTABLE_DEFS, npcTypes: NPC_TYPES });
  selectedQuestId = view.selectedQuestId;
  if (ui.questIntro) ui.questIntro.textContent = view.intro;
  if (ui.questTabs) ui.questTabs.innerHTML = view.tabsHtml;
  ui.questList.innerHTML = view.contentHtml;
  fitQuestWindowToContent();
}

let questWindowFitFrame = 0;
function fitQuestWindowToContent() {
  const questWindow = document.getElementById("questWindow");
  if (!questWindow || questWindow.style.display === "none") return;
  cancelAnimationFrame(questWindowFitFrame);
  questWindowFitFrame = requestAnimationFrame(() => {
    if (questWindow.style.display === "none") return;
    const bar = questWindow.querySelector(":scope > .gameWinBar");
    const intro = questWindow.querySelector("#questIntro");
    const tabs = questWindow.querySelector("#questTabs");
    const list = questWindow.querySelector("#questList");
    if (!list) return;

    list.style.overflowY = "visible";
    list.style.flex = "0 0 auto";
    const chromeHeight = (bar?.offsetHeight || 30) + (intro?.offsetHeight || 0) + (tabs?.offsetHeight || 0);
    const desiredHeight = chromeHeight + list.scrollHeight + 2;
    const top = Math.max(8, questWindow.getBoundingClientRect().top || 8);
    const availableHeight = Math.max(180, window.innerHeight - top - 12);
    const nextHeight = Math.min(desiredHeight, availableHeight);
    const heightValue = `${Math.ceil(nextHeight)}px`;
    const overflowValue = desiredHeight > availableHeight + 1 ? "auto" : "visible";
    const flexValue = overflowValue === "auto" ? "1 1 auto" : "0 0 auto";
    if (questWindow.style.height !== heightValue) questWindow.style.height = heightValue;
    if (list.style.overflowY !== overflowValue) list.style.overflowY = overflowValue;
    if (list.style.flex !== flexValue) list.style.flex = flexValue;
  });
}

window.addEventListener("resize", fitQuestWindowToContent);
let questTreeResizeFrame = 0;
window.addEventListener("resize", () => {
  cancelAnimationFrame(questTreeResizeFrame);
  questTreeResizeFrame = requestAnimationFrame(drawQuestTreeEdges);
});
const questWindowElement = document.getElementById("questWindow");
if (questWindowElement) {
  new MutationObserver(() => {
    if (questWindowElement.style.display !== "none") fitQuestWindowToContent();
  }).observe(questWindowElement, { attributes: true, attributeFilter: ["class", "style"] });
}

let selectedQuestOfferId = null;
let questTerminalSearch = "";
let questTerminalFilter = "open";
let questNpcLocations = {};
let questTreeZoom = 1;
let selectedQuestLineage = new Set();

// Lignée de la quête sélectionnée : ancêtres jusqu'aux racines +
// descendants jusqu'aux feuilles. Sert à éclairer toute la chaîne en jaune.
function computeQuestLineage(selectedId) {
  const lineage = new Set();
  const canvas = document.getElementById("questTreeCanvas");
  if (!canvas || !selectedId) return lineage;
  const parentsOf = new Map();
  const childrenOf = new Map();
  for (const node of canvas.querySelectorAll("[data-quest-offer]")) {
    const id = node.dataset.questOffer;
    const parents = String(node.dataset.questParents || "").split(",").map(s => s.trim()).filter(Boolean);
    parentsOf.set(id, parents);
    for (const p of parents) {
      if (!childrenOf.has(p)) childrenOf.set(p, []);
      childrenOf.get(p).push(id);
    }
  }
  if (!parentsOf.has(selectedId)) return lineage;
  lineage.add(selectedId);
  const up = [...(parentsOf.get(selectedId) || [])];
  while (up.length) {
    const id = up.pop();
    if (lineage.has(id)) continue;
    lineage.add(id);
    for (const p of parentsOf.get(id) || []) up.push(p);
  }
  const down = [...(childrenOf.get(selectedId) || [])];
  while (down.length) {
    const id = down.pop();
    if (lineage.has(id)) continue;
    lineage.add(id);
    for (const c of childrenOf.get(id) || []) down.push(c);
  }
  return lineage;
}

function applyQuestTreeZoom() {
  const canvas = document.getElementById("questTreeCanvas");
  if (!canvas) return;
  const zoom = Math.min(1.6, Math.max(0.5, Number(questTreeZoom) || 1));
  questTreeZoom = zoom;
  // `zoom` CSS plutôt que `transform: scale` : le scroll horizontal/vertical
  // suit la vraie taille (le transform ne change pas la zone scrollable).
  canvas.style.transform = "";
  try { canvas.style.zoom = zoom === 1 ? "" : String(zoom); } catch {}
  // Le bouton reset affiche le % réel (sinon il reste bloqué sur "100%").
  try {
    const label = ui.questOfferList?.querySelector('[data-quest-zoom="reset"]');
    if (label) {
      const pct = `${Math.round(zoom * 100)}%`;
      if (label.textContent !== pct) label.textContent = pct;
      label.title = `Zoom ${pct} — cliquer pour réinitialiser`;
    }
  } catch {}
}

function drawQuestTreeEdges(retry = 0) {
  const scroll = document.getElementById("questTreeScroll");
  const canvas = document.getElementById("questTreeCanvas");
  const svg = document.getElementById("questTreeEdges");
  if (!scroll || !canvas || !svg) return;
  const canvasRect = canvas.getBoundingClientRect();
  if (!canvasRect.width || !canvasRect.height) {
    // Fenêtre cachée ou en cours d'animation d'ouverture : les mesures sont
    // à zéro. On réessaye sur les frames suivantes au lieu d'abandonner
    // (sinon les fils restent vides/mal placés jusqu'au prochain clic).
    if (retry < 10) requestAnimationFrame(() => drawQuestTreeEdges(retry + 1));
    return;
  }
  const byOffer = new Map();
  for (const node of canvas.querySelectorAll("[data-quest-offer]")) byOffer.set(node.dataset.questOffer, node);
  let paths = "";
  for (const node of byOffer.values()) {
    const parents = String(node.dataset.questParents || "").split(",").map(s => s.trim()).filter(Boolean).slice(0, 8);
    if (!parents.length) continue;
    const target = node.getBoundingClientRect();
    const x2 = target.left - canvasRect.left;
    const y2 = target.top - canvasRect.top + target.height / 2;
    for (const parentId of parents) {
      const parent = byOffer.get(parentId);
      if (!parent) continue;
      const source = parent.getBoundingClientRect();
      const x1 = source.right - canvasRect.left;
      const y1 = source.top - canvasRect.top + source.height / 2;
      if (x2 - x1 < 4) continue;
      const midX = (x1 + x2) / 2;
      // Jaune sur toute la lignée (racines → sélection → feuilles),
      // pas seulement sur l'arête d'arrivée.
      const inLineage = selectedQuestLineage.has(parentId) && selectedQuestLineage.has(node.dataset.questOffer);
      const cls = inLineage ? "isActive" : parent.classList.contains("completed") ? "isDone" : "";
      paths += `<path class="${cls}" d="M ${x1.toFixed(1)} ${y1.toFixed(1)} C ${midX.toFixed(1)} ${y1.toFixed(1)}, ${midX.toFixed(1)} ${y2.toFixed(1)}, ${x2.toFixed(1)} ${y2.toFixed(1)}"/>`;
    }
  }
  // viewBox = dimensions visuelles (getBoundingClientRect), PAS scrollWidth :
  // avec le zoom CSS les deux diffèrent et les fils se détachent des nœuds.
  // Les coords ci-dessus sont déjà dans cet espace visuel → alignement à tout zoom.
  svg.setAttribute("viewBox", `0 0 ${Math.max(1, canvasRect.width)} ${Math.max(1, canvasRect.height)}`);
  svg.innerHTML = paths;
}

function centerQuestTreeOn(id) {
  const scroll = document.getElementById("questTreeScroll");
  if (!scroll || !id) return;
  const node = scroll.querySelector(`[data-quest-offer="${CSS.escape(String(id))}"]`);
  if (!node) return;
  try { node.scrollIntoView({ block: "center", inline: "center", behavior: "smooth" }); } catch { node.scrollIntoView(); }
}

function renderQuestTerminal() {
  if (!shouldRefreshWindow("questOfferWindow")) { questTerminalRenderPending = true; return; }
  if (!ui.questOfferDetail || !ui.questOfferList) return;
  questTerminalRenderPending = false;
  const hasAccess = hasQuestTerminalAccess();
  lastQuestTerminalAccess = hasAccess;
  let pilotSector = null;
  try {
    const pilot = account.user || getCurrentUserFull();
    pilotSector = getFaction(pilot?.faction)?.sector ?? null;
  } catch {}
  const prevScroll = (() => {
    const scroll = document.getElementById("questTreeScroll");
    return scroll ? { left: scroll.scrollLeft, top: scroll.scrollTop } : null;
  })();
  const view = buildQuestTerminalView({
    questState,
    selectedId: selectedQuestOfferId,
    hasAccess,
    collectables: COLLECTABLE_DEFS,
    npcTypes: NPC_TYPES,
    npcLocations: questNpcLocations,
    searchQuery: questTerminalSearch,
    filter: questTerminalFilter,
    playerSector: pilotSector,
  });
  selectedQuestOfferId = view.selectedQuestId;
  ui.questOfferList.innerHTML = view.listHtml;
  ui.questOfferDetail.innerHTML = view.detailHtml;
  selectedQuestLineage = computeQuestLineage(selectedQuestOfferId);
  applyQuestTreeZoom();
  if (prevScroll) {
    const scroll = document.getElementById("questTreeScroll");
    if (scroll) { scroll.scrollLeft = prevScroll.left; scroll.scrollTop = prevScroll.top; }
  }
  requestAnimationFrame(() => { applyQuestTreeZoom(); drawQuestTreeEdges(); });
}

loadNpcLocationIndex().then(locations => {
  questNpcLocations = locations;
  renderQuestTerminal();
  try { window.dispatchEvent(new CustomEvent("orbit:npc-locations-ready")); } catch {}
});

// Graphe des portails pour le voyage physique du BOT (BFS multi-sauts).
let botPortalIndex = null;
loadPortalIndex().then(index => {
  botPortalIndex = index;
  try { window.dispatchEvent(new CustomEvent("orbit:portal-index-ready")); } catch {}
});

function openQuestTerminal() {
  if (!hasQuestTerminalAccess()) return;
  renderQuestTerminal();
  window.GameWindowManager?.restore("questOfferWindow");
  // Double rAF : dessine après que la fenêtre soit réellement affichée
  // (le restore peut être animé). Redraws différés : rattrapent la fin
  // d'animation et le chargement des images qui décalent les nœuds.
  requestAnimationFrame(() => requestAnimationFrame(() => {
    centerQuestTreeOn(selectedQuestOfferId);
    drawQuestTreeEdges();
  }));
  setTimeout(() => drawQuestTreeEdges(), 150);
  setTimeout(() => drawQuestTreeEdges(), 500);
}

function closeQuestTerminal() {
  const card = ui.questOfferWindow;
  if (!card || card.classList.contains("gameWinClosing")) return;
  if (window.GameWindowManager) {
    // Même effet de disparition que le commerce, sans icône dock.
    card.classList.add("gameWinClosing");
    setTimeout(() => {
      card.classList.remove("gameWinClosing");
      window.GameWindowManager?.close("questOfferWindow");
    }, 360);
  } else card.style.display = "none";
}

ui.questOfferList?.addEventListener("click", event => {
  const zoomBtn = event.target.closest("[data-quest-zoom]");
  if (zoomBtn) {
    const mode = zoomBtn.dataset.questZoom;
    if (mode === "in") questTreeZoom = Math.min(1.6, (Number(questTreeZoom) || 1) + 0.1);
    else if (mode === "out") questTreeZoom = Math.max(0.5, (Number(questTreeZoom) || 1) - 0.1);
    else questTreeZoom = 1;
    applyQuestTreeZoom();
    requestAnimationFrame(drawQuestTreeEdges);
    return;
  }
  const chip = event.target.closest("[data-quest-filter]");
  if (chip) {
    questTerminalFilter = chip.dataset.questFilter;
    selectedQuestOfferId = null;
    renderQuestTerminal();
    requestAnimationFrame(() => {
      const first = document.querySelector("#questTreeCanvas .questTreeNode:not(.dimmed)");
      centerQuestTreeOn(first?.dataset?.questOffer || selectedQuestOfferId);
      drawQuestTreeEdges();
    });
    return;
  }
  const offer = event.target.closest("[data-quest-offer]");
  if (!offer) return;
  selectedQuestOfferId = offer.dataset.questOffer;
  renderQuestTerminal();
  requestAnimationFrame(() => { centerQuestTreeOn(selectedQuestOfferId); drawQuestTreeEdges(); });
});

// Le layout peut bouger après le dessin (images/polices chargées, resize,
// zoom) : revalide les fils sans boucle (le SVG est absolu, il ne resize rien).
try {
  if (typeof ResizeObserver !== "undefined" && ui.questOfferList) {
    new ResizeObserver(() => {
      if (!document.getElementById("questTreeCanvas")) return;
      cancelAnimationFrame(questTreeResizeFrame);
      questTreeResizeFrame = requestAnimationFrame(() => drawQuestTreeEdges());
    }).observe(ui.questOfferList);
  }
} catch {}

ui.questOfferList?.addEventListener("input", event => {
  const search = event.target.closest("[data-quest-search]");
  if (!search) return;
  questTerminalSearch = String(search.value || "");
  renderQuestTerminal();
  // Rend le focus à la recherche (le re-rendu remplace l'input).
  try {
    const input = ui.questOfferList.querySelector("[data-quest-search]");
    if (input) {
      input.focus();
      input.setSelectionRange(input.value.length, input.value.length);
    }
  } catch {}
});

ui.questOfferDetail?.addEventListener("click", event => {
  if (event.target.closest("[data-quest-terminal-close]")) {
    closeQuestTerminal();
    return;
  }
  const button = event.target.closest("[data-quest-terminal-accept]");
  if (!button) return;
  if (!hasQuestTerminalAccess()) {
    showToast("Rapproche-toi du bâtiment de quêtes", 1.5);
  } else if (acceptQuest(questState, button.dataset.questTerminalAccept)) {
    selectedQuestId = button.dataset.questTerminalAccept;
    markProgressDirty();
    saveProgressNow();
    showToast("Mission acceptée", 1.3);
    advanceQuestProgress("visit", String(window.__CURRENT_MAP_ID__ || "").toLowerCase());
  }
  renderQuestWindow();
  renderQuestTerminal();
});

// Les kills mettent l'état à jour immédiatement ; les panneaux fermés
// sont reconstruits une seule fois à leur prochaine ouverture.
function refreshPendingQuestViews() {
  const visible = node => node && !node.hidden && node.style.display !== "none"
    && !node.classList.contains("gameWinMinimized") && !node.classList.contains("gameWinClosing");
  if (questJournalRenderPending && visible(ui.questWindow)) renderQuestWindow();
  if (questTerminalRenderPending && visible(ui.questOfferWindow)) renderQuestTerminal();
}
for (const node of [ui.questWindow, ui.questOfferWindow]) {
  if (node) new MutationObserver(refreshPendingQuestViews).observe(node, {
    attributes: true, attributeFilter: ["class", "style", "hidden"],
  });
}

function advanceQuestProgress(kind, type, amount = 1, context = null) {
  const advanced = recordQuestProgress(questState, kind, type, amount, {
    map: String(context?.map ?? window.__CURRENT_MAP_ID__ ?? "").toLowerCase(),
  });
  // Passe de combat Halloween : mêmes événements, paliers séparés.
  // AVANT le return anticipé : le passe compte même sans quête active.
  try { advanceBattlepassProgress(kind, type, amount); } catch {}
  if (!advanced.length) return;
  markProgressDirty();

  for (const id of advanced) {
    const quest = QUEST_DEFINITIONS.find(item => item.id === id);
    if (quest && isQuestComplete(questState, quest)) {
      showToast(`Mission accomplie : ${quest.title}`, 2);
      // Validation automatique : la récompense part sans bouton Récupérer.
      claimQuestReward(id);
    }
  }
  // Filet : quêtes déjà complètes au chargement (vieilles sauvegardes).
  for (const id of Object.keys(questState.active)) {
    if (advanced.includes(id)) continue;
    const quest = QUEST_DEFINITIONS.find(item => item.id === id);
    if (quest && isQuestComplete(questState, quest)) claimQuestReward(id);
  }
  questJournalRenderPending = true;
  questTerminalRenderPending = true;
  refreshPendingQuestViews();
}

// Passe de combat : progression persistée (account.user.battlepass),
// récompenses en clés récupérées depuis la fenêtre dédiée.
// Event uniquement : hors event, rien ne progresse.
function advanceBattlepassProgress(kind, type, amount = 1) {
  try {
    if (!isHalloweenEventActive()) return;
  } catch { return; }
  const u = account.user || getCurrentUserFull();
  if (!u) return;
  u.battlepass = normalizeBattlepassState(u.battlepass);
  const res = recordBattlepassProgress(u.battlepass, kind, type, amount);
  if (!res.advanced.length) return;
  const live = netList()[0];
  if (live && live.id === u.id && live !== u) live.battlepass = mergeBattlepassProgress(u.battlepass, live.battlepass);
  markProgressDirty();
  for (const id of res.completed) {
    const def = getBattlepassObjective(id);
    try { showToast(`Passe de combat : ${def?.label || id} — clé(s) à récupérer`, 3); } catch {}
  }
  try { window.dispatchEvent(new CustomEvent("orbit:battlepass-updated")); } catch {}
}

// Suivi des ressources collectées pour les quêtes (Rinusk, Traceurs...).
function trackResourceGain(resourceId, qty) {
  const amount = Math.max(0, Math.floor(Number(qty) || 0));
  if (!resourceId || amount <= 0) return;
  try { advanceQuestProgress("collect", String(resourceId), amount); } catch {}
}

ui.questTabs?.addEventListener("click", event => {
  const tab = event.target.closest("[data-quest-tab]");
  if (!tab) return;
  selectedQuestId = tab.dataset.questTab;
  renderQuestWindow();
});

// Rend une quête terminée + distribue les récompenses (même logique que le
// clic manuel : crédits, munitions, XP, honneur, énergie GG). Réutilisé par
// le BOT (quêtes auto). Retourne true si rendue.
function claimQuestReward(questId) {
  const reward = claimQuest(questState, questId);
  if (!reward) return false;
  const quest = QUEST_DEFINITIONS.find(item => item.id === questId);
  // Booster QR-01 : récompenses de quêtes doublées.
  const questMult = playerBoosterMults().quest;
  const creditsGained = Math.max(0, Math.floor(Number(reward.credits || 0) * questMult));
  player.credits += creditsGained;
  // Mode multi : sinon les gains sont perdus sur 409 (canon serveur).
  try { noteNetCreditGain(creditsGained); } catch {}
  const ammoRewards = Object.entries(reward.ammo || {}).filter(([type, amount]) => Object.hasOwn(player.ammo, type) && Number(amount) > 0);
  const ammoGained = ammoRewards.map(([type, amount]) => [type, Math.max(0, Math.floor(Number(amount) * questMult || 0))]);
  for (const [type, gained] of ammoGained) player.ammo[type] += gained;
  if (ammoGained.length) {
    updateAmmoUI();
    try { noteNetPurchase(0, { ammo: Object.fromEntries(ammoGained) }); } catch {}
  }
  // Lasers offerts (ex : Prometheus) : stockés en inventaire (modules),
  // à équiper manuellement via les slots lasers.
  const laserMessages = [];
  try {
    const laserGains = Object.entries(reward.lasers || {}).filter(([id, qty]) => id && Number(qty) > 0);
    if (account.user && laserGains.length) {
      account.user.inventory ||= {};
      account.user.inventory.modules ??= [];
      account.user.inventory.counts ||= {};
      for (const [id, qty] of laserGains) {
        const q = Math.max(1, Math.floor(Number(qty) || 0));
        for (let i = 0; i < q; i++) {
          if (!account.user.inventory.modules.includes(id)) account.user.inventory.modules.push(id);
        }
        account.user.inventory.counts[id] = Math.max(0, Number(account.user.inventory.counts[id]) || 0) + q;
        let lname = String(id);
        try { lname = findCatalogItem(id)?.name || id; } catch {}
        laserMessages.push(`Vous avez reçu ${q} laser ${lname} (inventaire)`);
      }
    }
  } catch {}
  // Ressources offertes (ex : Cerebrum, Code secret) : direct inventaire.
  // Non suivies par les quêtes (pas de validation en cascade).
  const resourceMessages = [];
  try {
    const resGains = Object.entries(reward.resources || {}).filter(([id, qty]) => id && Number(qty) > 0);
    if (account.user && resGains.length) {
      account.user.inventory ||= {};
      account.user.inventory.resources ||= {};
      for (const [id, qty] of resGains) {
        const q = Math.max(1, Math.floor(Number(qty) || 0));
        account.user.inventory.resources[id] = Math.max(0, Number(account.user.inventory.resources[id]) || 0) + q;
        // Non-minerais (cipher...) : sinon perdus sur 409 (pas de MAX).
        try { if (!isOreResource(id)) noteNetResourceGain({ [id]: q }); } catch {}
        resourceMessages.push(`Vous avez reçu ${formatInteger(q)} ${getResourceName(id, q)}`);
      }
    }
  } catch {}
  const experience = Math.floor(getQuestExperienceReward(quest) * questMult);
  const honor = Math.floor(getQuestHonorReward(quest) * questMult);
  // Montants réellement reçus (bonus modules + boosters XP/honneur inclus).
  const gainedXp = awardExperience(experience)?.gained ?? experience;
  const gainedHonor = awardHonor(honor)?.gained ?? honor;
  if (account.user?.stats) account.user.stats.rankPoints = calculateRankPoints(account.user.stats);
  // Titres offerts par la quête : déblocage + notification.
  const titleMessages = [];
  try {
    const titleIds = Array.isArray(reward.titles) ? reward.titles.map(String) : [];
    for (const tid of titleIds) {
      const res = unlockCurrentUserTitle(tid);
      if (res?.ok) {
        account.user = res.user;
        titleMessages.push(`Titre débloqué : ${res.title?.name || tid}`);
      }
    }
    // Rattrapage auto (kills / quêtes) après chaque récompense.
    try { const r = refreshCurrentUserTitles(); if (r?.ok && r.user) account.user = r.user; } catch {}
  } catch {}
  markProgressDirty();
  saveProgressNow();
  const galaxyEnergy = Math.max(0, Math.floor(Number(reward.galaxyEnergy) * questMult || 0));
  if (galaxyEnergy > 0) {
    const energyResult = grantCurrentUserGalaxyEnergy(galaxyEnergy);
    if (energyResult.ok) {
      account.user = energyResult.user;
      renderGalaxyGateWindow();
    }
  }
  const AMMO_REWARD_NAMES = { x6: "RSB-75", rcb: "RCB-140", cbo: "CBO-100", job: "JOB-100", rb: "RB-214", pib: "PIB-100", idb: "IDB-125", vb: "VB-142", emaa: "EMAA-20", sbl: "SBL-100", abl: "A-BL", tent: "TENT-100", ice: "ICE-100", sab: "SAB-50", x2: "MCB-25", x3: "MCB-50", x4: "UCB-100", x1: "LCB-10" };
  const ammoMessages = ammoGained.map(([type, gained]) => `Vous avez reçu ${formatInteger(gained)} munitions ${AMMO_REWARD_NAMES[type] || String(type).toUpperCase()}`);
  const energyMessage = galaxyEnergy > 0 ? `Vous avez reçu ${formatInteger(galaxyEnergy)} énergies pour les portails intergalactiques (GG)` : "";
  addGameLog(`Mission ${quest?.title || questId} · +${formatInteger(creditsGained)} crédits · +${formatInteger(gainedXp)} XP · +${formatInteger(gainedHonor)} honneur${ammoMessages.length ? ` · ${ammoMessages.join(" · ")}` : ""}${laserMessages.length ? ` · ${laserMessages.join(" · ")}` : ""}${resourceMessages.length ? ` · ${resourceMessages.join(" · ")}` : ""}${energyMessage ? ` · ${energyMessage}` : ""}${titleMessages.length ? ` · ${titleMessages.join(" · ")}` : ""}`, "reward");
  showNotificationGroup([
    `Vous avez reçu ${formatInteger(creditsGained)} crédits`,
    `Vous avez gagné ${formatInteger(gainedXp)} XP`,
    `Vous avez gagné ${formatInteger(gainedHonor)} honneur`,
    ...ammoMessages,
    ...laserMessages,
    ...resourceMessages,
    ...(energyMessage ? [energyMessage] : []),
    ...titleMessages,
  ]);
  try { window.dispatchEvent(new CustomEvent("orbit:titles-updated")); } catch {}
  return true;
}

ui.questList?.addEventListener("click", event => {
  const button = event.target.closest("[data-quest-action]");
  if (!button) return;
  const questId = button.dataset.questId;

  if (button.dataset.questAction === "abandon") {
    if (button.dataset.abandonConfirmed !== "true") {
      button.dataset.abandonConfirmed = "true";
      button.classList.add("questCancelConfirm");
      button.textContent = "Confirmer l’abandon";
      window.setTimeout(() => {
        if (!button.isConnected || button.dataset.abandonConfirmed !== "true") return;
        delete button.dataset.abandonConfirmed;
        button.classList.remove("questCancelConfirm");
        button.textContent = "Abandonner la mission";
      }, 4000);
      return;
    }

    if (abandonQuest(questState, questId)) {
      selectedQuestId = null;
      markProgressDirty();
      saveProgressNow();
      showToast("Mission abandonnée — progression perdue", 1.7);
    }
  }

  if (button.dataset.questAction === "claim") {
    claimQuestReward(questId);
  }

  renderQuestWindow();
  renderQuestTerminal();
});

function sanitizeRocketsForSave() {
  const out = {};
  for (const id of ROCKET_IDS) {
    out[id] = Math.max(0, Math.floor(Number(player.rockets?.[id] || 0)));
  }
  return out;
}

function saveProgressNow() {
  return measureGameTask("saveProgressNow", saveProgressNowMeasured);
}

function saveProgressNowMeasured() {
  // Les missions peuvent être acceptées depuis le terminal avant que la
  // boucle de jeu ait initialisé `account.user`. Recharge alors le compte
  // directement afin de ne jamais perdre la sauvegarde des quêtes.
  if (!account.user) account.user = getCurrentUserFull();
  if (!account.user) return;
  
  const currentMap = window.__CURRENT_MAP_ID__ || "1-1";
  const result = updateCurrentUserProgress({
  credits: player.credits,
  quests: questState,
  battlepass: account.user.battlepass,
  stats: { ...(account.user.stats || {}) },
  inventory: { resources: { ...(account.user.inventory?.resources || {}) } },
  // Sauvegarde legere : drones/pet/upgrades/skylab/auction vivent deja dans
  // account.user (mute en direct). Les re-cloner ici a chaque autosave
  // coutait cher sans rien changer. Les changements de structure ecrivent
  // en direct + saveUser immediat sur leur propre chemin.
hangarState: !player.dead && started && !hangarLocationTransferPending() ? {
    id: SESSION_HANGAR_ID || null,
    x: player.x,
    y: player.y,
    mapId: currentMap,
    hpPct: savedHpPct(),
    shPct: savedShPct(),
  } : null,

  // ⚠ï¸ Ne pas sauvegarder ship ici non plus.
  ammo: {
    x1: Infinity,
    x2: player.ammo.x2 || 0,
    x3: player.ammo.x3 || 0,
    x4: player.ammo.x4 || 0,
    sab: player.ammo.sab || 0,
    x6: player.ammo.x6 || 0,
    rcb: player.ammo.rcb || 0,
    cbo: player.ammo.cbo || 0,
    job: player.ammo.job || 0,
    rb: player.ammo.rb || 0,
    pib: player.ammo.pib || 0,
    idb: player.ammo.idb || 0,
    vb: player.ammo.vb || 0,
    emaa: player.ammo.emaa || 0,
    sbl: player.ammo.sbl || 0,
    abl: player.ammo.abl || 0,
    tent: player.ammo.tent || 0,
    ice: player.ammo.ice || 0,
  },
  // Sélections (munition/roquette/lanceur actifs, modes AUTO) : JAMAIS ici.
  // Elles persistent en écriture immédiate au moment du choix (setAmmo,
  // dock roquettes/lanceurs, toggles AUTO) : l'autosave périodique avec
  // une mémoire périmée (2e onglet) réécraserait sinon le dernier choix.
  rockets: sanitizeRocketsForSave(),
  // Autosave chaud : que des nombres (credits/stats/stocks/pos). La forme
  // est garantie par ailleurs -> light:true saute ensureUserShape complet.
}, { light: true });
  if (result?.ok && result.user) account.user = result.user;
  account.dirty = false;
  window.dispatchEvent(new CustomEvent("orbit:profile-progress"));
}

// Commandes locales de développement : elles modifient l'état chargé et la
// sauvegarde en même temps, contrairement à une écriture directe localStorage.
window.giveHybridAlloy = function giveHybridAlloy(amount = 100) {
  if (!account.user) loadAccountUser();
  if (!account.user) throw new Error("Aucun pilote connecté.");
  const gained = Math.max(0, Math.floor(Number(amount) || 0));
  account.user.inventory ||= {};
  account.user.inventory.resources ||= {};
  const resources = account.user.inventory.resources;
  resources.hybrid_alloy = Math.max(0, Math.floor(Number(resources.hybrid_alloy) || 0)) + gained;
  markProgressDirty();
  saveProgressNow();
  showNotification(`Vous avez reçu ${formatInteger(gained)} Alliages hybrides`, 3, "reward");
  return resources.hybrid_alloy;
};

function savedHpPct() {
  return player.hpMax > 0 ? clamp(player.hp / player.hpMax, 0, 1) : null;
}

function savedShPct() {
  return player.shMax > 0 ? clamp(player.sh / player.shMax, 0, 1) : null;
}

function savePositionNow() {
  if (hangarLocationTransferPending()) return;
  if (!account.user) return;
  if (player.dead || !started) return;

  const currentMap = window.__CURRENT_MAP_ID__ || "1-1";
  if (SESSION_HANGAR_ID) {
    saveHangarStateById(SESSION_HANGAR_ID, player.x, player.y, currentMap, savedHpPct(), savedShPct(), { deferred: true });
  } else {
    saveActiveHangarState(player.x, player.y, currentMap, savedHpPct(), savedShPct(), { deferred: true });
  }
  markProgressDirty();
}

// ============================================================
// ✅ Configuration 1 / 2 + niveau
// ============================================================
const CONFIG_SWITCH = {
  cooldownMs: 5000,
  until: 0,
};
let configSwitchApplyPending = false;

// ✅ Bouclier séparé par configuration
// HP = partagé entre les configs
// Shield = chaque config garde sa propre valeur
const CONFIG_SHIELDS = {
  "1": null,
  "2": null,
};
// Dernière config VRAIMENT vue (anti-aliasing) : previous/next peuvent
// partager les mêmes objets via le cache de lecture et masquer un switch.
let lastSeenConfigNo = 0;

function normalizeConfigNo(configNo) {
  return Number(configNo) === 2 ? "2" : "1";
}

function saveShieldForConfig(configNo = getActiveConfigNo()) {
  const cfg = normalizeConfigNo(configNo);

  CONFIG_SHIELDS[cfg] = {
    sh: Math.max(0, Math.min(player.shMax || 0, Number(player.sh || 0))),
    shMax: Math.max(0, Number(player.shMax) || 0),
  };
}

function restoreShieldForConfig(configNo) {
  const cfg = normalizeConfigNo(configNo);
  const saved = CONFIG_SHIELDS[cfg];

  // Première fois qu'on va sur cette config : bouclier plein
  if (!saved) {
    player.sh = player.shMax;
    return;
  }

  // Le cache suit la nouvelle capacité si l'équipement a changé depuis la visite.
  const resized = resizeShield(saved, player.shMax);
  CONFIG_SHIELDS[cfg] = resized;
  player.sh = resized.sh;
}

function getActiveConfigNo() {
  const h = getActiveHangarFromUser(account.user);
  return Number(h?.activeConfig) === 2 ? 2 : 1;
}

function getSpeedBreakdown() {
  const u = account.user || getCurrentUserFull();
  const hangar = getActiveHangarFromUser(u);
  const shipId = u?.ship || ACTIVE_SHIP?.id || "PhoenixBleu";
  const pack = getShipPackById(shipId);

  const activeConfig = Number(hangar?.activeConfig) === 2 ? "2" : "1";

  const fit =
    hangar?.fits?.[activeConfig] ||
    hangar?.fit ||
    { gens: [], shipMods: [] };

  const base = Math.max(0, Number(pack?.speed || 0));

  let genSpeed = 0;
  const speedItems = [];

  for (const itemId of fit.gens || []) {
    if (!itemId) continue;

    const it = findCatalogItem(itemId);
    if (it?.module?.type !== "speed") continue;

    const bonus = Number(it.module.bonusSpeed || 0);
    genSpeed += bonus;

    speedItems.push({
      id: itemId,
      name: it.name || itemId,
      bonus,
    });
  }

  let speedPct = 0;
  const speedModules = [];

  const shipModules = Array.isArray(u?.inventory?.shipModules)
    ? u.inventory.shipModules
    : [];

  const modulesById = shipModuleIndex(shipModules);
  for (const modId of fit.shipMods || []) {
    if (!modId) continue;

    const mod = modulesById.get(modId);
    if (!mod) continue;

    for (const b of mod.bonuses || []) {
      if (b.stat !== "speed") continue;

      const pct = Number(b.pct || 0);
      speedPct += pct;

      speedModules.push({
        id: mod.id,
        type: mod.type,
        tier: mod.tier,
        pct,
      });
    }
  }

  speedPct += Number(getActiveDroneFormation(u).effects?.speedPct || 0);
  // ✅ Passif vitesse du design actif (ex : Tyrannos +15 %) : le déplacement
  // (player.baseSpeed via bonusSpeed du hangar) l'applique déjà — sans ça
  // l'HUD affichait une vitesse inférieure à la réelle.
  let designSpeedPct = 0;
  let designSpeedFlat = 0;
  let designSpeedLabel = "";
  try {
    const designFx = getShipEffectStats(shipId) || {};
    designSpeedPct = Math.max(0, Number(designFx.speedPct || 0));
    designSpeedFlat = Math.max(0, Number(designFx.speedFlat || 0));
    if (designSpeedPct > 0 || designSpeedFlat > 0) {
      designSpeedLabel = ` | Design: +${designSpeedPct}%${designSpeedFlat > 0 ? ` +${designSpeedFlat}` : ""}`;
    }
  } catch {}
  // ✅ Leonov home (x-1 à x-4 de sa firme) : vitesse x2, comme le moteur
  // de déplacement (player.baseSpeed) — sinon l'HUD affiche la moitié.
  const leonovHome = isLeonovHomeActive();
  // ✅ Ralentis et boosts temporaires (IEM, kamikaze, Hecate, Voyage, RVG) :
  // playerSlowMult central, comme le moteur de déplacement — sinon l'HUD
  // affiche la vitesse de base (ex. 280 au lieu de 252 ralenti).
  // Tech Speed Burst : 900 forcés comme le moteur (updatePlayerVelocity).
  const burst = (Number(player?.speedBurstT) || 0) > 0;
  const total = burst ? SPEED_BURST_SPEED : Math.floor(((base + genSpeed) * (1 + (speedPct + designSpeedPct) / 100) + designSpeedFlat) * playerUpgradeMults().speed * (leonovHome ? 1.2 : 1) * playerSlowMult(player));

  return {
    shipId,
    config: Number(activeConfig),
    base,
    genSpeed,
    speedPct,
    designSpeedLabel,
    leonovHome,
    total,
    speedItems,
    speedModules,
  };
}

function getConfigCooldownLeft() {
  return Math.max(0, (CONFIG_SWITCH.until - Date.now()) / 1000);
}

function applyCurrentConfigStats(keepRatios = true, restoreShieldConfigNo = null, keepAbsolute = false) {
  const u = loadAccountUser();
  if (!u) return false;

  const shipId = u.ship || ACTIVE_SHIP?.id || "PhoenixBleu";
  const pack = getShipPackById(shipId);
  ACTIVE_SHIP = pack;
  if (String(getShipDesignBaseId(pack?.id) || pack?.id).toLowerCase() === "hyperion") preloadGravityAnchorImages();

  const hangar = getActiveHangarFromUser(u);
  const stats = computeHangarStats(hangar, u, { mapId: currentMapId() });
  player.dr = BASE_RUN.dr;

  // ✅ HP partagé entre les configs
  const oldHpPct =
    keepRatios && player.hpMax > 0
      ? clamp(player.hp / player.hpMax, 0, 1)
      : 1;

  // Ancien comportement utilisé seulement hors changement de config
  const oldShPct =
    keepRatios && player.shMax > 0
      ? clamp(player.sh / player.shMax, 0, 1)
      : 1;

  player.shPen = BASE_RUN.shPen + ((stats.bonusPenetrationPct || 0) / 100);

  const isPoliceHull = String(getShipDesignBaseId(pack?.id) || pack?.id || "").toLowerCase() === "police";
  const shipBaseHP = Number(pack?.hp || 1) + (isPoliceHull ? 0 : 100_000);
  player.hpMax = Math.max(
    1,
    Math.floor((shipBaseHP + (stats.bonusFlatHP || 0) + playerPilotMults().hpFlat) * (1 + (stats.bonusHPPct || 0) / 100) * playerBoosterMults().hp)
  );
  refreshBuoyHpBase();

  player.shMax = Math.max(0, Math.floor((Number(stats.bonusShield) || 0) * playerBoosterMults().shield * playerPilotMults().shield * playerUpgradeMults().shield));
  // Absorption officielle du générateur équipé (max monté), défaut 80 %.
  player.shAbsorb = clamp(
    (Number(stats.bonusAbsorb) > 0 ? Number(stats.bonusAbsorb) / 100 : 0.8)
      + Number(stats.formationEffects?.shieldAbsorptionPct || 0) / 100,
    0,
    1,
  );
  // Détail des canons du vaisseau (bonus conditionnels vsMatch au tir).
  player.laserMods = Array.isArray(stats.laserMods) ? stats.laserMods : [];
  // Drones : bonus par canon aussi (overdrive/vs/instable x nombre équipé).
  player.droneLaserMods = Array.isArray(stats.droneLaserMods) ? stats.droneLaserMods : [];
  // OS-L Odysseus : 5 % de base + 3 % de critique par canon, plafond 50 %, dégâts ×2.
  let oslCount = 0;
  for (const m of player.laserMods) if (Number(m?.critPct || 0) > 0) oslCount += 1;
  player.critChance = oslCount > 0 ? Math.min(0.50, 0.05 + (3 * oslCount) / 100) : 0.05;
  player.critMult = oslCount > 0 ? 2.0 : 1.5;

  if (!player.dead) {
    // ✅ Valeurs absolues conservées : le now ne bouge pas, seul le max
    // change (les barres now/max se recalculent).
    if (keepAbsolute) {
      player.hp = Math.max(1, Math.min(player.hpMax, Math.floor(player.hp)));
      // Si on change de config : on restaure le bouclier de CETTE config.
      if (restoreShieldConfigNo !== null) {
        restoreShieldForConfig(restoreShieldConfigNo);
      } else {
        player.sh = Math.max(0, Math.min(player.shMax, Math.floor(player.sh)));
      }
    } else {
      // HP reste partage (changement de config)
      player.hp = Math.max(1, Math.floor(player.hpMax * oldHpPct));

      // Si on change de config : on restaure le bouclier de CETTE config
      if (restoreShieldConfigNo !== null) {
        restoreShieldForConfig(restoreShieldConfigNo);
      } else {
        player.sh = Math.max(0, Math.floor(player.shMax * oldShPct));
      }
    }
  }

  player.baseDamage = Math.max(1, Math.floor(stats.totalLaserDamage || 1));
  player.baseDamageNoLeonov = Math.max(1, Math.floor(stats.totalLaserDamageNoLeonov ?? stats.totalLaserDamage ?? 1));
  // Cadence de tir (formations type Polygone) : appliquée ici aussi, sinon
  // un changement de formation en cours de jeu ne l'active jamais.
  player.fireRateMult = BASE_RUN.fireRateMult * formationFireRateMult();
  // Modules roulette dégâts ciblés (appliqués au tir, pas dans la base).
  player.bonusNpcDmgPct = Number(stats.bonusNpcDmgPct || 0);
  player.bonusPvpDmgPct = Number(stats.bonusPvpDmgPct || 0);
  player.bonusRocketDmgPct = Number(stats.bonusRocketDmgPct || 0);

  player.laserHitBonusPct = clamp(Number(stats.bonusLaserHitPct || 0), -100, 100);
  player.rocketHitBonusPct = clamp(Number(stats.bonusRocketHitPct || 0), -100, 100);
  player.evasionBonusPct = clamp(Number(stats.bonusEvasionPct || 0), -100, 90);
  player.droneCooldownReductionPct = Number(stats.bonusAbilityCooldownPct || 0);
  player.droneDamageBonusPct = Number(stats.droneDesignEffects?.damagePct || 0);
  player.expBonusPct = Number(stats.bonusExpPct || 0);
  player.honorBonusPct = Number(stats.bonusHonorPct || 0);

  const shipBaseSpeed = Number(pack?.speed || 0);
  player.baseSpeed = Math.max(
    10,
    Math.floor((shipBaseSpeed + (stats.bonusSpeed || 0)) * playerUpgradeMults().speed * (stats.speedMult || 1))
  );

  player.accel = BASE_RUN.accel;
  player.friction = BASE_RUN.friction;

  // Recalcule la portée (ex : formation Polygone => 600).
  try { stockUpdateRange(); } catch {}

  return true;
}

function updateConfigButtons() {
  if (!shouldRefreshWindow("boxVitals")) return;
  const active = getActiveConfigNo();
  const left = getConfigCooldownLeft();

  if (ui.cfgToggleBtn) {
    setHudText(ui.cfgToggleBtn, String(active));
    setHudClass(ui.cfgToggleBtn, "active", true);
    setHudDisabled(ui.cfgToggleBtn, left > 0 || player.dead);
  }
  if (ui.cfg1Btn) {
    setHudClass(ui.cfg1Btn, "active", active === 1);
    setHudDisabled(ui.cfg1Btn, left > 0 || active === 1 || player.dead);
  }

  if (ui.cfg2Btn) {
    setHudClass(ui.cfg2Btn, "active", active === 2);
    setHudDisabled(ui.cfg2Btn, left > 0 || active === 2 || player.dead);
  }

  setHudText(ui.cfgCooldownTxt, left > 0 ? `${left.toFixed(1)}s` : "");
}

function trySwitchConfig(nextConfig) {
  if (player.dead) return;

  const current = getActiveConfigNo();
  nextConfig = Number(nextConfig) === 2 ? 2 : 1;

  if (current === nextConfig) return;

  const left = getConfigCooldownLeft();
  if (left > 0) {
    showToast(`Configuration en recharge: ${left.toFixed(1)}s`, 1.1);
    return;
  }

// ✅ sauvegarde le bouclier de la config actuelle avant de changer
saveShieldForConfig(current);

saveProgressNow();

// ✅ Toujours la vérité stockage d'abord : SESSION_HANGAR_ID peut être périmé
// après un changement de vaisseau sans refresh (overlay Espace pilote intégré).
// Écrire la config sur l'ancien hangar mettait le CD mais restait sur la config.
const hangarId = getActiveHangarId() || SESSION_HANGAR_ID;
configSwitchApplyPending = true;
const out = setActiveHangarConfig(hangarId, nextConfig);

  if (!out?.ok) {
    configSwitchApplyPending = false;
    showToast(out?.error || "Impossible de changer de configuration", 1.5);
    return;
  }

  // L'événement compte est normalement synchrone et applique déjà le profil.
  // Ce repli ne s'exécute que si aucun événement de switch n'a été observé.
  if (configSwitchApplyPending) {
    configSwitchApplyPending = false;
    applyCurrentConfigStats(false, nextConfig, true);
  }

  CONFIG_SWITCH.until = Date.now() + CONFIG_SWITCH.cooldownMs;

  updateConfigButtons();
  drawUI();

  showToast(`Configuration ${nextConfig} activée`, 1.1);
}

