// ============================================================
// ✅ PULSE/IEM FX (sprites one-shot)
// ============================================================
const PULSE_PACK = {
  path: "ASSETS/PULSE/",
  frames: 29,
  firstNumber: 1,
  ext: ".png",
  fps: 30,
  w: 437,
  h: 437,
};

let pulseImgs = [];
let pulseReady = false;

function ensurePulseFxLoaded() {
  if (PULSE_PACK._promise) return PULSE_PACK._promise;

  PULSE_PACK._imgs = new Array(PULSE_PACK.frames);

  PULSE_PACK._promise = (async () => {
    const jobs = [];
    for (let i = 0; i < PULSE_PACK.frames; i++) {
      const src = `${PULSE_PACK.path}${PULSE_PACK.firstNumber + i}${PULSE_PACK.ext}`;
      jobs.push(
        loadImage(src, { priority: false })
          .then((img) => (PULSE_PACK._imgs[i] = img))
          .catch(() => (PULSE_PACK._imgs[i] = null))
      );
    }
    await Promise.all(jobs);
    pulseImgs = PULSE_PACK._imgs;
    pulseReady = true;
    return true;
  })();

  return PULSE_PACK._promise;
}

const pulseFxs = [];

function spawnPulseFx(x, y, scale = 1, followPlayer = false, followNpcId = null) {
  if (!pulseReady || !pulseImgs?.length) return;
  pushBounded(pulseFxs, {
    x,
    y,
    t: 0,
    scale: Math.max(0.2, Number(scale) || 1),
    followPlayer: followPlayer === true,
    followNetId: typeof followPlayer === "string" ? followPlayer : null,
    // ✅ suit un NPC (ex. IEM claquée par un Saimon qui bouge).
    followNpcId: followNpcId ?? null,
  }, ENTITY_LIMITS.pulseFxs);
}

function tickPulseFx(dt) {
  if (!pulseFxs.length) return;
  const fps = PULSE_PACK.fps || 30;
  const frames = PULSE_PACK.frames || pulseImgs.length || 1;
  const dur = frames / fps;

  for (let i = pulseFxs.length - 1; i >= 0; i--) {
    pulseFxs[i].t += dt;
    if (pulseFxs[i].t >= dur) pulseFxs.splice(i, 1);
  }
}

function drawPulseFx(ox, oy) {
  if (!pulseReady || !pulseImgs?.length) return;

  const fps = PULSE_PACK.fps || 30;
  const frames = PULSE_PACK.frames || pulseImgs.length || 1;

  for (const fx of pulseFxs) {
    let fxTarget = null;
    try { if (fx.followNetId) fxTarget = getNetplayRemotes()?.get(String(fx.followNetId)); } catch {}
    let fxNpc = null;
    try { if (fx.followNpcId != null) fxNpc = getEnemyById(fx.followNpcId); } catch {}
    const fxX = fxNpc && fxNpc.hp > 0 ? Number(fxNpc.x) : (fxTarget ? Number(fxTarget.rx ?? fxTarget.x) : fx.x);
    const fxY = fxNpc && fxNpc.hp > 0 ? Number(fxNpc.y) : (fxTarget ? Number(fxTarget.ry ?? fxTarget.y) : fx.y);
    if (!fx.followPlayer && !fxTarget && !fxNpc && isBeyondSensorRadius(fx.x, fx.y)) continue;
    if ((fxTarget || fxNpc) && isBeyondSensorRadius(fxX, fxY)) continue;
    const idx = Math.min(frames - 1, Math.floor(fx.t * fps));
    const img = pulseImgs[idx];
    if (!isImgReady(img)) continue;

    const x = (fx.followPlayer ? player.x : (fxNpc && fxNpc.hp > 0 ? Number(fxNpc.x) : (fxTarget ? Number(fxTarget.rx ?? fxTarget.x) : fx.x))) + ox;
    const y = (fx.followPlayer ? player.y : (fxNpc && fxNpc.hp > 0 ? Number(fxNpc.y) : (fxTarget ? Number(fxTarget.ry ?? fxTarget.y) : fx.y))) + oy;

    const w = (PULSE_PACK.w || (img.naturalWidth || img.width || 256)) * fx.scale;
    const h = (PULSE_PACK.h || (img.naturalHeight || img.height || 256)) * fx.scale;

    ctx.save();
    ctx.imageSmoothingEnabled = false;
    ctx.imageSmoothingQuality = "low";
    ctx.globalAlpha = 1;
    ctx.drawImage(img, x - w / 2, y - h / 2, w, h);
    ctx.restore();
  }
}

// ============================================================
// ✅ SMARTBOMB SMB-01 FX : vidéo officielle smartbomb1.swf (VP6A 320x320,
// 213 ticks @12fps -> 118 frames uniques extraites en PNG RGBA dans
// ASSETS/SMARTBOMB/). Jouée à 30fps (~4 s), centrée sur le lanceur.
// ============================================================
const SMB_FX_PACK = {
  path: "ASSETS/SMARTBOMB/",
  frames: 118,
  firstNumber: 1,
  ext: ".png",
  fps: 30,
  // Vraie taille de la vidéo officielle (320x320, sans upscale).
  w: 320,
  h: 320,
};

let smbFxImgs = [];
let smbFxReady = false;

function ensureSmbFxLoaded() {
  if (SMB_FX_PACK._promise) return SMB_FX_PACK._promise;

  SMB_FX_PACK._imgs = new Array(SMB_FX_PACK.frames);

  SMB_FX_PACK._promise = (async () => {
    const jobs = [];
    for (let i = 0; i < SMB_FX_PACK.frames; i++) {
      const src = `${SMB_FX_PACK.path}${SMB_FX_PACK.firstNumber + i}${SMB_FX_PACK.ext}`;
      jobs.push(
        loadImage(src, { priority: false })
          .then((img) => (SMB_FX_PACK._imgs[i] = img))
          .catch(() => (SMB_FX_PACK._imgs[i] = null))
      );
    }
    await Promise.all(jobs);
    smbFxImgs = SMB_FX_PACK._imgs;
    smbFxReady = true;
    return true;
  })();

  return SMB_FX_PACK._promise;
}

const smbFxs = [];

function spawnSmbFx(x, y, scale = 1, followPlayer = false) {
  if (!smbFxReady || !smbFxImgs?.length) return;
  pushBounded(smbFxs, {
    x,
    y,
    t: 0,
    scale: Math.max(0.2, Number(scale) || 1),
    followPlayer: followPlayer === true,
    followNetId: typeof followPlayer === "string" ? followPlayer : null,
  }, ENTITY_LIMITS.smbFxs);
}

function tickSmbFx(dt) {
  if (!smbFxs.length) return;
  const fps = SMB_FX_PACK.fps || 30;
  const frames = SMB_FX_PACK.frames || smbFxImgs.length || 1;
  const dur = frames / fps;

  for (let i = smbFxs.length - 1; i >= 0; i--) {
    smbFxs[i].t += dt;
    if (smbFxs[i].t >= dur) smbFxs.splice(i, 1);
  }
}

function drawSmbFx(ox, oy) {
  if (!smbFxReady || !smbFxImgs?.length) return;

  const fps = SMB_FX_PACK.fps || 30;
  const frames = SMB_FX_PACK.frames || smbFxImgs.length || 1;

  for (const fx of smbFxs) {
    let fxTarget = null;
    try { if (fx.followNetId) fxTarget = getNetplayRemotes()?.get(String(fx.followNetId)); } catch {}
    if (!fx.followPlayer && !fxTarget && isBeyondSensorRadius(fx.x, fx.y)) continue;
    if (fxTarget && isBeyondSensorRadius(Number(fxTarget.rx ?? fxTarget.x), Number(fxTarget.ry ?? fxTarget.y))) continue;
    const idx = Math.min(frames - 1, Math.floor(fx.t * fps));
    const img = smbFxImgs[idx];
    if (!isImgReady(img)) continue;

    const x = (fx.followPlayer ? player.x : (fxTarget ? Number(fxTarget.rx ?? fxTarget.x) : fx.x)) + ox;
    const y = (fx.followPlayer ? player.y : (fxTarget ? Number(fxTarget.ry ?? fxTarget.y) : fx.y)) + oy;

    const w = (SMB_FX_PACK.w || (img.naturalWidth || img.width || 256)) * fx.scale;
    const h = (SMB_FX_PACK.h || (img.naturalHeight || img.height || 256)) * fx.scale;

    ctx.save();
    ctx.imageSmoothingEnabled = false;
    ctx.imageSmoothingQuality = "low";
    ctx.globalAlpha = 1;
    ctx.drawImage(img, x - w / 2, y - h / 2, w, h);
    ctx.restore();
  }
}

