// ============================================================
// ✅ BOOSTERS temporaires (boutique + fenêtre Boosters)
// ============================================================
function playerBoosterMults() {
  try {
    const base = activeBoosterMults(account.user?.boosters, Date.now());
    // Bonus de groupe B02 (proportionnel aux autres membres) : s'additionne
    // aux mults perso. En solo ou sans B02 autour : aucun changement.
    try {
      const counts = groupBoosterCounts();
      for (const [bid, n] of Object.entries(counts)) {
        if (!(Number(n) > 0)) continue;
        const bonus = GROUP_BOOSTER_BONUS[bid];
        if (!bonus) continue;
        for (const [k, v] of Object.entries(bonus)) {
          const add = (Number(v) || 0) * Number(n);
          if (!add) continue;
          if (k === "hitPct") base.hit = (Number(base.hit) || 0) + add;
          else if (k in base) base[k] = Number(base[k] || 1) + add / 100;
        }
      }
    } catch {}
    // Bases du clan avec modules DMG/HON/EXP/REP : +2 % dégâts, +10 % honneur,
    // +10 % exp, +2 % réparation par base (cumulé).
    try {
      const st = stationClanDmgMult();
      if (st !== 1) base.dmg = (Number(base.dmg) || 1) * st;
      const stH = stationClanHonMult();
      if (stH !== 1) base.honor = (Number(base.honor) || 1) * stH;
      const stE = stationClanExpMult();
      if (stE !== 1) base.exp = (Number(base.exp) || 1) * stE;
      const stR = stationClanRepMult();
      if (stR !== 1) base.repair = (Number(base.repair) || 1) * stR;
    } catch {}
    return base;
  } catch {
    return { dmg: 1, shield: 1, hp: 1, exp: 1, honor: 1, repair: 1, res: 1, petXp: 1, hit: 0, sreg: 1, box: 1, quest: 1 };
  }
}

// Bases construites tenues par le clan avec modules DMG/HON/EXP équipés :
// [{ map, dmg, hon, exp }] en % (+2 dégâts, +10 honneur, +10 exp par base).
// TEMPS RÉEL : liste live du serveur (toutes maps, via les snapshots) ;
// en solo (pas de serveur), la station locale uniquement.
function stationClanBaseBonuses() {
  const out = [];
  try {
    let myClan = "";
    try { myClan = String(getMyClanTag() || "").toUpperCase(); } catch {}
    if (!myClan) return out;
    let online = false;
    try { online = typeof netConnected === "function" && netConnected(); } catch {}
    if (online) {
      // En ligne : liste live du serveur (toutes maps, temps réel),
      // quel que soit la map courante. Vide = aucun bonus (pas de fantôme).
      let live = null;
      try { live = getNetClanBases(); } catch {}
      if (!Array.isArray(live)) return out;
      for (const b of live) {
        if (!b || typeof b !== "object") continue;
        if (String(b.clan || "").toUpperCase() !== myClan) continue;
        const entry = { map: String(b.map || "").toUpperCase(), dmg: 0, hon: 0, exp: 0, rep: 0 };
        if (b.dmg === true) entry.dmg = 2;
        if (b.hon === true) entry.hon = 10;
        if (b.exp === true) entry.exp = 10;
        if (b.rep === true) entry.rep = 2;
        if (!entry.dmg && !entry.hon && !entry.exp && !entry.rep) continue;
        out.push(entry);
      }
      return out;
    }
    const st = zoneStation;
    if (st && st.built && String(st.owner?.clan || "").toUpperCase() === myClan) {
      const equipped = (rid) => (st.slots || []).some((s) => s && s.resourceId === rid && Number(s.hp) > 0 && !(stationCooldownLeft(s.cooldownUntil) > 0));
      const entry = { map: "", dmg: 0, hon: 0, exp: 0, rep: 0 };
      if (equipped("station_module_dmg")) entry.dmg = 2;
      if (equipped("station_module_hon")) entry.hon = 10;
      if (equipped("station_module_exp")) entry.exp = 10;
      if (equipped("station_module_rep")) entry.rep = 2;
      if (entry.dmg || entry.hon || entry.exp || entry.rep) {
        entry.map = String(window.__CURRENT_MAP_ID__ || rules?.mapLabel || "").toUpperCase();
        if (entry.map) out.push(entry);
      }
    }
  } catch {}
  return out;
}

function stationClanBonusTotal(key) {
  try {
    let total = 0;
    for (const b of stationClanBaseBonuses()) total += Number(b[key]) || 0;
    return total;
  } catch { return 0; }
}

function stationClanDmgMult() {
  // Bonus bases plafonné à +10 % : même avec 23 bases au module dégâts,
  // seules 10 % s'appliquent (5 bases).
  const total = Math.min(10, stationClanBonusTotal("dmg"));
  return total > 0 ? 1 + total / 100 : 1;
}

function stationClanHonMult() {
  // Bonus bases plafonné à +50 % : même avec 13 bases au module honneur,
  // seules 50 % s'appliquent.
  const total = Math.min(50, stationClanBonusTotal("hon"));
  return total > 0 ? 1 + total / 100 : 1;
}

function stationClanExpMult() {
  // Bonus bases plafonné à +50 % : même avec 13 bases au module expérience,
  // seules 50 % s'appliquent.
  const total = Math.min(50, stationClanBonusTotal("exp"));
  return total > 0 ? 1 + total / 100 : 1;
}

function stationClanRepMult() {
  // Bonus bases plafonné à +10 % : même avec 23 bases au module réparation,
  // seules 10 % s'appliquent (5 bases).
  const total = Math.min(10, stationClanBonusTotal("rep"));
  return total > 0 ? 1 + total / 100 : 1;
}

// Bonus passifs de l'arbre de pilotage (même convention que les boosters :
// facteurs x pour les %, points additifs pour la précision, flat pour les PV).
function playerPilotMults() {
  let m = null;
  try {
    m = pilotSkillMults(account.user?.pilotSkills);
  } catch {
    m = null;
  }
  const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
  const fac = (v) => 1 + Math.max(0, num(v)) / 100;
  return {
    hpFlat: Math.max(0, Math.floor(num(m?.hpFlat))),
    repair: fac(m?.repairPct),
    shield: fac(m?.shieldPct),
    tough: Math.max(0, Math.min(90, num(m?.shieldToughPct))) / 100,
    exp: fac(m?.expPct),
    honor: fac(m?.honorPct),
    credit: fac(m?.creditPct),
    cargo: fac(m?.cargoPct),
    cargoLoot: fac(m?.cargoLootPct),
    bonusLoot: fac(m?.bonusLootPct),
    rocketDmg: fac(m?.rocketDmgPct),
    alienDmg: fac(m?.alienDmgPct),
    pvpDmg: fac(m?.pvpPct),
    laserHit: Math.max(0, num(m?.laserHitPct)),
    evade: Math.max(0, Math.min(0.9, num(m?.evadePct) / 100)),
    luck: fac(m?.luckPct),
    rocketHit: Math.max(0, num(m?.rocketHitPct)),
  };
}

let boosterPrevSignature = "";
let boosterWindowRefreshT = 0;
let boosterResyncT = 0;
let upgradeDrainT = 0;
let auctionTickT = 0;

// Liaison serveur (vrai jeu multi) : entrée + vie.
// - Sas d'entrée : pas de spawn sans hello traité (anti-fantôme).
// - Heartbeat 3 s : sans message serveur depuis 30 s = liaison morte -> overlay
//   bloquant + simulation gelée, reconnexion jusqu'au succès.
let linkDead = false;
let retryAcc = 0;
let retryCount = 0;

function netLinkReadyForEntry() {
  try {
    if (!netConnected()) return false;
    // Le hello reste valide pendant toute la vie du socket. Un chargement
    // de ressources de plus de 15 s ne doit pas bloquer le bouton Départ.
    if (!Number.isFinite(netHelloAckAge())) return false;
    if (netServerMessageAge() >= 30000) return false;
    return true;
  } catch {
    return false;
  }
}

function waitNetLink(timeoutMs) {
  const limit = Math.max(1000, Number(timeoutMs) || 15000);
  const t0 = Date.now();
  return new Promise((resolve) => {
    const step = () => {
      let ok = false;
      try {
        ok = netLinkReadyForEntry();
      } catch {
        ok = false;
      }
      if (ok) {
        resolve(true);
        return;
      }
      if (Date.now() - t0 > limit) {
        resolve(false);
        return;
      }
      setTimeout(step, 100);
    };
    step();
  });
}

function netLinkAliveInGame() {
  try {
    if (!netConnected()) return false;
    return netServerMessageAge() < 30000;
  } catch {
    return false;
  }
}

function setLinkOverlay(visible, text) {
  try {
    let el = document.getElementById("linkOverlay");
    if (!el) return;
    if (visible) {
      const label = el.querySelector("[data-link-label]");
      if (label && typeof text === "string" && text) label.textContent = text;
      el.style.display = "flex";
    } else {
      el.style.display = "none";
    }
  } catch {}
}

// Kick admin : déconnexion + popup bloquante avec le motif. Retour
// UNIQUEMENT via refresh manuel (bouton) : aucun retry auto, le joueur
// ne revient jamais tout seul (le heartbeat l'ignore tant que c'est armé).
let kickedReason = null;
function setKickOverlay(reason, title) {
  try {
    kickedReason = typeof reason === "string" && reason ? reason : null;
    const el = document.getElementById("kickOverlay");
    if (!el) return;
    if (kickedReason != null) {
      renderSpeedGuard(false);
      const label = el.querySelector("[data-kick-reason]");
      if (label) label.textContent = kickedReason;
      const heading = el.querySelector("[data-kick-title]");
      if (heading && typeof title === "string" && title) heading.textContent = title;
      try { setLinkOverlay(false); } catch {}
      el.style.display = "flex";
    } else {
      el.style.display = "none";
    }
  } catch {}
}

function enterLinkDead() {
  if (linkDead) return;
  linkDead = true;
  retryAcc = 0;
  retryCount = 0;
  // Liaison coupée (restart/MAJ serveur, réseau) : les entités réseau
  // (NPC, cadavres) sont purgées aussitôt. Sans ça, un cadavre conservé
  // bloque la nouvelle incarnation (même uid, seq remis à zéro) et le NPC
  // ne réapparaît jamais côté client alors que le serveur l'a respawné.
  try { purgeNetEntitiesForReconnect(); } catch {}
  try {
    forceNetReconnect();
  } catch {}
  setLinkOverlay(true, "Connexion perdue — reconnexion…");
}

// Retire toutes les entités réseau (reconstruction propre aux prochains
// snapshots). Les NPC locaux (gates) sont conservés.
function purgeNetEntitiesForReconnect() {
  let lockedPurged = false;
  let locked = null;
  try { locked = Target.get(); } catch {}
  for (let i = enemies.length - 1; i >= 0; i--) {
    const e = enemies[i];
    if (!e || e._netUid == null) continue;
    try { if (e.id != null) enemiesById.delete(e.id); } catch {}
    if (locked && e === locked) lockedPurged = true;
    enemies.splice(i, 1);
  }
  if (lockedPurged) { try { Target.clear(); } catch {} }
}

function tickLinkHeartbeat(realDt) {
  if (!started || starting) return;
  // Traiter aussi les fins de session quand linkDead gele la simulation.
  for (const K of drainNetAdminKickInbox()) {
    if (!K?.title) {
      try { spawnExplosion(player.x, player.y, 1.4); } catch {}
      try { SFX.play("npcDeath", { cooldown: 0 }); } catch {}
    }
    try { netDisconnect(); } catch {}
    try { setKickOverlay(K?.reason || "Comportement inapproprié.", K?.title || "Exclu par l'administrateur"); } catch {}
  }
  try {
    for (const B of drainNetBannedInbox()) {
      try { netDisconnect(); } catch {}
      // Banni : popup bloquante (motif + date de retour), refresh manuel.
      // Aucun retry auto (validation heartbeat) tant que c'est armé.
      const until = Number(B?.until);
      const dateTxt = Number.isFinite(until) && until > 0
        ? ` Vous pourrez vous reconnecter à partir du ${new Date(until).toLocaleString("fr-FR")}.`
        : " Bannissement définitif.";
      try { setKickOverlay(`Vous avez été banni. Motif : ${B?.reason || "Comportement inapproprié."}.${dateTxt}`, "Banni par l'administrateur"); } catch {}
    }
    for (const C of drainNetCheatInbox()) {
      try { netDisconnect(); } catch {}
      // Triche (kick + gel, dossier en examen) : comme une déconnexion
      // volontaire + message modération, refresh manuel pour revenir
      // (rejeté tant que le gel est actif).
      try { setKickOverlay(C?.reason || "Vous avez triché. La modération étudie actuellement votre cas. Si cela est avéré, vous serez définitivement banni.", "Triche détectée"); } catch {}
    }
  } catch {}
  // Kické : popup bloquante, aucun retry, aucun masquage auto.
  if (kickedReason != null) {
    try { setKickOverlay(kickedReason); } catch {}
    return;
  }
  if (!linkDead) {
    // Les pings sont geres par NETPLAY, independamment des frames du jeu.
    // Onglet masqué : timers étranglés, on ne déclare pas la mort
    // (vérification reprise au retour).
    try {
      if (document.visibilityState === "hidden") return;
    } catch {}
    if (!netLinkAliveInGame()) enterLinkDead();
    return;
  }
  // Liaison morte : réessaie jusqu'au succès (bloquant, comme un vrai MMO).
  retryAcc += realDt;
  if (retryAcc >= 3) {
    retryAcc = 0;
    retryCount++;
    setLinkOverlay(true, `Connexion perdue — reconnexion… (tentative ${retryCount})`);
    try {
      forceNetReconnect();
    } catch {}
  }
  if (netLinkReadyForEntry()) {
    linkDead = false;
    retryAcc = 0;
    setLinkOverlay(false);
  }
}

// Mise à jour déployée (git pull + restart serveur) : le pong porte la
// version serveur. Si elle diffère de celle du boot, on prévient 5 s
// puis on recharge (sauvegarde d'abord : position + progression).
let versionCheckT = 0;
let versionReloadArmed = false;
function isNewerGameVersion(candidate, current) {
  if (!/^\d+(\.\d+)*$/.test(candidate) || !/^\d+(\.\d+)*$/.test(current)) return false;
  const next = candidate.split(".").map(Number), previous = current.split(".").map(Number);
  for (let i = 0; i < Math.max(next.length, previous.length); i++) {
    const delta = (next[i] || 0) - (previous[i] || 0);
    if (delta) return delta > 0;
  }
  return false;
}
function forceReloadAfterServerRestart() {
  if (versionReloadArmed || kickedReason != null) return;
  versionReloadArmed = true;
  try { showNotification("Serveur redémarré — actualisation automatique…", 3, "info"); } catch {}
  setTimeout(() => {
    try { saveStateImmediate(); } catch {}
    try { saveProgressNow(); } catch {}
    setTimeout(() => { try { location.reload(); } catch {} }, 1000);
  }, 2000);
}
window.addEventListener("orbit:server-restarted", forceReloadAfterServerRestart);
window.addEventListener("orbit:server-maintenance", () => {
  try { saveStateImmediate(); } catch {}
  try { saveProgressNow(); } catch {}
  try { showNotification("Maintenance — sauvegarde et reconnexion automatique…", 4, "info"); } catch {}
});
function tickGameVersionCheck(dt) {
  if (versionReloadArmed) return;
  // Kické : on ne recharge jamais tout seul (retour via refresh manuel).
  if (kickedReason != null) return;
  versionCheckT += Math.max(0, Number(dt) || 0);
  if (versionCheckT < 5) return;
  versionCheckT = 0;
  let srv = "";
  try { srv = String(netServerVersion() || ""); } catch { return; }
  const mine = String(GAME_VERSION || "");
  if (!srv || !mine || srv === mine) return;
  armVersionReload(srv, mine);
}
function armVersionReload(srv, mine) {
  // Pendant un déploiement le fichier client peut précéder le redémarrage
  // du processus serveur. Sa version plus ancienne ne justifie aucun reload.
  if (versionReloadArmed || !isNewerGameVersion(srv, mine)) return;
  versionReloadArmed = true;
  try { showNotification(`Mise à jour du jeu reçue (v${mine} → v${srv}) — actualisation dans 5 s…`, 5, "info"); } catch {}
  setTimeout(() => {
    try { saveStateImmediate(); } catch {}
    try { saveProgressNow(); } catch {}
    // Laisse le push réseau partir avant de couper.
    setTimeout(() => { try { location.reload(); } catch {} }, 1500);
  }, 5000);
}
// Retour d'onglet (veille téléphone...) : le WS peut être mort, donc le
// check par pong ne voit plus rien. On relit la version par HTTP (petit
// fichier, sans cache) : si le serveur a bougé pendant l'absence, on
// recharge au lieu de jouer sur du vieux code indéfiniment.
let visibilityVersionCheckAt = 0;
function checkVersionOnReturn() {
  try {
    if (versionReloadArmed || kickedReason != null) return;
    if (typeof document === "undefined" || document.visibilityState !== "visible") return;
    const now = Date.now();
    if (now - visibilityVersionCheckAt < 30000) return;
    visibilityVersionCheckAt = now;
    fetch("SRC/DATA/VERSION.js", { cache: "no-store" }).then((r) => r.text()).then((t) => {
      try {
        const m = /GAME_VERSION\s*=\s*"([^"]+)"/.exec(String(t || ""));
        const srv = m ? m[1] : "";
        const mine = String(GAME_VERSION || "");
        if (!srv || !mine || srv === mine) return;
        armVersionReload(srv, mine);
      } catch {}
    }).catch(() => {});
  } catch {}
}
try {
  window.addEventListener("visibilitychange", () => {
    try { if (document.visibilityState === "visible") checkVersionOnReturn(); } catch {}
  });
} catch {}

// Base de Combat partagée : sync serveur (filtrée par clan), accusés et
// remboursements. Toute action attend obligatoirement le premier snapshot.
function stationSharedActive() {
  try {
    const map = String(window.__CURRENT_MAP_ID__ || rules?.mapLabel || "").toLowerCase();
    return isSharedStation(map) && netIsAuthed();
  } catch {
    return false;
  }
}

function stationApplyNetStock(resourceId, delta) {
  try {
    const u = getCurrentUserForMutation();
    if (!u) return;
    u.inventory = u.inventory || {};
    u.inventory.resources = u.inventory.resources || {};
    const id = String(resourceId || "");
    if (!id) return;
    const cur = Math.max(0, Math.floor(Number(u.inventory.resources[id]) || 0));
    u.inventory.resources[id] = Math.max(0, cur + Math.floor(Number(delta) || 0));
    account.user = u;
    saveUser(u, { durable: true });
    try { localStorage.setItem("orbit_sync", String(Date.now())); } catch {}
  } catch {}
}

function tickStationLogic() {
  if (!account.user || !zoneStation) return;
  try {
    const map = String(window.__CURRENT_MAP_ID__ || rules?.mapLabel || "").toLowerCase();
    // Reconnexion après coupure/restart serveur : forcer une sync complète.
    const upNow = (() => { try { return !!netConnected(); } catch { return false; } })();
    if (upNow && !tickStationLogic._wasUp) {
      try { resetSharedStation(); } catch {}
    }
    tickStationLogic._wasUp = upNow;
    ensureStationSync(map, zoneStation);
    // Compte à rebours affiché à chaque frame (fenêtre ouverte uniquement).
    try { stationTickCooldowns(); } catch {}
    // Remplacements et réparations : le client attend toujours l'état serveur.
    // Resync ~1/s pendant le cycle + 3 s de grâce afin que les changements
    // appliqués par le serveur restent visibles par tous.
    // Comparaisons en heure serveur estimée (décalage d'horloge possible).
    try {
      if (stationSharedActive()) {
        const now = serverNow();
        const done = (zoneStation.slots || []).some((s) => s?.replace && Number(s.replace.cooldownUntil) <= now);
        const rep = zoneStation.repair;
        const repActive = rep && Number(rep.until) > now;
        if (repActive) tickStationLogic._repairSeenUntil = now;
        const repGrace = !repActive && now - (tickStationLogic._repairSeenUntil || 0) < 3000;
        if ((done || repActive || repGrace) && now - (tickStationLogic._repairSyncReq || 0) > 1000) {
          tickStationLogic._repairSyncReq = now;
          requestStationSync(map);
        }
        // Resync périodique du déflecteur (banque + ON/OFF temps réel).
        if (zoneStation.deflect && now - (tickStationLogic._deflectSyncReq || 0) > 5000) {
          tickStationLogic._deflectSyncReq = now;
          requestStationSync(map);
        }
      }
    } catch {}
    const pump = pumpStationNet(zoneStation, map);
    const events = pump.events || [];
    if (!pump.dirty && !events.length) return;
    // Dès qu'un clan termine la base, tous les autres perdent l'accès à
    // l'interface. La fenêtre est réduite immédiatement chez eux.
    if (zoneStation.built && !stationOwnedByMyClan()) {
      zoneStation.cbsButtonHovered = false;
      zoneStation.cbsButtonPressed = false;
      if (isStationWindowOpen()) window.GameWindowManager?.minimize?.("stationWindow");
    }
    // Fenêtre station : s'éloigner ou mourir la réduit dans tous les cas.
    // Base NON construite : la pose en cours est annulée (module retiré,
    // stock recrédité au sync). Base construite : le remplacement continue,
    // seule la fenêtre se réduit.
    try {
      const st = zoneStation;
      let dead = false;
      try { dead = !!player?.dead; } catch {}
      let far = true;
      try { far = !isPlayerNearStation(); } catch {}
      if ((far || dead) && isStationWindowOpen()
        && !(ui.stationWindow && ui.stationWindow.classList.contains("gameWinMinimized"))) {
        try { window.GameWindowManager?.minimize?.("stationWindow"); } catch {}
      }
      if (!st.built && (far || dead) && stationSharedActive()) {
        const now = Date.now();
        const sent = tickStationLogic._stationAutoCancel || (tickStationLogic._stationAutoCancel = {});
        for (const k of Object.keys(sent)) {
          if (now - Number(sent[k] || 0) > 15000) { try { delete sent[k]; } catch {} }
        }
        const me = (() => { try { return String(netMyId() || ""); } catch { return ""; } })();
        const pendings = [];
        try {
          if (st.hub && Number(st.hubCd) > now && (!me || !st.hubPlacer || String(st.hubPlacer) === me)) pendings.push("hub");
        } catch {}
        try {
          for (const s of st.slots || []) {
            if (!s?.id || !s.resourceId || !(Number(s.cooldownUntil) > now)) continue;
            if (me && s.placerId && String(s.placerId) !== me) continue;
            pendings.push(String(s.id));
          }
        } catch {}
        for (const sid of pendings) {
          if (now - Number(sent[sid] || 0) < 10000) continue;
          sent[sid] = now;
          try { stationUninstallSlot(sid); } catch {}
          try { showToast("Pose annulée — trop loin de la base.", 2); } catch {}
        }
      }
    } catch {}
    // Flottants réparation : +85 000/+42 500 par seconde pendant un cycle
    // actif, +5 000 en passif REP. Membres du clan uniquement (même
    // chiffre sur tous les écrans). On marque les pièces ayant vraiment
    // gagné des PV (même devenues pleines entre-temps).
    // Heures serveur (décalage d'horloge possible).
    try {
      const rep = zoneStation.repair;
      const repActive = rep && Number(rep.until) > serverNow();
      let hasRepPassive = false;
      try {
        hasRepPassive = !!zoneStation.built && (zoneStation.slots || []).some((s) => s && s.resourceId === "station_module_rep" && Number(s.hp) > 0);
      } catch {}
      const prev = tickStationLogic._repairHp || (tickStationLogic._repairHp = new Map());
      const marks = tickStationLogic._repairMarks || (tickStationLogic._repairMarks = { hub: 0, slots: {} });
      if (repActive || hasRepPassive) {
        const mark = (key, cur, slotId) => {
          const c = Math.max(0, Number(cur) || 0);
          const had = prev.has(key) ? prev.get(key) : null;
          prev.set(key, c);
          if (had == null || !(c > had)) return;
          if (slotId) marks.slots[slotId] = (marks.slots[slotId] || 0) + (c - had);
          else marks.hub += c - had;
        };
        mark("hub", zoneStation.hubHp);
        for (const slot of zoneStation.slots || []) {
          if (!slot?.id || !slot.resourceId) {
            if (slot?.id) prev.delete(`slot:${slot.id}`);
            continue;
          }
          mark(`slot:${slot.id}`, slot.hp, slot.id);
        }
        if (Date.now() - (tickStationLogic._repairFloatT || 0) >= 1000) {
          tickStationLogic._repairFloatT = Date.now();
          flushRepairFloats(zoneStation, marks,
            repActive ? (Number(rep?.rateHub) || 85000) : 5000,
            repActive ? (Number(rep?.rateSlot) || 42500) : 5000);
          marks.hub = 0;
          marks.slots = {};
        }
      } else {
        if (tickStationLogic._repairHp) tickStationLogic._repairHp.clear();
        if (tickStationLogic._repairMarks) { tickStationLogic._repairMarks.hub = 0; tickStationLogic._repairMarks.slots = {}; }
      }
    } catch {}
    for (const ev of events) {
      try {
        if (ev?.type === "installed") {
          stationApplyNetStock(ev.resourceId, -1);
        } else if (ev?.type === "replaced") {
          stationApplyNetStock(ev.resourceId, -1);
          if (ev.replaced) stationApplyNetStock(ev.replaced, 1);
          showNotification(`Module remplacé : ${getResourceName(ev.resourceId, 1)}`, 3, "reward");
        } else if (ev?.type === "replaceCancelled") {
          if (ev.resourceId) stationApplyNetStock(ev.resourceId, 1);
          showNotification("Remplacement annulé.", 3, "reward");
        } else if (ev?.type === "uninstalled" || ev?.type === "refunded") {
          stationApplyNetStock(ev.resourceId, 1);
          if (ev?.type === "refunded") showNotification(`Module restitué : ${getResourceName(ev.resourceId, 1)}`, 3, "reward");
        } else if (ev?.type === "reject") {
          if (ev?.reason) showToast(ev.reason, 2.5);
        } else if (ev?.type === "stationDestroyed") {
          if (String(ev.target) === "hub") {
            // Cœur détruit : toute la base tombe — explosion simultanée sur
            // le cœur et chaque emplacement (tous garnis : 10/10 requis).
            const hx = Number(zoneStation.x);
            const hy = Number(zoneStation.y);
            spawnExplosion(hx, hy, 1, "rocket");
            try { stationDestroyedAnims.clear(); } catch {}
            for (const slot of zoneStation.slots || []) {
              try {
                spawnExplosion(hx + (slot ? Number(slot.dx || 0) : 0), hy + (slot ? Number(slot.dy || 0) : 0), 1, "rocket");
              } catch {}
            }
            if (Target.get()?._stationTarget) { Target.clear(); stopAttack(); }
          } else {
            const slot = (zoneStation.slots || []).find((entry) => String(entry?.id) === String(ev.target));
            const x = Number(zoneStation.x) + (slot ? Number(slot.dx || 0) : 0);
            const y = Number(zoneStation.y) + (slot ? Number(slot.dy || 0) : 0);
            spawnExplosion(x, y, 1, "rocket");
            try { stationDestroyedAnims.set(String(ev.target), performance.now()); } catch {}
            if (Target.get()?._stationTarget === ev.target) { Target.clear(); stopAttack(); }
          }
        }
      } catch {}
    }
    stationRefresh();
  } catch (error) {
    console.warn("Station tick:", error);
  }
}

function tickAuctionLogic() {  if (!account.user) return;
  // Liaison morte : enchères gelées jusqu'à la reprise.
  if (linkDead) return;
  // Le serveur tranche toujours ; aucun tick ni règlement client de secours.
  try {
    const pump = pumpSharedAuction();
    if (pump && pump.shared) {
      // Les remboursements (surenchère, rejet, défaite au settle) modifient
      // les crédits + lots en stockage via saveUser(). Sans resync ici,
      // account.user / player.credits restaient périmés et la prochaine
      // sauvegarde écrasait le remboursement ("marqué remboursé" mais
      // crédits jamais recrédités). On resync donc sur dirty aussi.
      // Sync à delta préservé (pas de syncPlayerFromAccount aveugle) :
      // player.credits peut contenir des gains/dépenses non sauvés
      // (collecte, pulse...) qu'on ne doit pas effacer à chaque mise rivale.
      if (pump.profileDirty || pump.dirty) {
        try {
          const fresh = getCurrentUserFull();
          if (fresh && account.user) {
            const delta = Math.floor(Number(fresh.credits || 0)) - Math.floor(Number(account.user.credits || 0));
            account.user.credits = fresh.credits;
            account.user.auction = fresh.auction;
            account.user.revision = fresh.revision;
            if (Number.isFinite(delta) && delta !== 0) {
              player.credits = Math.max(0, Math.floor(Number(player.credits || 0) + delta));
            }
          } else {
            syncPlayerFromAccount();
          }
        } catch {
          try { syncPlayerFromAccount(); } catch {}
        }
        markProgressDirty();
        window.dispatchEvent(new CustomEvent("orbit:profile-progress"));
      }
      if (pump.dirty) {
        try { renderAuctionWindow(); } catch {}
      }
      for (const ev of pump.events || []) {
        if (ev?.type === "won") showNotification(`Enchère remportée : ${ev.name} !`, 3.5, "reward");
        else if (ev?.type === "toast" && ev.text) showNotification(ev.text, 2.5, "info");
      }
      return;
    }
  } catch {}
}
let refineryLiveT = 0;

function boosterActiveSignature() {
  const active = account.user?.boosters?.active || {};
  const counts = account.user?.inventory?.counts || {};
  const now = Date.now();
  // Actifs + stocks : un achat (stock seul) re-rend aussi la fenêtre.
  return BOOSTERS.map((d) => `${Number(active[d.id] || 0) > now ? "1" : "0"}:${Math.max(0, Math.floor(Number(counts[boosterCatalogId(d)] || 0)))}`).join("|");
}

function tickBoosters(dt) {
  if (!started) return;
  tickRefineryAuto(dt);
  // Usure améliorations bouclier/vitesse : 1 minerai / 60 s.
  upgradeDrainT += dt;
  if (upgradeDrainT >= 60) {
    upgradeDrainT = 0;
    let drained = false;
    if (consumeUpgradeStock("shield")) drained = true;
    if (consumeUpgradeStock("speed")) drained = true;
    if (drained && ui.refineryWindow && ui.refineryWindow.style.display !== "none") renderRefineryWindow();
  }
  // Relecture périodique du compte (achats boutique, autre onglet...) :
  // les nouveaux boosters s'appliquent aux calculs sous 2 s max.
  boosterResyncT += dt;
  if (boosterResyncT >= 2) {
    boosterResyncT = 0;
    try {
      const fresh = netList()[0] || getCurrentUserFull();
      if (fresh && Number(fresh.revision || 0) !== Number(account.user?.revision || 0)) {
        // Minerais : jamais de redescente sur un gain local pas encore
        // persisté (collecte +1 par +1 : le Palladium rendait ça visible).
        // Même règle que mergeProgressiveFields côté net : les dépenses
        // écrivent le canon + resync le moteur, seul le moteur collecte.
        try {
          const pRes = account.user?.inventory?.resources;
          const nRes = fresh?.inventory?.resources;
          if (pRes && nRes && typeof pRes === "object" && typeof nRes === "object") {
            for (const id of ["palladium", "prometium", "endurium", "terbium", "prometid", "duranium", "promerium", "seprom", "xenomit", "osmium"]) {
              const pv = Math.max(0, Math.floor(Number(pRes[id]) || 0));
              if (pv > Math.max(0, Math.floor(Number(nRes[id]) || 0))) nRes[id] = pv;
            }
          }
        } catch {}
        account.user = preserveLivePetVitals(account.user, fresh);
        try { applyCurrentConfigStats(false, null, true); } catch {}
      }
    } catch {}
  }
  const now = Date.now();
  const userBoosters = account.user?.boosters;
  // Migration du stock résiduel (anciennes versions) : tout part en timer.
  const counts = account.user?.inventory?.counts;
  if (userBoosters && counts) {
    for (const def of BOOSTERS) {
      const stockKey = `booster_${def.id}`;
      const stock = Math.max(0, Math.floor(Number(counts[stockKey] || 0)));
      if (stock <= 0) continue;
      const current = Number(userBoosters.active?.[def.id] || 0);
      const base = current > now ? current : now;
      userBoosters.active ??= {};
      userBoosters.active[def.id] = base + Math.max(1, Number(def.durationSec) || 0) * 1000 * stock;
      counts[stockKey] = 0;
    }
  }
  const signature = boosterActiveSignature();
  if (signature !== boosterPrevSignature) {
    const prev = boosterPrevSignature;
    boosterPrevSignature = signature;
    if (prev !== "") {
      // Activation ou expiration : on recalcule les max (bouclier/coque)
      // en gardant les valeurs absolues, on annonce les fins, on sauvegarde.
      try { applyCurrentConfigStats(false, null, true); } catch {}
      const prevStates = prev.split("|");
      const nextStates = signature.split("|");
      if (prevStates.length === nextStates.length) {
        BOOSTERS.forEach((b, i) => {
          const wasActive = (prevStates[i] || "").startsWith("1:");
          const isActive = (nextStates[i] || "").startsWith("1:");
          if (wasActive && !isActive) showToast(`Booster ${b.name} terminé`, 2.2);
          if (!wasActive && isActive) showToast(`Booster ${b.name} activé`, 2.2);
        });
      }
      markProgressDirty();
      saveProgressNow();
      renderBoosterWindow();
    }
  }
  // Compte à rebours de la fenêtre (1 s).
  boosterWindowRefreshT += dt;
  if (boosterWindowRefreshT >= 1) {
    boosterWindowRefreshT = 0;
    refreshBoosterCountdowns();
  }
}

// Dessiné par-dessus le vaisseau ET toute autre effet de vaisseau.
function drawInstaShield() {
  if (instaShieldT < 0 || !instaShieldReady || !instaShieldImgs?.length) return;

  const frames = INSTA_SHIELD_PACK.frames || instaShieldImgs.length;
  const idx = Math.min(frames - 1, Math.floor((instaShieldT / INSTA_SHIELD_PACK.dur) * frames));
  const img = instaShieldImgs[idx];
  if (!isImgReady(img)) return;

  const w = INSTA_SHIELD_PACK.w;
  const h = INSTA_SHIELD_PACK.h;

ctx.save();
    ctx.imageSmoothingEnabled = false;
    ctx.imageSmoothingQuality = "low";
    ctx.globalAlpha = 1;
    ctx.drawImage(img, -w / 2, -h / 2, w, h);
    ctx.restore();
}

// ============================================================
// ✅ SHIELD SHIMMER - halo de bouclier officiel rejoué par-dessus
// le vaisseau à intervalle aléatoire (1 à 10 s) tant que la config
// active a du bouclier, avec le son shieldSelected.
// ============================================================
const SHIELD_SHIMMER_PACK = {
  path: "ASSETS/SHIELD_SHIMMER/",
  frames: 33,
  firstNumber: 1,
  ext: ".png",
  fps: 24,
};

let shieldShimmerImgs = [];
let shieldShimmerReady = false;
let shieldShimmerT = -1; // progression de l'anim (-1 = inactif)
let shieldShimmerNext = 10 + Math.random() * 20; // délai avant le prochain jeu (s)
let shieldShimmerCfg = null; // config suivie (détecte le changement)

function ensureShieldShimmerLoaded() {
  if (SHIELD_SHIMMER_PACK._promise) return SHIELD_SHIMMER_PACK._promise;

  SHIELD_SHIMMER_PACK._imgs = new Array(SHIELD_SHIMMER_PACK.frames);

  SHIELD_SHIMMER_PACK._promise = (async () => {
    const jobs = [];
    for (let i = 0; i < SHIELD_SHIMMER_PACK.frames; i++) {
      const src = `${SHIELD_SHIMMER_PACK.path}${SHIELD_SHIMMER_PACK.firstNumber + i}${SHIELD_SHIMMER_PACK.ext}`;
      jobs.push(
        loadImage(src, { priority: false })
          .then((img) => (SHIELD_SHIMMER_PACK._imgs[i] = img))
          .catch(() => (SHIELD_SHIMMER_PACK._imgs[i] = null))
      );
    }
    await Promise.all(jobs);
    shieldShimmerImgs = SHIELD_SHIMMER_PACK._imgs;
    shieldShimmerReady = true;
  })();

  return SHIELD_SHIMMER_PACK._promise;
}

function tickShieldShimmer(dt) {
  if (!started || player.dead) {
    shieldShimmerT = -1;
    return;
  }
  // Une anim déjà lancée va toujours au bout (combat compris, Sentinel la
  // relance chaque seconde) : la geler laissait le sprite figé sur le
  // vaisseau dès qu'un NPC touchait pendant le shimmer.
  if (shieldShimmerT >= 0) {
    shieldShimmerT += dt;
    if (shieldShimmerT >= SHIELD_SHIMMER_PACK.frames / SHIELD_SHIMMER_PACK.fps) shieldShimmerT = -1;
    return;
  }
  // En combat, seul le délai avant le prochain shimmer est gelé.
  if ((Number(player.combatT) || 0) > 0 || attackActive === true) return;
  const cfg = getActiveConfigNo();
  if (cfg !== shieldShimmerCfg) {
    // Changement de config : on repart vite si la nouvelle a du bouclier.
    shieldShimmerCfg = cfg;
    shieldShimmerT = -1;
    shieldShimmerNext = 1 + Math.random() * 2;
  }
  const hasShield = (player.shMax > 0) && (player.sh > 0);
  if (!hasShield) {
    // Plus de bouclier : pause. Au retour du bouclier, ça rejoue
    // dans un délai frais de 10 à 30 s.
    shieldShimmerT = -1;
    shieldShimmerNext = 10 + Math.random() * 20;
    return;
  }
  shieldShimmerNext -= dt;
  if (shieldShimmerNext <= 0) {
    shieldShimmerT = 0;
    shieldShimmerNext = 10 + Math.random() * 20;
    ensureShieldShimmerLoaded();
    SFX.play("shieldShimmer");
  }
}

// Dessiné par-dessus le vaisseau quand l'anim est en cours,
// avec fondu d'apparition / disparition.
function drawShieldShimmer() {
  if (shieldShimmerT < 0 || !shieldShimmerReady || !shieldShimmerImgs?.length) return;

  const frames = SHIELD_SHIMMER_PACK.frames || shieldShimmerImgs.length;
  const idx = Math.min(frames - 1, Math.floor(shieldShimmerT * SHIELD_SHIMMER_PACK.fps));
  const img = shieldShimmerImgs[idx];
  if (!isImgReady(img)) return;

  const pack = ACTIVE_SHIP || SHIP_PACKS[0];
  const size = Math.max(pack?.w ?? 170, pack?.h ?? 170) + 30;
  const dur = frames / SHIELD_SHIMMER_PACK.fps;
  const fade = 0.3;
  const alpha = clamp(Math.min(shieldShimmerT / fade, (dur - shieldShimmerT) / fade), 0, 1);

  ctx.save();
  ctx.imageSmoothingEnabled = false;
  ctx.globalAlpha = alpha;
  ctx.drawImage(img, -size / 2, -size / 2, size, size);
  ctx.restore();
}

// ============================================================
// ✅ REPAIR ORBIT FX - sprite qui tourne autour du vaisseau
// ============================================================
const DEFAULT_REPAIR_ORBIT_SPR = {
path: "ASSETS/REPAIR_ROBOT/",
frames: 10,
firstNumber: 1,
ext: ".png",
fps: 30,

w: 56,
h: 42,
scale: 1,

// ✅ position fixe par rapport au vaisseau
// négatif en X = gauche
// négatif en Y = haut
xOff: -65,
yOff: -65,

// ✅ plus de rotation autour du vaisseau
radius: 0,
orbitSpeed: 0,
spinSpeed: 0,

alpha: 1,
};

const REPAIR_ORBIT_PACK = {
  ...DEFAULT_REPAIR_ORBIT_SPR,
  ...(REPAIR_ORBIT_SPR || {}),
};

let repairOrbitImgs = [];
let repairOrbitReady = false;

const repairOrbitFx = {
  t: 0,
  alpha: 0,
  fx: 1,
  fy: 1,
  x: -65,
  y: -65,
  tx: -65,
  ty: -65,
  rot: 0,
  tRot: 0,
  cornerT: 0,
  prevActive: false,
};

function getRepairOrbitFrameSrc(pack, index) {
  if (!pack) return null;

  if (pack.src) return pack.src;

  const first = Number(pack.firstNumber ?? 1);
  const ext = pack.ext || ".png";
  const n = first + index;

  return `${pack.path}${n}${ext}`;
}

function ensureRepairOrbitLoaded() {
  if (REPAIR_ORBIT_PACK._promise) return REPAIR_ORBIT_PACK._promise;

  const frames = Math.max(1, Number(REPAIR_ORBIT_PACK.frames || 1));
  REPAIR_ORBIT_PACK._imgs = new Array(frames);

  REPAIR_ORBIT_PACK._promise = (async () => {
    const jobs = [];

    for (let i = 0; i < frames; i++) {
      const src = getRepairOrbitFrameSrc(REPAIR_ORBIT_PACK, i);
      if (!src) continue;

      jobs.push(
        loadImage(src, { priority: false })
          .then((img) => (REPAIR_ORBIT_PACK._imgs[i] = img))
          .catch(() => (REPAIR_ORBIT_PACK._imgs[i] = null))
      );
    }

    await Promise.all(jobs);

    repairOrbitImgs = REPAIR_ORBIT_PACK._imgs;
    repairOrbitReady = true;

    return true;
  })();

  return REPAIR_ORBIT_PACK._promise;
}

function isRepairingNow() {
  if (!started || player.dead || player.repairJumpLock) return false;
  if (player.repairT < REPAIR.cooldown) return false;

  const needHp = player.hp < player.hpMax - 0.5;

  return needHp;
}

// Rotation du robot selon son coin (référence) :
// haut gauche = 0°, haut droite = 90° (droite), bas gauche = -90° (gauche), bas droite = 180°.
function repairOrbitCornerRot(fx = repairOrbitFx.fx, fy = repairOrbitFx.fy) {
  if (fx === -1 && fy === 1) return Math.PI / 2;
  if (fx === 1 && fy === -1) return -Math.PI / 2;
  if (fx === -1 && fy === -1) return Math.PI;
  return 0;
}

function tickRepairOrbitFx(dt) {
  const active = isRepairingNow();

  if (active) {
    repairOrbitFx.t += dt;
    repairOrbitFx.alpha = Math.min(1, repairOrbitFx.alpha + dt * 5);

    // Repioche un coin toutes les 1 s (peut être le même ou un autre).
    if (!repairOrbitFx.prevActive || repairOrbitFx.cornerT >= 1) {
      repairOrbitFx.cornerT = 0;
      repairOrbitFx.fx = Math.random() < 0.5 ? -1 : 1;
      repairOrbitFx.fy = Math.random() < 0.5 ? -1 : 1;
      const px = Number(REPAIR_ORBIT_PACK.xOff ?? -45);
      const py = Number(REPAIR_ORBIT_PACK.yOff ?? -45);
      repairOrbitFx.tx = px * repairOrbitFx.fx;
      repairOrbitFx.ty = py * repairOrbitFx.fy;
      repairOrbitFx.tRot = repairOrbitCornerRot(repairOrbitFx.fx, repairOrbitFx.fy);
    }
    repairOrbitFx.cornerT += dt;

    // Lissage vers la cible : mouvement visible, sans cassure.
    const k = 1 - Math.pow(0.0001, dt);
    repairOrbitFx.x += (repairOrbitFx.tx - repairOrbitFx.x) * k;
    repairOrbitFx.y += (repairOrbitFx.ty - repairOrbitFx.y) * k;
    let dRot = repairOrbitFx.tRot - repairOrbitFx.rot;
    dRot = Math.atan2(Math.sin(dRot), Math.cos(dRot));
    repairOrbitFx.rot += dRot * k;
  } else {
    repairOrbitFx.alpha = Math.max(0, repairOrbitFx.alpha - dt * 8);
    repairOrbitFx.cornerT = 0;

    if (repairOrbitFx.alpha <= 0) {
      repairOrbitFx.t = 0;
    }
  }

  repairOrbitFx.prevActive = active;
}

function drawRepairOrbitFxLocal() {
  if (!repairOrbitReady || !repairOrbitImgs?.length) return;
  if (repairOrbitFx.alpha <= 0.01) return;

  const pack = REPAIR_ORBIT_PACK;

  const frames = Math.max(1, Number(pack.frames || repairOrbitImgs.length || 1));
  const fps = Math.max(1, Number(pack.fps || 30));

  const idx = Math.floor(repairOrbitFx.t * fps) % frames;
  const img = repairOrbitImgs[idx];

  if (!isImgReady(img)) return;

const x = repairOrbitFx.x;
const y = repairOrbitFx.y;

const spinSpeed = Number(pack.spinSpeed ?? 0);

const w = (pack.w || img.naturalWidth || img.width || 96) * (pack.scale || 1);
const h = (pack.h || img.naturalHeight || img.height || 96) * (pack.scale || 1);

ctx.save();
ctx.translate(x, y);

// ✅ rotation selon le coin (lissée) + rotation optionnelle du sprite sur lui-même
ctx.rotate(repairOrbitFx.rot);

// ✅ rotation optionnelle du sprite sur lui-même
if (spinSpeed !== 0) {
  ctx.rotate(repairOrbitFx.t * TAU * spinSpeed);
}

  ctx.imageSmoothingEnabled = false;
  ctx.imageSmoothingQuality = "low";

  ctx.globalAlpha *= repairOrbitFx.alpha * Number(pack.alpha ?? 1);

  drawCenteredImage(ctx, img, w, h);

  ctx.restore();
}

// ✅ Éclair vert venant uniquement du coin où se trouve le robot, en direction du vaisseau.
function drawRepairBolts() {
  if (repairOrbitFx.alpha <= 0.01) return;

  const pack = REPAIR_ORBIT_PACK;
  const cx = repairOrbitFx.x;
  const cy = repairOrbitFx.y;

  const t = performance.now() / 1000;
  const alpha = repairOrbitFx.alpha * Number(pack.alpha ?? 1);

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.strokeStyle = "rgba(80,255,140,0.9)";
  ctx.lineWidth = 2;
  ctx.lineCap = "round";
  ctx.shadowColor = "rgba(80,255,140,0.95)";
  ctx.shadowBlur = 10;

  const tx = 0;
  const ty = 0;
  const segs = 5;

  ctx.beginPath();
  ctx.moveTo(cx, cy);
  for (let i = 1; i < segs; i++) {
    const f = i / segs;
    const ix = cx + (tx - cx) * f;
    const iy = cy + (ty - cy) * f;
    const jx = (
      Math.sin(t * 46 + i * 9.3 + cx * 0.35) * 0.5 +
      Math.sin(t * 71 + i * 5.1 + cy * 0.29) * 0.5
    ) * 12 * f;
    const jy = (
      Math.cos(t * 42 + i * 7.7 + cy * 0.31) * 0.5 +
      Math.cos(t * 64 + i * 11.3 + cx * 0.27) * 0.5
    ) * 12 * f;
    ctx.lineTo(ix + jx, iy + jy);
  }
  ctx.lineTo(tx, ty);
  ctx.stroke();

  ctx.restore();
}

// ============================================================
// ✅ EXPLOSION FX (sprites) — mort NPC = HIT_NPC (FLV 300x300 12fps)
// ============================================================
const EXPLOSION_PACK = {
  path: "COMBAT/EXPLOSIONS/HIT_NPC/",
  frames: 40,
  firstNumber: 1,
  ext: ".png",
  fps: 40,
  w: 300,
  h: 300,
};

// ✅ impacts laser : aucun sprite, aucun rond jaune (rien affiché).
// ✅ impacts roquette : mini explosion HIT_NPC (voir spawnExplosion aux hits).

let explosionImgs = [];
let explosionReady = false;

function ensureExplosionLoaded() {
  if (EXPLOSION_PACK._promise) return EXPLOSION_PACK._promise;

  EXPLOSION_PACK._imgs = new Array(EXPLOSION_PACK.frames);

  EXPLOSION_PACK._promise = (async () => {
    const jobs = [];
    for (let i = 0; i < EXPLOSION_PACK.frames; i++) {
      const src = `${EXPLOSION_PACK.path}${EXPLOSION_PACK.firstNumber + i}${EXPLOSION_PACK.ext}`;
      jobs.push(
        loadImage(src, { priority: false })
          .then((img) => (EXPLOSION_PACK._imgs[i] = img))
          .catch(() => (EXPLOSION_PACK._imgs[i] = null))
      );
    }
    await Promise.all(jobs);

    explosionImgs = EXPLOSION_PACK._imgs;
    explosionReady = true;
    return true;
  })();

  return EXPLOSION_PACK._promise;
}

const explosions = [];

function spawnExplosion(x, y, scale = 1, kind = "npc") {
  if (!explosionReady || !explosionImgs || !explosionImgs.length) {
    return;
  }
  // Densité Off : aucune explosion (même joueur).
  if (fxDensityMult() === 0) return;
  // Options perf (Général) : explosions NPC et mini-explosions roquettes coupables séparément.
  try {
    if (kind === "rocket" && GAME_SETTINGS.rocketSmoke === false) return;
    if (kind === "npc" && GAME_SETTINGS.npcExplosions === false) return;
  } catch {}

  pushBounded(explosions, {
    x,
    y,
    t: 0,
    scale: Math.max(0.2, Number(scale) || 1),
    kind: kind === "rocket" ? "rocket" : kind === "player" ? "player" : "npc",
  }, fxDensityCap(ENTITY_LIMITS.explosions));
}

// Capteurs 1800 (même règle que les NPC) : tout effet visuel au-delà du rayon
// est ignoré (explosions, tirs distants, FX, étincelles, chiffres).
// Infinity en gates/raid = aucun culling. Le joueur local et ses tirs
// restent à plein régime (pas de filtre de ce côté).
function isBeyondSensorRadius(wx, wy, margin = 0) {
  try {
    const visR = Number(NPC_SENSOR_RANGES?.visibility);
    if (!Number.isFinite(visR)) return false;
    const dx = Number(wx) - Number(player.x);
    const dy = Number(wy) - Number(player.y);
    const r = visR + Math.max(0, Number(margin) || 0);
    return dx * dx + dy * dy > r * r;
  } catch { return false; }
}

function tickExplosions(dt) {
  if (!explosions.length) return;

  const fps = EXPLOSION_PACK.fps || 30;
  const frames = EXPLOSION_PACK.frames || explosionImgs.length || 1;
  const dur = frames / fps;

  for (let i = explosions.length - 1; i >= 0; i--) {
    const ex = explosions[i];
    ex.t += dt;
    if (ex.t >= dur) explosions.splice(i, 1);
  }
}

function drawExplosions(ox, oy) {
  if (!explosionReady || !explosionImgs || !explosionImgs.length) return;

  const fps = EXPLOSION_PACK.fps || 30;
  const frames = EXPLOSION_PACK.frames || explosionImgs.length || 1;

  for (const ex of explosions) {
    try {
      if (ex.kind === "rocket" && GAME_SETTINGS.rocketSmoke === false) continue;
      if (ex.kind === "npc" && GAME_SETTINGS.npcExplosions === false) continue;
    } catch {}
    if (isBeyondSensorRadius(ex.x, ex.y)) continue;
    const idx = Math.min(frames - 1, Math.floor(ex.t * fps));
    const img = explosionImgs[idx];
    if (!isImgReady(img)) continue;

    const x = ex.x + ox;
    const y = ex.y + oy;

    const w = (EXPLOSION_PACK.w || (img.naturalWidth || img.width || 128)) * ex.scale;
    const h = (EXPLOSION_PACK.h || (img.naturalHeight || img.height || 128)) * ex.scale;

    if (x + w / 2 < 0 || y + h / 2 < 0 || x - w / 2 > innerWidth || y - h / 2 > innerHeight) continue;

    ctx.save();
    ctx.imageSmoothingEnabled = false;
    ctx.imageSmoothingQuality = "low";
    ctx.globalAlpha = 1;
    ctx.drawImage(img, x - w / 2, y - h / 2, w, h);
    ctx.restore();
  }
}

// ============================================================
// ✅ SHIP_DAMAGE FX (sprite, 1x par tir reçu)
// ============================================================
const SHIP_DAMAGE_PACK = {
  path: "ASSETS/SHIP_DAMAGE/",
  frames: 9,
  firstNumber: 1,
  ext: ".png",
  fps: 30,
  w: 320,
  h: 320,
  scale: 1,
};

let shipDamageImgs = [];
let shipDamageReady = false;

function ensureShipDamageLoaded() {
  if (SHIP_DAMAGE_PACK._promise) return SHIP_DAMAGE_PACK._promise;

  SHIP_DAMAGE_PACK._imgs = new Array(SHIP_DAMAGE_PACK.frames);

  SHIP_DAMAGE_PACK._promise = (async () => {
    const jobs = [];
    for (let i = 0; i < SHIP_DAMAGE_PACK.frames; i++) {
      const src = `${SHIP_DAMAGE_PACK.path}${SHIP_DAMAGE_PACK.firstNumber + i}${SHIP_DAMAGE_PACK.ext}`;
      jobs.push(
        loadImage(src, { priority: false })
          .then((img) => (SHIP_DAMAGE_PACK._imgs[i] = img))
          .catch(() => (SHIP_DAMAGE_PACK._imgs[i] = null))
      );
    }
    await Promise.all(jobs);

    shipDamageImgs = SHIP_DAMAGE_PACK._imgs;
    shipDamageReady = true;
    return true;
  })();

  return SHIP_DAMAGE_PACK._promise;
}

const shipDamages = [];

// ✅ rayon du rond calculé automatiquement d'après la taille du sprite du
// vaisseau : grande dimension (w ou h) / 6.
function shipDamageBubbleRadius() {
  const pack = ACTIVE_SHIP || SHIP_PACKS[0];
  const w = Number(pack?.w) || 170;
  const h = Number(pack?.h) || 170;
  return Math.max(w, h) / 6;
}

// ✅ le sprite est posé sur la ligne du rond (bord du cercle), à l'angle du
// tir qui arrive, et orienté "face au tir" (vers le NPC qui nous a touchés).
// Il est ancré au vaisseau : pendant l'animation il reste donc toujours
// sur le cercle, même si le joueur continue d'avancer.
function spawnShipDamage(fromX, fromY) {
  if (!shipDamageReady || !shipDamageImgs || !shipDamageImgs.length) return;
  // Densité Off : aucun anneau de dégâts.
  if (fxDensityMult() === 0) return;
  // Option "Explosions et impacts" : aucun spawn quand coupée.
  try { if (GAME_SETTINGS.npcExplosions === false) return; } catch {}

  const ang = Math.atan2(fromY - player.y, fromX - player.x);
  const rad = shipDamageBubbleRadius();

  pushBounded(shipDamages, {
    ang,
    rad,
    rot: ang,
    t: 0,
    scale: Number(SHIP_DAMAGE_PACK.scale) || 0.4,
  }, fxDensityCap(ENTITY_LIMITS.explosions));
}

function tickShipDamages(dt) {
  if (!shipDamages.length) return;

  const fps = SHIP_DAMAGE_PACK.fps || 30;
  const frames = SHIP_DAMAGE_PACK.frames || shipDamageImgs.length || 1;
  const dur = frames / fps;

  for (let i = shipDamages.length - 1; i >= 0; i--) {
    const sd = shipDamages[i];
    sd.t += dt;
    if (sd.t >= dur) shipDamages.splice(i, 1);
  }
}

function drawShipDamages(ox, oy) {
  if (!shipDamageReady || !shipDamageImgs || !shipDamageImgs.length) return;

  const fps = SHIP_DAMAGE_PACK.fps || 30;
  const frames = SHIP_DAMAGE_PACK.frames || shipDamageImgs.length || 1;

  for (const sd of shipDamages) {
    const idx = Math.min(frames - 1, Math.floor(sd.t * fps));
    const img = shipDamageImgs[idx];
    if (!isImgReady(img)) continue;

    // ✅ recalculé à chaque frame sur le cercle AUTOUR DU VAISSEAU :
    // le sprite suit le joueur qui avance au lieu de rester en place.
    const x = player.x + Math.cos(sd.ang) * sd.rad + ox;
    const y = player.y + Math.sin(sd.ang) * sd.rad + oy;

    const w = (SHIP_DAMAGE_PACK.w || (img.naturalWidth || img.width || 128)) * sd.scale;
    const h = (SHIP_DAMAGE_PACK.h || (img.naturalHeight || img.height || 128)) * sd.scale;

    if (x + w / 2 < 0 || y + h / 2 < 0 || x - w / 2 > innerWidth || y - h / 2 > innerHeight) continue;

    ctx.save();
    ctx.imageSmoothingEnabled = false;
    ctx.imageSmoothingQuality = "low";
    // ✅ rotation libre sur 360° : le sprite pointe "à droite" (angle 0) par
    // défaut ; on le pivote vers l'angle du tir reçu pour qu'il fasse face.
    ctx.translate(x, y);
    ctx.rotate(sd.rot || 0);
    ctx.globalAlpha = 1;
    ctx.drawImage(img, -w / 2, -h / 2, w, h);
    ctx.restore();
  }
}

