function getShipPackById(shipId) {
  return getShipPackByIdData(shipId) || SHIP_PACKS[0];
}

function getActiveHangarFromUser(u) {
  const hs = Array.isArray(u?.hangars) ? u.hangars : [];
  return hs.find(h => h?.active) || hs[0] || null;
}

function normalizeFit(fit, pack) {
  const slots = pack?.slots || { lasers: 15, gens: 15, extras: 15 };
  const L = Math.max(0, Number(slots.lasers || 0));
  const G = Math.max(0, Number(slots.gens || 0));
  const E = Math.max(0, Number(slots.extras || 0));

  const base = fit || {};
  const lasers = (Array.isArray(base.lasers) ? base.lasers : []).slice(0, L);
  const gens = (Array.isArray(base.gens) ? base.gens : []).slice(0, G);
  const extras = (Array.isArray(base.extras) ? base.extras : []).slice(0, E);

  while (lasers.length < L) lasers.push(null);
  while (gens.length < G) gens.push(null);
  while (extras.length < E) extras.push(null);

  return { lasers, gens, extras, slots: { lasers: L, gens: G, extras: E } };
}

function resetPlayerToBase() {
  player.dead = false;
  player.iFrames = 1.0;

  const u = loadAccountUser();
  const shipId = (u?.ship || ACTIVE_SHIP?.id || "PhoenixBleu");

  const pack = getShipPackById(shipId);
  ACTIVE_SHIP = pack;
  if (String(getShipDesignBaseId(pack?.id) || pack?.id).toLowerCase() === "hyperion") preloadGravityAnchorImages();

  const hangar = u ? getActiveHangarFromUser(u) : null;
  const fitNorm = normalizeFit(hangar?.fit, pack);

  const stats = computeHangarStats(hangar, u, { mapId: currentMapId() });

  player.dr = BASE_RUN.dr;
  player.shPen = BASE_RUN.shPen + ((stats.bonusPenetrationPct || 0) / 100);

  const isPoliceHull = String(getShipDesignBaseId(pack?.id) || pack?.id || "").toLowerCase() === "police";
  const shipBaseHP = Number(pack?.hp || 1) + (isPoliceHull ? 0 : 100_000);

  // ✅ Aucun soin au changement de carte/portail/URL : on garde le même
  // pourcentage de vie et de bouclier. Seul le robot réparateur régénère.
  // (Au boot : hpMax=0 → ratio 1 → vie pleine. Après une mort : hp=0 → 1 PV,
  // puis l'override de résurrection applique sa pénalité de 10 %.)
  const oldHpPct = player.hpMax > 0 ? clamp(player.hp / player.hpMax, 0, 1) : 1;
  const oldShPct = player.shMax > 0 ? clamp(player.sh / player.shMax, 0, 1) : 1;

  player.hpMax = Math.max(1, Math.floor((shipBaseHP + (stats.bonusFlatHP || 0) + playerPilotMults().hpFlat) * (1 + (stats.bonusHPPct || 0) / 100) * playerBoosterMults().hp));
  player.hp = Math.max(1, Math.floor(player.hpMax * oldHpPct));
  refreshBuoyHpBase();

  player.shMax = Math.max(0, Math.floor((Number(stats.bonusShield) || 0) * playerBoosterMults().shield * playerPilotMults().shield * playerUpgradeMults().shield));
  player.sh = Math.max(0, Math.floor(player.shMax * oldShPct));
  player.shAbsorb = clamp(
    (Number(stats.bonusAbsorb) > 0 ? Number(stats.bonusAbsorb) / 100 : 0.8)
      + Number(stats.formationEffects?.shieldAbsorptionPct || 0) / 100,
    0,
    1,
  );
  player.laserMods = Array.isArray(stats.laserMods) ? stats.laserMods : [];
  player.droneLaserMods = Array.isArray(stats.droneLaserMods) ? stats.droneLaserMods : [];
  let oslCount = 0;
  for (const m of player.laserMods) if (Number(m?.critPct || 0) > 0) oslCount += 1;
  player.critChance = oslCount > 0 ? Math.min(0.50, 0.05 + (3 * oslCount) / 100) : 0.05;
  player.critMult = oslCount > 0 ? 2.0 : 1.5;

  player.baseDamage = Math.max(1, Math.floor(stats.totalLaserDamage || 1));
  player.baseDamageNoLeonov = Math.max(1, Math.floor(stats.totalLaserDamageNoLeonov ?? stats.totalLaserDamage ?? 1));
  // Modules roulette dégâts ciblés (appliqués au tir, pas dans la base).
  player.bonusNpcDmgPct = Number(stats.bonusNpcDmgPct || 0);
  player.bonusPvpDmgPct = Number(stats.bonusPvpDmgPct || 0);
  player.bonusRocketDmgPct = Number(stats.bonusRocketDmgPct || 0);

  player.laserHitBonusPct = clamp(Number(stats.bonusLaserHitPct || 0), -100, 100);
  player.rocketHitBonusPct = clamp(Number(stats.bonusRocketHitPct || 0), -100, 100);
  player.evasionBonusPct = clamp(Number(stats.bonusEvasionPct || 0), -100, 90);
  player.droneCooldownReductionPct = Number(stats.bonusAbilityCooldownPct || 0);
  player.droneDamageBonusPct = Number(stats.droneDesignEffects?.damagePct || 0);
  player.expBonusPct = Number(stats.bonusExpPct || 0);
  player.honorBonusPct = Number(stats.bonusHonorPct || 0);

  player.baseFireRate = BASE_RUN.baseFireRate;
  player.baseBulletSpeed = BASE_RUN.baseBulletSpeed * formationBulletSpeedMult();
  player.fireRateMult = BASE_RUN.fireRateMult * formationFireRateMult();
  player.laserDmgMult = BASE_RUN.laserDmgMult;

  const shipBaseSpeed = Number(pack?.speed || 0);
  player.baseSpeed = Math.max(10, Math.floor((shipBaseSpeed + (stats.bonusSpeed || 0)) * playerUpgradeMults().speed * (stats.speedMult || 1)));

player.accel = BASE_RUN.accel;
player.friction = BASE_RUN.friction;

  if (!player.repairColdStart) {
    player.repairT = REPAIR.cooldown;
  }
  player.repairTickT = 0;
  player.altShot = false;

  // ✅ Crédits / munitions / roquettes : restaurés depuis le compte,
  // JAMAIS depuis des valeurs par défaut. Avant, player contenait 10M +
  // kit de base entre ce reset et le restore suivant : un save parti dans
  // cette fenêtre écrasait la vraie progression (cas constaté en multi).
  restorePlayerStockFromUser(u);
  playerRange = BASE_RUN.range;
  // Stockpile : hors Hecate Plus on purge charges + effet, sinon on
  // réapplique le bonus de portée des charges conservées.
  try {
    if (!isHecatePlusBase()) {
      player.stockCharges = 0;
      player.stockT = 0;
      player.stockShieldPct = 0;
    } else {
      stockUpdateRange();
    }
  } catch {}

  player.kills = BASE_RUN.kills;
  player.vx = 0;
  player.vy = 0;

  updateAmmoUI();
}

// Source unique des stocks : le compte. Sans compte (cas limite), on garde
// l'état mémoire tel quel — jamais de valeurs inventées persistables.
function restorePlayerStockFromUser(u) {
  if (!u) return false;
  player.credits = Math.max(0, Math.floor(Number(u.credits) || 0));
  const a = (u.ammo && typeof u.ammo === "object") ? u.ammo : {};
  player.ammo = {
    active: player.ammo.active || "x1",
    x1: Infinity,
    x2: Math.max(0, Number(a.x2 || 0)),
    x3: Math.max(0, Number(a.x3 || 0)),
    x4: Math.max(0, Number(a.x4 || 0)),
    sab: Math.max(0, Number(a.sab || 0)),
    x6: Math.max(0, Number(a.x6 || 0)),
    rcb: Math.max(0, Number(a.rcb || 0)),
    cbo: Math.max(0, Number(a.cbo || 0)),
    job: Math.max(0, Number(a.job || 0)),
    rb: Math.max(0, Number(a.rb || 0)),
    pib: Math.max(0, Number(a.pib || 0)),
    idb: Math.max(0, Number(a.idb || 0)),
    vb: Math.max(0, Number(a.vb || 0)),
    emaa: Math.max(0, Number(a.emaa || 0)),
    sbl: Math.max(0, Number(a.sbl || 0)),
    abl: Math.max(0, Number(a.abl || 0)),
    tent: Math.max(0, Number(a.tent || 0)),
    ice: Math.max(0, Number(a.ice || 0)),
  };
  const rk0 = (u.rockets && typeof u.rockets === "object") ? u.rockets : {};
  player.rockets = Object.fromEntries(ROCKET_IDS.map((id) => [id, Math.max(0, Math.floor(Number(rk0[id] || 0)))]));
  player.rocketActive = ROCKET_TYPES[String(u.rocketActive || "").toLowerCase()] ? String(u.rocketActive).toLowerCase() : "r310";
  player.rocketAuto = (typeof GAME_SETTINGS !== "undefined" && GAME_SETTINGS.phoneMode === true) || u.rocketAuto === true;
  player.launcherActive = ROCKET_TYPES[String(u.launcherActive || "").toLowerCase()] ? String(u.launcherActive).toLowerCase() : "eco10";
  player.launcherAuto = (typeof GAME_SETTINGS !== "undefined" && GAME_SETTINGS.phoneMode === true) || u.launcherAuto === true;
  rocketCooldown = 0;
  launcherReloadT = 0;
  launcherFullT = 0;
  launcherPhase = "reload";
  launcherPhaseT = 0;
  // Restaure la munition du dock rapide (sinon retour x1).
  // Lecture du compte : aucune sauvegarde avant la restauration de position.
  setAmmo(String(u.ammoActive ?? u.ammo?.active ?? player.ammo.active ?? "x1").toLowerCase(), { persist: false });
  updateAmmoUI();
  return true;
}

function ammoCount(key) {
  return key === "x1" ? Infinity : player.ammo[key] || 0;
}

// Repercute immediatement une consommation dans l'objet canonique local sans
// declencher un POST par tir. Ainsi, une sauvegarde de position ou un achat
// ne peut plus relire l'ancien stock et le remettre dans le vaisseau.
function mirrorConsumedStock(field, id, value) {
  try {
    const key = String(id || "").toLowerCase();
    const amount = Math.max(0, Math.floor(Number(value) || 0));
    const current = getCurrentUserFull();
    if (current) {
      current[field] ||= {};
      current[field][key] = amount;
    }
    if (account.user) {
      account.user[field] ||= {};
      account.user[field][key] = amount;
    }
  } catch {}
}

function setAmmo(key, { persist = true } = {}) {
  if (!AMMO[key]) return;
  if (key !== "x1" && ammoCount(key) <= 0) key = "x1";
  // Déjà actif : rien à faire (anti-spam : évite persist + UI à chaque frame
  // quand le bot redemande la munition courante).
  if (player.ammo.active === key) return;
  player.ammo.active = key;
  if (persist) {
    // Persiste les choix du joueur, jamais une simple restauration du compte.
    markProgressDirty();
    // Écriture immédiate de la sélection dans le compte : sans ça, un sync
    // (boutique, craft, enchères, net-adopted...) relit l'ancien ammoActive
    // persisté et réécrit l'ancienne munition par-dessus (ex. x4 → retour x3).
    // updateCurrentUserProgress ne touche qu'ammoActive et publie en
    // source "progress" (ignorée par le listener orbit:user-updated) : pas de
    // boucle de resync.
    try {
      const out = updateCurrentUserProgress({ ammoActive: key });
      if (out?.ok && out.user && account) account.user = out.user;
    } catch {}
  }
  updateAmmoUI();
}

// Anti-spam de la notification de bascule X1 (une par épuisement).
let ammoFallbackNotifiedKey = "";
let ammoFallbackNotifiedAt = 0;

function consumeAmmo(shots) {
  const k = player.ammo.active;
  if (k === "x1") return;
  const before = Math.max(0, Number(player.ammo[k]) || 0);
  player.ammo[k] = Math.max(0, before - shots);
  noteNetConsumption("ammo", k, before - player.ammo[k]);
  mirrorConsumedStock("ammo", k, player.ammo[k]);
  if (player.ammo[k] <= 0 && player.ammo.active !== "x1") {
    player.ammo.active = "x1";
    // Bascule visible : une seule notification par épuisement (pas de spam,
    // même pattern que les roquettes). Throttle si le stock oscille à 0.
    try {
      const now = Date.now();
      if (ammoFallbackNotifiedKey !== k || now - ammoFallbackNotifiedAt > 8000) {
        ammoFallbackNotifiedKey = k;
        ammoFallbackNotifiedAt = now;
        showNotification(`Plus de ${BOT_AMMO_NAMES[k] || String(k).toUpperCase()} — retour X1.`, 2.5, "info");
      }
    } catch {}
    // Bascule persistée (événement rare : une seule fois par épuisement) :
    // sinon le stockage garde l'ancienne munition et le prochain sync y revient.
    try {
      const out = updateCurrentUserProgress({ ammoActive: "x1" });
      if (out?.ok && out.user && account) account.user = out.user;
    } catch {}
  }
  // Persiste la consommation (sinon un save entre deux syncs
  // réécrivait l'ancien stock et les tirs semblaient "annulés").
  try { markProgressDirty(); } catch {}
  updateAmmoUI();
}

function formatAmmoCount(value) {
  if (value === Infinity || value === "Infinity" || value === "∞") {
    return "∞";
  }

  const n = Math.max(0, Math.floor(Number(value) || 0));

  return String(Math.min(n, 999999));
}

function formatRocketCount(value) {
  const n = Math.max(0, Math.floor(Number(value) || 0));

  return String(Math.min(n, 999999));
}

// Dernier état des carrés AUTO affiché : le refresh ne les retouche que si
// le stock change (laisse jouer la charge après un changement de munition).
let launcherSquaresShown = -1;

// Rafraîchit les boutons roquettes de la palette et des slots (compte + actif).
function refreshRocketPaletteCounts() {
  // Init du jeu : player n'existe pas encore (déclaré plus bas) → on saute.
  try { void player.rockets; } catch { return; }
  const bar = document.getElementById("ammoBar");
  if (!bar) return;
  const activeStd = `rocket:${String(player.rocketActive || "r310").toLowerCase()}`;
  const activeLauncher = `rocket:${String(player.launcherActive || "eco10").toLowerCase()}`;
  for (const el of bar.querySelectorAll('[data-action-id^="rocket:"]')) {
    const id = String(el.dataset.actionId || "").slice("rocket:".length);
    const count = el.querySelector(".rocketCount");
    if (count) count.textContent = formatRocketCount(rocketCount(id));
    const isLauncher = getRocketType(id)?.manual === false;
    el.classList.toggle("active", el.dataset.actionId === (isLauncher ? activeLauncher : activeStd));
    // Survol : nom + quantité live (standards comme lance-roquettes).
    try { el.title = rocketTip(id); } catch {}
  }
  // Carrés du bouton USE : chargeur (1/s jusqu'à min(5, stock)).
  // On ne retouche que si ça a changé (laisse la charge jouer entre deux).
  const launcherLit = launcherLitNow();
  if (launcherLit !== launcherSquaresShown) {
    launcherSquaresShown = launcherLit;
    for (const el of bar.querySelectorAll(".launcherAutoBtn")) {
      el.querySelectorAll(".lsq").forEach((sq, i) => {
        sq.classList.toggle("lit", i < launcherLit);
      });
    }
  }
  for (const el of bar.querySelectorAll(".launcherAutoBtn .launcherCount")) {
    el.textContent = formatRocketCount(rocketCount(player.launcherActive));
  }
  // Fond du bouton USE (palette + slots) : suit la sélection.
  const launcherBgIcon = rocketDockIcon(String(player.launcherActive || "eco10").toLowerCase()) || rocketDockIcon("eco10") || "";
  const launcherBgWant = launcherBgIcon ? `url("${launcherBgIcon}")` : "";
  for (const el of bar.querySelectorAll(".launcherAutoBtn")) {
    if (el.style.backgroundImage !== launcherBgWant) el.style.backgroundImage = launcherBgWant;
  }
  // Petit bouton ON/OFF lance-roquettes.
  for (const el of bar.querySelectorAll(".launcherAutoToggle")) {
    el.classList.toggle("active", !!player.launcherAuto);
    const s = el.querySelector("small");
    if (s) s.textContent = player.launcherAuto ? "ON" : "OFF";
  }
}

function updateAmmoUI() {
  const active = player.ammo.active;

  ui.btnX1.classList.toggle("active", active === "x1");
  ui.btnX2.classList.toggle("active", active === "x2");
  ui.btnX3.classList.toggle("active", active === "x3");
  ui.btnX4.classList.toggle("active", active === "x4");
  ui.btnX6.classList.toggle("active", active === "x6");

  if (ui.btnSAB) {
    ui.btnSAB.classList.toggle("active", active === "sab");
  }

  ui.cntX1.textContent = "∞";
  ui.cntX2.textContent = formatAmmoCount(player.ammo.x2);
  ui.cntX3.textContent = formatAmmoCount(player.ammo.x3);
  ui.cntX4.textContent = formatAmmoCount(player.ammo.x4);
  ui.cntX6.textContent = formatAmmoCount(player.ammo.x6);

  if (ui.cntSAB) {
    ui.cntSAB.textContent = formatAmmoCount(player.ammo.sab);
  }

  refreshRocketPaletteCounts();

  syncActionDockState();
  try { window.__SYNC_PHONE_ACTION_GOLD__?.(); } catch {}
}

// Vente de munitions depuis l'inventaire : recopie le stock du compte vers
// la session live (même pattern que les achats), puis rafraîchit l'UI.
function applyAccountAmmoToPlayer() {
  const u = account.user || getCurrentUserFull();
  if (!u) return false;
  account.user = u;
  player.ammo = player.ammo || {};
  for (const [key, value] of Object.entries(u.ammo || {})) {
    if (key === "x1" || key === "active") continue;
    player.ammo[key] = Math.max(0, Math.floor(Number(value) || 0));
  }
  player.ammo.x1 = Infinity;
  if (player.ammo.active !== "x1" && !(Number(player.ammo[player.ammo.active] || 0) > 0)) player.ammo.active = "x1";
  player.rockets = player.rockets || {};
  for (const [key, value] of Object.entries(u.rockets || {})) {
    player.rockets[key] = Math.max(0, Math.floor(Number(value) || 0));
  }
  try {
    updateAmmoUI();
  } catch {}
  return true;
}

let actionDockCache = null;
let actionDockDirty = true;
let actionDockObserver = null;
const lastDockField = new WeakMap();
// Durée du verrou après un changement de formation (doit rester synchronisée
// avec setCurrentUserDroneFormation dans ACCOUNT.js).
const FORMATION_SWITCH_MS = 2000;

function invalidateActionDockCache() {
  actionDockCache = null;
  actionDockDirty = true;
}

function isTextOnlyMutation(records) {
  for (const record of records) {
    if (record.type !== "childList") return false;
    const nodes = [...record.addedNodes, ...record.removedNodes];
    if (nodes.some((node) => node.nodeType !== 3)) return false;
  }
  return true;
}

function ensureActionDockCache() {
  const bar = document.getElementById("ammoBar");
  if (!bar) return null;
  const fresh = { bar, ammo: [], formations: [], skills: [], rockets: [], launchers: [], abilities: [], petmodes: [], techmodes: [] };
  for (const button of bar.querySelectorAll("[data-ammo]")) {
    fresh.ammo.push({ button, ammo: button.dataset.ammo, small: button.querySelector("small") });
  }
  for (const button of bar.querySelectorAll("[data-action-id^='formation:']")) {
    fresh.formations.push({ button, actionId: button.dataset.actionId });
  }
  for (const button of bar.querySelectorAll("[data-action-id^='rocket:']")) {
    // Standards uniquement : le lance-roquettes est exclu (comme pour l'IEM).
    const rid = String(button.dataset.actionId || "").slice("rocket:".length).toLowerCase();
    if (getRocketType(rid)?.manual === false) { fresh.launchers.push({ button, rocketId: rid }); continue; }
    fresh.rockets.push({ button, rocketId: rid });
  }
  for (const button of bar.querySelectorAll("[data-skill]")) {
    fresh.skills.push({ button, skill: button.dataset.skill, small: button.querySelectorAll("small") });
  }
  for (const button of bar.querySelectorAll("[data-action-id^='ability:']")) {
    fresh.abilities.push({ button, abilityId: String(button.dataset.actionId || "").slice("ability:".length) });
  }
  for (const button of bar.querySelectorAll("[data-action-id^='petmode:']")) {
    fresh.petmodes.push({ button, value: String(button.dataset.actionId || "").slice("petmode:".length) });
  }
  for (const button of bar.querySelectorAll("[data-action-id^='tech:']")) {
    fresh.techmodes.push({ button, actionId: button.dataset.actionId });
  }
  if (!actionDockObserver && typeof MutationObserver !== "undefined") {
    actionDockObserver = new MutationObserver((records) => {
      if (isTextOnlyMutation(records)) return;
      invalidateActionDockCache();
    });
    actionDockObserver.observe(bar, { childList: true, subtree: true });
  }
  return fresh;
}

function dockFieldCache(button) {
  let byField = lastDockField.get(button);
  if (!byField) {
    byField = new Map();
    lastDockField.set(button, byField);
  }
  return byField;
}

function applyDockField(button, field, value, apply) {
  const byField = dockFieldCache(button);
  if (byField.get(field) === value) return;
  byField.set(field, value);
  apply(value);
}

// Bordure d'un slot pour le liseré du voile : getComputedStyle force un
// recalcul de style, on le limite à 4 Hz par bouton (les longues recharges
// aptitude/roquette faisaient chuter les FPS).
const cdEdgeAt = new WeakMap();
function dockCdEdge(button) {
  const nowMs = performance.now();
  if (nowMs - (cdEdgeAt.get(button) || 0) < 250) return null;
  cdEdgeAt.set(button, nowMs);
  try { return getComputedStyle(button).borderColor; } catch { return null; }
}

function syncActionDockState() {
  if (!actionDockCache) {
    if (actionDockDirty) {
      actionDockCache = ensureActionDockCache();
      actionDockDirty = false;
    }
    if (!actionDockCache) return;
  }

  const activeAmmo = player.ammo.active || "x1";

  for (const { button, ammo, small } of actionDockCache.ammo) {
    const value = ammo === "x1" ? "∞" : formatAmmoCount(player.ammo[ammo]);
    applyDockField(button, "active", ammo === activeAmmo,
      (v) => button.classList.toggle("active", v));
    // Dock rapide : munition épuisée (sauf X1 infini) = masquée.
    try {
      const hasStock = String(ammo || "").toLowerCase() === "x1" || Number(player.ammo?.[ammo] || 0) > 0;
      applyDockField(button, "stock", hasStock,
        (v) => { button.style.display = v ? "" : "none"; });
    } catch {}
    applyDockField(button, "text", value,
      (v) => { if (small) small.textContent = v; });
    // Survol : nom + quantité live.
    try {
      const tip = ammoTip(ammo);
      applyDockField(button, "tip", tip,
        (v) => { button.title = v; });
    } catch {}
    // Pastille orbitale blanche pendant le tir (x1-x4, sab, spéciales ; X6/RCB exclus).
    // Suit la munition active : change de slot avec elle, disparaît à l'arrêt.
    const firing = attackActive && !player.dead && ammo === activeAmmo && !isRsbLike(ammo);
    applyDockField(button, "firing", firing,
      (v) => button.classList.toggle("firing", v));
    // X6/RCB : voile de leur cooldown 5 s. Liseré auto-adaptatif en continu
    // comme roquettes/formations ; flash de fin couleur du contour du slot.
    if (isRsbLike(ammo)) {
      const cd = rsbLikeCooldown(ammo);
      const cdMax = ammo === "rcb" ? RCB_COOLDOWN : RSB_COOLDOWN;
      const cooling = cd > 0;
      const progress = cooling ? clamp(cd / cdMax, 0, 1) : 0;
      const wasCooling = button.dataset.x6Cooling === "1";
      if (wasCooling && !cooling && ammo === activeAmmo) {
        // Flash "prêt" uniquement si X6/RCB est la munition active : sinon
        // il ressemble à une sélection permanente.
        button.classList.remove("x6Ready");
        void button.offsetWidth;
        button.classList.add("x6Ready");
        setTimeout(() => button.classList.remove("x6Ready"), 500);
      } else if (wasCooling && !cooling) {
        button.classList.remove("x6Ready");
      }
      button.dataset.x6Cooling = cooling ? "1" : "0";
      applyDockField(button, "cdVeil", cooling,
        (v) => button.classList.toggle("cdVeil", v));
      applyDockField(button, "cdProgress", progress.toFixed(3),
        (v) => button.style.setProperty("--cd", v));
      if (cooling) {
        // Liseré brillant seulement si X6 est la munition active : sinon
        // le voile de recharge ressemble à une sélection (double-sélection
        // apparente avec la vraie munition active).
        const edgeColor = ammo === activeAmmo
          ? (dockCdEdge(button) || "rgba(120,130,140,.35)")
          : "rgba(120,130,140,.35)";
        applyDockField(button, "cdEdge", edgeColor,
          (v) => button.style.setProperty("--cd-edge", v));
      }
    }
  }

  const activeFormationId = getActiveDroneFormation(account.user).id;
  // Verrou 2 s après un changement de formation (miroir de ACCOUNT.js :
  // setCurrentUserDroneFormation). Pilote le voile + le flash des formations.
  let formationLockLeft = 0;
  try {
    const lastChange = account?.user?.drones?.lastFormationChangeAt || 0;
    formationLockLeft = Math.max(0, FORMATION_SWITCH_MS - (Date.now() - lastChange));
  } catch { formationLockLeft = 0; }
  for (const { button, actionId } of actionDockCache.formations) {
    const selected = actionId === `formation:${activeFormationId}`;
    applyDockField(button, "active", selected,
      (v) => button.classList.toggle("active", v));
    // Dock rapide : seules les formations possédées sont affichées
    // (standard toujours visible, c'est la formation de base).
    try {
      let owned = null;
      try {
        const list = account?.user?.drones?.formations;
        if (Array.isArray(list) && list.length) owned = new Set(list.map((f) => String(f || "").toLowerCase()));
      } catch {}
      if (!owned) owned = new Set(["standard"]);
      owned.add("standard");
      const fid = String(actionId || "").split(":")[1] || "";
      applyDockField(button, "owned", owned.has(fid.toLowerCase()),
        (v) => { button.style.display = v ? "" : "none"; });
    } catch {}
    // Pendant le verrou, toutes les formations sont indisponibles :
    // le voile s'affiche sur chaque slot qui contient une formation.
    const cooling = formationLockLeft > 0;
    const progress = cooling ? clamp(formationLockLeft / FORMATION_SWITCH_MS, 0, 1) : 0;
    applyDockField(button, "cdVeil", cooling,
      (v) => button.classList.toggle("cdVeil", v));
    applyDockField(button, "cdProgress", progress.toFixed(3),
      (v) => button.style.setProperty("--cd", v));
    // Liseré auto-adaptatif : suit la bordure du slot (4 Hz max, voir dockCdEdge).
    if (cooling) {
      const edge = dockCdEdge(button);
      if (edge) applyDockField(button, "cdEdge", edge,
        (v) => button.style.setProperty("--cd-edge", v));
    }
  }

  // Roquettes standard : cooldown partagé, voile sur chaque slot de roquette.
  // (Pas de flash : ~1 s en tir soutenu = trop de clignotement.)
  for (const { button, rocketId } of actionDockCache.rockets) {
    const cooldownLeft = rocketCooldownLeft(rocketId);
    const cooldownMax = rocketCooldownMaxFor(rocketId);
    const cooling = cooldownLeft > 0;
    // Dock rapide : roquette épuisée = masquée (comme la palette).
    try {
      const hasStock = rocketCount(rocketId) > 0;
      applyDockField(button, "stock", hasStock,
        (v) => { button.style.display = v ? "" : "none"; });
    } catch {}
    // Survol : nom + quantité live.
    try {
      const tip = rocketTip(rocketId);
      applyDockField(button, "tip", tip,
        (v) => { button.title = v; });
    } catch {}
    const progress = cooling ? clamp(cooldownLeft / cooldownMax, 0, 1) : 0;
    applyDockField(button, "cdVeil", cooling,
      (v) => button.classList.toggle("cdVeil", v));
    applyDockField(button, "cdProgress", progress.toFixed(3),
      (v) => button.style.setProperty("--cd", v));
    // Liseré auto-adaptatif (4 Hz max, voir dockCdEdge).
    if (cooling) {
      const edge = dockCdEdge(button);
      if (edge) applyDockField(button, "cdEdge", edge,
        (v) => button.style.setProperty("--cd-edge", v));
    }
  }

  // Lance-roquettes : masqué si stock épuisé (comme roquettes et palette).
  for (const { button, rocketId } of actionDockCache.launchers || []) {
    try {
      const hasStock = rocketCount(rocketId) > 0;
      applyDockField(button, "stock", hasStock,
        (v) => { button.style.display = v ? "" : "none"; });
    } catch {}
  }

  // Aptitudes : voile de recharge sur chaque slot d'aptitude (slots + palette),
  // comme les roquettes (pas de flash). Branchées une par une via getAbilityCooldown.
  for (const { button, abilityId } of actionDockCache.abilities) {
    const cd = getAbilityCooldown(abilityId);
    const cooling = Number(cd.left || 0) > 0 && Number(cd.max || 0) > 0;
    const progress = cooling ? clamp(Number(cd.left) / Number(cd.max), 0, 1) : 0;
    applyDockField(button, "cdVeil", cooling,
      (v) => button.classList.toggle("cdVeil", v));
    applyDockField(button, "cdProgress", progress.toFixed(3),
      (v) => button.style.setProperty("--cd", v));
    // Liseré auto-adaptatif (4 Hz max, voir dockCdEdge).
    if (cooling) {
      const edge = dockCdEdge(button);
      if (edge) applyDockField(button, "cdEdge", edge,
        (v) => button.style.setProperty("--cd-edge", v));
    }
    // Compteur en secondes : temps d'effet restant pendant l'effet, recharge sinon.
    let cdText = "";
    if (cooling) {
      const lowId = String(abilityId || "").toLowerCase();
      const fxLeft = isCloakAbility(abilityId) ? Number(player.cloakT || 0)
        : lowId === "ability_aegis_repair-pod" ? Number(player.podT || 0)
        : lowId === "ability_basilisk_noxious-nebula" ? Number(player.nebT || 0)
        : lowId === "ability_basilisk_heightened-valour" ? Number(player.valT || 0)
        : lowId === "ability_berserker_shl" ? Number(player.shlT || 0)
        : lowId === "ability_berserker_bsk" ? Number(player.bskT || 0)
        : lowId === "ability_berserker_rvg" ? Number(player.rvgT || 0)
        : lowId === "ability_citadel_draw-fire" || lowId === "ability_citadel-plus_draw-fire" ? Number(player.drawFireT || 0)
        : lowId === "ability_citadel_protection" || lowId === "ability_citadel-plus_protection" ? Number(player.protectionT || 0)
        : lowId === "ability_citadel_travel" || lowId === "ability_citadel-plus_travel" ? Number(player.travelT || 0)
        : lowId === "ability_yamato_travel" ? Number(player.yamatoT || 0)
        : lowId === "ability_citadel_fortify" || lowId === "ability_citadel-plus_fortify" ? Number(player.fortifyT || 0)
        : lowId === "ability_citadel-plus_prismatic-endurance" ? Number(player.prismT || 0)
        : lowId === "ability_spectrum" ? Number(player.specT || 0)
        : lowId === "ability_spectrum-plus_prismatic-reflecting" ? Number(player.specPlusT || 0)
        : lowId === "ability_tartarus-plus_rapid-fire-plus" ? Number(player.tartRapidPlusT || 0)
        : lowId === "ability_tartarus_speed-boost" ? (player.tartBoostOn === true ? 1 : 0)
        : lowId === "ability_tartarus-plus_speed-boost-plus" ? (player.tartPlusBoostOn === true ? 1 : 0)
        : lowId === "ability_tempest_volt-backup" ? Number(player.tempestBackupT || 0)
        : lowId === "ability_tempest_volt-discharge" ? Number(player.tempestDischT || 0)
        : lowId === "ability_zephyr_mmt" ? Number(player.mmtT || 0)
        : lowId === "ability_zephyr_tbr" ? Number(player.tbrT || 0)
        : lowId === "ability_diminisher" ? Number(player.diminishT || 0)
        : lowId === "ability_holo_self-reversal" ? Number(player.holoSelfT || 0)
        : lowId === "ability_holo_enemy-reversal" ? Number(player.holoEnemyT || 0)
        : lowId === "ability_hyperion_ga" ? Number(player.gaT || 0)
        : lowId === "ability_keres_spr" ? (player.keresSprActive ? 1 : 0)
        : lowId === "ability_keres_sle" ? (Number(player.sleightT || 0) > 0 ? 1 : 0)
        : lowId === "ability_liberator-plus_self-repair" ? Number(player.libRepT || 0)
        : lowId === "ability_lightning" ? Number(player.lightT || 0)
        : lowId === "ability_mimesis_scramble" ? (Number(player.scrambleT || 0) > 0 ? 1 : 0)
        : lowId === "ability_mimesis_hologram" ? (player.holoGramPhase != null ? 1 : 0)
        : lowId === "ability_orcus_assimilate" || lowId === "ability_orcus-plus_assimilate" ? Number(player.orcusT || 0)
        : lowId === "ability_cyborg_singularity" ? Number(player.cyborgT || 0)
        : lowId === "ability_venom" ? Number(player.venomT || 0)
        : lowId === "ability_sentinel" ? Number(player.sentT || 0)
        : lowId === "ability_spearhead_double-minimap" || lowId === "ability_spearhead-plus_recon" ? Number(player.reconT || 0)
        : lowId === "ability_solaris_inc" ? Number(player.incT || 0)
        : lowId === "ability_solaris-plus_incinerate-plus" ? Number(player.incPlusT || 0)
        : lowId === "ability_pusat-plus_speed-sap" ? Number(player.sapT || 0)
        : lowId === "ability_retiarus_spc" ? Number(player.spcT || 0)
        : lowId === "ability_retiarus-plus_spcp" ? Number(player.spcPlusT || 0)
        : lowId === "ability_retiarus_chs" ? (player.chsPhase != null && !player.chsPlus ? 1 : 0)
        : lowId === "ability_retiarus-plus_chsp" ? (player.chsPhase != null && player.chsPlus ? 1 : 0)
        : lowId === "ability_paladin_ripper" ? Number(player.ripperT || 0)
        : lowId === "ability_disruptor_ddol" ? Number(player.ddolT || 0)
        : lowId === "ability_disruptor_redirect" ? Number(player.redirectT || 0)
        : lowId === "ability_disruptor_shield-disarray" ? Number(player.disarrayT || 0)
        : lowId === "ability_hammerclaw-plus_reallocate" ? Number(player.reallocT || 0)
        : lowId === "ability_hecate_particle-beam" ? Number(player.hecateT || 0)
        : lowId === "ability_hecate-plus_particle-beam-plus" ? Number(player.hecatePlusT || 0)
        : lowId === "ability_hecate-plus_stockpile" ? Number(player.stockT || 0)
        : lowId === "ability_aegis_hp-repair" ? Number(player.healHpT || 0)
        : lowId === "ability_aegis_shield-repair" ? Number(player.healShT || 0)
        : lowId === "ability_hammerclaw_hp-repair" ? Number(player.hammerHpT || 0)
        : lowId === "ability_hammerclaw-plus_hp-repair" ? Number(player.hammerHpPlusT || 0)
        : lowId === "ability_hammerclaw_shield-repair" ? Number(player.hammerShT || 0)
        : lowId === "ability_hammerclaw-plus_shield-repair" ? Number(player.hammerShPlusT || 0)
        : lowId === "ability_hammerclaw_repair-pod" ? Number(player.hammerPodT || 0)
        : lowId === "ability_hammerclaw-plus_repair-pod" ? Number(player.hammerPodPlusT || 0) : 0;
      // Spread : compteur d'infectés pendant l'effet (pas un temps).
      if (lowId === "ability_keres_spr" && player.keresSprActive) {
        cdText = `x${Number(player.keresSprN || 0)}`;
      } else if (lowId === "ability_keres_sle" && Number(player.sleightT || 0) > 0) {
        cdText = ">>";
      } else if (lowId === "ability_mimesis_scramble" && Number(player.scrambleT || 0) > 0) {
        cdText = ">>";
      } else if (lowId === "ability_mimesis_hologram" && player.holoGramPhase != null) {
        cdText = formatAbilityCd(Number(player.holoGramT || 0));
      } else if (lowId === "ability_retiarus_chs" && (player.chsPhase != null && !player.chsPlus)) {
        cdText = ">>";
      } else if (lowId === "ability_retiarus-plus_chsp" && (player.chsPhase != null && player.chsPlus)) {
        cdText = ">>";
      } else {
        cdText = formatAbilityCd(fxLeft > 0 ? fxLeft : cd.left);
      }
    }
    applyDockField(button, "cdText", cdText,
      (v) => { const small = button.querySelector(".abilityCd"); if (small) small.textContent = v; });
  }

  for (const { button, skill, small } of actionDockCache.skills) {
    if (skill === "pulse") {
      const progress = pulseCd > 0 ? clamp(pulseCd / PULSE_COOLDOWN, 0, 1) : 0;
      const canUse = canUseSkill(PULSE_COST);
      const cooling = progress > 0;
      // Front descendant du cooldown -> petite lueur "prête" (one-shot).
      const wasCooling = button.dataset.iemCooling === "1";
      if (wasCooling && !cooling && canUse) {
        button.classList.remove("skillReadyPop");
        void button.offsetWidth;
        button.classList.add("skillReadyPop");
        setTimeout(() => button.classList.remove("skillReadyPop"), 750);
      }
      button.dataset.iemCooling = cooling ? "1" : "0";
      applyDockField(button, "feedback", cooling,
        (v) => button.classList.toggle("skillFeedback", v));
      applyDockField(button, "progress", progress.toFixed(3),
        (v) => button.style.setProperty("--skill-feedback", v));
      applyDockField(button, "disabled", !canUse || cooling,
        (v) => button.classList.toggle("disabled", v));
      applyDockField(button, "ready", canUse && !cooling,
        (v) => button.classList.toggle("ready", v));
      // Plus de compteur 0->100% : le voile circulaire montre la progression.
      // On affiche le temps restant pendant la recharge, "PRET" une fois dispo.
      applyDockField(button, "main", cooling ? `${pulseCd.toFixed(1)}s` : "PRET",
        (v) => { if (small[0]) small[0].textContent = v; });
      applyDockField(button, "cd", cooling ? "" : "30k",
        (v) => { if (small[1]) small[1].textContent = v; });
    } else if (skill === "ish") {
      const ishProgress = ishCd > 0 ? clamp(ishCd / ISH_COOLDOWN, 0, 1) : 0;
      const ishCanUse = canUseSkill(ISH_COST);
      const ishCooling = ishProgress > 0;
      // Front descendant du cooldown -> petite lueur "prête" (one-shot).
      const ishWasCooling = button.dataset.ishCooling === "1";
      if (ishWasCooling && !ishCooling && ishCanUse) {
        button.classList.remove("skillReadyPop");
        void button.offsetWidth;
        button.classList.add("skillReadyPop");
        setTimeout(() => button.classList.remove("skillReadyPop"), 750);
      }
      button.dataset.ishCooling = ishCooling ? "1" : "0";
      applyDockField(button, "feedback", ishCooling,
        (v) => button.classList.toggle("skillFeedback", v));
      applyDockField(button, "progress", ishProgress.toFixed(3),
        (v) => button.style.setProperty("--skill-feedback", v));
      applyDockField(button, "disabled", !ishCanUse || ishCooling,
        (v) => button.classList.toggle("disabled", v));
      applyDockField(button, "ready", ishCanUse && !ishCooling,
        (v) => button.classList.toggle("ready", v));
      // Temps restant pendant la recharge, "PRET" une fois dispo.
      applyDockField(button, "main", ishCooling ? `${ishCd.toFixed(1)}s` : "PRET",
        (v) => { if (small[0]) small[0].textContent = v; });
      applyDockField(button, "cd", ishCooling ? "" : "30k",
        (v) => { if (small[1]) small[1].textContent = v; });
    } else if (skill === "smb") {
      // Mine SMB-01 : tout pareil que IEM/ISH (voile circulaire + flash "prêt",
      // temps restant pendant la recharge, "PRET"/"30k" sinon).
      const smbProgress = smbCd > 0 ? clamp(smbCd / SMB_COOLDOWN, 0, 1) : 0;
      const smbCanUse = canUseSkill(SMB_COST);
      const smbCooling = smbProgress > 0;
      const smbWasCooling = button.dataset.smbCooling === "1";
      if (smbWasCooling && !smbCooling && smbCanUse) {
        button.classList.remove("skillReadyPop");
        void button.offsetWidth;
        button.classList.add("skillReadyPop");
        setTimeout(() => button.classList.remove("skillReadyPop"), 750);
      }
      button.dataset.smbCooling = smbCooling ? "1" : "0";
      applyDockField(button, "feedback", smbCooling,
        (v) => button.classList.toggle("skillFeedback", v));
      applyDockField(button, "progress", smbProgress.toFixed(3),
        (v) => button.style.setProperty("--skill-feedback", v));
      applyDockField(button, "disabled", !smbCanUse || smbCooling,
        (v) => button.classList.toggle("disabled", v));
      applyDockField(button, "ready", smbCanUse && !smbCooling,
        (v) => button.classList.toggle("ready", v));
      applyDockField(button, "main", smbCooling ? `${smbCd.toFixed(1)}s` : "PRET",
        (v) => { if (small[0]) small[0].textContent = v; });
      applyDockField(button, "cd", smbCooling ? "" : "30k",
        (v) => { if (small[1]) small[1].textContent = v; });
    } else if (skill === "cloak") {
      // CPU CL04K-XL : comme IEM/ISH (voile circulaire + flash "prêt").
      // 1 s de recharge après chaque (dés)activation (anti-spam).
      const cloakProgress = cloakCd > 0 ? clamp(cloakCd / CPU_CLOAK_COOLDOWN, 0, 1) : 0;
      const cloakCanUse = canUseSkill(CPU_CLOAK_COST);
      const cloakCooling = cloakProgress > 0;
      const cloakWasCooling = button.dataset.cloakCooling === "1";
      if (cloakWasCooling && !cloakCooling && cloakCanUse) {
        button.classList.remove("skillReadyPop");
        void button.offsetWidth;
        button.classList.add("skillReadyPop");
        setTimeout(() => button.classList.remove("skillReadyPop"), 750);
      }
      button.dataset.cloakCooling = cloakCooling ? "1" : "0";
      const cloakActive = isPlayerCpuCloaked();
      // Carte à camouflage interdit : bouton grisé (la sortie reste possible).
      const cloakDenied = !cloakActive && cloakBlockedOnMap();
      // Pendant l'effet : voile noir plein (comme si le CD venait de
      // s'armer) ; il ne se balaye qu'à la sortie (ACTIF -> PRET).
      applyDockField(button, "feedback", cloakCooling || cloakActive,
        (v) => button.classList.toggle("skillFeedback", v));
      applyDockField(button, "progress", (cloakActive ? 1 : cloakProgress).toFixed(3),
        (v) => button.style.setProperty("--skill-feedback", v));
      applyDockField(button, "disabled", (!cloakCanUse && !cloakActive) || cloakCooling || cloakDenied,
        (v) => button.classList.toggle("disabled", v));
      applyDockField(button, "ready", (cloakCanUse || cloakActive) && !cloakCooling && !cloakDenied,
        (v) => button.classList.toggle("ready", v));
      applyDockField(button, "active", cloakActive,
        (v) => button.classList.toggle("active", v));
      applyDockField(button, "main", cloakCooling ? `${cloakCd.toFixed(1)}s` : (cloakActive ? "ACTIF" : (cloakDenied ? "OFF" : "PRET")),
        (v) => { if (small[0]) small[0].textContent = v; });
      applyDockField(button, "cd", cloakCooling ? "" : "30k",
        (v) => { if (small[1]) small[1].textContent = v; });
    } else if (skill === "repair") {
      applyDockField(button, "active", false,
        (v) => button.classList.remove("active"));
      applyDockField(button, "disabled", player.dead,
        (v) => button.classList.toggle("disabled", v));
      applyDockField(button, "text", ui.repairTxt ? ui.repairTxt.textContent : "",
        (v) => { if (small[0]) small[0].textContent = v; });
      // Robot réparateur : même voile que le reste pendant sa recharge (6 s).
      const repairPct = REPAIR.cooldown <= 0 ? 1 : clamp(player.repairT / REPAIR.cooldown, 0, 1);
      const repairCooling = !player.dead && repairPct < 1;
      const repairProgress = repairCooling ? 1 - repairPct : 0;
      const repairReady = !player.dead && !repairCooling;
      if (button.dataset.repairCooling === "1" && repairReady) {
        button.classList.remove("skillReadyPop");
        void button.offsetWidth;
        button.classList.add("skillReadyPop");
        setTimeout(() => button.classList.remove("skillReadyPop"), 750);
      }
      button.dataset.repairCooling = repairCooling ? "1" : "0";
      applyDockField(button, "ready", repairReady,
        (v) => button.classList.toggle("ready", v));
      applyDockField(button, "feedback", repairCooling,
        (v) => button.classList.toggle("skillFeedback", v));
      applyDockField(button, "progress", repairProgress.toFixed(3),
        (v) => button.style.setProperty("--skill-feedback", v));
      applyDockField(button, "cdVeil", false,
        (v) => button.classList.toggle("cdVeil", v));

    }
  }

  // Modes P.E.T (slots + palette ouverte) : actif + compte à rebours, comme
  // le menu Mode de la fenêtre. Même rythme que les autres (chaque passe).
  // Tech Speed Burst : pareil (recharge 300 s individuelle, voile + secondes).
  {
    const { opts, want } = petModeEntries();
    const byValue = new Map(opts.map((o) => [`petmode:${o.value}`, o]));
    const paintPetDock = (button, actionId) => {
      const o = byValue.get(actionId);
      if (o) {
        paintPetModeNode(button, o, want);
        // Voile de recharge dans le slot (comme roquettes/aptitudes), fluide.
        const left = Math.max(0, Number(o.cd) || 0);
        const max = Math.max(0, Number(o.cdMax) || 0);
        const cooling = left > 0 && max > 0;
        applyDockField(button, "cdVeil", cooling,
          (v) => button.classList.toggle("cdVeil", v));
        applyDockField(button, "cdProgress", cooling ? clamp(left / max, 0, 1).toFixed(3) : "0",
          (v) => button.style.setProperty("--cd", v));
      }
      else {
        // Gear déséquipé après coup : grisé, jamais actif.
        const key = String(actionId || "").replace(/^petmode:gear:/, "");
        paintPetModeNode(button, {
          value: String(actionId || "").slice("petmode:".length),
          label: `${key.toUpperCase()} (retiré)`,
          disabled: true,
          icon: PET_GEAR_DROPDOWN_ICON[key] || "",
        }, want);
      }
    };
    for (const { button, value } of actionDockCache.petmodes) paintPetDock(button, `petmode:${value}`);
    try {
      for (const button of document.querySelectorAll('#ammoBar .actionPaletteItems [data-action-id^="petmode:"]')) {
        paintPetDock(button, button.dataset.actionId);
      }
    } catch {}
    // Techs branchées (slots + palette ouverte) : actif + voile.
    // NPC Bomb : fin d'aura -> le CD de 300 s démarre (après le 6e pulse).
    if (techNpcBombFrom && performance.now() - techNpcBombFrom >= NPC_BOMB_DURATION_MS) {
      techNpcBombFrom = 0;
      techNpcBombPulse = 0;
      try { persistCdUntil("techAura:npc-bomb", 0, "global"); } catch {}
      setTechCooldown("npc-bomb", TECH_COOLDOWN);
    }
    // Precision : fin d'effet -> le CD de 300 s demarre.
    if (player.precisionUntil && Date.now() >= player.precisionUntil) {
      player.precisionUntil = 0;
      try { persistCdUntil("techPrecisionFx", 0, "global"); } catch {}
      setTechCooldown("precision-targeter", TECH_COOLDOWN);
    }
    // Energy Leech : fin d'effet -> le CD de 900 s demarre (spécifique).
    if (player.energyLeechUntil && Date.now() >= player.energyLeechUntil) {
      player.energyLeechUntil = 0;
      player.energyLeechNeedsResync = false;
      try { persistCdUntil("techAura:energy-leech", 0, "global"); } catch {}
      setTechCooldown("energy-leech", ENERGY_LEECH_CD_S);
    }
    // Après un refresh/rebranchement, réannonce l'aura persistée au serveur.
    // L'activation serveur est idempotente et renvoie sa durée autoritaire.
    if (player.energyLeechNeedsResync === true && techEnergyLeechActive()
      && !techInLocalInstance() && netConnected()) {
      try {
        if (sendSkillUse(ENERGY_LEECH_ID, { phase: "fire" })) player.energyLeechNeedsResync = false;
      } catch {}
    }
    const paintTechDock = (button) => {
      const entry = TECH_DOCK_ITEMS.find((t) => `tech:${t.id}` === button.dataset.actionId);
      if (!entry) return;
      const vis = techDockVisual(entry.id);
      paintTechNode(button, entry, vis.active, vis.cd, vis.cdMax);
      const cooling = vis.cd > 0;
      applyDockField(button, "cdVeil", cooling,
        (v) => button.classList.toggle("cdVeil", v));
      applyDockField(button, "cdProgress", cooling ? clamp(vis.cd / vis.cdMax, 0, 1).toFixed(3) : "0",
        (v) => button.style.setProperty("--cd", v));
    };
    for (const { button } of actionDockCache.techmodes) paintTechDock(button);
    try {
      for (const button of document.querySelectorAll('#ammoBar .actionPaletteItems [data-action-id^="tech:"]')) {
        paintTechDock(button);
      }
    } catch {}
  }
  // Téléphone : même voile de recharge sur les boutons ronds (même rythme).
  try { window.__SYNC_PHONE_ACTION_CD__?.(); } catch {}
}

// Son de sélection du dock rapide : nouveau choix vs choix déjà actif.
function playDockSelectSound(isNew) {
  SFX.play(isNew ? "selectNew" : "selectAgain");
}

// (Câblage des munitions : générique sur les originaux, voir
// initializeCustomActionBar — les clones slots/palette suivent.)

// ✅ Munitions spéciales : même câblage que X1-X6 (le dock est générique :
// counts + actif déjà gérés par syncActionDockState pour tout [data-ammo]).
// (Voir initializeCustomActionBar : les originaux sont câblés là-bas,
// les clones des slots/palette redirigent vers eux.)

// ============================================================
// Repair
// ============================================================
function stopRepairSound({ fadeOut = 0 } = {}) {
  if (!repairSoundActive) return;
  repairSoundActive = false;
  SFX.stopLoop("repairLoop", { fadeOut });
}

function resetRepairCooldown() {
  player.repairT = 0;
  player.repairTickT = 0;
  stopRepairSound({ fadeOut: 0 });
}

// Formations à drain (Papillon : -5 %/s...) : le bouclier drainé est le prix
// de la formation. Le robot ne le remonte pas et ne le réclame pas
// (ni son, ni HUD, ni floats) — seule la coque est réparée.
function formationDrainsShield() {
  return Number(getActiveDroneFormation(account.user)?.effects?.shieldDrainPct || 0) > 0;
}

function tickRepair(dt) {
  if (player.dead) {
    player.repairTickT = 0;
    stopRepairSound({ fadeOut: 0 });
    return;
  }

  // Volt Back-up actif : robot de réparation coupé (aucun soin coque).
  if ((player.tempestBackupT || 0) > 0) {
    player.repairTickT = 0;
    stopRepairSound({ fadeOut: 0 });
    return;
  }

  // ✅ pendant un saut de portail : cooldown bloqué à 0 (le robot ne peut
  // pas se recharger ni réparer). À l'arrivée (resetRun) il est réarmé
  // immédiatement et relance sa réparation avec le son.
  if (player.repairJumpLock) {
    player.repairT = 0;
    player.repairTickT = 0;
    stopRepairSound({ fadeOut: 0 });
    return;
  }

  const previousRepairT = player.repairT;
  player.repairT = Math.min(REPAIR.cooldown, player.repairT + dt);
  if (player.repairT < REPAIR.cooldown) return;

  // ✅ Démarre le son de réparation dès que le robot est actif et "a besoin".
  // Cas du saut : le cooldown arrive déjà plein (resetPlayerToBase) sans
  // jamais franchir le seuil → on relance le son au réarmement si la boucle
  // n'est pas déjà en cours (repairSoundActive).
  if (!repairSoundActive) {
    // Robot = coque uniquement : le bouclier ne le déclenche jamais.
    if (player.hp < player.hpMax - 0.01) {
      SFX.play("repairStart");
      repairSoundActive = true;
      SFX.loop("repairLoop", { fadeIn: 0.25 });
    }
  }

  const repairingDt = previousRepairT >= REPAIR.cooldown
    ? dt
    : Math.max(0, dt - (REPAIR.cooldown - previousRepairT));
  player.repairTickT += repairingDt;
  const tickCount = Math.floor((player.repairTickT + 1e-9) / REPAIR.tickInterval);
  if (tickCount <= 0) return;
  player.repairTickT -= tickCount * REPAIR.tickInterval;

  const oldHp = player.hp;
  const repairMult = playerBoosterMults().repair * playerPilotMults().repair;
  // Robot = coque uniquement. Le bouclier se recharge par tick passif
  // (tickShield) : plus de réparation instantanée nulle part.
  player.hp = Math.min(player.hpMax, player.hp + player.hpMax * REPAIR.ratePct * repairMult * REPAIR.tickInterval * tickCount);

  if (player.hp >= player.hpMax - 0.01) {
    stopRepairSound({ fadeOut: 0 });
  }

  const hpGain = Math.round(player.hp - oldHp);
  if (hpGain > 0) {
    addPlayerCombatFloat(hpGain, "rgba(80,255,125,0.98)", "+");
  }
}

function updateRepairUI(syncDock = true) {
  const pct = REPAIR.cooldown <= 0 ? 1 : clamp(player.repairT / REPAIR.cooldown, 0, 1);
  const needs = !player.dead && player.hp < player.hpMax - 0.01;

  const text = player.dead ? "OFF"
    : pct < 1 ? `${Math.floor(pct * 100)}%`
    : needs ? `+${Math.round(REPAIR.ratePct * 100)}%/s` : "OK";
  setHudText(ui.repairTxt, text);

  setHudClass(ui.btnRepair, "active", false);
  setHudClass(ui.btnRepair, "ready", false);
  setHudClass(ui.btnRepair, "disabled", player.dead);
  // Note : le glow "repairing" est piloté dans syncActionDockState (les boutons
  // visibles sont des clones ; ui.btnRepair est détaché après init du dock).
  if (syncDock) syncActionDockState();
}

// ============================================================
// Input
// ============================================================
const keyboard = createKeyboardState();
const keys = keyboard.held;
const justPressed = keyboard.pressed;

// ✅ Anti-zoom navigateur
window.addEventListener(
  "wheel",
  (e) => {
    if (e.ctrlKey) {
      e.preventDefault();
    }
  },
  { passive: false }
);

window.addEventListener(
  "keydown",
  (e) => {
    const isZoomKey =
      e.key === "+" ||
      e.key === "-" ||
      e.key === "=" ||
      e.key === "0" ||
      e.code === "NumpadAdd" ||
      e.code === "NumpadSubtract";

    if ((e.ctrlKey || e.metaKey) && isZoomKey) {
      e.preventDefault();
    }
  },
  { passive: false }
);

addEventListener(
  "keydown",
  (e) => {
    // ✅ si on est en train de choisir une nouvelle touche
    if (waitingForBindAction) {
      e.preventDefault();
      e.stopPropagation();

      finishKeyCapture(e.code);
      return;
    }

    const typingTarget = e.target?.closest?.("input, textarea, select, [contenteditable='true']");
    if (typingTarget) return;

const boundKeys = Object.values(GAME_SETTINGS.keybinds || {});
const used = [...boundKeys];

    if (used.includes(e.code)) e.preventDefault();

    triggerBoundCommand(e.code, e.repeat);
  },
  { passive: false }
);

// Touches E / R (rebindables en paramètres) : activation du P.E.T,
// et activation + passage direct en mode combat.
// (Définies ici, au même niveau que triggerBoundCommand, pour être visibles.)
// NOTE : on relit l'état persisté (getCurrentUserFull) plutôt que le cache
// mémoire account.user, qui peut être écrasé par un snapshot (multi/autosave)
// entre deux appuis — sinon le 2e appui ne désactive pas.
function petFreshActive() {
  try {
    const fresh = getCurrentUserFull();
    if (fresh?.pet?.owned === true) return fresh.pet.active === true;
  } catch {}
  return account.user?.pet?.active === true;
}
function togglePetByKey() {
  const live = account.user?.pet?.owned === true ? account.user.pet : null;
  if (!live) return showToast("P.E.T non possédé.", 1.5);
  const out = setPetActive(!petFreshActive());
  if (!out?.ok) return showToast(out?.error || "Impossible.", 1.5);
  loadAccountUser();
  showToast(out.active ? "P.E.T activé" : "P.E.T désactivé", 1.2);
}
function activatePetCombatByKey() {
  const live = account.user?.pet?.owned === true ? account.user.pet : null;
  if (!live) return showToast("P.E.T non possédé.", 1.5);
  if (!petFreshActive()) {
    const out = setPetActive(true);
    if (!out?.ok) return showToast(out?.error || "Impossible.", 1.5);
  }
  const m = setPetMode("combat");
  if (!m?.ok) return showToast(m?.error || "Impossible.", 1.5);
  loadAccountUser();
  showToast("P.E.T activé — mode combat", 1.5);
}

function triggerBoundCommand(code, repeat = false) {
    keyboard.keyDown(code, repeat);
    if (repeat) return;

    if (isKeybind("portal", code)) {
      if (!isZoneMap && betweenWaves) {
        const near = getInteractivePortals().find(isPlayerNearPortal);
        if (near) startGatePortalJump(near, near === portal ? "continue" : "return");
      }
      return;
    }

    if (isKeybind("switchConfig", code)) {
      toggleActiveConfigByKey();
      return;
    }

    if (isKeybind("toggleAttack", code)) {
      toggleAttack();
      return;
    }

    if (isKeybind("fireRocket", code)) {
      tryFireRocket();
      return;
    }

    if (isKeybind("toggleWindows", code)) {
      window.GameWindowManager?.toggleAll?.();
      return;
    }

    if (isKeybind("toggleDock", code)) {
      toggleActionDockMenu?.();
      return;
    }

    if (isKeybind("tertiaryToggle", code)) {
      toggleTertiaryActionBar?.();
      return;
    }

    if (isKeybind("petToggle", code)) {
      togglePetByKey();
      return;
    }

    if (isKeybind("petCombat", code)) {
      activatePetCombatByKey();
      return;
    }

    if (isKeybind("botToggle", code)) {
      botSetActive(!Bot.active);
      return;
    }

    for (let slotIndex = 0; slotIndex < 20; slotIndex++) {
      if (!isKeybind(`slot${slotIndex + 1}`, code)) continue;
      // 3e barre ouverte : elle reprend les touches 1..0 (slots 1..10),
      // puis se referme automatiquement après l'activation. F1..F10
      // continuent de piloter la barre principale.
      if (typeof isTertiaryActionBarOpen === "function" && isTertiaryActionBarOpen()) {
        if (slotIndex < 10) {
          document.querySelectorAll("#ammoBar .tertiarySlots > .actionSlot")[slotIndex]?.querySelector(".ammoBtn, .rocketQuickAction, .launcherAutoBtn")?.click();
        } else {
          document.querySelectorAll("#ammoBar .actionSlots > .actionSlot")[slotIndex]?.querySelector(".ammoBtn, .rocketQuickAction")?.click();
        }
        collapseTertiaryActionBar();
        return;
      }
      document.querySelectorAll("#ammoBar .actionSlots > .actionSlot")[slotIndex]?.querySelector(".ammoBtn, .rocketQuickAction")?.click();
      return;
    }
}

addEventListener("keyup", (e) => keyboard.keyUp(e.code));

// Seuls les boutons supplémentaires (souris 4 et suivantes) sont assignables.
// Gauche, droit, clic molette et clics d'interface gardent leur usage habituel.
const heldMouseBinds = new Set();
const suppressedMouseClicks = new Set();

function mouseButtonCode(event) {
  if (event.pointerType && event.pointerType !== "mouse") return null;
  if (event.sourceCapabilities?.firesTouchEvents) return null;
  return Number.isInteger(event.button) && event.button >= 3 ? `Mouse${event.button}` : null;
}

function consumeMouseBindEvent(event) {
  event.preventDefault();
  event.stopImmediatePropagation();
}

function mouseBindDown(event) {
  const code = mouseButtonCode(event);
  if (!code) return;
  // mousedown complète pointerdown pour les boutons pressés simultanément.
  if (heldMouseBinds.has(code)) {
    consumeMouseBindEvent(event);
    return;
  }
  suppressedMouseClicks.delete(code);
  const capturing = !!waitingForBindAction;
  if (!capturing && (event.target !== canvas
    || !Object.keys(DEFAULT_KEYBINDS).some(action => isKeybind(action, code)))) return;
  heldMouseBinds.add(code);
  suppressedMouseClicks.add(code);
  consumeMouseBindEvent(event);
  if (capturing) finishKeyCapture(code);
  else triggerBoundCommand(code);
}

function mouseBindUp(event) {
  const code = mouseButtonCode(event);
  if (!heldMouseBinds.has(code) && !suppressedMouseClicks.has(code)) return;
  heldMouseBinds.delete(code);
  keyboard.keyUp(code);
  consumeMouseBindEvent(event);
}

for (const type of ["pointerdown", "mousedown"]) {
  addEventListener(type, mouseBindDown, { capture: true, passive: false });
}
for (const type of ["pointerup", "mouseup"]) {
  addEventListener(type, mouseBindUp, { capture: true, passive: false });
}
for (const type of ["click", "auxclick", "contextmenu"]) {
  addEventListener(type, event => {
    const code = mouseButtonCode(event);
    if (!suppressedMouseClicks.has(code)) return;
    consumeMouseBindEvent(event);
    if (type !== "contextmenu") suppressedMouseClicks.delete(code);
  }, { capture: true, passive: false });
}
function resetMouseBinds() {
  for (const code of heldMouseBinds) keyboard.keyUp(code);
  heldMouseBinds.clear();
  suppressedMouseClicks.clear();
}
addEventListener("blur", resetMouseBinds);
addEventListener("pointercancel", event => {
  if (event.pointerType === "mouse") resetMouseBinds();
});

// Click-to-move / Lock manuel
canvas.style.touchAction = "none";
canvas.addEventListener("contextmenu", (e) => e.preventDefault());

function isPlayerNearPortal(ptl) {
  if (!ptl) return false;

  const radius = DEFAULT_PORTAL_RADIUS;

  return dist2(
    player.x,
    player.y,
    ptl.x,
    ptl.y
  ) <= radius * radius;
}

function pickPortalButtonAtScreen(clientX, clientY) {
  if (isPortalJumpInProgress()) return null;
  const portals = getInteractivePortals();
  if (!portals.length) return null;

  const mouseWorld = screenToWorld(clientX, clientY);

  // On parcourt à l'envers pour prendre celui dessiné au-dessus
  for (let i = portals.length - 1; i >= 0; i--) {
    const ptl = portals[i];
    const spr = getPortalSpriteSet(ptl);
    const btn = spr.jumpButton;

    if (!btn || ptl.jumping) continue;

    const x = ptl.x + Number(btn.xOff || 0);
    const y = ptl.y + Number(btn.yOff ?? -210);

    const w = Math.max(1, Number(btn.w || 160));
    const h = Math.max(1, Number(btn.h || 45));

    if (
      mouseWorld.x >= x - w / 2 &&
      mouseWorld.x <= x + w / 2 &&
      mouseWorld.y >= y - h / 2 &&
      mouseWorld.y <= y + h / 2
    ) {
      return ptl;
    }
  }

  return null;
}

function updatePortalButtonCursor(clientX, clientY) {
  const portals = getInteractivePortals();
  if (!portals.length) return false;

  const hoveredPortal = pickPortalButtonAtScreen(
    clientX,
    clientY
  );

  for (const ptl of portals) {
    ptl.buttonHovered = ptl === hoveredPortal;
  }

  if (hoveredPortal) {
    canvas.style.cursor = "pointer";
    return true;
  }

  return false;
}

function canUseStation(module) {
  return canUseFactionModule(module, (account.user || getCurrentUserFull())?.faction);
}

function isQuestModule(module) {
  return module?.questTerminal === true || String(module?.spr || "").startsWith("QUEST_");
}

function isTradeModule(module) {
  return module?.oreTrade === true;
}

// Bouclier : recharge passive par tick d'1 s (base + regen de formation),
// drain de formation par tick aussi — aucun regen continu nulle part.
let shieldTickT = 0;
function tickShield(dt) {
  if (player.dead || !(player.shMax > 0)) { shieldTickT = 0; return; }
  shieldTickT += Math.max(0, Number(dt) || 0);
  if (shieldTickT < 1.0) return;
  shieldTickT -= 1.0;
  const effects = getActiveDroneFormation(account.user).effects || {};
  const oldSh = player.sh;
  // ✅ Pas de régénération de base sous le feu : chaque coup reçu (hurtPlayer)
  // relance le même délai de 10 s que la réparation ; la base ne remonte que hors combat. Le drain de
  // formation reste appliqué même sous le feu (c'est un coût, pas un soin).
  // ✅ Regen de formation (ex Diamant +1 %/s) : s'applique QUOI QU'IL ARRIVE,
  // même sous le feu (seule une formation à drain la neutralise).
  const outOfCombat = !((player.attackedT || 0) > 0);
  const sregMult = playerBoosterMults().sreg;
  const repairMult = playerBoosterMults().repair;
  const regenPct = Number(effects.shieldRegenPct || 0);
  const perSecond = regenPct > 0 && !formationDrainsShield()
    ? Math.min(Number(effects.shieldRegenCap || Infinity), player.shMax * regenPct / 100)
    : 0;
  const baseRegen = (!formationDrainsShield() && outOfCombat)
    ? player.shMax * REPAIR.ratePct * repairMult * sregMult
    : 0;
  player.sh = Math.min(player.shMax, player.sh + baseRegen + perSecond);
  const drainPct = Number(effects.shieldDrainPct || 0);
  if (drainPct > 0) player.sh = Math.max(0, player.sh - player.shMax * drainPct / 100);
  const shGain = Math.round(player.sh - oldSh);
  if (shGain > 0) addPlayerCombatFloat(shGain, "rgba(70,180,255,0.98)", "+");
}

function tickDroneFormationEffects(dt) {
  tickShield(dt);
}

function getQuestButtonPosition(module) {
  // Base avec comptoir : les deux boutons côte à côte, centrés (quêtes à gauche).
  const shift = isTradeModule(module) ? QUEST_BUTTON.w / 2 + QUEST_BUTTON.gap / 2 : 0;
  return {
    x: module.x - shift,
    y: module.y - Number(module.h || 0) / 2 - QUEST_BUTTON.h / 2 - QUEST_BUTTON.gap,
  };
}

function pickQuestButtonAtScreen(clientX, clientY) {
  if (!isZoneMap || !zoneSafe?.modules?.length) return null;
  const mouseWorld = screenToWorld(clientX, clientY);

  for (let i = zoneSafe.modules.length - 1; i >= 0; i--) {
    const module = zoneSafe.modules[i];
    if (!isQuestModule(module) || !canUseStation(module)) continue;
    const pos = getQuestButtonPosition(module);

    if (
      mouseWorld.x >= pos.x - QUEST_BUTTON.w / 2 &&
      mouseWorld.x <= pos.x + QUEST_BUTTON.w / 2 &&
      mouseWorld.y >= pos.y - QUEST_BUTTON.h / 2 &&
      mouseWorld.y <= pos.y + QUEST_BUTTON.h / 2
    ) return module;
  }

  return null;
}

function updateQuestButtonCursor(clientX, clientY) {
  const hoveredModule = pickQuestButtonAtScreen(clientX, clientY);
  for (const module of zoneSafe?.modules || []) {
    if (isQuestModule(module)) module.questButtonHovered = module === hoveredModule;
  }
  if (hoveredModule) canvas.style.cursor = "pointer";
  return Boolean(hoveredModule);
}

function isPlayerNearBaseModule(module, extraMargin = 320) {
  // Le bouton flotte au-dessus de la base (parfois à 500+ px du centre
  // pour les grosses bases) : le joueur posé sur la base doit quand même
  // avoir accès au terminal / comptoir, sinon la fenêtre refuse de
  // s'ouvrir ou se referme aussitôt.
  if (!module) return false;
  const hw = Number(module.w || 0) / 2 + extraMargin;
  const hh = Number(module.h || 0) / 2 + extraMargin;
  return Math.abs(player.x - module.x) <= hw && Math.abs(player.y - module.y) <= hh;
}

function isPlayerNearQuestModule(module) {
  if (!module) return false;
  if (isPlayerNearBaseModule(module)) return true;
  const pos = getQuestButtonPosition(module);
  const radius = Number(QUEST_BUTTON.proximityRadius || 450);
  return dist2(player.x, player.y, pos.x, pos.y) <= radius * radius;
}

function getTradeButtonPosition(module) {
  if (Number.isFinite(Number(module?.tradeButtonX)) && Number.isFinite(Number(module?.tradeButtonY))) {
    return { x: Number(module.tradeButtonX), y: Number(module.tradeButtonY) };
  }
  // Base avec terminal de quêtes : bouton commerce à côté (à droite), paire centrée.
  if (isQuestModule(module)) {
    return {
      x: module.x + TRADE_BUTTON.w / 2 + TRADE_BUTTON.gap / 2,
      y: module.y - Number(module.h || 0) / 2 - TRADE_BUTTON.h / 2 - TRADE_BUTTON.gap,
    };
  }
  return {
    x: module.x,
    y: module.y - Number(module.h || 0) / 2 - TRADE_BUTTON.h / 2 - TRADE_BUTTON.gap,
  };
}

function pickTradeButtonAtScreen(clientX, clientY) {
  if (!isZoneMap || !zoneSafe?.modules?.length) return null;
  const mouseWorld = screenToWorld(clientX, clientY);

  for (let i = zoneSafe.modules.length - 1; i >= 0; i--) {
    const module = zoneSafe.modules[i];
    if (!isTradeModule(module) || !canUseStation(module)) continue;
    const pos = getTradeButtonPosition(module);

    if (
      mouseWorld.x >= pos.x - TRADE_BUTTON.w / 2 &&
      mouseWorld.x <= pos.x + TRADE_BUTTON.w / 2 &&
      mouseWorld.y >= pos.y - TRADE_BUTTON.h / 2 &&
      mouseWorld.y <= pos.y + TRADE_BUTTON.h / 2
    ) return module;
  }

  return null;
}

function updateTradeButtonCursor(clientX, clientY) {
  const hoveredModule = pickTradeButtonAtScreen(clientX, clientY);
  for (const module of zoneSafe?.modules || []) {
    if (isTradeModule(module)) module.tradeButtonHovered = module === hoveredModule;
  }
  if (hoveredModule) canvas.style.cursor = "pointer";
  return Boolean(hoveredModule);
}

// Survol NPC / P.E.T (même main que box, portails et terminaux).
function updateEnemyCursor(clientX, clientY) {
  let hovered = null;
  try {
    if (typeof pickEnemyAtScreen === "function") hovered = pickEnemyAtScreen(clientX, clientY);
  } catch {}
  if (hovered) canvas.style.cursor = "pointer";
  return Boolean(hovered);
}

function isPlayerNearTradeModule(module) {
  if (!module) return false;
  if (isPlayerNearBaseModule(module)) return true;
  const pos = getTradeButtonPosition(module);
  const radius = Number(TRADE_BUTTON.proximityRadius || 250);
  return dist2(player.x, player.y, pos.x, pos.y) <= radius * radius;
}

// Bouton Base de Combat : flotte au-dessus de la station (hub 350 ou base
// vide 334), même logique que les boutons quêtes/commerce.
function getCbsButtonPosition() {
  if (!zoneStation) return null;
  const baseH = zoneStation.hub ? 350 : 334;
  return {
    x: Number(zoneStation.x),
    y: Number(zoneStation.y) - baseH / 2 - CBS_BUTTON.h / 2 - CBS_BUTTON.gap,
  };
}

function stationOwnedByMyClan() {
  if (!zoneStation?.built) return false;
  const ownerClan = String(zoneStation?.owner?.clan || "").toUpperCase();
  if (!ownerClan) return false;
  try {
    return ownerClan === String(getMyClanTag() || "").toUpperCase();
  } catch {
    return false;
  }
}

function stationButtonAvailable() {
  if (!zoneStation) return false;
  let myClan = "";
  try { myClan = String(getMyClanTag() || "").toUpperCase(); } catch {}
  if (!myClan) return false;
  return !zoneStation.built || stationOwnedByMyClan();
}

function pickCbsButtonAtScreen(clientX, clientY) {
  if (!isZoneMap || !zoneStation) return null;
  if (!stationButtonAvailable()) return null;
  const pos = getCbsButtonPosition();
  if (!pos) return null;
  const mouseWorld = screenToWorld(clientX, clientY);
  if (
    mouseWorld.x >= pos.x - CBS_BUTTON.w / 2 &&
    mouseWorld.x <= pos.x + CBS_BUTTON.w / 2 &&
    mouseWorld.y >= pos.y - CBS_BUTTON.h / 2 &&
    mouseWorld.y <= pos.y + CBS_BUTTON.h / 2
  ) return zoneStation;
  return null;
}

function updateCbsButtonCursor(clientX, clientY) {
  if (!zoneStation) return false;
  zoneStation.cbsButtonHovered = pickCbsButtonAtScreen(clientX, clientY) === zoneStation;
  if (zoneStation.cbsButtonHovered) canvas.style.cursor = "pointer";
  return Boolean(zoneStation.cbsButtonHovered);
}

function isPlayerNearStation() {
  if (!zoneStation) return false;
  // Posé sur la station (demi-emprise 535 + petite marge) : le clic reste
  // valide même si le bouton flotte à ~250px au-dessus du hub.
  const hw = 535 + 60;
  const hh = 535 + 60;
  if (Math.abs(player.x - zoneStation.x) <= hw && Math.abs(player.y - zoneStation.y) <= hh) return true;
  const pos = getCbsButtonPosition();
  if (!pos) return false;
  const radius = Number(CBS_BUTTON.proximityRadius || 450);
  return dist2(player.x, player.y, pos.x, pos.y) <= radius * radius;
}

// Module commerce actif (fenêtre ouverte dessus). Fermeture si on s'éloigne.
let activeTradeModule = null;

function isTradeWindowAnchored() {
  // Cargo Trader (G-TRA) : vente hors base pendant la session.
  if (traWindowActive()) return true;
  if (!activeTradeModule) return false;
  if (!(zoneSafe?.modules || []).includes(activeTradeModule)) return false;
  return canUseStation(activeTradeModule) && isPlayerNearTradeModule(activeTradeModule);
}

canvas.addEventListener(
  "mousemove",
  (e) => {
    const overPortalButton = updatePortalButtonCursor(
      e.clientX,
      e.clientY
    );

    const overQuestButton = updateQuestButtonCursor(e.clientX, e.clientY);

    const overTradeButton = updateTradeButtonCursor(e.clientX, e.clientY);

    const overCbsButton = updateCbsButtonCursor(e.clientX, e.clientY);

    const overEnemy = updateEnemyCursor(e.clientX, e.clientY);

    if (!overPortalButton && !overQuestButton && !overTradeButton && !overCbsButton && !overEnemy) {
      updateCollectableCursor(e.clientX, e.clientY);
    }
  },
  { passive: true }
);

// Double-clic maison géré dans le pointerup (fiable sur cibles mobiles).
// Le dblclick natif est désactivé pour éviter les doubles attaques.
let lastClickAtMs = 0;
let lastClickEnemyId = null;
let lastClickX = 0;
let lastClickY = 0;
const DOUBLE_CLICK_MAX_MS = 350;
const DOUBLE_CLICK_MAX_DIST = 14;

const moveTarget = { active: false, x: 0, y: 0 };

const pointer = createPointerState();
const DRAG_THRESHOLD = 8;

function syncPhoneControls() {
  if (!phoneControls) return;
  const movingJoysticks = document.body.classList.contains("phoneJoystickLayoutOpen");
  phoneControls.configure(GAME_SETTINGS.phoneMode === true && started && !player.dead && !document.hidden,
    isPlayerMovementLocked() && !movingJoysticks);
}

function phoneAimTarget(angle) {
  const locked = Target.get();
  const candidates = spatialNpcsNear(player.x, player.y, playerRange);
  // Le joystick utilisait uniquement l'index spatial des NPC : les vaisseaux
  // réseau n'y figurent pas, contrairement au clic manuel.
  if (isSharedZone()) {
    try { candidates.push(...netPlayerProxies.values()); } catch {}
    try { candidates.push(...netPetProxies.values()); } catch {}
  }
  return pickPhoneAimTarget(player, candidates, angle, playerRange, enemy => {
    if (enemy?._netPlayer != null || enemy?._netPet != null) {
      // Même règle que le verrouillage manuel : un camouflage d'aptitude ou
      // une cible temporairement masquée par IEM ne peut pas être verrouillée.
      return enemy._netCloaked !== true && Number(enemy._netIemT || 0) <= 0;
    }
    return shouldDetectNpc(player, enemy, NPC_SENSOR_RANGES.visibility, locked);
  });
}

function releasePhoneAim(angle, ring = 0) {
  if (GAME_SETTINGS.phoneMode !== true || !started || player.dead || isPlayerMovementLocked()) return;
  // Centre = annulation ; couronne 1 = sélection ; couronne 2 = attaque.
  if (!(ring > 0) || !Number.isFinite(angle)) return;
  const target = phoneAimTarget(angle);
  if (!target || !(target.hp > 0) || target.isPetTarget) return;
  Target.set(target);
  try { botNotifyManual(); } catch {}
  if (ring >= 2) toggleAttack();
}

function releasePhoneQuickSlot(index) {
  if (GAME_SETTINGS.phoneMode !== true || !started || player.dead || isPlayerMovementLocked()) return;
  const slot = document.querySelectorAll("#ammoBar .actionSlots > .actionSlot")[Number(index)];
  const action = slot?.querySelector(".ammoBtn, .rocketQuickAction, .launcherAutoBtn");
  if (action) action.click();
}

function openPhoneDockEditor() {
  if (GAME_SETTINGS.phoneMode !== true || !started) return;
  try { window.__OPEN_PHONE_DOCK_EDITOR__?.(); } catch {}
}

function drawPhoneAim(ox, oy) {
  const angle = phoneControls?.aimAngle();
  if (!Number.isFinite(angle)) return;
  drawPhoneAimCone(ctx, player, angle, playerRange, phoneAimTarget(angle), ox, oy);
}

const phoneControlsRoot = document.getElementById("phoneControls");
if (phoneControlsRoot) {
  phoneControls = createPhoneControls(phoneControlsRoot, {
    onMoveStart() {
      cancelCollectableTarget();
      moveTarget.active = false;
      pointer.reset();
      try { botNotifyManual(); } catch {}
    },
    onMoveStop() {
      moveTarget.active = false;
      player.vx = 0;
      player.vy = 0;
    },
    onAimRelease: releasePhoneAim,
    onQuickRelease: releasePhoneQuickSlot,
  });
  const dockEditButton = document.getElementById("phoneQuickEditBtn");
  dockEditButton?.addEventListener("click", () => {
    if (document.body.classList.contains("phoneDockEditorOpen")) {
      try { window.__CLOSE_PHONE_DOCK_EDITOR__?.(); } catch {}
      dockEditButton.textContent = "Modifier le dock";
      return;
    }
    openPhoneDockEditor();
    if (document.body.classList.contains("phoneDockEditorOpen")) dockEditButton.textContent = "Sauvegarder";
  });
  const layoutButton = document.getElementById("phoneJoystickLayoutBtn");
  const sizeControls = [...document.querySelectorAll(".phoneJoystickSizeControl[data-phone-size]")];
  sizeControls.forEach(control => control.querySelector("input")?.addEventListener("input", event => {
    const name = control.dataset.phoneSize;
    phoneControls.setLayoutScale(name, event.target.value);
    const output = control.querySelector("output");
    if (output) output.textContent = `${event.target.value} %`;
  }));
  const resetPhoneJoystickLayout = () => {
    phoneControls.resetLayout();
    try { window.__RESET_PHONE_ACTION_LAYOUT__?.(); } catch {}
    sizeControls.forEach(control => {
      const input = control.querySelector("input"), output = control.querySelector("output");
      if (input) input.value = "100";
      if (output) output.textContent = "100 %";
    });
    showToast("Joysticks réinitialisés", 1.2);
  };
  document.getElementById("phoneJoystickResetBtn")?.addEventListener("click", resetPhoneJoystickLayout);
  document.getElementById("btnResetPhoneJoysticks")?.addEventListener("click", resetPhoneJoystickLayout);
  layoutButton?.addEventListener("click", () => {
    const opening = !document.body.classList.contains("phoneJoystickLayoutOpen");
    if (opening) {
      try { window.__CLOSE_PHONE_ACTION_TRAY__?.(); } catch {}
      moveTarget.active = false;
      player.vx = 0;
      player.vy = 0;
      try { stopAttack(); } catch {}
      try { phoneControls.cancel(); } catch {}
    }
    document.body.classList.toggle("phoneJoystickLayoutOpen", opening);
    phoneControls.setLayoutEditing(opening);
    try { window.__SET_PHONE_ACTION_LAYOUT_EDITING__?.(opening); } catch {}
    if (opening) sizeControls.forEach(control => {
      const input = control.querySelector("input"), output = control.querySelector("output");
      const value = String(phoneControls.layoutScale(control.dataset.phoneSize));
      if (input) input.value = value;
      if (output) output.textContent = `${value} %`;
    });
    layoutButton.textContent = opening ? "Sauvegarder" : "Déplacer";
    syncPhoneControls();
  });
}
// Mode téléphone : bloque le menu d'appui long ("Ouvrir dans un nouvel
// onglet", aperçu de lien...) quand on garde le doigt appuyé en jeu.
// Champs texte exclus pour garder copier/coller. Bureau inchangé.
document.addEventListener("contextmenu", (event) => {
  try {
    if (!document.querySelector("#phoneControls:not([hidden])")) return;
    if (event.target?.closest?.("input, select, textarea, [contenteditable='true']")) return;
    event.preventDefault();
  } catch {}
});

// ✅ Position souris écran mémorisée
function rememberPointer(e) {
  pointer.remember(e);
}

function setMoveTargetFromScreen(clientX, clientY) {
  if (isPlayerMovementLocked()) return;
  // ✅ Tout clic manuel sur la map annule l'ordre de collecte
  cancelCollectableTarget();
  try { botNotifyManual(); } catch {}

  const w = screenToWorld(clientX, clientY);
  // La destination ne traverse jamais un mur : elle s'arrête à la bordure
  // du premier mur traversé (marge = rayon du vaisseau).
  let dest = { x: w.x, y: w.y };
  try {
    if (isZoneMap && Array.isArray(zoneWalls) && zoneWalls.length && !player.dead) {
      dest = clampSegmentToWalls(player.x, player.y, w.x, w.y, zoneWalls, player.r || 18);
    }
  } catch {}
  moveTarget.active = true;
  moveTarget.x = dest.x;
  moveTarget.y = dest.y;
}

function setMoveTargetFromEvent(e) {
  rememberPointer(e);
  setMoveTargetFromScreen(e.clientX, e.clientY);
}

// Repli pour les navigateurs qui annulent le cycle pointer du bouton droit
// en ouvrant leur menu contextuel. Le bouton droit sélectionne les cibles et
// collectables, mais ne donne jamais d'ordre de déplacement dans le vide.
window.__ORBIT_RIGHT_CLICK_AS_LEFT__ = (clientX, clientY) => {
  if (!started || player.dead || isPlayerMovementLocked()) return false;
  const enemy = pickEnemyAtScreen(clientX, clientY);
  if (enemy) {
    Target.set(enemy);
    try { botNotifyManual(); } catch {}
    return true;
  }
  const collectable = pickCollectableAtScreen(clientX, clientY);
  if (collectable) {
    selectCollectable(collectable);
    try { botNotifyManual(); } catch {}
    return true;
  }
  return false;
};

// ✅ Recalcule la cible chaque frame tant que le clic est maintenu
function refreshHoldMoveTarget() {
  if (!pointer.down) return;
  if (!pointer.followWhileDown) return;
  if (pointer.downOnEnemy) return;
  if (player.dead) return;
  if (!started) return;

  setMoveTargetFromScreen(pointer.clientX, pointer.clientY);
}

canvas.addEventListener(
  "pointerdown",
  (e) => {
    SFX.resume();

    // Le clic droit utilise les mêmes interactions monde que le clic gauche.
    if (e.button !== 0 && e.button !== 2) return;
    if (e.button === 2 && e.cancelable) e.preventDefault();

    // Le toucher est gere par le jeu : pas de selection native du canvas.
    if (e.pointerType === "touch" && e.cancelable) e.preventDefault();

pointer.begin(e);

    canvas.setPointerCapture(e.pointerId);

    const portalButton = pickPortalButtonAtScreen(
  e.clientX,
  e.clientY
);

if (portalButton) {
  portalButton.buttonPressed = true;
  portalButton.buttonHovered = true;

  pointer.dragArmed = false;
  pointer.dragging = false;
  pointer.downOnEnemy = false;
  pointer.followWhileDown = false;

  return;
}

const questButton = pickQuestButtonAtScreen(e.clientX, e.clientY);

if (questButton) {
  questButton.questButtonPressed = true;
  questButton.questButtonHovered = true;
  pointer.dragArmed = false;
  pointer.dragging = false;
  pointer.downOnEnemy = false;
  pointer.followWhileDown = false;
  return;
}

const tradeButton = pickTradeButtonAtScreen(e.clientX, e.clientY);

if (tradeButton) {
  tradeButton.tradeButtonPressed = true;
  tradeButton.tradeButtonHovered = true;
  pointer.dragArmed = false;
  pointer.dragging = false;
  pointer.downOnEnemy = false;
  pointer.followWhileDown = false;
  return;
}

const cbsButton = pickCbsButtonAtScreen(e.clientX, e.clientY);

if (cbsButton) {
  cbsButton.cbsButtonPressed = true;
  cbsButton.cbsButtonHovered = true;
  pointer.dragArmed = false;
  pointer.dragging = false;
  pointer.downOnEnemy = false;
  pointer.followWhileDown = false;
  return;
}

   const enemy = pickEnemyAtScreen(e.clientX, e.clientY);
  // ✅ On lock le NPC
  // ✅ Mais on ne touche PAS à l'ordre de collecte de box
  try {
    if (netPlayerProxies.size) console.info("[pick] clic:", enemy ? (enemy._netPlayer ? `joueur:${enemy._netPlayer}` : `npc:${enemy.type}`) : "rien");
  } catch {}
if (enemy) {
  Target.set(enemy);
  try { botNotifyManual(); } catch {}
  try {
    // Clic sur le vaisseau d'un joueur : pré-remplit l'ajout d'ami
    // et l'invitation d'escadrille avec son pseudo.
    const rid = enemy._netPlayer != null ? String(enemy._netPlayer) : "";
    if (rid) {
      let rpseudo = "";
      try { rpseudo = String(getNetplayRemotes().get(rid)?.pseudo || "").slice(0, 20); } catch {}
      if (rpseudo) {
        const fi = document.getElementById("friendAddInput");
        if (fi) fi.value = rpseudo;
        const gi = document.getElementById("groupInviteInput");
        if (gi) gi.value = rpseudo;
      }
    }
  } catch {}

  pointer.downOnEnemy = true;
  pointer.dragArmed = false;
  pointer.dragging = false;
  pointer.followWhileDown = false;

  return;
}

const collectable = pickCollectableAtScreen(e.clientX, e.clientY);
if (collectable) {

  selectCollectable(collectable);
  try { botNotifyManual(); } catch {}

  pointer.dragArmed = false;
  pointer.dragging = false;
  pointer.downOnEnemy = false;
  pointer.followWhileDown = false;

  return;
}
if (e.button === 2) {
  pointer.dragArmed = false;
  pointer.dragging = false;
  pointer.followWhileDown = false;
  return;
}
cancelCollectableTarget();
pointer.followWhileDown = true;
setMoveTargetFromEvent(e);
  },
  { passive: false }
);

canvas.addEventListener(
  "pointermove",
  (e) => {
    rememberPointer(e);

    if (!pointer.down || !pointer.dragArmed || pointer.downOnEnemy) return;

    const dx = e.clientX - pointer.dragStartX;
    const dy = e.clientY - pointer.dragStartY;

    if (!pointer.dragging) {
      if (dx * dx + dy * dy < DRAG_THRESHOLD * DRAG_THRESHOLD) return;
      pointer.dragging = true;
    }

    pointer.followWhileDown = true;
    setMoveTargetFromEvent(e);
  },
  { passive: false }
);

canvas.addEventListener(
  "pointerup",
  (e) => {
    const releasedOnPortal = pickPortalButtonAtScreen(
      e.clientX,
      e.clientY
    );
    const releasedOnQuest = pickQuestButtonAtScreen(e.clientX, e.clientY);
    const releasedOnTrade = pickTradeButtonAtScreen(e.clientX, e.clientY);
    const releasedOnCbs = pickCbsButtonAtScreen(e.clientX, e.clientY);

    let pressedPortal = null;

    for (const ptl of getInteractivePortals()) {
      if (ptl.buttonPressed) {
        pressedPortal = ptl;
      }

      ptl.buttonPressed = false;
    }

    let pressedQuest = null;
    for (const module of zoneSafe?.modules || []) {
      if (module.questButtonPressed) pressedQuest = module;
      module.questButtonPressed = false;
    }

    let pressedTrade = null;
    for (const module of zoneSafe?.modules || []) {
      if (module.tradeButtonPressed) pressedTrade = module;
      module.tradeButtonPressed = false;
    }

    // Le clic doit être relâché sur le même bouton
    if (
      pressedPortal &&
      releasedOnPortal === pressedPortal
    ) {
      const spr = getPortalSpriteSet(pressedPortal);
      const btn = spr.jumpButton;

      const requireNear = btn?.requireNear !== false;
      const nearEnough = isPlayerNearPortal(pressedPortal);

      if (pressedPortal.jumping) {
        // Le portail est déjà en train de sauter
      } else if (mapPortalLock > 0) {
        showToast("Portail temporairement indisponible", 1);
      } else if (requireNear && !nearEnough) {
        showToast("Approche-toi du portail", 1.2);
      } else {
        if (!isZoneMap && pressedPortal === portal) {
          startGatePortalJump(portal, "continue");
        } else if (!isZoneMap && pressedPortal === gateReturnPortal) {
          startGatePortalJump(gateReturnPortal, "return");
        } else {
          startZonePortalJump(pressedPortal);
        }
      }
    }

    if (pressedQuest && releasedOnQuest === pressedQuest) {
      if (!isPlayerNearQuestModule(pressedQuest)) {
        showToast("Approche-toi du bâtiment de quêtes", 1.4);
      } else {
        openQuestTerminal();
      }
    }

    if (pressedTrade && releasedOnTrade === pressedTrade) {
      if (!isPlayerNearTradeModule(pressedTrade)) {
        showToast("Approche-toi du comptoir", 1.4);
      } else {
        openOreTradeWindow(pressedTrade);
      }
    }

    if (zoneStation?.cbsButtonPressed) {
      const pressedStation = zoneStation;
      zoneStation.cbsButtonPressed = false;
      if (releasedOnCbs === pressedStation) {
        openStationWindow();
      }
    }

    // Double-clic maison (fiable sur cibles mobiles) : 2 relâchés sur le même
    // ennemi à moins de 350 ms ET à moins de 14 px l'un de l'autre ->
    // verrouille + attaque. Pas de re-visée. Désactivable dans Général.
    if (e.button === 0 && !e.shiftKey && GAME_SETTINGS.doubleClickAttack !== false) {
      const nowMs = performance.now();
      const releasedEnemy = pickEnemyAtScreen(e.clientX, e.clientY);
      if (releasedEnemy && releasedEnemy.hp > 0 && lastClickEnemyId === releasedEnemy.id && nowMs - lastClickAtMs < DOUBLE_CLICK_MAX_MS) {
        const mdx = e.clientX - lastClickX, mdy = e.clientY - lastClickY;
        if (mdx * mdx + mdy * mdy <= DOUBLE_CLICK_MAX_DIST * DOUBLE_CLICK_MAX_DIST) {
          lastClickAtMs = 0;
          lastClickEnemyId = null;
          Target.set(releasedEnemy);
          stopAttack();
          startAttack();
        } else {
          lastClickAtMs = nowMs;
          lastClickX = e.clientX;
          lastClickY = e.clientY;
          lastClickEnemyId = releasedEnemy.id;
        }
      } else if (releasedEnemy && releasedEnemy.hp > 0) {
        lastClickAtMs = nowMs;
        lastClickX = e.clientX;
        lastClickY = e.clientY;
        lastClickEnemyId = releasedEnemy.id;
      } else {
        lastClickAtMs = 0;
        lastClickEnemyId = null;
      }
    }

    pointer.reset();

    try {
      canvas.releasePointerCapture(e.pointerId);
    } catch {}
  },
  { passive: false }
);

canvas.addEventListener(
  "pointercancel",
  (e) => {
    pointer.reset();

    for (const ptl of getInteractivePortals()) {
      ptl.buttonPressed = false;
      ptl.buttonHovered = false;
    }

    for (const module of zoneSafe?.modules || []) {
      module.questButtonPressed = false;
      module.questButtonHovered = false;
      module.tradeButtonPressed = false;
      module.tradeButtonHovered = false;
    }
    if (zoneStation) {
      zoneStation.cbsButtonPressed = false;
      zoneStation.cbsButtonHovered = false;
    }

    try {
      canvas.releasePointerCapture(e.pointerId);
    } catch {}
  },
  { passive: true }
);

