// ============================================================
// Entities
// ============================================================
const bullets = [];
const enemyBullets = [];
const enemies = [];

// ============================================================
// Univers persistant (SIM pure, serveur-ready) : horloge qui ne
// s'arrete jamais + slots stables par camp. Le client ne decide
// plus de regen : il lit l'univers et marque mort/vivant.
// ============================================================
function createBrowserStorage() {
  try {
    if (typeof localStorage === "undefined") return null;
    return {
      getItem: (k) => localStorage.getItem(k),
      setItem: (k, v) => localStorage.setItem(k, v),
    };
  } catch {
    return null;
  }
}
const universeStorage = createBrowserStorage();
const worldClock = createWorldClock({ storage: universeStorage });
let universe = createUniverse();
try {
  universe = deserializeUniverse(universeStorage?.getItem?.(UNIVERSE_KEY));
} catch {
  universe = createUniverse();
}
// Rattrapage au boot : un refresh de 30s fait avancer le monde de 30s
// (respawns dus pendant l'absence), jamais de re-roll.
// Seules les maps zone vivent en fond : les instances GG (alpha/beta/gamma,
// mode "gate") ne sont pas stockees dans l'univers. La map active est
// ignoree : c'est sa vraie IA qui tourne.
try {
  tickBackground(universe, worldClock.now(), { skipMapId: String(window.__CURRENT_MAP_ID__ || "") });
} catch {}
// Tick de fond continu : toutes les 5s les maps sans joueur avancent
// (respawns dus + derive bornee). Throttle dans persistUniverse.
try {
  if (typeof window !== "undefined" && !window.__UNIVERSE_BG_TICK__) {
    window.__UNIVERSE_BG_TICK__ = true;
    let persistBackgroundCollectables = false;
    setInterval(() => {
      try {
        // Multi : les zones partagees sont entierement simulees par le
        // serveur (npcSims + npc_respawns.json). Le tick monde de fond
        // (cartes hors ecran) ne sert plus en mode net. En instance privee
        // la persistance continue (elle saute d'elle-meme en zone partagee).
        const net = netActive();
        // Zone partagée : seuls les drops personnels (Sun Box, cargos...)
        // restent à sauvegarder localement.
        if (net && isSharedZone()) { persistCollectables(); return; }
        if (!net) tickBackground(universe, worldClock.now(), { skipMapId: String(window.__CURRENT_MAP_ID__ || "") });
        // Ne jamais sérialiser le monde et les collectables dans le même
        // passage : deux gros JSON/localStorage consécutifs créent un pic
        // visible sur mobile. Chaque store reste sauvegardé toutes les 10 s.
        if (persistBackgroundCollectables) persistCollectables();
        else persistUniverse();
        persistBackgroundCollectables = !persistBackgroundCollectables;
      } catch {}
    }, 5000);
  }
} catch {}
const persistUniverse = createDeferredPersistence(force => {
  // Multi : serveur autorite sur les zones partagees, rien a persister ici.
  try { if (netActive() && isSharedZone()) return; } catch {}
  worldClock.markTick({ force });
  try {
    measureGameTask("persistUniverse", () => universeStorage?.setItem?.(UNIVERSE_KEY, serializeUniverse(universe)));
  } catch {}
}, { now: () => worldClock.now() });
// Monde continu collectables : même rythme que l'univers (5 s, force au quit).
let collectableStore = createCollectableStore();
try {
  collectableStore = deserializeCollectableStore(universeStorage?.getItem?.(COLLECTABLE_STORE_KEY));
} catch {
  collectableStore = createCollectableStore();
}
// Toujours écrit, multi compris : les box partagées (syncNetBoxes) ne passent
// jamais par ce store, mais les drops personnels (Sun Box, cargos...) n'existent
// QUE là. Sauter l'écriture en zone partagée les perdait au moindre refresh
// (ex. redémarrage serveur = rechargement automatique de la page).
const persistCollectables = createDeferredPersistence(() => {
  try {
    measureGameTask("persistCollectables", () => universeStorage?.setItem?.(COLLECTABLE_STORE_KEY, serializeCollectableStore(collectableStore)));
  } catch {}
}, { now: () => worldClock.now() });
// ✅ Purge des ressources d'une Galaxy Gate terminée/perdue : supprime les
// collectables non ramassés (cargos + assemblage) en mémoire ET dans le
// store persisté. Évite l'accumulation quand on enchaîne les runs
// (ex : 10 alpha d'affilée = map blindée sinon).
function purgeGateCollectables(gateId) {
  const id = String(gateId || "").trim().toLowerCase();
  if (!id) return 0;
  let removed = 0;
  try {
    for (let i = collectables.length - 1; i >= 0; i--) {
      const c = collectables[i];
      if (!c) continue;
      if (String(c.map || currentMapId()).trim().toLowerCase() !== id) continue;
      if (collectableTargetId === c.id) collectableTargetId = null;
      collectables.splice(i, 1);
      removed++;
    }
  } catch {}
  try {
    removed += clearCollectableMap(collectableStore, id);
  } catch {}
  try {
    persistCollectables({ force: true });
  } catch {}
  return removed;
}
function snapshotActiveEnemiesToUniverse(mapId) {
  if (!isZoneMap) return;
  const nowMs = worldClock.now();
  for (const e of enemies) {
    if (!e || e.hp <= 0 || !e.universeUid) continue;
    const hpPct = e.hpMax > 0 ? e.hp / e.hpMax : 1;
    const shPct = e.shMax > 0 ? e.sh / e.shMax : (e.sh > 0 ? 1 : 0);
    try {
      snapshotUniverseEnemy(universe, mapId, e.universeUid, { x: e.x, y: e.y, hpPct, shPct }, nowMs);
    } catch {}
  }
}
const escortShips = [];
const pickups = [];
const collectables = [];
const npcSpatialIndex = new SpatialIndex(700);
const collectableSpatialIndex = new SpatialIndex(700);
let npcSpatialFrame = -1;
let collectableSpatialLength = -1;
let collectableSpatialDirty = true;

function refreshNpcSpatialIndex() {
  const frame = Math.floor(performance.now() / 16);
  if (frame === npcSpatialFrame) return;
  npcSpatialFrame = frame;
  npcSpatialIndex.rebuild(enemies);
}

function refreshCollectableSpatialIndex() {
  if (!collectableSpatialDirty && collectableSpatialLength === collectables.length) return;
  collectableSpatialLength = collectables.length;
  collectableSpatialDirty = false;
  collectableSpatialIndex.rebuild(collectables);
}

function invalidateCollectableSpatialIndex() {
  collectableSpatialDirty = true;
}

function indexCollectableAdded(c) {
  if (collectableSpatialDirty || !c) return;
  collectableSpatialIndex.add(c);
  collectableSpatialLength = collectables.length;
}

function indexCollectableRemoved(c) {
  if (collectableSpatialDirty || !c) return;
  collectableSpatialIndex.delete(c);
  collectableSpatialLength = collectables.length;
}

function indexCollectableMoved(c) {
  if (collectableSpatialDirty || !c) return;
  collectableSpatialIndex.update(c);
}

function spatialNpcsInRect(minX, minY, maxX, maxY) {
  refreshNpcSpatialIndex();
  return npcSpatialIndex.queryRect(minX, minY, maxX, maxY);
}

function spatialNpcsNear(x, y, radius) {
  refreshNpcSpatialIndex();
  return npcSpatialIndex.queryCircle(x, y, radius);
}

function nearestSpatialNpc(x, y, predicate, maxRadius = 0) {
  const limit = maxRadius > 0 ? maxRadius : Math.hypot(WORLD.w, WORLD.h);
  let radius = Math.min(700, limit);
  while (radius > 0) {
    let best = null, bestD2 = Infinity;
    for (const item of spatialNpcsNear(x, y, radius)) {
      if (!predicate(item)) continue;
      const d2 = dist2(x, y, item.x, item.y);
      if (d2 < bestD2) { best = item; bestD2 = d2; }
    }
    if (best || radius >= limit) return best ? { item: best, d2: bestD2 } : null;
    radius = Math.min(limit, radius * 2);
  }
  return null;
}

function spatialCollectablesInRect(minX, minY, maxX, maxY) {
  refreshCollectableSpatialIndex();
  return collectableSpatialIndex.queryRect(minX, minY, maxX, maxY);
}

function spatialCollectablesNear(x, y, radius) {
  refreshCollectableSpatialIndex();
  return collectableSpatialIndex.queryCircle(x, y, radius);
}

function nearestSpatialCollectable(x, y, predicate, maxRadius = 0) {
  const limit = maxRadius > 0 ? maxRadius : Math.hypot(WORLD.w, WORLD.h);
  let radius = Math.min(700, limit);
  while (radius > 0) {
    let best = null, bestD2 = Infinity;
    for (const item of spatialCollectablesNear(x, y, radius)) {
      if (!predicate(item)) continue;
      const d2 = dist2(x, y, item.x, item.y);
      if (d2 < bestD2) { best = item; bestD2 = d2; }
    }
    if (best || radius >= limit) return best ? { item: best, d2: bestD2 } : null;
    radius = Math.min(limit, radius * 2);
  }
  return null;
}
const sparks = [];
const healerPulses = [];
// Pulsations de halo génériques (pod Aegis, bouées pet) : même visuel que
// le soigneur via drawHaloPulse, avec leurs propres couleurs.
