// ============================================================
// Laser
// ============================================================
const LASER = {
  chance: 1,
  minCd: 3.0,
  maxCd: 5.0,
  lenExtra: -300,
  width: 30,
  hitWidth: 30,
  baseDmg: 20000,
  falloff: 0.8,
  visualExtraLen: 900,
  hitExtraLen: 900,
};

let laserCd = 2.0;

function maybeTriggerLaser() {
  return; // Raygun supprimé : ni visuel ni dégâts.
}

function spawnLaser(x, y, ang, targetId) {
  return; // Raygun supprimé : ni visuel ni dégâts.
}

// ============================================================
// Shooting (attaque continue sans maintenir)
// ============================================================
let attackActive = false;

// Suivi de portée laser pendant l'attaque : true = à portée (combat),
// false = hors de portée, null = pas d'attaque en cours.
// Les notifs ne partent que sur transition → jamais de spam, même en continu.
let laserCombatInRange = null;
// Surveillance d'évasion : attaque arrêtée en plein combat, on guette la
// sortie de portée pour annoncer "Vous avez échappé à l'attaque !".
let escapeWatch = null;

// Anti-spam des notifs manuelles répétées (clic / CTRL).
let laserRangeNotifyLast = -10;
function notifyLaserRange(text, type) {
  const now = (typeof performance !== "undefined" ? performance.now() : Date.now()) / 1000;
  if (now - laserRangeNotifyLast < 1.5) return false;
  laserRangeNotifyLast = now;
  showNotification(text, 1.5, type);
  return true;
}

// "Hors de portée" : Out_Of_Range joué 3x en enchaîné (le suivant démarre
// quand le précédent atteint 50 % de sa durée).
// La suite est annulée si on rentre en combat ou si l'attaque s'arrête entre-temps.
let outOfRangeSeq = 0;
function playOutOfRangeTriple() {
  const seq = ++outOfRangeSeq;
  const buffered = SFX?.buffers?.outOfRange?.duration;
  const gapMs = Number.isFinite(buffered) && buffered > 0 ? Math.round((buffered * 1000) / 2) : 250;
  SFX?.play?.("outOfRange");
  for (let i = 1; i < 3; i++) {
    window.setTimeout(() => {
      if (seq !== outOfRangeSeq) return; // relance plus récente
      if (!attackActive) return; // attaque arrêtée entre-temps
      if (laserCombatInRange === true) return; // rentré en combat entre-temps
      SFX?.play?.("outOfRange");
    }, i * gapMs);
  }
}

function isLaserTargetOutOfRange(t) {
  if (!t) return false;
  return dist2(player.x, player.y, t.x, t.y) > playerRange * playerRange;
}

// Annonce immédiate au déclenchement manuel : "Le combat a commencé."
// à portée, "Cible hors de portée." sinon (comme roquettes / lance-roquettes).
function announceLaserCombatRange(t) {
  const out = isLaserTargetOutOfRange(t);
  laserCombatInRange = !out;
  escapeWatch = null;
  if (out) {
    if (notifyLaserRange("Cible hors de portée.", "error")) playOutOfRangeTriple();
  } else notifyLaserRange("Le combat a commencé.", "info");
}

function cancelOwnStationAttack(target, notify = true) {
  if (!target?._stationTarget || !stationOwnedByMyClan()) return false;
  attackActive = false;
  laserCombatInRange = null;
  clearPendingSalvo({ keepQa: true });
  if (notify) showToast("Tu ne peux pas attaquer la base de ton clan", 1.5);
  return true;
}

function startAttack(ammoOverride = null) {
  const currentAmmo = player.ammo.active || "x1";

  if (ammoOverride && attackActive && ammoOverride === currentAmmo) {
    stopAttack();
    return;
  }
  // Changement de munition en plein combat : pas de nouvelle annonce,
  // tickAutoAttack suit déjà les transitions de portée.
  const wasAttackActive = attackActive;

  if (!ammoOverride) {
    if (attackActive) {
      stopAttack();
      return;
    }
    if (player.dead || !started) return;
    const t = Target.get();
    if (!t) return;
    if (cancelOwnStationAttack(t)) return;
    // ZNA : si l'un des deux est en zone de non-agression, l'attaque ne
    // démarre même pas (pas d'attackActive -> la ZNA reste active).
    if (netPvpBlocked(t)) return;
    attackActive = true;
    announceLaserCombatRange(t);
    const fired = tryFireOnce(null, true);
    // Vrai tir encore en cooldown (ex. switch après un kill) : on affiche
    // des faux tirs jusqu'au vrai tir, aucun trou visuel.
    if (!fired) { try { scheduleSwitchDecoys(t); } catch {} }
    return;
  }

  // Les rafales deja lancees gardent leur munition et leur cadence,
  // y compris la QA. La selection ne concerne que les prochains vrais tirs.
  const switchingToRsbLike = isRsbLike(ammoOverride);

  if (ammoOverride) setAmmo(ammoOverride);

  if (player.dead || !started) return;

  const t = Target.get();
  if (!t) return;
  if (cancelOwnStationAttack(t)) return;

  // ZNA : attaque impossible si l'un des deux est en zone de non-agression.
  if (netPvpBlocked(t)) return;

  // ✅ salve rapide indisponible : l'attaque reste active mais visuellement
  // rien ne part jusqu'à la fin du cooldown, où la salve se déclenche d'elle-même.
  if (switchingToRsbLike && rsbLikeCooldown(ammoOverride) > 0) {
    attackActive = true;
    if (!wasAttackActive) announceLaserCombatRange(t);
    return;
  }

  attackActive = true;
  if (!wasAttackActive) announceLaserCombatRange(t);
  const firedAmmo = tryFireOnce(null, true);
  if (!firedAmmo) { try { scheduleSwitchDecoys(t); } catch {} }
}

function stopAttack() {
  // Arrêt en plein combat : on surveille les sorties de portée (évasion).
  // Réarmé à chaque retour à portée → le message revient à chaque sortie.
  const t = laserCombatInRange === true ? Target.get() : null;
  escapeWatch = t ? { targetId: t.id, wasIn: true } : null;
  attackActive = false;
  laserCombatInRange = null;
  clearPendingSalvo({ keepQa: true });
}

function toggleAttack() {
  if (attackActive) stopAttack();
  else startAttack();
}

// ============================================================
// Roquettes (tir manuel façon DarkOrbit, lanceur natif au vaisseau)
// ============================================================
function activeRocket() {
  return getRocketType(player.rocketActive) || getRocketType("r310");
}

function activeFormationEffects() {
  return getActiveDroneFormation(account.user)?.effects || {};
}

function formationRocketDamageMult() {
  return Math.max(0, 1 + (Number(activeFormationEffects().rocketDamagePct || 0) + Number(player.droneDamageBonusPct || 0)) / 100);
}

function formationRocketCooldownMult() {
  return Math.max(0.05, 1 + Number(activeFormationEffects().rocketCooldownPct || 0) / 100);
}

// Cadence de tir laser (formations type Polygone) : +100 % => x2.
function formationFireRateMult() {
  return Math.max(0.05, 1 + Number(activeFormationEffects().fireRatePct || 0) / 100);
}

// Vitesse visuelle des tirs laser (Polygone : -50 % => 2000 au lieu de 4000).
function formationBulletSpeedMult() {
  return Math.max(0.05, 1 + Number(activeFormationEffects().bulletSpeedPct || 0) / 100);
}

// Portée d'attaque (Polygone : portée fixée à 600 au lieu de 700).
function formationRangeOverride() {
  const v = Number(activeFormationEffects().rangeOverride || 0);
  return v > 0 ? v : 0;
}

// Nombre d'éclairs affichés par salve (le 1er = vrai tir, les suivants =
// faux tirs esthétiques dmg 0) : divisé par la cadence pour garder un nombre
// de faux tirs standard par seconde (Polygone x2 => moitié moins par salve).
function salvoShotCount(ammoKey) {
  const base = isRsbLike(ammoKey) ? 12 : 6;
  return Math.max(1, Math.round(base / formationFireRateMult()));
}

function formationNpcDamageMult(target) {
  const isNpc = target && !target._netPlayer && !target._netPet;
  return isNpc ? Math.max(0, 1 + Number(activeFormationEffects().npcDamagePct || 0) / 100) : 1;
}

function formationPlayerLaserDamageMult(target) {
  return target?._netPlayer
    ? Math.max(0, 1 + Number(activeFormationEffects().playerLaserDamagePct || 0) / 100)
    : 1;
}

// Modules roulette dégâts ciblés (équipés sur le hangar actif) :
// Dég. NPC -> lasers + roquettes vs NPC (ni joueurs, ni pets, ni JPC, ni stations) ;
// Dég. PvP -> lasers + roquettes vs joueurs ET bots JPC (faux joueurs) ;
// Dég. Roquettes -> toutes les roquettes. Cumul additif, jamais négatif.
function moduleNpcDamageMult(target) {
  const isNpc = target && target._netPlayer == null && target._netPet == null
    && target.isJpcBot !== true && !target._stationTarget;
  return isNpc ? Math.max(0, 1 + Number(player.bonusNpcDmgPct || 0) / 100) : 1;
}

function modulePvpDamageMult(target) {
  const isPvp = target?._netPlayer != null || target?.isJpcBot === true;
  return isPvp
    ? Math.max(0, 1 + Number(player.bonusPvpDmgPct || 0) / 100)
    : 1;
}

function moduleRocketDamageMult() {
  return Math.max(0, 1 + Number(player.bonusRocketDmgPct || 0) / 100);
}

function rocketCount(id = player.rocketActive) {
  const key = String(id || "r310").toLowerCase();
  return Math.max(0, Math.floor(Number(player.rockets?.[key] || 0)));
}

function tryFireRocket(opts = {}) {
  const silent = opts.auto === true;
  const notify = (text, dur, type) => { if (!silent) showNotification(text, dur, type); };
  if (player.dead || !started) return false;
  const rocket = activeRocket();
  // Standards uniquement : les lance-roquettes passent par le bouton USE (salves).
  if (rocket.manual === false) {
    notify("Roquette de lance-roquettes — bouton USE.", 2, "error");
    return false;
  }
  if (rocketCount(rocket.id) <= 0) {
    // Bascule auto vers un type standard possédé (sauf tir strict : la sélection).
    if (!opts.strict) {
      const fallback = ROCKET_IDS.filter((id) => getRocketType(id)?.manual !== false).find((id) => rocketCount(id) > 0);
      if (fallback) {
        player.rocketActive = fallback;
        markProgressDirty();
        refreshRocketPaletteCounts();
        updateAmmoUI();
        // Bascule visible : une seule notification par changement (pas de spam
        // en mode AUTO, les tirs suivants utilisent déjà la nouvelle sélection).
        showNotification(`Bascule auto : ${getRocketType(fallback)?.name || fallback} (plus de ${rocket?.name || "roquettes"}).`, 2.5, "info");
        return tryFireRocket(opts);
      }
    }
    notify("Plus de roquettes — boutique > Roquettes.", 2.5, "error");
    return false;
  }
  if (rocketCooldownLeft(rocket.id) > 0) return false;

  const t = Target.get();
  if (!t) return false;
  if (cancelOwnStationAttack(t, !silent)) return false;

  if (netPvpBlocked(t)) return false;

  const d2 = dist2(player.x, player.y, t.x, t.y);
  if (d2 > playerRange * playerRange) {
    notify("Cible hors de portée.", 1.5, "error");
    return false;
  }

  player.angle = Math.atan2(t.y - player.y, t.x - player.x);

  SFX.play("sfx_shot_roquettes", { cooldown: 0.05, cut: true });

  player.rockets[rocket.id] = rocketCount(rocket.id) - 1;
  noteNetConsumption("rockets", rocket.id, 1);
  mirrorConsumedStock("rockets", rocket.id, player.rockets[rocket.id]);
  const personalCooldown = personalRocketCooldownFor(rocket.id);
  if (personalCooldown > 0) {
    personalRocketCooldowns.set(String(rocket.id).toLowerCase(), personalCooldown);
  } else {
    rocketCooldownMax = (rocket?.cooldown || 1.0) * formationRocketCooldownMult();
    rocketCooldown = rocketCooldownMax;
  }
  // Arme comme les lasers : lève la zone de non-agression pendant 5 s.
  player.combatT = 5.0;
  markProgressDirty();
  updateAmmoUI();

  // Tir réel : toute attaque casse le camouflage ultime.
  breakPoliceCloak();
  spawnRocketProjectile(rocket, t, { volleyId: volleySeq++, volleySize: 1 });
  return true;
}

// Fabrique un projectile roquette (tir unique ou salve) : centre du vaisseau,
// tête chercheuse en arc (C), fumée arc-en-ciel, MISS possible au contact.
function spawnRocketProjectile(rocket, t, { spread = 0, volleyId = 0, volleySize = 1, arcDir = null, arcScale = 1, arcBoost = 0, miss = null, ability = "" } = {}) {
  const distToTarget = Math.hypot(t.x - player.x, t.y - player.y);
  // Même vitesse de base que les standards.
  const speed = rocketLaunchSpeed(distToTarget);
  // Durée garantie : la roquette touche toujours (ou MISS au contact),
  // jamais d'expiration en vol tant que la cible vit.
  const life = rocketFlightLife(playerRange, speed);
  // Boosters dégâts : tous les dégâts infligés (officiel), roquettes comprises.
  const rocketBoosterMults = playerBoosterMults();
  const dmg = (rocket?.damage ?? 1000)
    * tartLauncherDmgMult(rocket?.manual === false)
    * formationRocketDamageMult()
    * formationNpcDamageMult(t)
    * moduleNpcDamageMult(t)
    * modulePvpDamageMult(t)
    * moduleRocketDamageMult()
    * rocketBoosterMults.dmg * playerPilotMults().rocketDmg * playerUpgradeMults().rocket
    * leonovRocketMultForTarget(t);
  consumeUpgradeStock("rocket");
  const shotMiss = techPrecisionActive() ? false
    : typeof miss === "boolean"
      ? miss
      : Math.random() < Math.max(0, PLAYER_SHOTS.missChance - ((Number(player.rocketHitBonusPct || 0) + Number(rocketBoosterMults.hit || 0) + playerPilotMults().rocketHit) / 100));
  const ang = rocket.manual === false
    ? launcherRocketLaunchAngle(player.angle, arcDir, spread)
    : player.angle + spread;
  // Precision Targeter : aucun miss + marqueur pour le cercle rouge
  // (soi + autres via le flag prec du tir).
  const precise = techPrecisionActive() === true;
  // Multi : direction d'arc fige pour l'evenement allie (memes courbes).
  const arcDirEff = arcDir ?? (Math.random() < 0.5 ? -1 : 1);

  addCappedProjectile(bullets, {
    x: player.x,
    y: player.y,
    vx: Math.cos(ang) * speed,
    vy: Math.sin(ang) * speed,
    r: 8.0,
    life,
    dmg,
    rocketEffect: rocket.effect || null,
    ability,
    key: rocket.id,
    side: "player",
    targetId: t.id,
    homing: true,
    spd: speed,
    volleyId,
    volleySize: Math.max(1, volleySize || 1),
    isSab: false,
    isRocket: true,
    isLauncherRocket: rocket.manual === false,
    launcherDepartureX: Math.cos(ang),
    launcherDepartureY: Math.sin(ang),
    launcherDepartureT: 0,
    // Vol en arc (C) : 70° de près → 45° au max de portée (sens aléatoire),
    // + bonus d'angle pour les salves (arcs plus grands, plus loin).
    // Arc grand si la cible est proche, petit si elle est loin.
    // En salve : sens alterné + ampleur propre à chaque roquette (éventail, pas de superposition).
    arcDist0: distToTarget,
    arcT: 0,
    arcKick0: arcDirEff * arcScale * speed * Math.tan((70 + arcBoost - Math.min(1, distToTarget / playerRange) * 25) * Math.PI / 180),
    smokeT: 0,
    smokeHue: Math.floor(Math.random() * 360),
    miss: shotMiss,
    prec: precise === true,
  }, ENTITY_LIMITS.playerBullets);
  // Multi : evenement roquette exact pour les allies (arc + MISS identiques).
  try {
    sendShotEvent({
      t: "rshot", kind: rocket.id,
      ability,
      petTarget: t?.isPetTarget === true ? "owner" : (t?._netPet || undefined),
      stationTarget: t?._stationTarget || undefined,
      x: Math.round(player.x), y: Math.round(player.y), ang,
      tx: Math.round(t.x), ty: Math.round(t.y), spd: Math.round(speed),
      arcDir: arcDirEff, arcScale: Number(arcScale) || 1, arcBoost: Number(arcBoost) || 0,
      prange: Math.round(playerRange),
      miss: shotMiss === true, v: volleyId,
      prec: precise === true,
    });
  } catch {}
}

// Salve du lance-roquettes : N = carrés bleus (chargeur), tir possible à tout
// moment même partiel. Le tir vide le chargeur puis impose 2 s de pause
// (manuel comme auto) avant la recharge.
// Totalement séparé des standards (sélection, stock, cycle propres).
function tryFireSalvo(opts = {}) {
  const silent = opts.auto === true;
  const notify = (text, dur, type) => { if (!silent) showNotification(text, dur, type); };
  if (player.dead || !started) return false;
  const id = String(player.launcherActive || "eco10").toLowerCase();
  const rocket = getRocketType(id);
  if (!rocket || rocket.manual !== false) return false;
  const n = launcherLitNow();
  if (n <= 0) {
    notify("Chargeur vide — rechargement en cours…", 2, "error");
    return false;
  }
  // En auto : laisse le chargeur plein affiché 0.4 s avant la salve.
  if (opts.auto) {
    const full = Math.min(5, rocketCount(id));
    if (n < full || launcherFullT < 0.4) return false;
  }

  const t = Target.get();
  if (!t) return false;
  if (cancelOwnStationAttack(t, !silent)) return false;

  if (netPvpBlocked(t)) return false;

  if (dist2(player.x, player.y, t.x, t.y) > playerRange * playerRange) {
    notify("Cible hors de portée.", 1.5, "error");
    return false;
  }

  player.angle = Math.atan2(t.y - player.y, t.x - player.x);

  player.rockets[id] = rocketCount(id) - n;
  noteNetConsumption("rockets", id, n);
  mirrorConsumedStock("rockets", id, player.rockets[id]);
  launcherReloadT = 0;
  launcherFullT = 0;
  launcherPhase = "cooldown";
  launcherPhaseT = 0;
  // Arme comme les lasers : lève la zone de non-agression pendant 5 s.
  player.combatT = 5.0;
  markProgressDirty();
  updateAmmoUI();

  // Salve réelle : toute attaque casse le camouflage ultime.
  breakPoliceCloak();
  const volleyId = volleySeq++;
  const volleyMiss = Math.random() < Math.max(0, PLAYER_SHOTS.missChance - ((Number(player.rocketHitBonusPct || 0) + playerPilotMults().rocketHit) / 100));
  for (let i = 0; i < n; i++) {
    // 1 son par roquette, en même temps.
    SFX.play("sfx_shot_lance_roquettes");
    // Éventail large : sens alterné + grande ampleur → 5 grands C distincts.
    const dirSign = i % 2 === 0 ? -1 : 1;
    const scale = 1.8 + 1.2 * (n > 1 ? i / (n - 1) : 0.5);
    spawnRocketProjectile(rocket, t, { spread: (i - (n - 1) / 2) * 0.12, volleyId, volleySize: n, arcDir: dirSign, arcScale: scale, arcBoost: 15, miss: volleyMiss });
  }
  // Passif Tartarus Plus (officiel) : 1 salve sur 5 tire une roquette lanceur
  // extra gratuite (même type, même sans stock d'inventaire).
  try {
    if (isTartarusPlusBase() && Math.random() < TARTPLUS_EXTRA_ROCKET && t && t.hp > 0) {
      SFX.play("sfx_shot_lance_roquettes");
      spawnRocketProjectile(rocket, t, { spread: 0, volleyId, volleySize: n + 1, arcDir: 1, arcScale: 2.4, arcBoost: 15, miss: volleyMiss });
    }
  } catch {}
  return true;
}

// Autos roquettes : ne tirent que sur ON **et** attaque de base enclenchée
// (Activer / arrêter le tir). Silencieux : pas de spam de notifications.
function tickAutoRockets() {
  if (!attackActive) return;
  if (player.dead || !started) return;
  const t = Target.get();
  if (!t) return;
  if (dist2(player.x, player.y, t.x, t.y) > playerRange * playerRange) return;
  // Deux armes séparées : chacune son cooldown, pas de blocage croisé.
  if (player.rocketAuto) tryFireRocket({ auto: true });
  if (player.launcherAuto) tryFireSalvo({ auto: true });
}

function tickAutoAttack(dt) {
  // Attaque coupée en plein combat : on guette chaque sortie de portée.
  // Retour à portée = réarmé (silencieux) → le message revient à la sortie suivante.
  if (!attackActive) {
    if (escapeWatch && !player.dead && started) {
      const wt = Target.get();
      if (!wt || wt.id !== escapeWatch.targetId) escapeWatch = null;
      else if (isLaserTargetOutOfRange(wt)) {
        if (escapeWatch.wasIn) notifyLaserRange("Vous avez échappé à l'attaque !", "info");
        escapeWatch.wasIn = false;
      } else {
        escapeWatch.wasIn = true;
      }
    }
    return;
  }
  if (player.dead || !started) return;

  const t = Target.get();
  if (!t) {
    stopAttack();
    return;
  }
  // Cible entrée/sortie de ZNA en plein combat : on coupe l'attaque
  // (l'attaque est impossible dès qu'un des deux est protégé).
  if (netPvpBlocked(t)) {
    stopAttack();
    return;
  }

  const d2 = dist2(player.x, player.y, t.x, t.y);
  const inRange = d2 <= playerRange * playerRange;
  // Annonce les changements de portée pendant l'attaque :
  // "Le combat a commencé." en entrant, "Cible hors de portée." en sortant.
  if (laserCombatInRange === null) {
    laserCombatInRange = inRange;
  } else if (inRange !== laserCombatInRange) {
    laserCombatInRange = inRange;
    if (inRange) notifyLaserRange("Le combat a commencé.", "info");
    else {
      // Tir toujours enclenché et sortie de portée : hors de portée + triple bip.
      if (notifyLaserRange("Cible hors de portée.", "error")) playOutOfRangeTriple();
    }
  }
  if (!inRange) return;

  const ammoKey = player.ammo.active || "x1";
  // ✅ les salves rapides (X6, RCB) suivent leur propre cooldown (5 s),
  // indépendant du laser standard.
  if (isRsbLike(ammoKey)) {
    if (rsbLikeCooldown(ammoKey) <= 0) tryFireOnce(null, true);
    return;
  }

  if (fireCooldown <= 0) {
    tryFireOnce(null, true);
  }
}

const SIDE_OFFSET = 30;
const SIDE_DMG_SPLIT = 0.5;

const PLAYER_SHOT_SFX = {
  x0: "pShotX0",
  x1: "pShotX1",
  x2: "pShotX2",
  x3: "pShotX3",
  x4: "pShotX4",
  x6: "pShotX6",
  sab: "pShotSab",
  // Munitions spéciales : RCB = son RSB (comme son comportement) ;
  // les autres n'ont aucun son dédié côté officiel → son X1.
  rcb: "pShotX6",
  cbo: "pShotSab",
  job: "pShotX1",
  rb: "pShotX1",
  pib: "pShotX1",
  idb: "pShotX1",
  vb: "pShotX1",
  emaa: "pShotX1",
  sbl: "pShotX1",
  abl: "pShotX1",
  tent: "pShotX1",
};

function playPlayerShot(ammoKey) {
  const id = PLAYER_SHOT_SFX[ammoKey] || PLAYER_SHOT_SFX.x1;
  // ✅ hors salves rapides : on alterne entre son standard, légèrement plus
  // aigu et légèrement plus grave pour casser la monotonie.
  const RATE_VARIANTS = [0.9, 1.0, 1.1];
  const rate = isRsbLike(ammoKey)
    ? 0.98 + Math.random() * 0.04
    : RATE_VARIANTS[Math.floor(Math.random() * RATE_VARIANTS.length)];
  SFX.play(id, { rate, cooldown: 0.01, cut: true });
  // ✅ CBO-100 : double son SAB + X1 en même temps (absorption + tir).
  if (ammoKey === "cbo") {
    SFX.play(PLAYER_SHOT_SFX.x1, { rate, cooldown: 0.01, cut: true });
  }
}

// Tir réel du P.E.T : mêmes fichiers que le joueur mais clés SFX
// dédiées, réglées par la ligne "Sons des escortes" (sans couper le joueur).
const ESCORT_SHOT_SFX = {
  x1: "escortX1",
  x2: "escortX2",
  x3: "escortX3",
  x4: "escortX4",
  x6: "escortX6",
  sab: "escortSab",
  rcb: "escortX6",
  cbo: "escortSab",
  job: "escortX1",
  rb: "escortX1",
  pib: "escortX1",
  idb: "escortX1",
  vb: "escortX1",
  emaa: "escortX1",
  sbl: "escortX1",
  abl: "escortX1",
  tent: "escortX1",
};

function playEscortShot(ammoKey) {
  const id = ESCORT_SHOT_SFX[ammoKey] || ESCORT_SHOT_SFX.x1;
  const RATE_VARIANTS = [0.9, 1.0, 1.1];
  const rate = RATE_VARIANTS[Math.floor(Math.random() * RATE_VARIANTS.length)];
  SFX.play(id, { rate, cooldown: 0.05 });
}

// ✅ quand un vrai tir touche sa cible (dégâts, sans dégâts ou MISS),
// on joue aléatoirement un des 3 sons "laser hit".
const PLAYER_LASER_HIT_SFX = ["laserHit1", "laserHit2", "laserHit3"];

function playPlayerLaserHit() {
  const id = PLAYER_LASER_HIT_SFX[Math.floor(Math.random() * PLAYER_LASER_HIT_SFX.length)];
  SFX.play(id, { cooldown: 0.04 });
}

// Impacts d'une même volée : 1er immédiat, suivants décalés de 100 ms.
// (Map bornée : pas de fuite sur la durée d'une session.)
const rocketVolleyHitCount = new Map();
const launcherVolleyImpactCount = new Map();

function registerLauncherRocketImpact(b) {
  const key = b.volleyId;
  const need = Math.max(1, Number(b.volleySize) || 1);
  const count = (launcherVolleyImpactCount.get(key) || 0) + 1;
  if (count >= need) {
    launcherVolleyImpactCount.delete(key);
    return { final: true, count: need };
  }
  if (launcherVolleyImpactCount.size > 500 && !launcherVolleyImpactCount.has(key)) {
    launcherVolleyImpactCount.delete(launcherVolleyImpactCount.keys().next().value);
  }
  launcherVolleyImpactCount.set(key, count);
  return { final: false, count };
}
function playRocketImpactStaggered(volleyId) {
  const n = rocketVolleyHitCount.get(volleyId) || 0;
  if (rocketVolleyHitCount.size > 500 && !rocketVolleyHitCount.has(volleyId)) {
    const oldest = rocketVolleyHitCount.keys().next().value;
    rocketVolleyHitCount.delete(oldest);
  }
  rocketVolleyHitCount.set(volleyId, n + 1);
  if (n === 0) playPlayerLaserHit();
  else window.setTimeout(() => playPlayerLaserHit(), n * 100);
}

let fireCooldown = 0;

const RSB_COOLDOWN = 5.0;
let rsbCooldown = 0;

// ✅ X6 + RCB-140 : cooldown PARTAGÉ (5 s). Tirer l'un bloque l'autre,
// voiles et boutons suivent le même compteur des deux côtés.
const RCB_COOLDOWN = 5.0;
let rcbCooldown = 0;

// Munitions à salve rapide (tir RSB) : X6 + RCB.
const isRsbLike = (key) => key === "x6" || key === "rcb";
function rsbLikeCooldown(key) {
  void key;
  return Math.max(rsbCooldown, rcbCooldown);
}

// Roquettes R-310 : tir manuel à tête chercheuse, stock consommable.
let rocketCooldown = 0;
let rocketCooldownMax = 1.0;
const PERSONAL_ROCKET_COOLDOWNS = new Map([
  ["wizx", 15],
  ["dcr250", 30], ["pld8", 30], ["ric3", 30], ["rc100", 30],
  ["sr5", 30], ["agt500", 30], ["sp100x", 30], ["k300m", 30],
]);
const personalRocketCooldowns = new Map();

function personalRocketCooldownFor(rocketId) {
  return Math.max(0, Number(PERSONAL_ROCKET_COOLDOWNS.get(String(rocketId || "").toLowerCase())) || 0);
}

function rocketCooldownLeft(rocketId) {
  const id = String(rocketId || "").toLowerCase();
  return personalRocketCooldownFor(id) > 0
    ? Math.max(0, Number(personalRocketCooldowns.get(id)) || 0)
    : Math.max(0, Number(rocketCooldown) || 0);
}

function rocketCooldownMaxFor(rocketId) {
  const personalCooldown = personalRocketCooldownFor(rocketId);
  return personalCooldown > 0
    ? personalCooldown
    : Math.max(0.05, Number(rocketCooldownMax) || 1);
}
// Lance-roquettes : chargeur 5 coups à 1/s, tir quand on veut (même partiel),
// 2 s de pause après chaque salve avant la recharge. Pas d'autre blocage.
let launcherReloadT = 0;
let launcherPhase = "reload"; // reload | cooldown
let launcherPhaseT = 0;
let launcherFullT = 0; // temps passé chargeur plein (affichage avant salve auto)

function launcherThreshold() {
  return Math.max(0, Math.min(5, rocketCount(player.launcherActive)));
}

function launcherLitNow() {
  if (launcherPhase === "cooldown") return 0;
  const stock = rocketCount(player.launcherActive);
  return Math.max(0, Math.min(5, Math.floor(launcherReloadT), stock));
}

function tickLauncherCharger(dt) {
  const full = launcherThreshold();
  if (full <= 0) {
    // Rien à charger : retour au début du cycle.
    if (launcherPhase !== "reload" || launcherReloadT !== 0) {
      launcherPhase = "reload";
      launcherReloadT = 0;
    }
    launcherFullT = 0;
    return;
  }
  if (launcherPhase === "cooldown") {
    launcherPhaseT += dt;
    if (launcherPhaseT >= 2 * formationRocketCooldownMult()) {
      launcherPhase = "reload";
      launcherReloadT = 0;
      SFX.play("rocketsLoadStart", { cut: true });
    }
    launcherFullT = 0;
    return;
  }
  // reload : +1/s. Le tir est possible à tout moment (même partiel).
  const previousLit = launcherLitNow();
  launcherReloadT = Math.min(5, launcherReloadT + dt / formationRocketCooldownMult());
  // Mémorise le plein affiché pour la salve auto.
  const lit = launcherLitNow();
  for (let loaded = previousLit + 1; loaded <= lit; loaded++) {
    SFX.play(loaded === 5 ? "rocketsLoaded" : "rocketLoad");
  }
  if (lit >= full) launcherFullT += dt;
  else launcherFullT = 0;
}

const enemiesById = new Map();

function rebuildEnemyIndex() {
  rebuildIdIndex(enemiesById, enemies);
  // Multi PvP : le rebuild écrase tout — réinscrit les avatars joueurs
  // (hors tableau `enemies`, sinon les tirs à tête chercheuse les perdent).
  try {
    for (const e of netPlayerProxies.values()) {
      if (e && e.hp > 0) enemiesById.set(e.id, e);
    }
    for (const e of netPetProxies.values()) {
      if (e && e.hp > 0) enemiesById.set(e.id, e);
    }
    for (const e of stationCombatTargets()) {
      if (e?.hp > 0) enemiesById.set(e.id, e);
    }
  } catch {}
}

function getEnemyById(id) {
  if (id == null) return null;
  if (id === "pet") return petLockValid() ? petTargetProxy : null;
  if (String(id).startsWith("station:")) {
    stationCombatTargets();
    const stationTarget = stationTargetProxies.get(String(id).slice(8));
    return stationTarget?.hp > 0 ? stationTarget : null;
  }
  // Multi PvP : "self" = notre vaisseau (impacts visuels des tirs allies).
  if (id === "self") return !player.dead && player.hp > 0 ? player : null;
  const enemy = enemiesById.get(id);
  return enemy?.hp > 0 ? enemy : null;
}

let volleySeq = 1;
const VOLLEY_FLOAT_TIMEOUT = 0.08;
const pendingVolleys = new Map();

// Éclatement temporel : faux lasers normaux et salves QA à dégâts réels.
// les éclairs de la salve sont espacés sur la durée d'un tir.
// Chaque entree conserve la munition du depart, la cible et la balistique.
// Changer de selection ne transforme ni les tirs en attente ni ceux en vol.
const pendingSalvo = [];

function clearPendingSalvo({ keepQa = false } = {}) {
  if (!keepQa) {
    pendingSalvo.length = 0;
    return;
  }
  // L'arret du laser standard ne coupe pas une capacite independante.
  for (let i = pendingSalvo.length - 1; i >= 0; i--) {
    if (pendingSalvo[i].ability !== "ability_hyperion_qa") pendingSalvo.splice(i, 1);
  }
}

function scheduleSalvoPart(delay, entry) {
  if (delay <= 0) {
    spawnScheduledSalvo(entry);
    return;
  }
  pendingSalvo.push({ t: delay, ...entry });
}

function spawnScheduledSalvo(entry) {
  if (entry.ability === "ability_hyperion_qa") spawnQaSalvoPart(entry);
  else spawnSalvoDecoy(entry);
}

function spawnSalvoDecoy(e) {
  // ✅ la salve s'arrête si la cible n'existe plus (NPC mort)
  const t2 = getEnemyById(e.targetId);
  if (!t2 || netPvpBlocked(t2)) return;
  const key = e.forceKey || e.key || "x1";
  // ✅ SAB/CBO inversé : les faux tirs partent eux aussi de la cible vers le vaisseau.
  if (e.sabReverse && (key === "sab" || key === "cbo")) {
    const rdx = player.x - t2.x, rdy = player.y - t2.y;
    const rdl = Math.hypot(rdx, rdy) || 1;
    const rnx = rdx / rdl, rny = rdy / rdl;
    const startX = t2.x + rnx * ((t2.r || 18) + 6);
    const startY = t2.y + rny * ((t2.r || 18) + 6);
    const baseAng = Math.atan2(rny, rnx);
    // Multi : faux tirs exacts pour les allies (jamais MISS, meme volley).
    try {
      sendShotEvent({
        t: "shot", key, n: e.items.length,
        petTarget: t2.isPetTarget === true ? "owner" : (t2._netPet || undefined),
        stationTarget: t2._stationTarget || undefined,
        x: Math.round(startX), y: Math.round(startY), ang: baseAng,
        tx: Math.round(t2.x), ty: Math.round(t2.y), spd: Math.round(e.speed), sab: true,
        miss: false, v: e.volleyId,
      });
    } catch {}
    const qx = -rny, qy = rnx;
    for (const [off, aOff] of e.items) {
      addCappedProjectile(bullets, {
        x: startX + qx * off,
        y: startY + qy * off,
        vx: Math.cos(baseAng + aOff) * e.speed,
        vy: Math.sin(baseAng + aOff) * e.speed,
        r: 6.0,
        life: e.life,
        dmg: 0,
        key,
        side: "player",
        targetId: e.targetId,
        homing: true,
        sabReverse: true,
        spd: e.speed,
        volleyId: e.volleyId,
        volleySize: e.volleySize,
        isSab: key === "sab",
        miss: false,
        visual: true,
      }, ENTITY_LIMITS.playerBullets);
    }
    return;
  }
  // ✅ recalcule la position de départ depuis le vaisseau au moment du tir
  // (le joueur a pu bouger entre le début et la fin de la salve)
  const ang2 = Math.atan2(t2.y - player.y, t2.x - player.x);
  const fx2 = Math.cos(ang2), fy2 = Math.sin(ang2);
  const px2 = -fy2, py2 = fx2;
  const muzzle2X = player.x + fx2 * (player.r + 10);
  const muzzle2Y = player.y + fy2 * (player.r + 10);
  // Multi : faux tirs exacts pour les allies (jamais MISS, meme volley).
  try {
    sendShotEvent({
      t: "shot", key, n: e.items.length,
      petTarget: t2.isPetTarget === true ? "owner" : (t2._netPet || undefined),
      stationTarget: t2._stationTarget || undefined,
      x: Math.round(player.x), y: Math.round(player.y), ang: ang2,
      tx: Math.round(t2.x), ty: Math.round(t2.y), spd: Math.round(e.speed), sab: false,
      miss: false, v: e.volleyId,
    });
  } catch {}
  for (const [off, aOff] of e.items) {
    addCappedProjectile(bullets, {
      x: muzzle2X + px2 * off,
      y: muzzle2Y + py2 * off,
      vx: Math.cos(ang2 + aOff) * e.speed,
      vy: Math.sin(ang2 + aOff) * e.speed,
      r: 6.0,
      life: e.life,
      dmg: 0,
      key,
      side: "player",
      targetId: e.targetId,
      homing: true,
      spd: e.speed,
      volleyId: e.volleyId,
      volleySize: e.volleySize,
      isSab: false,
      miss: false,
      visual: true,
    }, ENTITY_LIMITS.playerBullets);
  }
}

function tickPendingSalvo(dt) {
  if (!pendingSalvo.length) return;
  for (let i = pendingSalvo.length - 1; i >= 0; i--) {
    const entry = pendingSalvo[i];
    entry.t -= dt;
    if (entry.t <= 0) {
      pendingSalvo.splice(i, 1);
      spawnScheduledSalvo(entry);
    }
  }
}

// ✅ Faux lasers des NPC façon joueur (ex. police Awakened) : visuels seuls
// (dégâts 0), étalés comme la salve du joueur (1 toutes les 0,2 s) au lieu
// d'un paquet instantané. Comme le joueur, la position de départ est
// recalculée au moment du tir (le NPC a pu bouger entre-temps).
const pendingNpcFaux = [];
const PENDING_NPC_FAUX_MAX = 240;

function clearPendingNpcFaux() {
  pendingNpcFaux.length = 0;
}

function scheduleNpcFaux(delay, entry) {
  if (!entry) return;
  if (delay <= 0) {
    spawnPendingNpcFaux(entry);
    return;
  }
  while (pendingNpcFaux.length >= PENDING_NPC_FAUX_MAX) pendingNpcFaux.shift();
  pendingNpcFaux.push({ t: delay, entry });
}

function spawnPendingNpcFaux(entry) {
  try {
    const npc = enemies.find(x => x?.id === entry.npcId && x.hp > 0);
    if (!npc) return;
    if (entry.jpcVolley != null && (npc._netJpcVolley !== entry.jpcVolley
      || npc.ishT > 0 || npc.empT > 0 || npc.freezeT > 0 || npc.redirectSilenceT > 0)) return;
    const target = entry.target === "player" ? player
      : (entry.target === "jpc" || entry.target === "npc") ? getEnemyById(entry.targetId)
      : (entry.targetId != null ? getEscortById(entry.targetId) : null);
    if (!target || !(target.hp > 0)) return;
    // ✅ position de départ recalculée depuis le NPC au moment du tir.
    const ang = Math.atan2(target.y - npc.y, target.x - npc.x);
    const fx = Math.cos(ang), fy = Math.sin(ang);
    const px = -fy, py = fx;
    const muzzle = (npc.r || 18) + (npc.isJpcBot ? 10 : 12);
    const sx = npc.x + fx * muzzle + px * entry.off;
    const sy = npc.y + fy * muzzle + py * entry.off;
    const dx = target.x - sx, dy = target.y - sy;
    const len = Math.hypot(dx, dy) || 1;
    const spd = entry.spd;
    // Visuels JPC purs (dégâts déjà appliqués au tir réel) : dmg 0,
    // téléguidés, sans collision. Sinon comportement police classique.
    const visualOnly = entry.visualOnly === true;
    const willMiss = visualOnly ? false
      : Math.random() < Math.min(1, NPC_SHOT_RULES.missChance + npcLaserAccuracyPenalty(npc));
    addCappedProjectile(enemyBullets, {
      x: sx, y: sy,
      vx: dx / len * spd, vy: dy / len * spd,
      spd,
      r: entry.bulletR ?? 7,
      life: visualOnly ? Math.max(0.25, len / Math.max(120, spd) + 0.08) : Math.max(entry.life, 2.5),
      dmg: visualOnly ? 0 : Math.max(1, Math.floor(Number(entry.dmg) || 0)), key: entry.key,
      scale: entry.scale ?? 1.5,
      sprite: entry.sprite || null,
      target: entry.target,
      targetId: (entry.target === "player" || entry.target == null) ? null : entry.targetId,
      homing: visualOnly ? true : entry.homing,
      ownerId: npc.id,
      miss: willMiss, visual: visualOnly,
      _jpcVisual: visualOnly,
      _jpcShot: npc.isJpcBot === true,
      hitRadiusBonus: entry.hitRadiusBonus,
    }, ENTITY_LIMITS.enemyBullets);
  } catch {}
}

function tickPendingNpcFaux(dt) {
  if (!pendingNpcFaux.length) return;
  for (let i = pendingNpcFaux.length - 1; i >= 0; i--) {
    const item = pendingNpcFaux[i];
    item.t -= dt;
    if (item.t <= 1e-9) {
      pendingNpcFaux.splice(i, 1);
      spawnPendingNpcFaux(item.entry);
    }
  }
}

// Faux tirs des escortes : même visuel que le joueur (éclairs dmg 0),
// spawnés depuis l'escorte au moment du tir, jamais de dégâts ni de son.
const pendingEscortSalvo = [];

function clearPendingEscortSalvo() {
  pendingEscortSalvo.length = 0;
}

function scheduleEscortSalvoPart(delay, entry) {
  if (delay <= 0) {
    spawnEscortSalvoDecoy(entry);
    return;
  }
  pendingEscortSalvo.push({ t: delay, ...entry });
}

function spawnEscortSalvoDecoy(e) {
  const isPet = e.escortId === "pet";
  const isTbr = e.escortId === "tbr0" || e.escortId === "tbr1";
  if (isPet && (!account.user?.pet?.active || !petState.ready || player.dead)) return;
  if (isPet && (petState.returning || petState.target?.id !== e.targetId
    || (normalizePetMode(account.user?.pet?.mode) !== "combat" && !hplLinkActive()))) return;
  if (isTbr && (!(player.tbrT > 0) || !tbrPetOk() || petKamikaze.active
    || petState.returning || petState.target?.id !== e.targetId)) return;
  const escort = isPet ? petState : isTbr
    ? player.tbrClones?.find(c => c.id === e.escortId) : getEscortById(e.escortId);
  const t2 = getEnemyById(e.targetId);
  if (!escort || (isPet ? account.user?.pet?.hp <= 0 : escort.hp <= 0) || !t2 || t2.hp <= 0) return;
  if ((isPet || isTbr) && netPvpBlocked(t2)) return;
  if (isTbr && dist2(escort.x, escort.y, t2.x, t2.y) > 305 * 305) return;
  // Multi : faux tirs du PET et de ses clones depuis leur propre position.
  // Jamais MISS, meme volley (deduplique l'affichage MISS distant).
  if (isPet || isTbr) {
    try {
      sendShotEvent({
        t: "shot", key: e.key || "x1", n: (e.items || []).length || 1,
        petSource: isPet,
        petClone: isTbr ? (e.escortId === "tbr0" ? 0 : 1) : undefined,
        petTarget: t2.isPetTarget === true ? "owner" : (t2._netPet || undefined),
        stationTarget: t2._stationTarget || undefined,
        x: Math.round(escort.x), y: Math.round(escort.y),
        ang: Math.atan2(t2.y - escort.y, t2.x - escort.x),
        tx: Math.round(t2.x), ty: Math.round(t2.y), spd: Math.round(e.speed || 4000), sab: false,
        miss: false, v: e.volleyId,
      });
    } catch {}
  }
  const ang2 = Math.atan2(t2.y - escort.y, t2.x - escort.x);
  const fx2 = Math.cos(ang2), fy2 = Math.sin(ang2);
  const px2 = -fy2, py2 = fx2;
  const muzzle = isPet || isTbr ? 50 : (escort.pack?.r || 34) + 10;
  const muzzle2X = escort.x + fx2 * muzzle;
  const muzzle2Y = escort.y + fy2 * muzzle;
  for (const [off, aOff] of e.items) {
    addCappedProjectile(bullets, {
      x: muzzle2X + px2 * off,
      y: muzzle2Y + py2 * off,
      vx: Math.cos(ang2 + aOff) * e.speed,
      vy: Math.sin(ang2 + aOff) * e.speed,
      r: 6.0,
      life: e.life,
      dmg: 0,
      key: e.key || "x3",
      side: "player",
      targetId: e.targetId,
      homing: true,
      spd: e.speed,
      volleyId: e.volleyId,
      volleySize: e.volleySize,
      isSab: false,
      miss: false,
      visual: true,
      ownerEscortId: e.escortId,
    }, ENTITY_LIMITS.playerBullets);
  }
}

function tickPendingEscortSalvo(dt) {
  if (!pendingEscortSalvo.length) return;
  for (let i = pendingEscortSalvo.length - 1; i >= 0; i--) {
    const entry = pendingEscortSalvo[i];
    entry.t -= dt;
    if (entry.t <= 0) {
      pendingEscortSalvo.splice(i, 1);
      spawnEscortSalvoDecoy(entry);
    }
  }
}

function flushVolleyKey(key, v) {
  pendingVolleys.delete(key);
  if (!v || v.rawDamage <= 0) return;

  if (v.hasRocketBreakdown) {
    const opts = { size: v.isCrit ? 25 : 21, pop: 0.3, shake: 0.6, life: 1, glow: v.isCrit ? 1.6 : 1, weight: 900, impact: true };
    if (v.rocketDirectRaw > 0) {
      addFloatText(v.x - 24, v.y - 52, v.rocketDirectRaw, "rgba(255,107,122,0.95)", opts);
    }
    if (v.rocketShieldDrainRaw > 0) {
      addFloatText(v.x + 24, v.y - 82, v.rocketShieldDrainRaw, "rgba(124,240,255,0.95)", opts);
    }
    return;
  }

  const n = Math.max(1, Math.round(v.rawDamage));

  const col = v.isCrit 
    ? "rgba(255,220,50,0.98)"
    : (v.hp > 0 
        ? "rgba(255,107,122,0.95)"
        : "rgba(124,240,255,0.95)");

  const opts = {
    size: v.isCrit ? 25 : 21,
    pop: 0.3,
    shake: 0.6,
    life: 1,
    glow: v.isCrit ? 1.6 : 1.0,
    weight: 900,
    impact: true
  };

  const offsetX = (Math.random() - 0.5) * 60;
  const offsetY = -40 - Math.random() * 20;

  addFloatText(v.x + offsetX, v.y + offsetY, n, col, opts);
}

function queueVolleyFloat(target, out, volleyId, volleySize, timeout = VOLLEY_FLOAT_TIMEOUT) {
  if (!target || !out) return;

  const key = `${volleyId}:${target.id}`;
  let v = pendingVolleys.get(key);
  if (!v) {
    v = {
      t: 0,
      need: Math.max(1, volleySize || 1),
      timeout: Math.max(VOLLEY_FLOAT_TIMEOUT, Number(timeout) || 0),
      got: 0,
      total: 0,
      hp: 0,
      sh: 0,
      rawDamage: 0,
      rocketDirectRaw: 0,
      rocketShieldDrainRaw: 0,
      hasRocketBreakdown: false,
      x: target.x,
      y: target.y,
      r: target.r || 18,
      isCrit: false
    };
    pendingVolleys.set(key, v);
  }

  v.t = 0;
  v.got++;
  v.total += out.total || 0;
  v.hp += out.hp || 0;
  v.sh += out.sh || 0;
  v.rawDamage += out.rawDamage || 0;
  v.rocketDirectRaw += out.rocketDirectRaw || 0;
  v.rocketShieldDrainRaw += out.rocketShieldDrainRaw || 0;
  if (Object.hasOwn(out, "rocketDirectRaw") || Object.hasOwn(out, "rocketShieldDrainRaw")) v.hasRocketBreakdown = true;
  v.x = target.x;
  v.y = target.y;
  v.r = target.r || v.r;

  if (out.isCrit) v.isCrit = true;

  if (v.got >= v.need) flushVolleyKey(key, v);
}

function tickVolleyFloats(dt) {
  if (!pendingVolleys.size) return;
  for (const [key, v] of pendingVolleys) {
    v.t += dt;
    if (v.t >= v.timeout) flushVolleyKey(key, v);
  }
}

function tryFireOnce(ammoOverride = null, silent = false) {
  if (player.dead) return false;
  if (Number(getNetSelf()?.redirectSilenceT) > 0) return false;

  if (ammoOverride) setAmmo(ammoOverride);

  const t = Target.get();
  if (!t) return false;
  if (cancelOwnStationAttack(t, !silent)) return false;
  if (netPvpBlocked(t)) return false;

  const volleyId = volleySeq++;
  const volleySize = player.altShot ? 2 : 1;
  const targetId = t.id;

  if (!t) return false;

  const d2 = dist2(player.x, player.y, t.x, t.y);
  if (d2 > playerRange * playerRange) return false;

  let ammoKey = player.ammo.active || "x1";

  // ✅ les salves rapides (X6, RCB) ont leur propre cooldown (5 s) : elles
  // ignorent le cooldown du tir laser standard et ne le réinitialisent pas.
  if (isRsbLike(ammoKey)) {
    if (rsbLikeCooldown(ammoKey) > 0) {
      // ✅ pendant le retour de la salve : on n'attaque pas (pas de repli x1)
      return false;
    }
  } else if (fireCooldown > 0) {
    return false;
  }

  player.angle = Math.atan2(t.y - player.y, t.x - player.x);

  const ammoCfg = AMMO[ammoKey] || AMMO.x1;

  const baseCd = 1 / Math.max(0.001, player.baseFireRate * player.fireRateMult);
  if (!isRsbLike(ammoKey)) {
    fireCooldown = typeof ammoCfg.cooldown === "number" ? ammoCfg.cooldown : baseCd;
  }

  // ✅ munitions spéciales : IDB rampe, JOB aliens/joueurs, bonus
  // conditionnels (Demaners, Sibelons...). Voir COMBAT/AMMO_TYPES.js.
  const mult = resolveAmmoMult(ammoKey, t);

  // Tir réel : toute attaque casse le camouflage ultime.
  breakPoliceCloak();
  playPlayerShot(ammoKey);

  const activeKey = player.ammo.active || "x1";
  if (ammoKey === activeKey) consumeAmmo(countPlayerLasers());

const isSab = ammoKey === "sab";
// ✅ CBO-100 : même tir inversé que SAB (absorption), mais avec dégâts ×3
// normaux + vol de bouclier ×1 (au lieu du drain pur).
const isCbo = ammoKey === "cbo";
const isSabLike = isSab || isCbo;

// ✅ Vitesse du tir : base 4000, et plus on est loin de la cible plus elle
// augmente (dist * bulletSpeedDistGain).
const distToTarget = Math.hypot(t.x - player.x, t.y - player.y);
const speed = (player.baseBulletSpeed + distToTarget * BASE_RUN.bulletSpeedDistGain)
  * (isSab ? SAB50.bulletSpeedMult : 1);

const life = bulletLifeForRange(playerRange, speed);

// ✅ SAB-50 ne fait pas de dégâts HP.
// Elle utilise ta puissance laser comme quantité de bouclier à voler.
player.volleyCount = (player.volleyCount || 0) + 1;
consumeUpgradeStock("laser", countPlayerLasers());
// Bonus par canon x nombre équipé : vaisseau + drones.
// 1x PR-L = +200, 2x = +400, 35x = +7000 tous les 5 tirs.
// Idem vsMatch (LF-3, Magmadrill, Paritydrill, AA-1/AAP-1 Mimesis, PR-L Blacklight, Xénocide...) et U-LF4 instable.
// Xénocide : +510/canon dans la GG Awakened (inclus dans laserFitVsExtra).
const droneLaserDamageMult = 1 + Math.max(0, Number(player.droneDamageBonusPct) || 0) / 100;
const laserBaseForTarget = laserBaseDamageForTarget(t);
let laserBase = laserBaseForTarget + laserFitVsExtra(player.laserMods, t, player.droneLaserMods) * droneLaserDamageMult;
laserBase += laserFitUnstableDelta(player.laserMods, player.droneLaserMods) * droneLaserDamageMult;
const overdrive = laserFitOverdrive(player.laserMods, player.droneLaserMods, player.volleyCount) * droneLaserDamageMult;
// Boosters : dégâts globaux + précision laser.
const shotBoosterMults = playerBoosterMults();
const shotHitBonusPct = Number(player.laserHitBonusPct || 0) + Number(shotBoosterMults.hit || 0);
  const dmgShot = isSab
    ? laserBaseForTarget * SAB50.drainMult * shotBoosterMults.dmg
    : (laserBase + overdrive) * mult * formationNpcDamageMult(t) * formationPlayerLaserDamageMult(t) * (typeof moduleNpcDamageMult === "function" ? moduleNpcDamageMult(t) : 1) * (typeof modulePvpDamageMult === "function" ? modulePvpDamageMult(t) : 1) * shotBoosterMults.dmg * playerPilotMults().alienDmg * (t?._netPlayer ? (Number(playerPilotMults()?.pvpDmg) || 1) : 1) * playerUpgradeMults().laser * buoyDamageMult() * valourDamageMult() * berserkDamageMult() * holoDamageMult() * scrambleDamageMult() * specDamageMult() * tempestDischargeMult() * shipPassiveDamageMult();

  const shotMiss = Math.random() < Math.max(0, PLAYER_SHOTS.missChance - ((shotHitBonusPct + playerPilotMults().laserHit) / 100));
  // Multi : evenement de tir exact pour les allies (vrais tirs, MISS inclus).
  try {
    sendShotEvent({
      t: "shot", key: ammoKey, n: isSabLike ? 1 : volleySize,
      petTarget: t?.isPetTarget === true ? "owner" : (t?._netPet || undefined),
      stationTarget: t?._stationTarget || undefined,
      x: Math.round(player.x), y: Math.round(player.y), ang: Number(player.angle) || 0,
      tx: Math.round(t.x), ty: Math.round(t.y), spd: Math.round(speed), sab: isSabLike,
      miss: shotMiss === true, v: volleyId,
    });
  } catch {}

  const ang = player.angle;
  const fx = Math.cos(ang), fy = Math.sin(ang);
  const px = -fy, py = fx;

  const muzzleX = player.x + fx * (player.r + 10);
  const muzzleY = player.y + fy * (player.r + 10);

  if (isSabLike) {
    // ✅ SAB/CBO inversé : UN seul laser central, tiré DE LA CIBLE VERS le vaisseau
    // (absorption de bouclier). Pas d'alternance paire/impair (altShot untouched).
    const rdx = player.x - t.x, rdy = player.y - t.y;
    const rdl = Math.hypot(rdx, rdy) || 1;
    const rnx = rdx / rdl, rny = rdy / rdl;
    addCappedProjectile(bullets, {
      x: t.x + rnx * ((t.r || 18) + 6),
      y: t.y + rny * ((t.r || 18) + 6),
      vx: rnx * speed,
      vy: rny * speed,
      r: 6.0,
      life,
      dmg: dmgShot,
      key: ammoKey,
      side: "player",
      targetId,
      homing: true,
      sabReverse: true, // homing vers le joueur + impact à l'arrivée au vaisseau
      spd: speed,
      volleyId,
      volleySize: 1,
      isSab,
      miss: shotMiss,
    }, ENTITY_LIMITS.playerBullets);
  } else if (!player.altShot) {
addCappedProjectile(bullets, {
  x: muzzleX,
  y: muzzleY,
  vx: fx * speed,
  vy: fy * speed,
  r: 6.0,
  life,
  dmg: dmgShot,
  key: ammoKey,
  side: "player",
  targetId,
  homing: true,
  spd: speed,
  volleyId,
  volleySize,
    isSab,
  miss: shotMiss,
}, ENTITY_LIMITS.playerBullets);
  } else {
    const ox = px * SIDE_OFFSET;
    const oy = py * SIDE_OFFSET;

    const leftX = muzzleX + ox, leftY = muzzleY + oy;
    const rightX = muzzleX - ox, rightY = muzzleY - oy;

    const ldx0 = t.x - leftX, ldy0 = t.y - leftY;
    const rdx0 = t.x - rightX, rdy0 = t.y - rightY;

    const ll = Math.hypot(ldx0, ldy0) || 1;
    const rl = Math.hypot(rdx0, rdy0) || 1;

    const ldx = ldx0 / ll, ldy = ldy0 / ll;
    const rdx = rdx0 / rl, rdy = rdy0 / rl;

addCappedProjectile(bullets, {
  x: leftX,
  y: leftY,
  vx: ldx * speed,
  vy: ldy * speed,
  r: 6.0,
  life,
  dmg: dmgShot * SIDE_DMG_SPLIT,
  key: ammoKey,
  side: "player",
  targetId,
  homing: true,
  spd: speed,
  volleyId,
  volleySize,
    isSab,
  miss: shotMiss,
}, ENTITY_LIMITS.playerBullets);

addCappedProjectile(bullets, {
  x: rightX,
  y: rightY,
  vx: rdx * speed,
  vy: rdy * speed,
  r: 6.0,
  life,
  dmg: dmgShot * SIDE_DMG_SPLIT,
  key: ammoKey,
  side: "player",
  targetId,
  homing: true,
  spd: speed,
  volleyId,
  volleySize,
    isSab,
  miss: shotMiss,
}, ENTITY_LIMITS.playerBullets);
  }

  if (ammoKey === "x6" || ammoKey === "rcb") { rsbCooldown = RSB_COOLDOWN; rcbCooldown = RCB_COOLDOWN; }

  // ✅ Salve visuelle : seule la première volée (le vrai tir) inflige les dégâts ;
  // les éclairs suivants sont des doublons esthétiques (dmg 0) qui convergent sur la cible.
  // X6/RCB → 12 tirs affichés par seconde ; autres munitions → 6 tirs (1 toutes les 200 ms).
  // Nombre ajusté à la cadence (salvoShotCount) : les faux tirs restent standards par seconde.
  const salvoShots = typeof salvoShotCount === "function" ? salvoShotCount(ammoKey) : (isRsbLike(ammoKey) ? 12 : 6);
  const salvoInterval = isRsbLike(ammoKey) ? 1 / 12 : 0.2;

  // ðŸ”« salve : le vrai tir compte pour le premier éclair affiché (t=0).
  // Les éclairs restants s'affichent toutes les `salvoInterval` ms en
  // alternant toujours "les 2" (paire gauche/droite) puis "le seul" (central),
  // même pour les faux tirs. SAB inversé : que des centraux (cible→vaisseau).
  const isRealPair = !!player.altShot && !isSab;
  const pairItems = [[-SIDE_OFFSET, 0], [SIDE_OFFSET, 0]];
  const singleItems = [[0, 0]];
  const salvoShotParams = { key: ammoKey, targetId, speed, life, volleyId, volleySize: isSabLike ? 1 : volleySize, sabReverse: isSabLike };
  for (let i = 1; i < salvoShots; i++) {
    const fakeIsPair = !isSabLike && (isRealPair ? i % 2 === 0 : i % 2 === 1);
    scheduleSalvoPart(i * salvoInterval, {
      ...salvoShotParams,
      items: fakeIsPair ? pairItems : singleItems,
    });
  }

  // SAB inversé : toujours central unique → l'alternance altShot est préservée
  // pour les autres munitions.
  if (!isSabLike) player.altShot = !player.altShot;
  maybeTriggerLaser();
  player.combatT = 5.0;
  // Tech Chain Impulse armée : le prochain tir la déclenche.
  if (player.chainArmed === true) { try { fireChainImpulse(); } catch {} }
  return true;
}

// ✅ Zone map spawner
let isZoneMap = rules?.mode === "zone";
let zoneCamps = [];
let zonePortals = [];
let zoneWalls = [];
let zoneSafe = null;
let zoneStation = null;
let mapPortalLock = 0;
let portalHintCd = 0;
// Cumul de présence en map Blacklight (quêtes "stay"), versé par tranches.
let stayBlAcc = 0;

let safeZoneActive = false;
let safeZoneX = 0;
let safeZoneY = 0;
let safeZoneR = 0;
// Mémorise l'état ZNA pour détecter son activation (front montant).
let wasSafeZoneActive = false;

// Rayon général de tous les portails
const DEFAULT_PORTAL_RADIUS = 450;

const SAFE_ZONE_MARGIN = 50; // Portails : 450 + 50 = 500 de non-agression.

function getCurrentZoneMapId() {
  return String(window.__CURRENT_MAP_ID__ || rules?.mapLabel || "").trim().toLowerCase();
}

function portalProvidesSafety(portal, forJpc = false) {
  const mapId = getCurrentZoneMapId();
  if (/^4-[123]$/.test(mapId) || mapId === "4-4" || mapId === "4-5") return false;
  const sectorMatch = mapId.match(/^([123])-/);
  const playerSector = getFaction((account.user || getCurrentUserFull())?.faction).sector;
  if (!forJpc && sectorMatch && sectorMatch[1] !== playerSector) return false;
  const destination = String(portal?.toMap || "").trim().toLowerCase();
  return !["alpha", "beta", "gamma", "delta", "epsilon", "zeta", "kappa", "lambda", "kronos", "awakened", "eternal"].includes(destination);
}

function baseProvidesSafety(forJpc = false) {
  const center = zoneSafe?.modules?.find(module => String(module?.id || "").startsWith("CENTRE_"));
  if (!center) return false;
  if (forJpc) return true;
  const owner = String(center.id).slice("CENTRE_".length).toLowerCase();
  if (owner === "pirates" || owner === "pirate") return true;
  return owner === getFaction((account.user || getCurrentUserFull())?.faction).id;
}

// Les contr?leurs prot?gent uniquement les joueurs de leur firme.
function getSafeModuleAt(x, y, forJpc = false) {
  if (!isZoneMap) return null;
  for (const module of zoneSafe?.modules || []) {
    const radius = Number(module?.safeRadius || 0);
    if (!(radius > 0) || (!forJpc && !canUseStation(module))) continue;
    if (dist2(x, y, module.x, module.y) <= radius * radius) return module;
  }
  return null;
}

function npcIsInSafeZone(e) {
  const forJpc = e?.isJpcBot === true;
  // La protection d'un JPC appartient à sa zone, pas à la firme de
  // l'observateur. Le serveur tranche avant le repli géométrique solo.
  if (forJpc && typeof e._netSafe === "boolean") return e._netSafe;
  if (!isZoneMap) return false;
  
  if (zonePortals && zonePortals.length) {
    for (const p of getInteractivePortals()) {
      if (!portalProvidesSafety(p, forJpc)) continue;
      const rr = DEFAULT_PORTAL_RADIUS + SAFE_ZONE_MARGIN;
      if (dist2(e.x, e.y, p.x, p.y) <= rr * rr) {
        return true;
      }
    }
  }

  if (baseProvidesSafety(forJpc) && zoneSafe?.zone?.kind === "circle") {
    const z = zoneSafe.zone;
    const rr = (z.r || 0) + SAFE_ZONE_MARGIN;
    if (dist2(e.x, e.y, z.x, z.y) <= rr * rr) {
      return true;
    }
  }

  if (getSafeModuleAt(e.x, e.y, forJpc)) return true;

  return false;
}

// ============================================================
// Wave system
// ============================================================
let wave = 1;
const waveSpawns = createWaveSpawnState();
const GATE_WAVE_COUNTDOWN_SECONDS = 5;
let waveStartCountdown = 0;
let waveCountdownSecond = -1;

  function nextTypeInQueue() {
    return waveSpawns.peek()?.type || null;
  }

function updateWaveCountdownNotice() {
  const second = Math.max(1, Math.ceil(waveStartCountdown));
  if (second === waveCountdownSecond) return;
  waveCountdownSecond = second;
  showNotification(String(second), 4, "info", { log: false });
}

function finishWaveCountdownNotice() {
  const gateId = String(window.__CURRENT_MAP_ID__ || "").toLowerCase();
  const gateName = GALAXY_GATE_DEFINITIONS[gateId]?.name || rules?.mapLabel || gateId;
  showNotification(`La vague ${wave} de la Galaxy Gate ${gateName} commence`, 4, "info", {
    log: false,
    goldTerms: [gateName],
  });
}

function beginWave() {
  const gateId = String(window.__CURRENT_MAP_ID__ || "").toLowerCase();
  if (rules?.mode === "gate" && GALAXY_GATE_DEFINITIONS[gateId]) wave = normalizeGalaxyGateWave(gateId, wave);
  const plan = getWavePlan(wave);
  currentWavePlan = plan;
  let spawns = plan.spawns || [];
  try {
    if (rules?.mode === "gate" && GALAXY_GATE_DEFINITIONS[gateId]) {
      const progress = getCurrentUserGalaxyGateWaveKills(gateId);
      if (progress && Number(progress.wave) === wave) spawns = remainingWaveSpawns(spawns, progress);
    }
  } catch {}
  try {
    // ✅ Gate Eternal : mémorise la vague (reprise refresh) et retire les
    // NPC déjà tués de la vague en cours (comme les GG classiques).
    if (rules?.mode === "gate" && gateId === "eternal") {
      const eu = getCurrentUserFull();
      if (Math.max(1, Math.floor(Number(eu?.eternalGate?.wave) || 1)) !== wave) {
        const sw = saveEternalGateWave(wave);
        if (sw.ok) account.user = sw.user;
      }
      const wk = normalizeEternalGateState((account.user || getCurrentUserFull())?.eternalGate).waveKills;
      if (wk && Number(wk.wave) === wave) spawns = remainingWaveSpawns(spawns, wk);
    }
  } catch {}
  waveSpawns.load(spawns);
  betweenWaves = false;
  waveStartCountdown = rules?.mode === "gate" ? GATE_WAVE_COUNTDOWN_SECONDS : 0;
  waveCountdownSecond = -1;

  portal.active = false;
  gateReturnPortal.active = false;
  ui.portalOverlay.style.display = "none";
  ui.nextWaveBtn.disabled = false;

  if (waveStartCountdown > 0) updateWaveCountdownNotice();
}

function tryCompleteClearedGalaxyGate() {
  if (mapSwitchInProgress) return true;
  const gateId = String(window.__CURRENT_MAP_ID__ || "").toLowerCase();
  const gate = rules?.mode === "gate" ? GALAXY_GATE_DEFINITIONS[gateId] : null;
  if (!gate || wave < gate.maxWaves) return false;
  if (gateCompletionPending) return true;
  if (waveSpawns.remaining > 0) return false;
  // Les renforts dynamiques hors plan (Protegit, phases...) ne bloquent
  // pas la fin. Tous les NPC prevus dans la derniere vague doivent mourir.
  const planTypes = new Set((currentWavePlan?.spawns || []).map(spawn => String(spawn?.type || "")));
  // Attendre aussi le retrait des NPC morts : processDeaths doit d'abord
  // crediter le dernier kill et enregistrer sa progression avant le bonus.
  if (enemies.some(enemy => enemy && !enemy._bossPhaseMinion && !enemy.masterId && planTypes.has(String(enemy.type || "")))) return false;
  runOnKillAction({ tp: { factionBase: true } });
  return true;
}

function onWaveCleared() {
  if (gateCompletionPending) return;
  if (tryCompleteClearedGalaxyGate()) return;
  // ✅ Gate Eternal (rules.autoChainWaves) : les vagues s'enchaînent toutes
  // seules, sans portails de choix continuer/retour. La suivante démarre
  // après le compte à rebours standard (recentrage comme le portail continuer).
  if (rules?.autoChainWaves && !mapSwitchInProgress && !player.dead) {
    const isEternalRun = String(window.__CURRENT_MAP_ID__ || "").toLowerCase() === "eternal";
    if (isEternalRun) {
      // ✅ vague Eternal terminée : compteur total persisté aussitôt
      // (le classement se met à jour à chaque vague). Objet frais
      // (pas account.user, potentiellement périmé en multi).
      // Synchro serveur immédiate : un refresh juste après ne doit rien perdre.
      try {
        const cleared = recordEternalGateWaveCleared(wave);
        if (cleared.ok) account.user = cleared.user;
        if (netActive()) flushNetUser().catch(() => {});
      } catch {}
    }
    const nextPlan = getWavePlan(wave + 1);
    if (nextPlan && Array.isArray(nextPlan.spawns) && nextPlan.spawns.length) {
      // ✅ pas de recentrage entre les vagues : ça enchaîne sur place.
      betweenWaves = false;
      wave++;
      beginWave();
      return;
    }
    // ✅ dernière vague Eternal : boucle bouclée -> compteur de boucles
    // persisté aussitôt, recentrage au centre, puis portails de choix
    // (continuer = boucle suivante ×N, retour = base, gate conservée).
    if (String(window.__CURRENT_MAP_ID__ || "").toLowerCase() === "eternal" && wave > 1) {
      try {
        const done = recordEternalGateLoopDone();
        if (done.ok) account.user = done.user;
        if (netActive()) flushNetUser().catch(() => {});
      } catch {}
      player.x = clamp(WORLD.w / 2, 80, WORLD.w - 80);
      player.y = clamp(WORLD.h / 2, 80, WORLD.h - 80);
      player.vx = 0;
      player.vy = 0;
      moveTarget.active = false;
      camera.x = player.x;
      camera.y = player.y;
    }
  }
  betweenWaves = true;
  resetGatePortalState(portal, { active: true, switchDuration: portal.switchDur });
  portal.switchDur = Math.max(0.1, Number(portal.switchDur || 1));
  portal.holdDur = Math.max(0.1, Number(portal.holdDur || 1.5));
  resetGatePortalState(gateReturnPortal, { active: true, switchDuration: portal.switchDur });
  positionGateChoicePortals(WORLD, portal, gateReturnPortal, 840);
  portal.startAfterSwitch = false;
  // ✅ précharge la base mère dès la fin de vague : le portail « retour »
  // bascule en interne sans écran de chargement.
  try { preloadRespawnMap(getGateReturnMap()); } catch {}

  if (ui.portalOverlay) ui.portalOverlay.style.display = "none";
}

function tryStartNextWave() {
  if (!started || player.dead) return;
  if (!betweenWaves) return;

  if (portal.switching || portal.holding) return;

  portal.switching = true;
  portal.switchT = 0;

  portal.open = false;
  portal.holding = false;
  portal.holdT = 0;

  portal.startAfterSwitch = true;
}

function waveController(dt) {
  if (!started || player.dead || betweenWaves || mapSwitchInProgress) return;

  if (waveStartCountdown > 0) {
    waveStartCountdown = Math.max(0, waveStartCountdown - dt);
    if (waveStartCountdown > 0) {
      updateWaveCountdownNotice();
      return;
    }
    finishWaveCountdownNotice();
  }

if (waveSpawns.remaining > 0 && (waveSpawns.queue || []).length > 0 && enemies.length < MAX_ALIVE) {
  if (waveSpawns.tick(dt)) {
    const next = waveSpawns.peek();
    const type = next?.type || DEFAULT_WAVE_TYPE;
    const isCubikon = (type === "npc_Cubikon");
    const isEncounterBoss = rules?.bossEncounter?.bossType === type;

    const extra = clamp((wave - 1) * 40, 0, 2200);
    const minD = 1800 + extra;
    const maxD = 3400 + extra;

    const encounterPosition = rules?.bossEncounter?.position;
    const pos = isEncounterBoss
      ? {
          x: Number.isFinite(Number(encounterPosition?.x)) ? Number(encounterPosition.x) : WORLD.w * (Number(encounterPosition?.xRatio) || 0.5),
          y: Number.isFinite(Number(encounterPosition?.y)) ? Number(encounterPosition.y) : WORLD.h * (Number(encounterPosition?.yRatio) || 0.5),
        }
      : (isCubikon ? spawnAtSafeDistance(minD, maxD, 700) : spawnRandomOnMap());

    const { x, y } = pos;

    const e = makeEnemy(type, x, y);
    if (e) {
      e._gateWave = wave;
      e._onKill = next?.onKill || null;
      if (!isEncounterBoss && rules?.bossEncounter?.initialGuard) e._bossInitialGuard = true;
      // ✅ boss de vague : même état encounter que le spawn factory (Zeta).
      if (isEncounterBoss) {
        e._bossEncounter = {
          phase: 0,
          invulnerable: !!rules?.bossEncounter?.initialGuard,
          initialGuard: !!rules?.bossEncounter?.initialGuard,
          minionIds: [],
        };
        e._stationaryBoss = !!rules?.bossEncounter?.stationary;
      }
      enemies.push(e);
    }

    waveSpawns.consume();
  }
}

  // ✅ paliers de vague (ex. Awakened vague 5 : 3 Impulse II verts après les
  // 30 Blighted) : file vide + aucun NPC en vie → on libère le palier suivant
  // au lieu de clôturer la vague.
  if (waveSpawns.remaining > 0 && (waveSpawns.queue || []).length === 0 && enemies.length === 0) {
    try { if (typeof waveSpawns.releaseStaged === "function") waveSpawns.releaseStaged(); } catch {}
  }

  if (tryCompleteClearedGalaxyGate()) return;
  if (waveSpawns.remaining === 0 && enemies.length === 0) {
    onWaveCleared();
  }
}

// Multi : kamikaze partage — degats a moi si je suis dans le rayon,
// une seule fois (comme l'explosion locale en solo).
const NET_AUDIO_RADIUS = 1200;
const NET_AUDIO_FULL_RADIUS = 250;

function netAudioVolume(x, y) {
  const distance = Math.hypot(Number(x) - Number(player.x), Number(y) - Number(player.y));
  if (!Number.isFinite(distance) || distance >= NET_AUDIO_RADIUS) return 0;
  if (distance <= NET_AUDIO_FULL_RADIUS) return 1;
  return clamp(1 - (distance - NET_AUDIO_FULL_RADIUS) / (NET_AUDIO_RADIUS - NET_AUDIO_FULL_RADIUS), 0, 1);
}

function playNetSpatialSound(name, x, y, options = {}) {
  const spatialVolume = netAudioVolume(x, y);
  if (!(spatialVolume > 0)) return false;
  try {
    SFX.play(name, { ...options, vol: spatialVolume * Math.max(0, Number(options.vol ?? 1)) });
    return true;
  } catch { return false; }
}

function netBoomSelfDamage(c, cause, x, y) {
  if (cause !== "boom" || c._netBoomDone) return;
  c._netBoomDone = true;
  try {
    const cfg = NPC_TYPES[c.type] || {};
    const rr = Number(cfg.explodeRadius ?? 180);
    if (!player.dead && dist2(player.x, player.y, x, y) <= rr * rr) {
      hurtPlayer(Number(cfg.explodeDmg ?? 12000), c);
    }
  } catch {}
}

// Multi PvP : pas de tir sur une cible en zone de non-agression.
// Si seul l'attaquant est protégé, l'attaque reste possible mais la fait
// tomber (combatT / attackActive lèvent sa ZNA pendant 5 s) : on peut tirer
// depuis sa base/portail sur un ennemi dehors, à ses risques et périls.
let lastPvpSafeToastAt = 0;
function netSelfSafe() {
  try { return safeZoneActive && playerIsInSafeZone(); } catch { return false; }
}
function netPvpBlocked(t) {
  if (!t) return false;
  // Bots JPC à l'abri (portail/base) : même règle que les joueurs en ZNA —
  // cible intouchable, l'attaque ne part pas (toast comme pour les joueurs).
  try {
    if (typeof isJpcBotSheltered === "function" && isJpcBotSheltered(t, npcIsInSafeZone)) {
      try {
        const nowMs = performance.now();
        if (nowMs - lastPvpSafeToastAt > 3000) {
          lastPvpSafeToastAt = nowMs;
          showToast("Zone de non-agression", 1.4);
        }
      } catch {}
      return true;
    }
  } catch {}
  // Propre REX : pas d'attaque dessus quand on est en ZNA (ailleurs, inchangé).
  if (isOwnPetTarget(t)) {
    if (!netSelfSafe()) return false;
    try {
      const nowMs = performance.now();
      if (nowMs - lastPvpSafeToastAt > 3000) {
        lastPvpSafeToastAt = nowMs;
        showToast("Zone de non-agression", 1.4);
      }
    } catch {}
    return true;
  }
  if ((!t._netPlayer && !t._netPet) || !isSharedZone()) return false;
  // Seule la cible compte : protégée -> intouchable. Attaquant protégé
  // seul -> autorisé (il perd sa ZNA en attaquant, mécanique existante).
  let foeSafe = false;
  try { foeSafe = t._netSafe === true; } catch {}
  if (!foeSafe) return false;
  try {
    const nowMs = performance.now();
    if (nowMs - lastPvpSafeToastAt > 3000) {
      lastPvpSafeToastAt = nowMs;
      showToast("Zone de non-agression", 1.4);
    }
  } catch {}
  return true;
}
// Propre REX (locké pour voir ses barres) : on ne peut jamais lui tirer
// dessus, ZNA ou pas. Le lock reste autorisé (affichage des barres).
function isOwnPetTarget(t) {
  try {
    return !!t && (t.isPetTarget === true || t === petTargetProxy || String(t.id || "") === "pet");
  } catch { return false; }
}

// Multi : cible de tir partagee d'un NPC serveur.
// - aggro == moi : le joueur local (vrais tirs, vrais degats) ;
// - aggro == copain : sa position interpolee (tirs visuels, zero degat :
//   enemyShoot les marque "escort" avec un targetId introuvable, ils volent
//   droit et expirent sans collision) ;
// - sinon : null (pas de tir, le NPC est calme).
function netNpcCombatTarget(e) {
  const aggro = e._netAggro;
  if (aggro == null) return null;
  if (String(aggro) === String(netMyId())) return player.dead ? null : player;
  try {
    const remotes = getNetplayRemotes();
    const f = remotes ? remotes.get(String(aggro)) : null;
    if (!f || f.dead) return null;
    return { x: Number(f.rx ?? f.x), y: Number(f.ry ?? f.y), hp: 1, r: 18, _netVisual: true };
  } catch { return null; }
}

// Multi PvP : avatars des joueurs distants (hors tableau `enemies` pour ne
// perturber aucun systeme NPC : ils vivent dans enemiesById pour le homing).
// Membres du groupe (cache 1 s) : visibles au-delà du rayon capteurs,
// comme un lock (coordination conservée malgré le culling 1800).
let remoteGroupIdsAt = 0;
let remoteGroupIds = new Set();
let remoteGroupPseudos = new Set();
function isRemoteGroupMember(r) {
  try {
    const now = performance.now();
    if (now - remoteGroupIdsAt > 1000) {
      remoteGroupIdsAt = now;
      remoteGroupIds = new Set();
      remoteGroupPseudos = new Set();
      const members = getNetGroup()?.members;
      if (Array.isArray(members)) {
        for (const m of members) {
          if (m?.id != null) remoteGroupIds.add(String(m.id));
          if (m?.pseudo) remoteGroupPseudos.add(String(m.pseudo));
        }
      }
    }
    if (r?.id != null && remoteGroupIds.has(String(r.id))) return true;
    if (r?.pseudo && remoteGroupPseudos.has(String(r.pseudo))) return true;
  } catch {}
  return false;
}
const netPlayerProxies = new Map(); // clientId -> entite cible
const netPetProxies = new Map(); // clientId -> proxy du PET allie (lock + degats PvP)
let lastPvpAdoptAt = 0;
let lastOrcusHealAt = 0;
let lastNpcDamageAdoptAt = 0;
let lastNpcDamageAdoptSeq = 0;
let lastPetPvpAdoptAt = 0;
function syncLocalDisarrayShield(self) {
  const previous = Number(player._netDisarrayRemoved) || 0;
  const base = Math.max(0, Number(player.shMax) || 0)
    + (player.shMax === player._netDisarrayMax ? previous : 0);
  const removed = self?.disarrayT > 0 && !player.dead ? Math.floor(base / 2) : 0;
  player.shMax = base - removed;
  if (removed > previous) player.sh = Math.min(player.sh, player.shMax);
  else if (removed < previous && !player.dead) player.sh = Math.min(player.shMax, player.sh + previous - removed);
  player._netDisarrayRemoved = removed;
  player._netDisarrayMax = player.shMax;
}
function syncLocalTempestBackup(self) {
  if (!isTempestHull() || !self) return;
  if (Number(self.jamT) > 0) return;
  if (self.voltBackupT > 0 && self.voltBackupAt !== player._netTempestBackupAt) {
    player._netTempestBackupAt = self.voltBackupAt;
    player.hp = 1;
    player.tempestBackupT = self.voltBackupT;
    player.tempestBackupCd = self.voltBackupCd;
    player.invincibleT = Math.max(Number(player.invincibleT) || 0, self.voltBackupT);
    persistCdUntil("tempestBackupFx", self.voltBackupT);
    persistCdUntil("tempestBackup", self.voltBackupT + self.voltBackupCd);
    showNotification("Volt Back-up : invincible 10 s", 3, "info");
  }
}
function syncNetPlayers(dt = 0.016) {
  let remotes = null;
  try { remotes = getNetplayRemotes(); } catch { remotes = null; }
  try { tickNetplayRemotes(dt); } catch {}
  const seen = new Set();
  const petSeen = new Set();
  if (remotes && isSharedZone()) {
    for (const [rid, r] of remotes) {
      if (!r) continue;
      try { warmNetplayRemoteAssets(r); } catch {}
      // Mort d'un joueur distant : explosion comme les NPC (une fois),
      // puis purge du proxy. Disparition sans mort (deco/changement
      // de map) : suppression silencieuse, sans explosion.
      const hasAuthoritativePools = Number.isFinite(Number(r.pvpHp)) && Number.isFinite(Number(r.pvpSh));
      const confirmedRemoteDeath = r.dead === true
        && (!hasAuthoritativePools || (Number(r.pvpHp) <= 0 && Number(r.pvpSh) <= 0));
      if (r.dead && !confirmedRemoteDeath) continue;
      if (confirmedRemoteDeath) {
        const gone = netPlayerProxies.get(rid);
        if (gone && !gone._netDeadBoom) {
          gone._netDeadBoom = true;
          const deathX = Number(r.rx ?? r.x) || gone.x;
          const deathY = Number(r.ry ?? r.y) || gone.y;
          try { spawnExplosion(deathX, deathY, 1.0); } catch {}
          playNetSpatialSound("npcDeath", deathX, deathY, { cooldown: 0 });
          try { if (Target.get() === gone) Target.clear(); } catch {}
        }
        continue;
      }
      seen.add(rid);
      let e = netPlayerProxies.get(rid);
      if (!e) {
        e = {
          id: `netp:${rid}`, _netPlayer: String(rid), type: "player",
          name: (r.clan ? `[${r.clan}] ` : "") + String(r.pseudo || "Pilote"),
          x: 0, y: 0, vx: 0, vy: 0, r: 20, angle: 0,
          hp: 1, hpMax: 1, sh: 0, shMax: 0,
          _previousX: 0, _previousY: 0,
        };
        netPlayerProxies.set(rid, e);
        try { enemiesById.set(e.id, e); } catch {}
      }
      e.name = (r.clan ? `[${r.clan}] ` : "") + String(r.pseudo || "Pilote");
      e.x = Number(r.rx ?? r.x);
      e.y = Number(r.ry ?? r.y);
      e._previousX = e.x;
      e._previousY = e.y;
      e.angle = Number(r.rangle ?? r.angle) || 0;
      const hm = Math.max(1, Number(r.hpMax) || 1);
      const sm = Math.max(0, Number(r.shMax) || 0);
      e.hpMax = hm;
      e.shMax = sm;
      e.hp = hasAuthoritativePools
        ? Math.max(0, Math.min(hm, Number(r.pvpHp)))
        : Math.max(0, Math.min(hm, hm * Number(r.hpPct ?? 1)));
      e.sh = hasAuthoritativePools
        ? Math.max(0, Math.min(sm, Number(r.pvpSh)))
        : Math.max(0, Math.min(sm, sm * Number(r.shPct ?? 1)));
      e._netSafe = r.safe === true;
      e.rocketSlowPct = Number(r.rocketSlowPct) || 0;
      e.rocketSlowT = Number(r.rocketSlowT) || 0;
      e.freezeT = Number(r.freezeT) || 0;
      e._netIemT = Number(r.iemT) || 0;
      e._netCloaked = r.cloaked === true;
      // Phase 2 : auras d'aptitudes visibles ([code, secLeft, x, y, target]).
      e.afx = Array.isArray(r.afx) ? r.afx : [];
      if (e._netIemT > 0 && Target.get() === e) {
        Target.clear();
        attackActive = false;
      }
      // Camouflage d'aptitude du distant : lock coupé comme par une IEM.
      if (r.cloaked === true && Target.get() === e) {
        Target.clear();
        attackActive = false;
      }
      // PET allie : proxy lockable (barres live). Degats PvP via pvpPetHit.
      if (r.peta === 1) {
        petSeen.add(rid);
        let pe = netPetProxies.get(rid);
        if (!pe) {
          pe = {
            id: `netpet:${rid}`, _netPet: String(rid), type: "pet",
            name: String(r.petn || "P.E.T"),
            x: 0, y: 0, r: 24, angle: 0,
            hp: 100, hpMax: 100, sh: 100, shMax: 100,
          };
          netPetProxies.set(rid, pe);
          try { enemiesById.set(pe.id, pe); } catch {}
        }
        pe.name = String(r.petn || "P.E.T");
        pe.x = Number(r.petrx ?? r.petx);
        pe.y = Number(r.petry ?? r.pety);
        pe.angle = Number(r.petd ?? r.angle) || 0;
        pe._netSafe = r.safe === true;
        // Barres = pool serveur (verite), pas le local du proprio (regenere).
        pe.hpMax = Math.max(1, Math.round(Number(r.petHpM) || 100));
        pe.shMax = Math.max(0, Math.round(Number(r.petShM) || 0));
        pe.hp = Math.max(0, Math.min(pe.hpMax, Math.round(Number(r.pvpPetHp ?? r.petHp * pe.hpMax) || 0)));
        pe.sh = pe.shMax > 0 ? Math.max(0, Math.min(pe.shMax, Math.round(Number(r.pvpPetSh ?? r.petSh * pe.shMax) || 0))) : 0;
      }
    }
  }
  for (const [rid, pe] of [...netPetProxies]) {
    if (petSeen.has(rid)) continue;
    netPetProxies.delete(rid);
    try { enemiesById.delete(pe.id); } catch {}
    try { if (Target.get() === pe) Target.clear(); } catch {}
  }
  for (const [rid, e] of [...netPlayerProxies]) {
    if (seen.has(rid)) continue;
    netPlayerProxies.delete(rid);
    try { enemiesById.delete(e.id); } catch {}
    try { if (Target.get() === e) Target.clear(); } catch {}
  }
}

try {
  window.__PVP__ = {
    proxies: () => { try { return netPlayerProxies.size; } catch { return -1; } },
    lockedNetPlayer: () => { try { return Target.get()?._netPlayer || null; } catch { return null; } },
    lockState: () => {
      try {
        const t = Target.get();
        if (!t) return "no-lock";
        if (t._netPlayer) return `locked:player:${t._netPlayer}`;
        return `locked:npc:${t.type || "?"}:${t.id ?? "?"}`;
      } catch (err) { return `err:${String(err && err.message || err)}`; }
    },
    probe: () => {
      try {
        const list = [...netPlayerProxies.values()].map((e) => ({ hp: e.hp, hpMax: e.hpMax, x: Math.round(e.x), y: Math.round(e.y) }));
        return { active: isSharedZone(), me: { x: Math.round(player.x), y: Math.round(player.y) }, proxies: list };
      } catch (err) { return { err: String(err && err.message || err) }; }
    },
    selfTest: () => {
      // Rejoue le clic exact au centre du proxy : doit retrouver le proxy.
      try {
        const e = [...netPlayerProxies.values()][0];
        if (!e) return { result: "no-proxy" };
        const s = worldToScreenPoint(e.x, e.y, camera, innerWidth, innerHeight);
        let found = null;
        try { found = pickEnemyAtScreen(s.x, s.y); } catch (err) { return { result: "pick-threw", err: String(err && err.message || err) }; }
        if (!found) return { result: "pick-null", screen: { x: Math.round(s.x), y: Math.round(s.y) }, proxyHp: e.hp, active: isSharedZone() };
        if (found._netPlayer) return { result: "OK-pick-works" };
        return { result: `found-npc-instead:${found.type}` };
      } catch (err) { return { result: "err", err: String(err && err.message || err) }; }
    },
    testFire: () => {
      // Force un tir laser sur le lock courant et rapporte chaque etape.
      try {
        const t = Target.get();
        const info = {
          locked: t ? (t._netPlayer ? `player:${t._netPlayer}` : `npc:${t.type}`) : null,
          dist: t ? Math.round(Math.hypot(t.x - player.x, t.y - player.y)) : null,
          range: Math.round(playerRange),
          attackActive,
          fireCooldown: Number(fireCooldown) || 0,
          bulletsBefore: bullets.length,
        };
        info.tryFireOnce = tryFireOnce(null, true);
        info.bulletsAfter = bullets.length;
        return JSON.stringify(info);
      } catch (err) { return `ERR:${String(err && err.message || err)}`; }
    },
    testRocket: () => {
      // Force une roquette sur le lock courant et rapporte chaque etape.
      try {
        const t = Target.get();
        const info = {
          locked: t ? (t._netPlayer ? `player:${t._netPlayer}` : `npc:${t.type}`) : null,
          stock: rocketCount(player.rocketActive),
          cd: rocketCooldownLeft(player.rocketActive),
          bulletsBefore: bullets.length,
        };
        info.fired = tryFireRocket({});
        info.bulletsAfter = bullets.length;
        return JSON.stringify(info);
      } catch (err) { return `ERR:${String(err && err.message || err)}`; }
    },
  };
} catch {}

// Multi : reconcilie les entites locales avec les snapshots NPC serveur.
// - apparition / positions (interpolees) / HP / angle depuis le serveur ;
// - mort + killer depuis le serveur (processDeaths tranche les recompenses) ;
// - hors zone (GG) : purge les entites réseau et laisse l'instance privée.
function syncNetNpcs(dt) {
  // Reboot serveur (run changé, consommé via welcome) : purge déterministe
  // des entités réseau. Le seq serveur repart de zéro : un cadavre conservé
  // (même uid, même seq) bloquerait sinon la nouvelle incarnation et le NPC
  // ne réapparaîtrait jamais côté client alors que le serveur l'a respawné.
  try {
    if (consumeNetServerRestart()) {
      purgeNetEntitiesForReconnect();
      forceReloadAfterServerRestart();
    }
  } catch {}
  let remotes = null;
  try { remotes = getNetNpcs(); } catch { remotes = null; }
  if (!isSharedZone() || !remotes) {
    let purged = false;
    for (let i = enemies.length - 1; i >= 0; i--) {
      if (enemies[i]?._netUid) { enemies.splice(i, 1); purged = true; }
    }
    if (purged) { try { if (Target.get()?._netUid) Target.clear(); } catch {} }
    return;
  }
  const k = Math.max(0, Math.min(1, (Number(dt) || 0.016) * 6));
  const seen = new Set();
  const now = performance.now();
  // Doublons locaux (spawnes avant le premier snapshot ou pendant une
  // coupure) : le serveur possede les spawns de zone, on les retire pour
  // ne garder que les entites partagees. Les speciaux (vagues de boss...)
  // n'ont pas d'universeUid et sont conserves — SAUF les Protegit de
  // Cubikon : la vague est desormais serveur (visible par tous), les
  // copies locales seraient des fantomes (poursuite infinie, sans partage).
  for (let i = enemies.length - 1; i >= 0; i--) {
    const c = enemies[i];
    if (!c || c._netUid) continue;
    if (c.universeUid) {
      try { if (Target.get() === c) Target.clear(); } catch {}
      enemies.splice(i, 1);
    } else if (c.type === "npc_Protegit" && c.masterId && !c._bossPhaseMinion) {
      try { if (Target.get() === c) Target.clear(); } catch {}
      enemies.splice(i, 1);
    } else if (!c.isPetTarget && typeof c.type === "string" && c.type.startsWith("npc_")
      && !c.masterId && !c._bossPhaseMinion) {
      // Renforts onKill locaux (vagues Gygerthrall...) : la vague est
      // desormais serveur en multi, ces copies fantomes (une par ecran,
      // recompenses locales = farm infini) sont purgees.
      try { if (Target.get() === c) Target.clear(); } catch {}
      enemies.splice(i, 1);
    }
  }
  // Retraits serveur sans mort (despawn de vague Cubikon) : purge immediate,
  // silencieuse (ni explosion ni recompense), lock libere.
  try {
    const gone = drainNetGone();
    if (gone.length) {
      for (const gid of gone) {
        for (let i = enemies.length - 1; i >= 0; i--) {
          const c = enemies[i];
          if (c && c._netUid === gid) {
            try { if (Target.get() === c) Target.clear(); } catch {}
            enemies.splice(i, 1);
          }
        }
      }
    }
  } catch {}
  // Journal des kills serveur D'ABORD : il tranche les morts de l'incarnation
  // courante, meme si la prediction locale la croyait encore en vie (les
  // degats du copain ont fait la difference). HP force a 0 pour que
  // processDeaths tranche les recompenses. Le seq protege la nouvelle
  // incarnation d'un vieux kill.
  try {
    const deaths = getNetDeaths();
    if (deaths && deaths.size) {
      for (const c of enemies) {
        if (!c || !c._netUid || c._netKiller != null) continue;
        const d = deaths.get(c._netUid);
        if (d && (Number(d.seq) || 0) === (c._netSeq || 0)) {
          const killerId = String(d.killer);
          const ownsKill = killerId === String(netMyId());
          const groupMate = rules?.mode !== "gate" && getNetGroup()?.members?.some((m) => String(m.id) === killerId && String(m.map).toLowerCase() === String(window.__CURRENT_MAP_ID__ || "").toLowerCase() && m.instance !== true);
          c._netKiller = ownsKill || groupMate === true;
          c._netKillerId = killerId;
          c._netKillerPseudo = getNetGroup()?.members?.find((m) => String(m.id) === killerId)?.pseudo || "";
          c._netLootOwner = ownsKill;
          c._netWaiting = false;
          c.hp = 0;
          c.sh = 0;
          netBoomSelfDamage(c, d.cause, Number(d.x) || c.x, Number(d.y) || c.y);
        }
      }
    }
  } catch {}
  // Index uid -> entite (une passe) : la recherche lineaire par snapshot
  // coutait O(n2) par frame (~0.2 ms a 220 NPC, quadratique au-dela).
  const netUidToEnemy = new Map();
  try {
    let currentTarget = null;
    try { currentTarget = Target.get(); } catch {}
    // Une seule entite locale par uid serveur. En cas de doublon transitoire,
    // conserver celle deja verrouillee evite tout saut de cible/mouvement.
    for (let i = enemies.length - 1; i >= 0; i--) {
      const c = enemies[i];
      if (!c || c._netUid == null) continue;
      const uid = String(c._netUid);
      const kept = netUidToEnemy.get(uid);
      if (!kept) {
        netUidToEnemy.set(uid, c);
        continue;
      }
      if (c === currentTarget) {
        const keptIndex = enemies.indexOf(kept);
        if (keptIndex >= 0) enemies.splice(keptIndex, 1);
        netUidToEnemy.set(uid, c);
      } else {
        enemies.splice(i, 1);
      }
    }
  } catch {}
  for (const s of remotes.values()) {
    if (!s || !s.uid) continue;
    const snapshotUid = String(s.uid);
    seen.add(snapshotUid);
    let e = netUidToEnemy.get(snapshotUid) || null;
    // Lors du premier snapshot apres un changement de carte, `s.x/y` peut
    // deja contenir la position serveur suivante tandis que `s.rx/ry` est la
    // position de rendu lissee. Creer le NPC sur x/y puis le ramener vers
    // rx/ry dans la meme frame produisait le petit dash collectif au portail.
    const snapX = Number(s.rx ?? s.x) || 0, snapY = Number(s.ry ?? s.y) || 0;
    if (s.alive === false) {
      if (e && (e._netSeq || 0) === (Number(s.seq) || 0)) {
        e.hp = 0;
        e.sh = 0;
        if (e._netKiller == null && s.killer != null) {
          const killerId = String(s.killer);
          const ownsKill = killerId === String(netMyId());
          const groupMate = rules?.mode !== "gate" && getNetGroup()?.members?.some((m) => String(m.id) === killerId && String(m.map).toLowerCase() === String(window.__CURRENT_MAP_ID__ || "").toLowerCase() && m.instance !== true);
          e._netKiller = ownsKill || groupMate === true;
          e._netKillerId = killerId;
          e._netKillerPseudo = getNetGroup()?.members?.find((m) => String(m.id) === killerId)?.pseudo || "";
          e._netLootOwner = ownsKill;
        }
        netBoomSelfDamage(e, s.cause, e.x, e.y);
      }
      continue;
    }
    if (!e) {
      e = makeEnemy(s.type, snapX, snapY);
      if (!e) continue;
      e._netUid = String(s.uid);
      e._netSeq = Number(s.seq) || 0;
      // Bots JPC natifs : présentation faux-joueur (même plaque qu'en solo).
      if (typeof s.type === "string" && s.type.indexOf("npc_Jpc_") === 0) {
        e.isJpcBot = true;
        e.jpcShip = String(s.type).slice(8).toLowerCase();
        e.jpcPseudo = String(s.jpPseudo || "JPC");
        e.name = e.jpcPseudo;
        e.droneCfg = {
          count: Math.max(0, Math.min(12, Number(s.jpDrones) || 0)),
          formation: String(s.jpForm || "standard"),
          design: "havoc",
          designs: (Array.isArray(s.jpDes) && s.jpDes.length ? s.jpDes : ["havoc"]).slice(0, 12).map(String),
          level: Math.max(1, Math.min(6, Number(s.jpLvl) || 1)),
        };
        if (e.droneCfg.designs.length && !e.droneCfg.designs.includes(e.droneCfg.design)) {
          e.droneCfg.design = e.droneCfg.designs[0];
        }
      }
      e.wanderMode = true;
      e._previousX = e.x;
      e._previousY = e.y;
      e._netSeenT = now;
      enemies.push(e);
      try { netUidToEnemy.set(e._netUid, e); } catch {}
    } else if ((e._netSeq || 0) !== (Number(s.seq) || 0)) {
      // Nouvelle incarnation (respawn).
      if (e._netKiller != null) {
        // Mort tranchee en attente de processDeaths : on garde l'entite
        // mourante telle quelle, la nouvelle incarnation spawnera apres.
        continue;
      }
      // Reset l'etat de mort precedent.
      e._netSeq = Number(s.seq) || 0;
      e._netKiller = null;
      e._netKillerId = null;
      e._netKillerPseudo = "";
      e._netLootOwner = false;
      e._netLockBy = null;
      e._netJpcBy = null;
      e._netWaiting = false;
      e._netSilent = false;
      e._deathFxPlayed = false;
      // Nouvelle incarnation : aucun trajet entre le cadavre et le nouveau
      // spawn. L'interpolation reprend seulement a partir de cette position.
      e.x = Number(s.x) || 0;
      e.y = Number(s.y) || 0;
      e.vx = 0;
      e.vy = 0;
      e._previousX = e.x;
      e._previousY = e.y;
    }
    const dx = snapX - e.x, dy = snapY - e.y;
    if (e.isJpcBot === true) {
      e._netSafe = typeof s.jpSafe === "boolean" ? s.jpSafe : null;
      // Le réseau borne déjà les pas : éviter un deuxième freinage ici.
      e.x = snapX; e.y = snapY;
      e.vx = Number(s.vx) || 0; e.vy = Number(s.vy) || 0;
    }
    else if (dx * dx + dy * dy > 2000 * 2000) { e.x = snapX; e.y = snapY; e.vx = 0; e.vy = 0; }
    else {
      e.x += dx * k; e.y += dy * k;
      // Vitesse reconstituée : flammes reacteurs + trainees du NPC.
      const vdt = Math.max(1e-3, Number(dt) || 0.016);
      e.vx = Math.max(-2000, Math.min(2000, (dx * k) / vdt));
      e.vy = Math.max(-2000, Math.min(2000, (dy * k) / vdt));
    }
    e._previousX = e.x;
    e._previousY = e.y;
    if (Number.isFinite(Number(s.angle))) e.angle = Number(s.angle);
    e.hpMax = Math.max(1, Number(s.hpMax) || e.hpMax);
    e.shMax = Math.max(0, Number(s.shMax) || 0);
    if (Number.isFinite(Number(s.hp))) {
      e.hp = e.hpMax > 0 ? Math.max(1, Math.min(e.hpMax, Math.round(Number(s.hp)))) : Math.max(1, Math.round(Number(s.hp)));
    }
    if (Number.isFinite(Number(s.sh))) {
      e.sh = e.shMax > 0 ? Math.max(0, Math.min(e.shMax, Math.round(Number(s.sh)))) : Math.max(0, Math.round(Number(s.sh)));
    }
    // Revive zombie (même seq, snapshot alive) : un ancien verdict de mort
    // (cadavre d'avant reboot, ou prédiction locale trop pessimiste) ne doit
    // pas coller à l'entité ressuscitée — sinon processDeaths la tuerait
    // sans attendre le serveur et le prochain respawn resterait bloqué.
    if (e._netKiller != null) {
      e._netKiller = null;
      e._netKillerId = null;
      e._netKillerPseudo = "";
      e._netLootOwner = false;
      e._netWaiting = false;
      e._netSilent = false;
      e._netReward = null;
      e._deathFxPlayed = false;
    }
    e._netAggro = s.aggro != null ? String(s.aggro) : null;
    e._netLockBy = s.lock != null ? String(s.lock) : null;
    e._netJpcBy = s.jpcBy != null ? String(s.jpcBy) : null;
    // Bots JPC natifs : pseudo + formation + ISH suivent le snapshot.
    if (e.isJpcBot === true) {
      if (s.jpPseudo) { e.jpcPseudo = String(s.jpPseudo); e.name = e.jpcPseudo; }
      if (e.droneCfg) {
        e.droneCfg.count = Math.max(0, Math.min(12, Number(s.jpDrones) || 0));
        e.droneCfg.formation = String(s.jpForm || "standard");
        e.droneCfg.level = Math.max(1, Math.min(6, Number(s.jpLvl) || 1));
        e.droneCfg.designs = Array.isArray(s.jpDes) && s.jpDes.length ? s.jpDes : ["havoc"];
      }
      e.ishT = Number(s.jpIsh) > 0 ? 1 : 0;
    }
    e.rocketSlowPct = Number(s.rocketSlowPct) || 0;
    e.rocketSlowT = Number(s.rocketSlowT) || 0;
    e.keresSprT = Number(s.keresSprT) || 0;
    e.jamxT = Number(s.jamT) || 0;
    if (e.jamxT > 0) {
      e._pendingSpawn = 0;
      e._animPhase = null;
      e.spritePlay = false;
    }
    e.freezeT = Number(s.freezeT) || 0;
    // Parite solo : le flag "m'a attaque recemment" (qui force l'affichage
    // radar/minimap) suit l'aggro partagee, sinon les NPC tires restent
    // visibles au loin pour toujours (leur boucle locale est sautee).
    e._attackedPlayerRecently = s.aggro != null && String(s.aggro) === String(netMyId());
    // Cubikon partage : le serveur pilote l'animation d'ouverture pour que
    // tous les ecrans la voient en meme temps. La machine locale (delay ->
    // open -> hold -> close) joue les sprites ; le spawn est inhibe en
    // multi (les Protegit arrivent via snapshot).
    if (e.type === "npc_Cubikon" && (s.cube === "delay" || s.cube === "open" || s.cube === "hold")) {
      const remain = Math.max(0, Number(s.cubeT) || 0);
      // Ordre delay < open < hold : si la machine locale a de l'avance sur
      // le snapshot (retard reseau), on ne revient jamais en arriere —
      // elle finit son cycle toute seule, sans rejouer l'ouverture.
      const cubeRank = s.cube === "hold" ? 2 : s.cube === "open" ? 1 : 0;
      const localRank = e._animPhase === "hold" ? 2 : e._animPhase === "open" ? 1 : e._animPhase === "delay" ? 0 : -1;
      if (e._animPhase !== s.cube && cubeRank >= localRank) {
        e._spawnedOnce = true;
        e._pendingSpawn = 0;
        e._animPhase = s.cube;
        e.spriteAcc = 0;
        if (s.cube === "delay") {
          e.spritePlay = false;
          e.spriteDir = 1;
          e.spriteIdx = 0;
          e._openDelayT = Math.max(0.1, remain);
          e._holdLastT = 0;
        } else if (s.cube === "open") {
          e.spritePlay = true;
          e.spriteDir = 1;
          e.spriteIdx = 0;
        } else if (s.cube === "hold") {
          try {
            const sp = NPC_TYPES[e.type]?.sprite;
            const frames = sp?.frames || sp?._imgs?.length || 1;
            e.spriteIdx = Math.max(0, frames - 1);
          } catch { e.spriteIdx = 12; }
          e.spritePlay = false;
          e._holdLastT = Math.max(0.1, remain);
        }
      } else if (s.cube === "delay") {
        e._openDelayT = Math.max(Number(e._openDelayT) || 0, remain);
      } else if (s.cube === "hold") {
        e._holdLastT = Math.max(Number(e._holdLastT) || 0, remain);
      }
    }
    e._netSeenT = now;
  }
  for (let i = enemies.length - 1; i >= 0; i--) {
    const e = enemies[i];
    if (!e || !e._netUid || seen.has(e._netUid)) continue;
    if (now - Number(e._netSeenT || 0) > 5000) enemies.splice(i, 1);
  }
  // Degats de l'allie : chiffres flottants (sans effet, le snapshot fait
  // foi pour les HP). NPC : uniquement si on locke la meme cible.
  // Subis (uid = moi) : toujours (laser / roquette / lance-roquettes).
  try {
    const feed = drainNetDmgInbox();
    const lockedUid = Target.get()?._netUid || null;
    let myId = null;
    try { myId = netMyId(); } catch {}
    for (const f of feed) {
      if (!f || !(f.total > 0)) continue;
      if (myId && String(f.uid) === String(myId)) {
        queueVolleyFloat(player, { total: f.total, sh: 0, hp: f.total, rawDamage: f.total }, `netdmg${(Math.random() * 1e9) | 0}`, 1, VOLLEY_FLOAT_TIMEOUT);
        continue;
      }
      // Degats subis par notre PET : chiffres sur le REX.
      if (myId && String(f.uid) === `pet:${String(myId)}`) {
        queueVolleyFloat(petState, { total: f.total, sh: 0, hp: f.total, rawDamage: f.total }, `netdmg${(Math.random() * 1e9) | 0}`, 1, VOLLEY_FLOAT_TIMEOUT);
        continue;
      }
      // Les degats allies ne s'affichent que sur la cible verrouillee.
      if (!lockedUid || String(f.uid) !== String(lockedUid)) continue;
      const e = netUidToEnemy.get(f.uid) || null;
      if (!e || !(e.hp > 0)) continue;
      queueVolleyFloat(e, { total: f.total, sh: 0, hp: f.total, rawDamage: f.total }, `netdmg${(Math.random() * 1e9) | 0}`, 1, VOLLEY_FLOAT_TIMEOUT);
    }
  } catch {}
  // Degats allies sur la station : chiffres flottants sur le cœur/module
  // verrouille uniquement (comme les NPC). Nos propres tirs sont exclus
  // du feed (deja affiches en local) et le serveur fait foi pour les HP.
  try {
    const sfeed = drainNetStationDmgInbox();
    if (sfeed.length) {
      const lockedStation = Target.get()?._stationTarget || null;
      for (const f of sfeed) {
        if (!f || !(Number(f.total) > 0)) continue;
        if (!lockedStation || String(f.target) !== String(lockedStation)) continue;
        const proxy = stationTargetProxies.get(String(f.target)) || null;
        if (!proxy || !(proxy.hp > 0)) continue;
        queueVolleyFloat(proxy, { total: f.total, sh: 0, hp: f.total, rawDamage: f.total }, `netdmg${(Math.random() * 1e9) | 0}`, 1, VOLLEY_FLOAT_TIMEOUT);
      }
    }
  } catch {}
  // Réparation JPC : chiffres +x (vert coque, bleu bouclier) sur le bot
  // locké uniquement, comme les dégâts alliés et les soins distants.
  try {
    const heals = drainNetHealInbox();
    const lockedUid = Target.get()?._netUid || null;
    for (const h of heals) {
      if (!h || !(Number(h.hp) > 0 || Number(h.sh) > 0)) continue;
      if (!lockedUid || String(h.uid) !== String(lockedUid)) continue;
      const e = netUidToEnemy.get(h.uid) || null;
      if (!e || !(e.hp > 0)) continue;
      if (Math.round(Number(h.hp) || 0) > 0) {
        addFloatText(e.x + (Math.random() - 0.5) * 60, e.y - 90 - Math.random() * 20,
          h.hp, "rgba(80,255,125,0.98)",
          { text: `+${DMG_FMT.format(Math.round(Number(h.hp) || 0))}`, size: 21, pop: 0.3, shake: 0.6, life: 1, glow: 1, weight: 900, impact: true });
      }
      if (Math.round(Number(h.sh) || 0) > 0) {
        addFloatText(e.x + (Math.random() - 0.5) * 60, e.y - 110 - Math.random() * 20,
          h.sh, "rgba(70,180,255,0.98)",
          { text: `+${DMG_FMT.format(Math.round(Number(h.sh) || 0))}`, size: 21, pop: 0.3, shake: 0.6, life: 1, glow: 1, weight: 900, impact: true });
      }
    }
  } catch {}
  // Recompenses PvP (serveur) : xp + honneur du kill, tueur uniquement.
  try {
    const kills = drainNetPvpKillInbox();
    for (const k of kills) {
      const gainedXp = awardExperience(Math.max(0, k.exp || 0), "pvp")?.gained ?? 0;
      const gainedHo = awardHonor(Math.max(0, k.honneur || 0))?.gained ?? 0;
      try {
        if (account.user) {
          account.user.stats ||= { honor: 0, exp: 0, rankPoints: 0, lifetimeKills: 0 };
          account.user.stats.lifetimeKills = Math.max(0, Number(account.user.stats.lifetimeKills || 0)) + 1;
          markProgressDirty();
        }
      } catch {}
      const farmed = Number(k.mult) > 0 && Number(k.mult) < 1 ? " (rendement réduit : même victime)" : "";
      showToast(`Vaisseau de ${k.victim} détruit : +${formatInteger(gainedHo)} honneur, +${formatInteger(gainedXp)} XP${farmed}`, 3.2);
      try { advanceQuestProgress("pvp", "pvp"); } catch {}
    }
    for (const k of drainNetPvpPetKillInbox()) {
      if (!k) continue;
      showToast(`P.E.T de ${k.victim} détruit !`, 2.6);
    }
  } catch {}
  // Cargo du vaincu : copies sur les autres ecrans + effacement au ramassage.
  try {
    for (const L of drainNetPvpLootInbox()) {
      if (!L || !L.uid || !L.onlyBy) continue;
      if (collectables.some((c) => c && c.id === L.uid)) continue;
      spawnCollectableAt("Cargo_Box", Number(L.x) || 0, Number(L.y) || 0, {
        armed: false,
        fromNpc: null,
        despawnAfter: 60,
        rewardOverride: { resources: {} },
        oreRemainder: { prometium: 1, endurium: 1, terbium: 1, prometid: 1, duranium: 1, promerium: 1, seprom: 1 },
        onlyBy: String(L.onlyBy),
        uid: String(L.uid),
      });
    }
    for (const uid of drainNetPvpLootTakeInbox()) {
      const i = collectables.findIndex((c) => c && c.id === uid);
      if (i < 0) continue;
      try { takeCollectableInstance(collectables[i], { fromNet: true }); } catch {}
      collectables.splice(i, 1);
    }
  } catch {}
  // Kick admin : explosion visible par tous + message a la victime.
  try {
    for (const B of drainNetAdminBoomInbox()) {
      if (!B) continue;
      try { spawnExplosion(Number(B.x) || 0, Number(B.y) || 0, 1.4); } catch {}
      try { SFX.play("npcDeath", { cooldown: 0 }); } catch {}
    }
  } catch {}
  // Verrou fantôme : géré par Target.get() qui suit le jumeau snapshot
  // (même uid) au lieu de casser le verrou en plein tir. Pas de clear ici :
  // la cible purgée puis réapparue reste verrouillée, la vraie mort (hp 0)
  // ou disparition (aucun jumeau) délocke normalement.
}

// --- Event Halloween : état par map (phase + compteur + boss tués), persisté ---
const HALLOWEEN_STATE_PREFIX = "orbit_halloween:";
const halloweenPhaseCache = { map: null, state: null };

function loadHalloweenState(mapId) {
  try {
    const raw = localStorage.getItem(HALLOWEEN_STATE_PREFIX + String(mapId || "").toLowerCase());
    if (!raw) return null;
    const st = JSON.parse(raw);
    if (!st || typeof st !== "object") return null;
    return normalizeHalloweenState(st);
  } catch { return null; }
}

function saveHalloweenState(mapId, st) {
  const id = String(mapId || "").toLowerCase();
  const clean = normalizeHalloweenState(st);
  halloweenPhaseCache.map = id;
  halloweenPhaseCache.state = clean;
  try {
    localStorage.setItem(HALLOWEEN_STATE_PREFIX + id, JSON.stringify(clean));
  } catch {}
}

function getHalloweenState(mapId) {
  const id = String(mapId || "").toLowerCase();
  if (halloweenPhaseCache.map === id && halloweenPhaseCache.state) return halloweenPhaseCache.state;
  const st = loadHalloweenState(id) || normalizeHalloweenState(null);
  halloweenPhaseCache.map = id;
  halloweenPhaseCache.state = st;
  return st;
}

function getHalloweenPhase(mapId) {
  return getHalloweenState(mapId).phase;
}

// Purge d'instances Halloween vivantes (sans récompense ni compteur).
// role null = tous les rôles (fin d'event en direct).
function purgeHalloweenInstances(role = "normal") {
  try {
    const curMap = currentMapId();
    for (let i = enemies.length - 1; i >= 0; i--) {
      const e = enemies[i];
      if (!e || !isHalloweenVariantType(e.type)) continue;
      if (role && halloweenRoleOf(e.type) !== role) continue;
      try { spawnExplosion(Number(e.x) || 0, Number(e.y) || 0, 1); } catch {}
      try {
        const deadUid = e.universeUid || (e.homeCampId != null ? slotUid(curMap, e.homeCampId) : null);
        if (deadUid && isZoneMap) markDead(universe, curMap, deadUid, worldClock.now());
      } catch {}
      enemies.splice(i, 1);
    }
    try { persistUniverse(); } catch {}
  } catch {}
}

// Passage en phase boss : tous les normaux vivants sont purgés. Leurs
// slots respawnent à la fin des boss.
function purgeHalloweenNormals() {
  purgeHalloweenInstances("normal");
}

// Compteur de l'event : 50 normaux -> 3 boss -> retour aux normaux.
function onHalloweenNpcKilled(e) {
  if (isSharedZone()) return; // multi : le serveur est autorité
  if (!isZoneMap) return;
  const role = halloweenRoleOf(e?.type);
  if (!role) return;
  const mapId = currentMapId();
  if (!isHalloweenMap(mapId)) return;
  const st = loadHalloweenState(mapId) || normalizeHalloweenState(null);
  const res = applyHalloweenKill(st, role, e.homeCampId);
  saveHalloweenState(mapId, res.state);
  if (res.transition === "toBoss") {
    purgeHalloweenNormals();
    try { showNotification("50 Curcubitors éliminés ! 3 Boss Curcubitors apparaissent !", 5, "info"); } catch {}
  } else if (res.transition === "toNormal") {
    try { showNotification("Boss Curcubitors éliminés ! Les Curcubitors reviennent…", 5, "info"); } catch {}
  }
}

let lastHalloweenSyncMs = 0;

// Synchro live de l'event (toutes les 5 s) : apparition / disparition SANS
// changer de map. Solo uniquement (zoneController est déjà coupé en multi).
function syncHalloweenLive(curMap) {
  const nowMs = worldClock.now();
  if (nowMs - lastHalloweenSyncMs < 5000) return;
  lastHalloweenSyncMs = nowMs;
  const mapId = String(curMap || currentMapId());
  const active = isHalloweenMapActive(mapId);
  const has = zoneCamps.some((c) => c?.event === "halloween");
  if (active && !has) {
    // Début d'event en direct : ajoute les camps + slots + précharge.
    const extras = appendHalloweenCamps([], WORLD, { npcTypes: NPC_TYPES, mapId });
    if (!extras.length) return;
    let nextId = 0;
    for (const c of zoneCamps) nextId = Math.max(nextId, Number(c?.id) || 0);
    for (const c of extras) { nextId += 1; zoneCamps.push({ ...c, id: nextId, t: 0 }); }
    try { ensureMapSlots(universe, mapId, zoneCamps, nowMs); } catch {}
    try { persistUniverse(); } catch {}
    for (const t of halloweenPreloadTypes(mapId, NPC_TYPES)) {
      try {
        const r = ensureNpcLoaded(t);
        if (r && typeof r.catch === "function") r.catch(() => {});
      } catch {}
    }
    try { showNotification("Event Halloween : les Curcubitors envahissent la map !", 5, "info"); } catch {}
  } else if (!active && has) {
    // Fin d'event en direct : purge les instances et retire camps + slots.
    purgeHalloweenInstances(null);
    for (let i = zoneCamps.length - 1; i >= 0; i--) {
      if (zoneCamps[i]?.event === "halloween") zoneCamps.splice(i, 1);
    }
    try {
      const list = universe?.maps?.[mapId];
      if (Array.isArray(list)) {
        universe.maps[mapId] = list.filter((s) => !isHalloweenVariantType(s?.type));
      }
      persistUniverse();
    } catch {}
    try { showNotification("L'event Halloween est terminé.", 4, "info"); } catch {}
  }
}

function zoneController() {
  // Les zones partagees sont entierement simulees par MULTI_SERVER.
}
function resetRun({ randomSpawn = false, preparedZoneCamps = null, preparedZonePortals = null } = {}) {
  phoneControls?.cancel();
  portalJumpActive = false;
  let spawnedFromPortal = false;
  attackActive = false;
  laserCombatInRange = null;
  escapeWatch = null;
  betweenWaves = false;
  pendingVolleys.clear();
  launcherVolleyImpactCount.clear();

  // ✅ arrivée effective sur la carte = saut réussi : le robot réparateur
  // est réarmé immédiatement (resetPlayerToBase le remet sur son cooldown),
  // la réparation repart dès l'arrivée, sons compris.
  player.repairJumpLock = false;

  portal.active = false;
  gateReturnPortal.active = false;
  if (ui.portalOverlay) ui.portalOverlay.style.display = "none";

bullets.length = 0;
enemyBullets.length = 0;
clearPendingSalvo();
clearPendingEscortSalvo();
clearPendingNpcFaux();
shipDamages.length = 0;
enemies.length = 0;
try { resetJpcState(String(window.__CURRENT_MAP_ID__ || "1-1")); } catch {}
try { resetJpcFill(); } catch {}
// Types JPC enregistrés au chargement de chaque map (multi natif : les
// entités partagées arrivent via snapshot, sans tick local).
try { ensureJpcTypes(); } catch {}
escortShips.length = 0;
pickups.length = 0;
collectables.length = 0;
collectablesWorldMap = null;
npcSpatialFrame = -1;
collectableSpatialLength = -1;
collectableSpatialDirty = true;
sparks.length = 0;
floatTexts.length = 0;
lasers.length = 0;
engineTrails.length = 0;
collectableSpawnT = 0;
collectableFarTickT = 0;

  fireCooldown = 0;
  laserCd = 2.0;
  rsbCooldown = 0;
  rcbCooldown = 0;

  const u = loadAccountUser();

  if (u?.ship) {
    const found = getShipPackByIdData(u.ship);
    if (found) ACTIVE_SHIP = found;
  }

  resetPlayerToBase();
  // 🔥 fin du cold start : le cooldown réparateur repart désormais normalement
  player.repairColdStart = false;

  // Stocks déjà restaurés depuis le compte par resetPlayerToBase
  // (restorePlayerStockFromUser) : rien de plus à faire ici.
  if (u) {
    updateAmmoUI();
  }

  moveTarget.active = false;
  Target.clear();

  if (isZoneMap && typeof rules.getZoneSpawns === "function") {
    // Event Halloween : Curcubitors calibrés par map, en plus des normaux.
    const rawCamps = appendHalloweenCamps(preparedZoneCamps || rules.getZoneSpawns(WORLD), WORLD,
      { npcTypes: NPC_TYPES, mapId: window.__CURRENT_MAP_ID__ });
    const freshCamps = applyNpcDensityToCamps(rawCamps).map((c, idx) => ({
      id: idx + 1,
      ...c,
      t: 0,
    }));
    // Univers persistant : apres la premiere generation, l'univers est
    // l'autorite (identite stable). Les defs fraiches (ordre random) ne
    // servent qu'au reglage (aggro, radius...) et aux nouveaux slots.
    // Sans ca, un Kristallon tape changeait de slot a chaque saut.
    try {
      const mapId = String(window.__CURRENT_MAP_ID__ || "1-1");
      // Hors event, les slots Halloween persistés sont écartés : les
      // Curcubitors disparaissent vraiment le 02/11.
      const stored = stripInactiveEventSlots(universe?.maps?.[mapId]);
      if (Array.isArray(stored) && stored.length > 0) {
        const tuningByType = new Map();
        for (const c of freshCamps) {
          if (!tuningByType.has(String(c.type))) tuningByType.set(String(c.type), c);
        }
        zoneCamps = pruneStoredSlotsToDensity(stored, Math.max(1, freshCamps.length)).map((s, idx) => {
          const tuning = tuningByType.get(String(s.type)) || freshCamps[idx] || freshCamps[0] || {};
          return {
            id: idx + 1,
            type: String(s.type),
            x: Number(s.homeX),
            y: Number(s.homeY),
            fixed: tuning.fixed === true,
            // Event Halloween : les flags viennent du tuning (les slots
            // persistés ne les portent pas). Sans eux, la gate de phase
            // ne bloque rien et les normaux spawnent pendant les boss.
            event: tuning.event === "halloween" ? "halloween" : null,
            role: tuning.event === "halloween" ? String(tuning.role || "normal") : null,
            spawnArea: tuning.spawnArea || null,
            spawnMinDistance: tuning.spawnMinDistance || 0,
            radius: tuning.radius ?? 350,
            respawn: tuning.respawn ?? 1.5,
            maxAlive: tuning.maxAlive ?? 1,
            speed: tuning.speed ?? null,
            aggroRange: tuning.aggroRange ?? 700,
            leashRange: tuning.leashRange ?? 1700,
            aggroHold: tuning.aggroHold ?? 4,
            t: 0,
          };
        });
        // La def a grandi (nouveau quota) : ajoute les slots manquants.
        if (freshCamps.length > zoneCamps.length) {
          for (let k = zoneCamps.length; k < freshCamps.length; k++) {
            zoneCamps.push({ ...freshCamps[k], id: k + 1, t: 0 });
          }
        }
        // Event (ex : Halloween) : les slots stockés remplissent déjà le
        // quota, mais les camps event n'y sont pas — les ajouter par rôle.
        try {
          const needHw = { normal: 0, boss: 0 };
          for (const c of freshCamps) {
            if (c?.event === "halloween") needHw[c.role === "boss" ? "boss" : "normal"]++;
          }
          const haveHw = { normal: 0, boss: 0 };
          for (const c of zoneCamps) {
            if (c?.event === "halloween") haveHw[c.role === "boss" ? "boss" : "normal"]++;
          }
          if (needHw.normal > haveHw.normal || needHw.boss > haveHw.boss) {
            const missing = {
              normal: Math.max(0, needHw.normal - haveHw.normal),
              boss: Math.max(0, needHw.boss - haveHw.boss),
            };
            for (const c of freshCamps) {
              if (c?.event !== "halloween") continue;
              const role = c.role === "boss" ? "boss" : "normal";
              if (missing[role] <= 0) continue;
              missing[role]--;
              zoneCamps.push({ ...c, id: zoneCamps.length + 1, t: 0 });
            }
          }
        } catch {}
      } else {
        zoneCamps = freshCamps;
      }
      ensureMapSlots(universe, mapId, zoneCamps, worldClock.now());
      tickBackground(universe, worldClock.now(), { skipMapId: mapId });
      persistUniverse({ force: false });
    } catch {
      zoneCamps = freshCamps;
    }
  } else {
    zoneCamps = [];
  }

if (isZoneMap && typeof rules.getZonePortals === "function") {
  zonePortals = (preparedZonePortals || rules.getZonePortals(WORLD) || []).map((p, i) => ({
    id: p.id ?? String(i + 1),
    ...p,

    buttonHovered: false,
    buttonPressed: false,

    switching: false,
    switchT: 0,

    open: false,
    holding: false,
    holdT: 0,

    autoOpen: p.autoOpen ?? true,

jumping: false,
jumpT: 0,
jumpDur: Math.max(0.1, Number(p.jumpDur ?? 2)),
jumpMap: null,
jumpPortal: null,
jumpSwitchPending: false,

closing: false,
closeT: 0,
closeFrom: 0,
closeDur: Math.max(0.1, Number(p.closeDur ?? portal.switchDur ?? 1)),

jumpSwitching: false,
jumpSwitchT: 0,
jumpSwitchDur: Math.max(0.1, Number(p.jumpSwitchDur ?? portal.switchDur ?? 1)),
jumpBaseFade: 1,
  }));

  for (const ptl of zonePortals) {
    preloadPortalSprites(ptl);
  }
} else {
  zonePortals = [];
}

  if (isZoneMap && typeof rules.getZoneSafeModules === "function") {
    zoneSafe = rules.getZoneSafeModules(WORLD) || null;
  } else {
    zoneSafe = null;
  }

  // Base de Combat de test (ex : 1-3) : station complète posée sur la map.
  if (isZoneMap && typeof rules.getZoneStation === "function") {
    try {
      zoneStation = rules.getZoneStation(WORLD) || null;
    } catch {
      zoneStation = null;
    }
    // Tag clan en direct (HTTP, comme la fenêtre Clan) : le push WS arrive
    // après la connexion, ce qui retardait le bouton CBS à chaque entrée.
    try {
      if (zoneStation && !String(getMyClanTag() || "")) void refreshMyClanTagNow();
    } catch {}
  } else {
    zoneStation = null;
  }

  if (!spawnedFromPortal) {
    try {
      const transfer = JSON.parse(sessionStorage.getItem("orbit_faction_transfer") || "null");
      const currentMap = String(window.__CURRENT_MAP_ID__ || "1-1");
      // ✅ compare normalisée (insensible à la casse) : même carte -> base.
      if (transfer && normalizeMapId(transfer.map) === normalizeMapId(currentMap)) {
        const center = resolveBaseCenter(zoneSafe, transfer.fallback);
        const baseX = center.x;
        const baseY = center.y;
        if (Number.isFinite(baseX) && Number.isFinite(baseY)) {
          player.x = clamp(baseX, 80, WORLD.w - 80);
          player.y = clamp(baseY, 80, WORLD.h - 80);
          spawnedFromPortal = true;
        }
        sessionStorage.removeItem("orbit_faction_transfer");
      }
    } catch {}
  }

  if (isZoneMap && typeof rules.getZoneWalls === "function") {
    zoneWalls = rules.getZoneWalls(WORLD) || [];
  } else {
    zoneWalls = [];
  }

  if (!spawnedFromPortal) {
    const currentMap = window.__CURRENT_MAP_ID__ || "1-1";
    const ov = popRespawnOverride();

    if (ov && normalizeMapId(ov.map) === normalizeMapId(currentMap)) {
      const position = ov.baseCenter ? resolveBaseCenter(zoneSafe, ov.fallback) : ov;
      const fallbackSpawn = getFactionFallbackSpawn();
      const spawnXY = clampSpawnPos(Number(position.x) || fallbackSpawn.x, Number(position.y) || fallbackSpawn.y);
      player.x = spawnXY.x;
      player.y = spawnXY.y;
      if (ov.respawn === true) {
        resetPetAfterRespawn();
        player.hp = Math.max(1, Math.ceil(player.hpMax * 0.1));
        player.sh = player.shMax > 0 ? Math.max(1, Math.ceil(player.shMax * 0.1)) : 0;
        player.repairT = 0;
        player.repairTickT = 0;
      }
      spawnedFromPortal = true;
    }
  }

  if (isZoneMap && zonePortals.length) {
    let wantPortal = null;
    let wantMap = null;

    try {
      wantPortal = sessionStorage.getItem("spawnPortalId");
      wantMap = sessionStorage.getItem("spawnMapId");

      sessionStorage.removeItem("spawnPortalId");
      sessionStorage.removeItem("spawnMapId");
    } catch {}

    const currentMap = window.__CURRENT_MAP_ID__ || "1-1";

    // Whitelist : id portail/map limités à [A-Za-z0-9_-.], 64 chars max, map == carte courante.
    // Majuscules requises : portails BL (p_1BL_to_2BL...) + maps 4-1 / 4-2 / 4-3 / 4-4.
    const isSafeId = (v) => typeof v === "string" || typeof v === "number"
      ? /^[A-Za-z0-9_\-.]{1,64}$/.test(String(v))
      : false;
    // Candidats dans l'ordre : 1) switch interne (sessionStorage),
    // 2) rechargement via __GO_TO_MAP__ (?map=&spawn=, window.__SPAWN_PORTAL_ID__).
    // Le 2) couvrait un trou : l'URL portait le portail mais resetRun ne le lisait
    // jamais → spawn fallback faction (ex 1500/1500) au lieu du portail.
    let urlPortal = null;
    let urlMap = null;
    try {
      const params = new URLSearchParams(location.search);
      urlPortal = params.get("spawn") || window.__SPAWN_PORTAL_ID__ || null;
      urlMap = params.get("map") || null;
    } catch {}
    const candidates = [];
    if (wantPortal) candidates.push([wantPortal, wantMap]);
    if (urlPortal) candidates.push([urlPortal, urlMap || currentMap]);
    for (const [candPortal, candMap] of candidates) {
      if (!candPortal || !candMap) continue;
      if (!isSafeId(candPortal) || !isSafeId(candMap)) continue;
      // ✅ compare normalisée (insensible à la casse).
      if (normalizeMapId(candMap) !== normalizeMapId(currentMap)) continue;
      const ptl = zonePortals.find(p => String(p.id) === String(candPortal));
      if (!ptl) continue;
      player.x = clamp(ptl.x, 80, WORLD.w - 80);
      player.y = clamp(ptl.y, 80, WORLD.h - 80);
      spawnedFromPortal = true;
      break;
    }
    if (spawnedFromPortal) {
      // ✅ Son "Saut terminée" quand on apparaît de l'autre côté du portail
      window.setTimeout(() => {
        SFX.stop("swJump");
        SFX.stop("swReady");
        SFX.play("swDone");
      }, 400);
    }
    // ✅ Arrivée via un saut de Galaxy Gate (entrée comme retour base) :
    // mêmes sons que les portails de zone.
    let gateJumpArrived = false;
    try {
      gateJumpArrived = sessionStorage.getItem("orbit_gate_jump") === "1";
      if (gateJumpArrived) sessionStorage.removeItem("orbit_gate_jump");
    } catch {}
    if (gateJumpArrived && !spawnedFromPortal) {
      window.setTimeout(() => {
        SFX.stop("swJump");
        SFX.stop("swReady");
        SFX.play("swDone");
      }, 400);
    }
  }

  // ✅ Consomme le spawn "portail" : il ne vaut que pour le saut en cours.
  // Les valeurs ont déjà été lues ci-dessus (wantPortal/urlPortal) et chaque
  // transition réécrit des valeurs fraîches avant le prochain resetRun.
  // Sans ça, l'URL garde ?spawn=... et un refresh (F5) refait apparaître
  // le joueur au portail au lieu de sa position sauvegardée.
  try {
    window.__SPAWN_PORTAL_ID__ = null;
    const spawnUrl = new URL(location.href);
    if (spawnUrl.searchParams.has("spawn")) {
      spawnUrl.searchParams.delete("spawn");
      history.replaceState(history.state ?? null, "", spawnUrl);
    }
  } catch {}

  if (!spawnedFromPortal) {
    const st = SESSION_HANGAR_ID
      ? getHangarStateById(SESSION_HANGAR_ID)
      : getActiveHangarState();

    const currentMap = window.__CURRENT_MAP_ID__ || "1-1";
    const fallbackSpawn = getFactionFallbackSpawn();
    // ✅ saut dans une GG (arrivée inter-maps) : pile au centre de la carte
    // au lieu du spawn faction (ex 1500/1500). Le refresh sur place garde la
    // position sauvegardée (branche st.pos inchangée ci-dessous).
    // Le bloc rules.playerSpawn plus bas reste prioritaire (ex : LOW).
    const gateEntrySpawn = rules?.mode === "gate"
      ? { x: WORLD.w / 2, y: WORLD.h / 2 }
      : fallbackSpawn;

    if (!st?.map) {
      player.x = clamp(gateEntrySpawn.x, 80, WORLD.w - 80);
      player.y = clamp(gateEntrySpawn.y, 80, WORLD.h - 80);
    } else {
      // ✅ compare normalisée : restaure la position sauvegardée
      // au lieu de retomber au spawn faction (1500/1500).
      if (normalizeMapId(st.map) !== normalizeMapId(currentMap)) {
        player.x = clamp(gateEntrySpawn.x, 80, WORLD.w - 80);
        player.y = clamp(gateEntrySpawn.y, 80, WORLD.h - 80);
      } else if (st.pos && st.pos.x != null && st.pos.y != null) {
        const savedXY = clampSpawnPos(st.pos.x, st.pos.y);
        player.x = savedXY.x;
        player.y = savedXY.y;
      } else {
        player.x = clamp(gateEntrySpawn.x, 80, WORLD.w - 80);
        player.y = clamp(gateEntrySpawn.y, 80, WORLD.h - 80);
      }
    }
  }

  if (rules?.mode === "gate" && rules?.playerSpawn) {
    const spawn = rules.playerSpawn;
    player.x = clamp(Number(spawn.x ?? WORLD.w * Number(spawn.xRatio ?? 0.08)), 80, WORLD.w - 80);
    player.y = clamp(Number(spawn.y ?? WORLD.h * Number(spawn.yRatio ?? 0.5)), 80, WORLD.h - 80);
  }

  // ✅ Arrivée via un portail : le saut nettoie le combat (façon DO officiel).
  // Sans ça, combatT (> 0 jusqu'à 5 s) bloquait safeZoneActive et le joueur
  // qui spawnait au centre d'un portail sûr n'était pas mis directement
  // en zone de non-agression (pas de toast, NPC toujours aggros, tirs reçus).
  if (spawnedFromPortal) {
    player.combatT = 0;
    player.attackedT = 0;
    player.pvpAttackT = 0;
  }

  initializeGateEscorts();

  setTimeout(() => {
    if (!player.dead && started) {
      const currentMap = window.__CURRENT_MAP_ID__ || "1-1";
      if (SESSION_HANGAR_ID) {
        saveHangarStateById(SESSION_HANGAR_ID, player.x, player.y, currentMap, savedHpPct(), savedShPct());
      } else {
        saveActiveHangarState(player.x, player.y, currentMap, savedHpPct(), savedShPct());
      }
    }
  }, 100);

  camera.x = player.x;
  camera.y = player.y;

  // ✅ refresh en radiation : on reprend l'exposition déjà écoulée au lieu
  // de relancer les 5 s de grâce (anti-abus boucle refresh).
  restorePersistedRadiationExposure();

  const activeGateId = String(window.__CURRENT_MAP_ID__ || "").toLowerCase();
  const savedGateWave = (rules?.mode === "gate" && account.user?.galaxyGates?.active === activeGateId)
    ? account.user.galaxyGates.activeWave
    // ✅ Eternal : reprend la vague sauvée (refresh), comme les GG classiques.
    : (rules?.mode === "gate" && activeGateId === "eternal")
      ? Math.max(1, Math.floor(Number(getCurrentUserFull()?.eternalGate?.wave) || 1))
      : 1;
  wave = Math.max(1, Math.floor(Number(savedGateWave) || 1));
  if (!isZoneMap) beginWave();

  markProgressDirty();
  saveProgressNow();
}

function die() {
  // Paladin Dernier rempart (passif) : à 1 PV, full heal au lieu de mourir.
  try { if (tryLastStand()) return; } catch {}
  // Tempest Volt Back-up (passif) : à 0 HP, 1 HP + invincible 10 s.
  try { if (tryTempestBackup()) return; } catch {}
  attackActive = false;
  laserCombatInRange = null;
  escapeWatch = null;
  player.dead = true;
  phoneControls?.cancel();
  portalJumpActive = false;
  // Mort = aptitudes coupées : leurs recharges démarrent.
  // Le CPU CL04K-XL tombe aussi (sans recharge, silencieux).
  if ((player.cloakT || 0) > 0) {
    player.cloakT = 0;
    startPoliceCloakCooldown();
  }
  player.cpuCloak = false;
  persistCpuCloak();
  try { cancelRepairPod(); } catch {}
  try { cancelRepairs(); } catch {}
  try { cancelHammerPod(); } catch {}
  try { cancelHammerRepairs(); } catch {}
  try { cancelNebula(); } catch {}
  try { cancelValour(); } catch {}
  try { cancelShl(); } catch {}
  try { cancelBsk(); } catch {}
  try { cancelRvg(); } catch {}
  try { cancelDrawFire(); } catch {}
  try { cancelProtection(); } catch {}
  try { cancelTravel(); } catch {}
  try { cancelYamatoTravel(); } catch {}
  // Tartarus boosts (toggles) : coupés à la mort comme au switch.
  try {
    if (player.tartBoostOn === true) {
      player.tartBoostOn = false;
      reportMovementAbility("ability_tartarus_speed-boost", false);
    }
  } catch {}
  try {
    if (player.tartPlusBoostOn === true) {
      player.tartPlusBoostOn = false;
      reportMovementAbility("ability_tartarus-plus_speed-boost-plus", false);
    }
  } catch {}
  try { cancelFortify(); } catch {}
  try { cancelPrism(); } catch {}
  try { cancelDiminish(); } catch {}
  try { cancelDdol(); } catch {}
  try { cancelHoloSelf(); } catch {}
  try { cancelHoloEnemy(); } catch {}
  try { cancelGa(); } catch {}
  try { cancelQaCharge(); } catch {}
  try { cancelQaBurst(); } catch {}
  try { cancelSpr(); } catch {}
  try { cancelSleight(); } catch {}
  try { cancelLibRep(); } catch {}
  try { cancelLight(); } catch {}
  try { cancelScramble(); } catch {}
  try { cancelHologram(); } catch {}
  try { cancelOrcus(); } catch {}
  try { cancelCyborg(); } catch {}
  try { cancelVenom(); } catch {}
  try { cancelMmt(); } catch {}
  try { cancelTbr(); } catch {}
  try { cancelRipper(); } catch {}
  try { cancelSap(); } catch {}
  try { cancelSpc(); } catch {}
  try { cancelSpcPlus(); } catch {}
  try { cancelChsCharge(); } catch {}
  try { cancelSent(); } catch {}
  try { cancelInc(); } catch {}
  try { player.kamiRex = []; player.kamiQueue = []; } catch {}
  try { cancelRecon(); } catch {}
  try { cancelRedirect(); } catch {}
  try { cancelDisarray(); } catch {}
  try { cancelRealloc(); } catch {}
  try { cancelHecate(); } catch {}
  try { cancelStockpile(); } catch {}
  player.vx = player.vy = 0;
  radiationSoundDelay = 0;
  triggerDeathShake();

  // Coupe immédiatement l'effet de radiation (son, glow rouge + texte pulsé) à la mort.
  radiationSystem.reset();
  clearPersistedRadiationExposure();
  radiationActive = false;
  SFX.stopLoop("radiationLoop", { fadeOut: 0 });
  repairSoundActive = false;
  SFX.stop("repairStart");
  SFX.stopLoop("repairLoop", { fadeOut: 0 });
  shipMoveSoundActive = false;
  SFX.stopLoop("shipMove", { fadeOut: 0 });
  if (toast?.fixed && toast.text === "Vous êtes en zone de radiations") toast = null;
  clearPendingSalvo();

  SFX.crossfade("deathPlayer", "deathPlayer2", { crossAt: 0.2 });

  lastDeathPos.x = player.x;
  lastDeathPos.y = player.y;
  lastDeathPos.map = window.__CURRENT_MAP_ID__ || "1-1";

  // ✅ explosion facon NPC sur le joueur.
  spawnExplosion(player.x, player.y, 1.0);

  // ✅ epave du joueur : cargo box a l'endroit de la mort.
  // Mort PvP : le cargo du vaincu (1x chaque minerai de base, sans osmium),
  // ramassable par le tueur uniquement. Sinon : 1 prometium pour tous.
  let wreckOres = { prometium: 1 };
  let wreckOnlyBy = null;
  let wreckUid = null;
  try {
    const self = getNetSelf();
    if (self && self.pvpFrom && Date.now() - Number(self.pvpAt || 0) < 8000) {
      wreckOres = { prometium: 1, endurium: 1, terbium: 1, prometid: 1, duranium: 1, promerium: 1, seprom: 1 };
      wreckOnlyBy = String(self.pvpFrom);
      wreckUid = `pvploot_${Date.now().toString(36)}${((Math.random() * 1e6) | 0).toString(36)}`;
    }
  } catch {}
  if (wreckOnlyBy && wreckUid) {
    // Mort PvP : annonce aux autres (tueur + temoins), mais pas de copie
    // locale — la victime ne voit pas le butin du tueur.
    try {
      sendPvpLoot({ uid: wreckUid, x: Math.round(player.x), y: Math.round(player.y), onlyBy: wreckOnlyBy });
    } catch {}
  } else {
    spawnCollectableAt("Cargo_Box", player.x, player.y, {
      armed: false,
      fromNpc: null,
      despawnAfter: 60,
      rewardOverride: { resources: {} },
      oreRemainder: wreckOres,
      onlyBy: wreckOnlyBy,
      uid: wreckUid,
    });
  }

  const defeatedGateId = String(window.__CURRENT_MAP_ID__ || "").toLowerCase();
  // ✅ Mort en Gate Eternal : le portail ET la progression disparaissent
  // (seule fin possible d'un run, avec la sortie manuelle).
  if (rules?.mode === "gate" && defeatedGateId === "eternal") {
    try {
      const cleared = clearEternalGateRun();
      if (cleared.ok) {
        account.user = cleared.user;
        showNotificationGroup(["Gate Eternal perdue", "Le portail a disparu de ta map X-1."]);
      }
    } catch {}
  }
  if (rules?.mode === "gate" && GALAXY_GATE_DEFINITIONS[defeatedGateId]) {
    const lifeResult = loseCurrentUserGalaxyGateLife(defeatedGateId, account.user);
    if (lifeResult.ok) {
      account.user = lifeResult.user;
      const gateName = GALAXY_GATE_DEFINITIONS[defeatedGateId].name;
      if (lifeResult.exhausted) {
        // ✅ GG perdue (0 vie) : la gate disparaît -> les ressources non
        // ramassées à l'intérieur sont effacées (y compris l'épave du joueur,
        // inaccessible puisque la gate n'existe plus).
        try { purgeGateCollectables(defeatedGateId); } catch {}
        showNotificationGroup([`Galaxy Gate ${gateName} perdue`, "Il ne vous reste plus aucune vie."]);
        // ✅ camouflage suspendu à l'entrée : restauré aussi en cas d'échec.
        try { restoreCloakAfterGate(); } catch {}
      }
      else showNotificationGroup([`Vaisseau détruit dans la Galaxy Gate ${gateName}`, `${lifeResult.lives} vie${lifeResult.lives > 1 ? "s" : ""} restante${lifeResult.lives > 1 ? "s" : ""}`]);
      renderGalaxyGateWindow();
    }
  }

  // ✅ on ne sauvegarde jamais la position/vitalité au moment de la mort :
  // sinon un refresh après une mort réapparaissait sur le lieu exact avec
  // ~0 PV. On garde la dernière sauvegarde « en vie ».
  // L'état « mort » lui est mémorisé séparément (sessionStorage) pour être
  // rejoué si le joueur refresh avant d'avoir choisi un lieu de réapparition.
  markDeathPending();

  // ✅ les bases mères sont déjà chargées au boot : rien à précharger ici.

  if (rules?.mode === "gate") {
    // ✅ en Galaxy Gate on ne renvoie plus direct à la base mère :
    // on affiche la fenêtre de réparation (seul choix = base), le joueur
    // clique pour valider le retour.
    setCenterMsg(false);
    startDeathSequence();
    return;
  }

  if (isZoneMap) {
    startDeathSequence();
    return;
  }

  respawnBase();
}

// ✅ Portails annexes (par destination) : jamais utilisés pour une
// réapparition au portail — low, QZ, Galaxy Gates (aussi celles des X-1),
// map maudite et 5-2 (portail central de 4-5).
const ANNEX_PORTAL_MAPS = new Set(["low", "qz", "alpha", "beta", "gamma", "delta", "epsilon", "zeta", "kappa", "lambda", "kronos", "awakened", "eternal", "maudite", "5-2"]);

function isAnnexPortal(portal) {
  // Retour Low : exclu aussi (sinon réapparition sur le portail masqué).
  if (portal?.factionReturn === true) return true;
  return ANNEX_PORTAL_MAPS.has(String(portal?.toMap || "").trim().toLowerCase());
}

function getNearestPortalTo(x, y, { excludeAnnex = false } = {}) {
  if (!zonePortals || !zonePortals.length) return null;
  let best = null;
  let bestD2 = Infinity;
  for (const p of zonePortals) {
    // Marqueur d'arrivée d'aller simple : jamais une option de respawn.
    if (p?.hidden === true) continue;
    if (excludeAnnex && isAnnexPortal(p)) continue;
    const d2 = dist2(x, y, p.x, p.y);
    if (d2 < bestD2) {
      bestD2 = d2;
      best = p;
    }
  }
  return best;
}

// ✅ Précharge une map mère (ou respawn) sans bloquer : remplit le cache
// __PRELOAD_MAP__ pour que le switch interne soit instantané.
function preloadRespawnMap(mapId) {
  try {
    const normalized = String(mapId || "").trim();
    if (!normalized) return;
    Promise.resolve(window.__PRELOAD_MAP__?.(normalized)).catch((error) => {
      console.warn("Préchargement de la map de réapparition incomplet :", error);
    });
  } catch {}
}

// ✅ Précharge les maps mères de la firme (base basse + base haute) en tâche
// de fond : au moment de « Réparée à la base », elles sont déjà en cache.
function preloadHomeMaps() {
  try {
    const faction = (account.user || getCurrentUserFull())?.faction;
    const maps = new Set([
      getFactionHomeMap(faction),
      getFactionUpperBaseMap(faction),
    ]);
    for (const mapId of maps) {
      if (mapId) preloadRespawnMap(mapId);
    }
  } catch {}
}

// ✅ Précharge tous les sprites de drones (iris / apis / zeus, tous niveaux,
// toutes frames) : évite les décalages visuels aux premiers virages.
function collectDroneSpriteJobs(background = false) {
  const jobs = [];
  try {
    for (const type of Object.values(DRONE_TYPES)) {
      if (!type?.path) continue;
      for (let level = 0; level < DRONE_MAX_LEVEL; level++) {
        for (let frame = 1; frame <= 32; frame++) {
          jobs.push(loadImage(`${type.path}${level}/${frame}.png`, { priority: !background }));
        }
      }
    }
  } catch {}
  return jobs;
}

let droneSpritesPreloaded = false;
function preloadAllDroneSprites() {
  if (droneSpritesPreloaded) return;
  droneSpritesPreloaded = true;
  try {
    Promise.allSettled(collectDroneSpriteJobs(true)).then(() => true);
  } catch {}
}

// ✅ Boot allégé : uniquement les sprites des drones possédés (type + niveau
// réels du joueur), au lieu des 576 images (3 types × 6 niveaux × 32 frames).
// Les autres niveaux/types arrivent en fond après le DÉPART (ou à la demande).
function collectOwnedDroneSpriteJobs() {
  const jobs = [];
  try {
    const wanted = new Set();
    const items = (account.user || getCurrentUserFull())?.drones?.items || [];
    for (const d of items) {
      const type = DRONE_TYPES[d?.type] || null;
      if (!type?.path) continue;
      const lvl = Math.max(0, Math.min(DRONE_MAX_LEVEL - 1, Math.floor(Number(d?.level) || 1) - 1));
      const path = getDroneDesign(d?.fit?.ability)?.sprite || type.path;
      wanted.add(`${path}${lvl}/`);
    }
    // Sans drone (nouveau joueur) : l'iris de base, visible en boutique/HUD.
    if (!wanted.size && DRONE_TYPES.iris?.path) wanted.add(`${DRONE_TYPES.iris.path}0/`);
    for (const base of wanted) {
      for (let frame = 1; frame <= 32; frame++) {
        jobs.push(loadImage(`${base}${frame}.png`, { priority: true }));
      }
    }
  } catch {}
  return jobs;
}

// ✅ Assets des 2 bases mères de la firme (X-1 + X-8). Au boot on ne bloque
// que sur les bases utiles : la map actuelle est déjà chargée par le chemin
// normal, donc `skipCurrentMap` l'exclut (zéro doublon). Le reste part en
// fond après le DÉPART (préchargement ciblé à la mort toujours actif).
async function collectHomeBaseJobs({ skipCurrentMap = false } = {}) {
  const jobs = [];
  try {
    const faction = (account.user || getCurrentUserFull())?.faction;
    const ids = [getFactionHomeMap(faction), getFactionUpperBaseMap(faction)];
    const currentId = String(window.__CURRENT_MAP_ID__ || "").toLowerCase();
    for (const id of ids) {
      if (!id) continue;
      // La map actuelle est déjà couverte par le chargement du secteur :
      // inutile de la recharger en double au boot.
      if (skipCurrentMap && String(id).toLowerCase() === currentId) continue;
      try {
        const [spawnsMod, worldMod] = await Promise.all([
          import(`../../MAPS/${id}/SPAWNS.js`),
          import(`../../MAPS/${id}/WORLD.js`),
        ]);
        const world = worldMod?.WORLD;
        if (!world) continue;
        const rules = {
          mode: "zone",
          getZoneSpawns: spawnsMod?.getZoneSpawns,
          getZonePortals: spawnsMod?.getZonePortals,
          getZoneSafeModules: spawnsMod?.getZoneSafeModules,
        };
        jobs.push(...preloadCollectables(id));
        jobs.push(...preloadSafeModuleSprites(rules, world));
        for (const camp of (rules.getZoneSpawns?.(world) || [])) {
          if (camp?.type && NPC_TYPES[camp.type]) jobs.push(ensureNpcLoaded(camp.type));
        }
        for (const type of halloweenPreloadTypes(id, NPC_TYPES)) {
          if (NPC_TYPES[type]) jobs.push(ensureNpcLoaded(type));
        }
        for (const targetPortal of (rules.getZonePortals?.(world) || [])) {
          jobs.push(...preloadPortalSprites(targetPortal));
        }
      } catch (error) {
        console.warn("Préchargement base incomplet:", id, error);
      }
    }
  } catch {}
  return jobs;
}

// ✅ Fond après DÉPART : bases mères restantes (X-1/X-8 non couvertes au boot)
// + FX secondaires + effet de vaisseau. Le cache d'images déduplique : ce qui
// est déjà chargé ne coûte rien, et tout est prêt avant usage (pas de pop-in).
async function preloadDeferredHomeBaseAssets() {
  try {
    await Promise.allSettled(await collectHomeBaseJobs());
  } catch {}
}

function preloadDeferredFx() {
  try {
    Promise.allSettled([
      ensurePulseFxLoaded(), ensureRepairOrbitLoaded(), ensureInstaShieldLoaded(),
      ensureSmbFxLoaded(),
      ensureShieldShimmerLoaded(), ensureSlowFxLoaded(), ensureIceFxLoaded(),
    ]).then(() => true);
  } catch {}
}

// Barre rapide : précharge les icônes du dock (onglets normal/hover/select,
// munitions, roquettes, techs, aptitudes, formations, gears PET...) en fond
// pour éviter le clignotement au premier affichage (icônes pas encore en
// cache navigateur). N'ajoute rien au chargement bloquant.
const DOCK_TAB_ICON_NAMES = Object.freeze(["lasers", "rockets", "mines", "cpus", "tech_items", "ship_abilities", "pet", "cannons", "drives", "special_items", "rocket_launchers", "drone_formations", "buy_now"]);
function actionDockIconUrls() {
  const urls = new Set();
  try {
    for (const tab of DOCK_TAB_ICON_NAMES) {
      for (const state of ["normal", "hover", "select"]) urls.add(`ASSETS/CONTROL_MENU/${tab}_${state}.png`);
    }
  } catch {}
  try { for (const id of ROCKET_IDS || []) { const u = rocketDockIcon(id); if (u) urls.add(u); } } catch {}
  try {
    for (const f of DRONE_FORMATIONS || []) {
      let u = null;
      try { u = formationDockIcon(f) || f?.icon; } catch { u = f?.icon; }
      if (u) urls.add(u);
    }
  } catch {}
  try { for (const t of TECH_DOCK_ITEMS || []) if (t?.icon) urls.add(t.icon); } catch {}
  try { for (const id of ABILITY_IDS || []) urls.add(`ASSETS/APTITUDES/ICONS/${abilityIconFile(id)}`); } catch {}
  try { for (const u of Object.values(PET_GEAR_DROPDOWN_ICON || {})) if (u) urls.add(u); } catch {}
  try { if (PET_MODE_PASSIVE_ICON) urls.add(PET_MODE_PASSIVE_ICON); } catch {}
  try { if (PET_MODE_COMBAT_ICON) urls.add(PET_MODE_COMBAT_ICON); } catch {}
  // Icones deja referencees dans le DOM du dock (slots, CPU camouflage, SMB...).
  try {
    document.querySelectorAll("#ammoBar img").forEach((img) => {
      const s = img?.getAttribute?.("src");
      if (s) urls.add(s);
    });
  } catch {}
  return [...urls];
}
let actionDockIconsPreloaded = false;
function preloadActionDockIcons() {
  if (actionDockIconsPreloaded) return;
  actionDockIconsPreloaded = true;
  for (const src of actionDockIconUrls()) { try { loadImage(String(src)); } catch {} }
}

// Icônes du dock du haut : le CSS n'en charge qu'un état (normal) ; les
// variantes _hover / _select n'étaient téléchargées qu'au premier survol ou
// clic, d'où un saut visible. On les précharge et décode toutes (lues dans
// les feuilles de style, donc aucune liste à maintenir). Les Image restent
// référencées pour ne pas être libérées.
const menuDockIconImages = new Map();
function preloadMenuDockIcons() {
  const found = [];
  const walk = (rules, base) => {
    for (const rule of rules || []) {
      if (rule.cssRules) walk(rule.cssRules, base);
      const text = String(rule.cssText || "");
      if (!text.includes("UI/MENU/")) continue;
      for (const match of text.matchAll(/url\(\s*["']?([^"')]*UI\/MENU\/[^"')]+)["']?\s*\)/g)) {
        try { found.push(new URL(match[1], base).href); } catch {}
      }
    }
  };
  for (const sheet of Array.from(document.styleSheets || [])) {
    let rules = null;
    try { rules = sheet.cssRules; } catch { continue; }
    walk(rules, sheet.href || location.href);
  }
  for (const href of found) {
    if (menuDockIconImages.has(href)) continue;
    const img = new Image();
    img.decoding = "async";
    img.src = href;
    try { img.decode?.().catch(() => {}); } catch {}
    menuDockIconImages.set(href, img);
  }
}
try {
  preloadMenuDockIcons();
  // Feuille encore en cours de chargement au démarrage : seconde passe.
  if (document.readyState !== "complete") window.addEventListener("load", preloadMenuDockIcons, { once: true });
} catch {}

function preloadShipEffectBackground() {
  try {
    if (!GAME_SETTINGS.shipEffect) return;
    loadShipEffect(ACTIVE_SHIP.id);
  } catch {}
}

// ✅ Changement de map sans rechargement de page quand c'est possible :
// tente le switch interne (__SWITCH_MAP__), sinon retombe sur __GO_TO_MAP__
// (rechargement complet avec écran de chargement).
async function goToMapFast(targetMap, spawnId = null) {
  const cur = window.__CURRENT_MAP_ID__ || "1-1";
  if (String(cur) === String(targetMap) && !spawnId) return "same";
  if (typeof window.__SWITCH_MAP__ === "function") {
    try {
      await window.__SWITCH_MAP__(targetMap, spawnId);
      return "switched";
    } catch (error) {
      console.warn("Changement interne impossible, rechargement :", error);
    }
  }
  if (typeof window.__GO_TO_MAP__ === "function") {
    window.__GO_TO_MAP__(targetMap, spawnId);
    return "reloaded";
  }
  return "failed";
}
function respawnBaseGate() {
  // ✅ base haute (X-8) pour les maps marquées respawnBase upper (maudite, QZ),
  // sinon logique standard (gate → base mère).
  const faction = (account.user || getCurrentUserFull())?.faction;
  const targetMap = rules?.respawnBase === "upper"
    ? getFactionUpperBaseMap(faction)
    : getFactionRespawnMap(faction, window.__CURRENT_MAP_ID__, { gate: true });
  const baseSpawn = getFactionBaseSpawn((account.user || getCurrentUserFull())?.faction);
  setRespawnOverride({ map: targetMap, baseCenter: true, fallback: baseSpawn, respawn: true });
  preloadRespawnMap(targetMap);
  // ✅ passe par startRespawn comme la zone : masque la fenêtre de réparation,
  // joue le son, puis bascule en interne vers la base mère.
  startRespawn(async () => {
    const cur = window.__CURRENT_MAP_ID__ || "1-1";

    if (String(cur) !== String(targetMap)) {
      // ✅ switch interne sans écran de chargement ; fallback = reload classique.
      const result = await goToMapFast(targetMap);
      if (result === "switched" || result === "same") startRespawnInstaShield();
      return;
    }

    resetRun({ randomSpawn: false });
  });
}

// À la réapparition choisie, le menu et le voile noir disparaissent instantanément,
// le son de réapparition joue, puis le respawn s'enchaîne directement.
function startRespawn(action) {
  // ✅ ignore les déclenchements multiples (double-clic, clics répétés
  // pendant le switch) : sinon sons en double et deux changements de map
  // concurrents qui se marchent dessus.
  if (respawnRunning) return;
  respawnRunning = true;
  clearDeathPending();
  SFX.resume();
  SFX.stop("deathPlayer");
  SFX.stop("deathPlayer2");
  SFX.play("respawnPlayer");
  if (toast?.fixed && toast.text === "Vous êtes en zone de radiations") toast = null;
  showRespawnOverlay(false);
  setCenterMsg(false);
  try {
    const result = action();
    if (result && typeof result.catch === "function") {
      result
        .catch((error) => console.warn("Réapparition impossible :", error))
        .finally(() => { respawnRunning = false; });
    } else {
      respawnRunning = false;
    }
  } catch (error) {
    console.warn("Réapparition impossible :", error);
    respawnRunning = false;
  }
  startRespawnInstaShield();
  // ✅ le portail reste bloqué 5 s à partir du moment où le vaisseau réapparaît vraiment
  player.portalLockT = Math.max(player.portalLockT || 0, 5);
}

function respawnBase() {
  // ✅ base haute (X-8) pour les maps marquées respawnBase upper (maudite),
  // sinon logique standard (zones basses → X-1, zones hautes → X-8).
  // Raid Low : "low" ne matche pas les zones X- → base mère (comme en gate).
  const faction = (account.user || getCurrentUserFull())?.faction;
  const targetMap = rules?.respawnBase === "upper"
    ? getFactionUpperBaseMap(faction)
    : getFactionRespawnMap(faction, lastDeathPos.map || window.__CURRENT_MAP_ID__);
  const baseSpawn = getFactionBaseSpawn((account.user || getCurrentUserFull())?.faction);
  setRespawnOverride({ map: targetMap, baseCenter: true, fallback: baseSpawn, respawn: true });
  // ✅ la destination est déjà préchargée (mort + boot) : le switch est immédiat.
  preloadRespawnMap(targetMap);
  startRespawn(async () => {
    const cur = window.__CURRENT_MAP_ID__ || "1-1";
    if (String(cur) !== String(targetMap)) {
      // ✅ plus de rechargement complet du jeu : bascule interne,
      // avec rechargement classique uniquement en secours.
      const result = await goToMapFast(targetMap);
      if (result === "switched" || result === "same") startRespawnInstaShield();
      return;
    }

    resetRun({ randomSpawn: false });
  });
}

function respawnNearestPortal() {
  // ✅ réparation unique : seul le retour base est autorisé.
  if (isBaseOnlyRespawnMap()) {
    respawnBaseGate();
    return;
  }
  const portalCd = getRespawnCdLeft("portal");
  if (portalCd > 0) {
    showToast(`Portail en recharge (${formatCdLeft(portalCd)})`, 1.4);
    refreshRespawnShop();
    return;
  }
  const curMap = window.__CURRENT_MAP_ID__ || "1-1";
  // ✅ portails annexes exclus (low, QZ, GG/gates X-1, maudite, 5-2) :
  // on réapparaît au portail normal le plus proche, sinon repli base.
  const p = getNearestPortalTo(lastDeathPos.x, lastDeathPos.y, { excludeAnnex: true });
  if (!p) {
    // ✅ pas de portail sur la carte : repli gratuit vers la base.
    respawnBase();
    return;
  }
  if (!chargeRespawnCost(RESPAWN_PORTAL_COST, "Portail")) return;

  setRespawnCd("portal", Date.now() + RESPAWN_PORTAL_CD_SEC * 1000);
  setRespawnOverride({ map: curMap, x: p.x, y: p.y, respawn: true });
  startRespawn(() => {
    resetRun({ randomSpawn: false });
  });
}

function respawnHere() {
  // ✅ réparation unique : seul le retour base est autorisé.
  if (isBaseOnlyRespawnMap()) {
    respawnBaseGate();
    return;
  }
  const hereCd = getRespawnCdLeft("here");
  if (hereCd > 0) {
    showToast(`Sur place en recharge (${formatCdLeft(hereCd)})`, 1.4);
    refreshRespawnShop();
    return;
  }
  if (!chargeRespawnCost(RESPAWN_HERE_COST, "Sur place")) return;
  const curMap = window.__CURRENT_MAP_ID__ || "1-1";

  setRespawnCd("here", Date.now() + RESPAWN_HERE_CD_SEC * 1000);

  setRespawnOverride({
    map: curMap,
    x: lastDeathPos.x,
    y: lastDeathPos.y,
    respawn: true,
  });

  startRespawn(() => {
    resetRun({ randomSpawn: false });
  });
}

function respawn() {
  if (isBaseOnlyRespawnMap()) {
    respawnBaseGate();
    setCenterMsg(false);
    // ✅ en gate on garde la progression ; sur la maudite on est éjecté vers la base.
    showToast(rules?.mode === "gate" ? "Retour à la base mère" : "Éjecté vers la base mère", 1.6);
    return;
  }
  if (isZoneMap) {
    respawnBase();
    return;
  }

  respawnBaseGate();
  setCenterMsg(false);
  // ✅ en gate on retourne à la base mère en gardant la progression (pas une run neuve).
  showToast("Retour à la base mère", 1.6);
}

// ============================================================
// Minimap
// ============================================================
const mini = document.getElementById("miniCanvas");
const mctx = mini.getContext("2d");
let miniPing = null;

mini.style.touchAction = "none";

function setMoveTargetFromMiniEvent(clientX, clientY) {
  if (isPlayerMovementLocked()) return;
  // ✅ Un clic minimap annule aussi l'ordre de collecte
  cancelCollectableTarget();

  const rect = mini.getBoundingClientRect();

  const cx = (clientX - rect.left) * (mini.width / rect.width);
  const cy = (clientY - rect.top) * (mini.height / rect.height);

  const mx = cx / mini.width;
  const my = cy / mini.height;

  const wx = mx * WORLD.w;
  const wy = my * WORLD.h;

  // Comme au clic map : la destination s'arrête à la bordure du premier
  // mur traversé au lieu de passer à travers.
  let dest = { x: wx, y: wy };
  try {
    if (isZoneMap && Array.isArray(zoneWalls) && zoneWalls.length && !player.dead) {
      dest = clampSegmentToWalls(player.x, player.y, wx, wy, zoneWalls, player.r || 18);
    }
  } catch {}
  moveTarget.active = true;
  moveTarget.x = dest.x;
  moveTarget.y = dest.y;
}

mini.addEventListener("pointerdown", (e) => {
  e.preventDefault();
  e.stopPropagation();
  SFX.resume();

  if (!started || player.dead) return;

  setMoveTargetFromMiniEvent(e.clientX, e.clientY);

  miniPing = { x: moveTarget.x, y: moveTarget.y, t: 0, dur: 0.75 };

  mini.setPointerCapture(e.pointerId);
}, { passive: false });

mini.addEventListener("pointermove", (e) => {
  if (!e.buttons) return;
  e.preventDefault();
  e.stopPropagation();

  if (!started || player.dead) return;

  setMoveTargetFromMiniEvent(e.clientX, e.clientY);
}, { passive: false });

mini.addEventListener("pointerup", (e) => {
  try { mini.releasePointerCapture(e.pointerId); } catch {}
}, { passive: true });

// Couleurs relationnelles UNIFIÉES (jeu + minimap + station) :
// même clan/allié = vert, guerre = rouge, NAP = orange,
// même firme ou sans clan = bleu, sinon rouge. Groupe = jaune (overlay).
const RELATION_COLORS = Object.freeze({
  own: Object.freeze({ map: "rgba(105,255,140,0.98)", mini: "rgba(105,255,140,0.95)", hex: "#35d957" }),
  ally: Object.freeze({ map: "rgba(105,255,140,0.98)", mini: "rgba(105,255,140,0.95)", hex: "#35d957" }),
  war: Object.freeze({ map: "rgba(255,65,82,0.98)", mini: "rgba(255,70,90,0.95)", hex: "#ff3b57" }),
  red: Object.freeze({ map: "rgba(255,65,82,0.98)", mini: "rgba(255,70,90,0.95)", hex: "#ff3b57" }),
  nap: Object.freeze({ map: "rgba(255,160,60,0.98)", mini: "rgba(255,160,60,0.95)", hex: "#ffd60a" }),
  blue: Object.freeze({ map: "rgba(80,225,255,0.98)", mini: "rgba(80,160,255,0.95)", hex: "#3b9dff" }),
  group: Object.freeze({ map: "rgba(255,229,138,0.98)", mini: "rgba(255,229,138,0.95)", hex: "#ffd60a" }),
});
function cleanClanTag(tag) {
  return String(tag || "").normalize("NFKC").slice(0, 32);
}
function clanTagKey(tag) {
  return cleanClanTag(tag).toLocaleLowerCase("fr");
}
function isSameFirm(firm) {
  try {
    const myFirm = String(normalizeFactionId(account.user?.faction) || "").toLowerCase();
    return myFirm !== "" && String(normalizeFactionId(firm) || "").toLowerCase() === myFirm;
  } catch { return false; }
}
// Clé relationnelle unique : own > war > nap > ally > même firme (blue) > autre firme (red).
function relationKey(tag, firm) {
  const clean = clanTagKey(tag);
  let myClan = "";
  try { myClan = clanTagKey(getMyClanTag()); } catch {}
  if (myClan && clean === myClan) return "own";
  let rel = "";
  if (clean) {
    try { rel = getClanRelation(clean); } catch {}
  }
  if (rel === "war") return "war";
  if (rel === "nap") return "nap";
  if (rel === "ally") return "ally";
  // Sans clan : la firme seule décide (autre firme = rouge). Firme inconnue
  // (donnée réseau pas encore reçue) : bleu par défaut.
  if (isSameFirm(firm) || !normalizeFactionId(firm, "")) return "blue";
  return "red";
}
function isPlayerGrouped(id) {
  if (id == null) return false;
  try {
    return !!getNetGroup()?.members?.some((member) => String(member.id) === String(id));
  } catch { return false; }
}

// Multi : allies minimap = escortes + joueurs distants (même règle unifiée
// que les pseudos en jeu : vert clan/allié, orange NAP, rouge guerre/autre
// firme, bleu même firme ou sans clan, jaune groupe sauf guerre).
function minimapAllies() {
  try {
    const remotes = getNetplayRemotes();
    if (!remotes || !remotes.size) return escortShips;
    const dots = [];
    for (const rr of remotes.values()) {
      if (!rr || rr.dead) continue;
      // Camouflage d'aptitude : pas de point (le CPU garde le sien).
      if (rr.cloaked === true) continue;
      const tag = cleanClanTag(rr.clan);
      const key = relationKey(tag, rr.firm);
      let color = RELATION_COLORS[key].mini;
      // Groupe : jaune (sauf guerre : le danger prime).
      if (key !== "war" && isPlayerGrouped(rr.id)) color = RELATION_COLORS.group.mini;
      dots.push({
        x: Number(rr.rx ?? rr.x), y: Number(rr.ry ?? rr.y), hp: 1, r: 18, _net: true,
        _netPlayer: String(rr.id),
        color,
      });
    }
    return dots.length ? escortShips.concat(dots) : escortShips;
  } catch { return escortShips; }
}

let minimapLastDraw = -Infinity;
let minimapLastWorld = null;
let minimapLastSize = "";
function drawMinimap() {
  if (!shouldRefreshWindow("minimap")) return;
  // This independent canvas retains its bitmap. Update at 20 Hz rather
  // than scanning every NPC and rebuilding the static key at monitor FPS.
  const now = performance.now();
  const size = `${mini.width}:${mini.height}:${mini.clientWidth}:${mini.clientHeight}:${window.devicePixelRatio}`;
  if (WORLD === minimapLastWorld && size === minimapLastSize && now - minimapLastDraw < 1000 / 20) return;
  minimapLastDraw = now; minimapLastWorld = WORLD; minimapLastSize = size;
  // Rendu en pixels CSS (bitmap = CSS × DPR, voir applyMinimapProportions) :
  // net à toutes les tailles, même après +.
  const cssW = mini.clientWidth || 0;
  const cssH = mini.clientHeight || 0;
  const dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
  const useCss = cssW > 0 && cssH > 0;
  mctx.setTransform(useCss ? dpr : 1, 0, 0, useCss ? dpr : 1, 0, 0);
  const petAccount = account.user?.pet;
  const isPetActive = !!petAccount?.owned && petAccount?.active === true && !player.dead && Number(petAccount.hp) > 0;
  // Marqueur du localisateur P.E.T (G-EL), résolu en direct.
  const petLocatorMarkers = [];
  if (isPetActive && petLocator.enemyId != null) {
    const foe = enemiesById.get(petLocator.enemyId);
    if (foe && foe.hp > 0) petLocatorMarkers.push({ x: foe.x, y: foe.y, color: "#ff2e4d", pulse: true });
  }
  renderMinimap(mctx, {
    width: useCss ? cssW : mini.width,
    height: useCss ? cssH : mini.height,
    world: WORLD,
    player,
    enemies,
    allies: minimapAllies(),
    markers: petLocatorMarkers,
    // Base de Combat : cercle couleur propriété, comme la base (vert = à
    // nous, jaune = NAP, rouge = ennemie, gris = vide). Rien en vue jeu.
    station: zoneStation ? { x: zoneStation.x, y: zoneStation.y, color: zoneStationRingColor() } : null,
    pet: isPetActive
      ? {
          active: true,
          x: petState.ready ? petState.x : player.x - 90,
          y: petState.ready ? petState.y : player.y + 70,
        }
      : null,
    portals: getInteractivePortals(),
    returnPortal: gateReturnPortal,
    isZoneMap,
    safeZone: zoneSafe,
    walls: zoneWalls,
    rallyZone: rules?.raidLow === true && isLowRaidCircleVisible() ? LOW_RAID_ZONE_CLIENT : null,
    moveTarget,
    ping: miniPing,
    camera,
    viewportWidth: innerWidth,
    viewportHeight: innerHeight,
    lockedNpc: Target.get(),
    // Boss Halloween : icône image (petit + blanc, frames 20 Hz), toujours
    // visible même hors portée radar — jamais le point rouge.
    bossIconFor: (enemy) => {
      try {
        if (!isHalloweenVariantType(enemy?.type) || halloweenRoleOf(enemy?.type) !== "boss") return null;
        const sp = NPC_TYPES[enemy.type]?.sprite;
        const imgs = Array.isArray(sp?._imgs) && sp._imgs.length ? sp._imgs : null;
        return { imgs, size: 12 };
      } catch { return null; }
    },
    // Spearhead Recon : radar minimap x2 pendant l'effet.
    shouldShowNpc: (source, enemy, locked) => shouldDetectNpc(source, enemy, ((player.reconT || 0) > 0 ? NPC_SENSOR_RANGES.radar * 2 : NPC_SENSOR_RANGES.radar), locked),
    npcOpacity: (source, enemy, locked) => {
      const recon = (player.reconT || 0) > 0 ? 2 : 1;
      return npcSensorOpacity(source, enemy, DEFAULT_NPC_RADAR_FADE_START * recon, NPC_SENSOR_RANGES.radar * recon, locked);
    },
  });
}

// ============================================================
// Labels / colors
// ============================================================
// Bots JPC d'Hyperion Orbit : même plaque que les joueurs classiques —
// barres HP/bouclier, pastilles drones, icône formation, pseudo JPC_XY,
// grade BOT à gauche, firme BOT à droite, titre violet dessous.
function drawJpcBotPlate(e, showBars) {
  try {
    if (!e || e.hp <= 0) return;
    const pseudo = String(e.jpcPseudo || e.name || "JPC");
    const count = Math.max(0, Math.min(12, Math.floor(Number(e.droneCfg?.count) || 0)));
    const designs = Array.isArray(e.droneCfg?.designs) && e.droneCfg.designs.length
      ? e.droneCfg.designs
      : (e.droneCfg?.design ? [e.droneCfg.design] : []);
    const dind = [];
    for (let i = 0; i < count; i++) {
      try {
        dind.push(droneIndicatorColor({ type: "iris", fit: { ability: designs.length ? designs[i % designs.length] : null } }));
      } catch { dind.push("rgb(255,255,255)"); }
    }
    let ficon = null;
    try {
      const icon = formationDockIcon(e.droneCfg?.formation || "standard");
      if (icon) {
        const im = getCachedImage(icon);
        if (isImgReady(im)) ficon = im;
        else loadImage(icon, { priority: true });
      }
    } catch {}
    // Grade BOT + firme BOT : vraies images, comme les joueurs classiques.
    let rankImg = null, factImg = null;
    try {
      const ri = getCachedImage("ASSETS/RANKS/BOT.png");
      if (isImgReady(ri)) rankImg = ri;
      else loadImage("ASSETS/RANKS/BOT.png", { priority: true });
      const fi = getCachedImage("ASSETS/FACTIONS/BOT.png");
      if (isImgReady(fi)) factImg = fi;
      else loadImage("ASSETS/FACTIONS/BOT.png", { priority: true });
    } catch {}
    drawPlayerStatus(
      ctx,
      { hp: Number(e.hp) || 0, hpMax: Math.max(1, Number(e.hpMax) || 1),
        sh: Number(e.sh) || 0, shMax: Math.max(0, Number(e.shMax) || 0),
        r: 20, dead: false },
      pseudo, 0, 0, rankImg, factImg, dind, ficon, [],
      // Comme les joueurs distants : plaque complète (barres + pastilles +
      // formation) seulement quand locké, sinon pseudo + grade/firme + titre.
      false, showBars === true,
      "rgba(255,255,255,0.95)", null, 0, renderSmoothingOn(),
      { text: "Bot JPC d'Hyperion Orbit", color: "#c77dff" },
    );
    // Bulle ISH : même animation de bouclier instantané que les joueurs
    // (locaux comme distants : sprite INSTANT_SHIELD 64 frames, 3 s), jouée
    // en boucle sur la durée de la bulle JPC (6 s). Plus de rond bleu.
    if ((e.ishT || 0) > 0) {
      try {
        if (!instaShieldReady) { try { ensureInstaShieldLoaded(); } catch {} }
        if (instaShieldReady && instaShieldImgs?.length) {
          let idx = 0;
          if (e._netUid) {
            // Multi : le snapshot ne donne qu'un booléen → horloge locale bouclée.
            const nowMs = (typeof performance !== "undefined" && performance.now ? performance.now() : Date.now());
            if (!Number.isFinite(Number(e._jpcIshAnimT0))) e._jpcIshAnimT0 = nowMs;
            const el = Math.max(0, (nowMs - Number(e._jpcIshAnimT0)) / 1000);
            idx = Math.floor(el / ISH_DURATION * instaShieldImgs.length) % instaShieldImgs.length;
          } else {
            // Solo : ishT compte 6 → 0 → deux boucles d'anim à vitesse normale.
            const el = Math.max(0, 6 - Number(e.ishT || 0));
            idx = Math.floor(el / ISH_DURATION * instaShieldImgs.length) % instaShieldImgs.length;
          }
          const img = instaShieldImgs[Math.min(instaShieldImgs.length - 1, idx)];
          if (isImgReady(img)) {
            ctx.save();
            ctx.imageSmoothingEnabled = false;
            ctx.drawImage(img, -INSTA_SHIELD_PACK.w / 2, -INSTA_SHIELD_PACK.h / 2, INSTA_SHIELD_PACK.w, INSTA_SHIELD_PACK.h);
            ctx.restore();
          }
        }
      } catch {}
    } else {
      try { e._jpcIshAnimT0 = null; } catch {}
    }
  } catch {}
}

function npcLabelFor(e) {
  // ✅ Awakened : nom brouillé (code 25 caractères lettres/chiffres/?),
  // régénéré toutes les 0,05 s, différent par NPC.
  if (e && typeof e.type === "string" && e.type.indexOf("npc_Awakened_") === 0) {
    try { return awakenedScrambleName(e); } catch {}
  }
  const name = e && e.name ? String(e.name).trim() : "";
  return name || `NPC ${e?.id ?? "?"}`;
}

// ✅ Code brouillé façon "signal corrompu" : LCG déterministe semé par
// l'id du NPC + la tranche de 0,05 s (stable pendant la tranche).
const AWAKENED_SCRAMBLE_CHARS = "abcdefghijklmnopqrstuvwxyz0123456789?";
const AWAKENED_SCRAMBLE_LEN = 25;
const AWAKENED_SCRAMBLE_MS = 50;
function awakenedScrambleName(e) {
  const slice = Math.floor(performance.now() / AWAKENED_SCRAMBLE_MS);
  if (e._scrambleT !== slice || typeof e._scrambleName !== "string") {
    e._scrambleT = slice;
    let seed = ((Number(e.id) || 0) * 2654435761 + slice * 40503) | 0;
    let out = "";
    for (let i = 0; i < AWAKENED_SCRAMBLE_LEN; i++) {
      seed = (seed * 1103515245 + 12345) & 0x7fffffff;
      out += AWAKENED_SCRAMBLE_CHARS[seed % AWAKENED_SCRAMBLE_CHARS.length];
    }
    e._scrambleName = out;
  }
  return e._scrambleName;
}

// ============================================================
// Draw: player & NPC sprites
// ============================================================
function drawPlayerBody() {
  if (!playerImgsReady || !playerImgs || !playerImgs.length) return false;

  const pack = ACTIVE_SHIP || SHIP_PACKS[0];
  const idx = getPlayerSpriteFrame();
  const img = playerImgs[idx] || playerImgs[0];
  if (!isImgReady(img)) return false;

  const w = pack.w ?? 170;
  const h = pack.h ?? 170;
  // Leonov sur ses maps natives (boosts) : contour turquoise de base.
  if (isLeonovHomeActive()) {
    const sil = outlineSilhouette(`ship:${pack?.id || "player"}:${idx}`, img, w, h, "#259abb");
    strokeOutlineCentered(sil, w, h, "#259abb", petLocatorPulse());
  }
  // Lissage du rendu graphique : aux positions fractionnaires (en mouvement),
  // le vaisseau suit en continu au lieu d'accrocher d'un pixel à l'autre.
  drawCenteredImage(ctx, img, w, h, renderSmoothingOn());

  ctx.save();
  ctx.imageSmoothingEnabled = false;
  ctx.restore();

  // ✅ Effet de vaisseau (Ship_effet) par-dessus le vaisseau, boucle à l'infini
  if (GAME_SETTINGS.shipEffect) {
    loadShipEffect(pack?.id);
    drawShipEffectOverlay();
  }

  drawCustomDesignParticles(pack?.id, account.user?.id || "self");

  return true;
}

// Pusat Plus ZBLI : notes SVG multicolores. Goliath Plus STIFLER : petits
// coeurs SVG roses/violets. L'animation permanente
// est calculée uniquement à partir du temps et d'une graine stable : elle est
// donc visible sur notre vaisseau comme sur les joueurs distants sans ajouter
// le moindre message réseau.
const ZBLI_NOTE_COLORS = Object.freeze([
  "#ff3f78", "#ff9f2f", "#ffe14a", "#66ef72",
  "#35dcff", "#5d82ff", "#bd66ff", "#ff63dc",
]);
const zbliNoteImgs = ZBLI_NOTE_COLORS.map((color, index) => {
  const img = new Image();
  const doubleNote = index % 2 === 1;
  const shape = doubleNote
    ? `<path fill="${color}" d="M7 3v20.2a6 6 0 1 0 3 5.2V11l13-3v11.2a6 6 0 1 0 3 5.2V2L7 6.3V3z"/>`
    : `<path fill="${color}" d="M11 2v20.1a6.2 6.2 0 1 0 3.4 5.5V10.2L27 7v11.1a6.2 6.2 0 1 0 3.4 5.5V2.5L11 7.2V2z"/>`;
  img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 38 38">${shape}</svg>`)}`;
  return img;
});
const STIFLER_HEART_COLORS = Object.freeze(["#ff4fa3", "#ff79c6", "#d85cff", "#9e55ff"]);
const stiflerHeartImgs = STIFLER_HEART_COLORS.map((color) => {
  const img = new Image();
  const shape = `<path fill="${color}" d="M19 33C15.5 29.8 5 22.1 5 13.3 5 7.7 9.1 4 14 4c2.8 0 4.6 1.4 5 3.2C19.4 5.4 21.2 4 24 4c4.9 0 9 3.7 9 9.3 0 8.8-10.5 16.5-14 19.7z"/>`;
  img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 38 38">${shape}</svg>`)}`;
  return img;
});

function designParticleSeed(value) {
  const text = String(value || "zbli");
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) hash = Math.imul(hash ^ text.charCodeAt(i), 16777619);
  return (hash >>> 0) / 4294967296;
}

function drawCustomDesignParticles(shipId, ownerId = "self") {
  if (!GAME_SETTINGS.customDesignEffects) return;
  const designId = String(shipId || "").toLowerCase();
  const notes = designId === "pusat_plus_zbli";
  const hearts = designId === "goliath_plus_stifler";
  if (!notes && !hearts) return;
  const colors = hearts ? STIFLER_HEART_COLORS : ZBLI_NOTE_COLORS;
  const images = hearts ? stiflerHeartImgs : zbliNoteImgs;
  const now = performance.now() / 1000;
  const seed = designParticleSeed(ownerId);
  const count = 24;
  for (let i = 0; i < count; i++) {
    const lane = (i + seed * count) / count;
    const progress = (now * 0.34 + lane) % 1;
    const angle = i * 2.399963 + seed * Math.PI * 2 + Math.sin(now * 1.7 + i) * 0.16;
    const radius = 8 + progress * 150;
    const drift = Math.sin(now * 2.2 + i * 1.73) * 10 * progress;
    const x = Math.cos(angle) * radius + Math.cos(angle + Math.PI / 2) * drift;
    const y = Math.sin(angle) * radius + Math.sin(angle + Math.PI / 2) * drift;
    const alpha = Math.sin(Math.PI * progress) * 0.92;
    const size = 12 + (1 - progress) * 10;
    const img = images[i % images.length];
    if (!isImgReady(img) || alpha <= 0.02) continue;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle + Math.sin(now * 2.8 + i) * 0.45);
    ctx.globalAlpha *= alpha;
    ctx.shadowColor = colors[i % colors.length];
    ctx.shadowBlur = 8;
    ctx.drawImage(img, -size / 2, -size / 2, size, size);
    ctx.restore();
  }
}

// Multi : autres joueurs de la meme map avec leur vrai vaisseau + leur laser.
// Les packs sont charges a la demande (comme la coque locale) ; en attendant,
// repli triangle + pseudo (meme style que l'etape 1).
// Les NPC reseau sont le seul gameplay autorise sur une carte zone.
// Les instances privees (GG) restent gerees par leur controleur local.
function isSharedZone() {
  return isZoneMap === true;
}
function isPrivateInstance() {
  return !isSharedZone();
}
const netplaySpriteCache = new Map();
// Etats moteurs (flammes) des vaisseaux distants, par id joueur.
const netplayEngines = new Map();
const netHoloClonesSeen = new Map();
// Mouvement visuel des formations de drones distantes, par id joueur.
// Chaque joueur conserve son propre cap lissé, son décalage de virage et les
// positions interpolées de ses drones.
const remoteDroneFormationMotions = new Map();
// Etats moteurs (reacteurs) des PET distants, par id joueur.
// Cle stable (holder) pour petEngine (WeakMap) + vitesse estimee pour les flames/trails.
const netplayPetEngines = new Map();
let netplayLastOx = 0, netplayLastOy = 0;
let netplayCacheCleanupAt = 0;
try {
  window.__NETPETDIAG__ = () => {
    const out = [];
    try {
      for (const r of getNetplayRemotes().values()) {
        const prx = Number(r.petrx ?? r.petx) + netplayLastOx;
        const pry = Number(r.petry ?? r.pety) + netplayLastOy;
        out.push({
          pseudo: String(r.pseudo || "?"),
          peta: r.peta, petl: r.petl,
          petx: Math.round(Number(r.petx) || 0), petrx: Math.round(Number(r.petrx) || 0),
          shipX: Math.round(Number(r.rx ?? r.x) || 0),
          shipScreenX: Math.round(Number(r.rx ?? r.x) + netplayLastOx),
          onScreen: prx > -260 && pry > -260 && prx < innerWidth + 260 && pry < innerHeight + 260,
        });
      }
    } catch (e) { out.push({ err: String(e?.message || e) }); }
    return out;
  };
} catch {}
// Anneaux Ship_damage autour des joueurs distants (degats NPC + PvP vus
// par l'observateur). Meme sprite que le notre, ancre au copain.
const netShipDamages = new Map(); // remoteId -> [{ ang, rad, rot, t }]
const netPvpAtSeen = new Map(); // remoteId -> dernier pvpAt affiche
const netNpcAtSeen = new Map(); // remoteId -> dernier impact NPC affiche
let netShipDamageLastT = 0;
// dt reel (comme l'anneau local) : le pas fixe 0.016 rendait l'anim 2x trop
// rapide sur les ecrans 120/144 Hz.
function netShipDamageDt() {
  let dt = 0.016;
  try {
    const now = performance.now();
    if (netShipDamageLastT > 0) dt = Math.max(0.001, Math.min(0.1, (now - netShipDamageLastT) / 1000));
    netShipDamageLastT = now;
  } catch {}
  return dt;
}
function spawnNetShipDamage(remoteId, ang, rad, why = "") {
  if (remoteId == null || !Number.isFinite(Number(ang))) return;
  // Même option que le local ("Explosions et impacts").
  try { if (GAME_SETTINGS.npcExplosions === false) return; } catch {}
  if (fxDensityMult() === 0) return;
  const key = String(remoteId);
  let list = netShipDamages.get(key);
  if (!list) { list = []; netShipDamages.set(key, list); }
  list.push({
    ang: Number(ang) || 0,
    rad: Math.max(10, Number(rad) || 30),
    rot: Number(ang) || 0,
    t: 0,
    // Meme echelle que l'anneau local (sans ca : w = 320 * undefined = NaN,
    // drawImage ne dessine rien et l'anneau distant reste invisible).
    scale: Number(SHIP_DAMAGE_PACK.scale) || 0.4,
  });
  while (list.length > 8) list.shift();
  try {
    window.__NETRING__ = window.__NETRING__ || { spawn: 0, drawn: 0, lastWhy: "" };
    window.__NETRING__.spawn++;
    if (why) window.__NETRING__.lastWhy = String(why).slice(0, 32);
  } catch {}
}
function tickNetShipDamages(dt) {
  if (!netShipDamages.size) return;
  const fps = SHIP_DAMAGE_PACK.fps || 30;
  const frames = SHIP_DAMAGE_PACK.frames || 9;
  const dur = frames / fps;
  for (const [key, list] of netShipDamages) {
    for (let i = list.length - 1; i >= 0; i--) {
      list[i].t += dt;
      if (list[i].t >= dur) list.splice(i, 1);
    }
    if (!list.length) { netShipDamages.delete(key); }
  }
}
function netplayPackFor(shipId) {
  const key = String(shipId || "").toLowerCase() || "__default__";
  if (netplaySpriteCache.has(key)) return netplaySpriteCache.get(key);
  let pack = null;
  try { pack = getShipPackByIdData(shipId) || null; } catch { pack = null; }
  if (!pack) pack = SHIP_PACKS[0];
  netplaySpriteCache.set(key, pack);
  return pack;
}

function warmNetplayRemoteAssets(remote) {
  if (!remote || remote.dead) return;
  const dx = Number(remote.x) - Number(player.x), dy = Number(remote.y) - Number(player.y);
  if (dx * dx + dy * dy > 3600 * 3600) return;
  try { preloadHangarSwapImages(); } catch {}
  if (String(getShipDesignBaseId(remote.shipId) || remote.shipId).toLowerCase() === "hyperion") {
    try { preloadGravityAnchorImages(); } catch {}
  }
  const signature = [remote.shipId, remote.rank, remote.firm, remote.ficon, remote.petl, remote.peta, remote.dslots, (remote.afx || []).map(e => e[0]).join(","), remote.fxFlash?.code, remote.lastStandReady].join("|");
  if (remote._assetWarmSignature === signature) return;
  remote._assetWarmSignature = signature;
  try {
    const pack = netplayPackFor(remote.shipId);
    if (pack && !pack._ready && !pack._promise) ensurePackLoaded(pack);
  } catch {}
  for (const path of [remote.rank, remote.ficon]) {
    if (!path) continue;
    try { loadImage(String(path), { priority: true }); } catch {}
  }
  try {
    const factionPath = getFaction(remote.firm)?.imagePath;
    if (factionPath) loadImage(factionPath, { priority: true });
  } catch {}
  if (remote.peta === 1) {
    try {
      const frame = ((angleToFrameIndex(Number(remote.petd ?? remote.angle) || 0, 32) + 16) % 32) + 1;
      loadImage(`${getPetStageBase(Math.max(1, Number(remote.petl) || 1))}${frame}.png`, { priority: true });
      if (getPetStage(remote.petl) >= 6) loadImage(`/PET/PET_SPRITES/NIVEAU5/${frame}.png`, { priority: true });
    } catch {}
  }
  // Sprites d'aptitudes des auras actives (rendu distant fidèle au local).
  try {
    const afx = [...(Array.isArray(remote.afx) ? remote.afx : []), ...(remote.lastStandReady ? [[48]] : [])];
    const seen = new Set();
    for (const entry of afx) {
      if (!Array.isArray(entry)) continue;
      const code = Math.floor(Number(entry[0]) || 0);
      if (!(code > 0) || seen.has(code)) continue;
      seen.add(code);
      for (const [folder, frames] of (REMOTE_FX_PRELOAD[code] || [])) {
        const base = String(folder).includes("/") ? String(folder) : `ASSETS/APTITUDES/${folder}`;
        for (let i = 1; i <= frames; i++) {
          try { loadImage(`${base}/${i}.png`, { priority: true }); } catch {}
        }
      }
    }
    const fl = remote.fxFlash;
    if (fl && Number(fl.until) > performance.now() && Number(fl.code) > 0) {
      for (const [folder, frames] of (REMOTE_FX_PRELOAD[Math.floor(Number(fl.code))] || [])) {
        try {
          const base = String(folder).includes("/") ? String(folder) : `ASSETS/APTITUDES/${folder}`;
          loadImage(`${base}/1.png`, { priority: true });
        } catch {}
        void frames;
      }
    }
  } catch {}
}

// Multi : projectiles visuels de l'allie, joues a la reception des
// evenements exacts du tireur (vrais + faux tirs, roquettes avec arcs).
// Zero degat : memes sprites et trajectoires, pas de sons ni de chiffres.
function netShotTarget(tx, ty, range) {
  try {
    let best = null, bestD2 = range * range;
    for (const c of enemies) {
      if (!c || !(c.hp > 0)) continue;
      const dx = c.x - tx, dy = c.y - ty;
      const d2 = dx * dx + dy * dy;
      if (d2 < bestD2) { bestD2 = d2; best = c.id; }
    }
    return best;
  } catch { return null; }
}

// Multi : cible visuelle = NPC, joueur distant, ou nous-meme (tirs allies
// recus : homing + impact visible, zero degat).
function netVisualTarget(tx, ty, range, ev = null) {
  try {
    const stationTarget = typeof ev?.stationTarget === "string" ? ev.stationTarget : "";
    if (stationTarget) {
      stationCombatTargets();
      const exact = stationTargetProxies.get(stationTarget);
      if (exact?.hp > 0) return exact.id;
    }
    const petTarget = typeof ev?.petTarget === "string" ? ev.petTarget : "";
    if (petTarget) {
      if (petTarget === "owner") {
        const ownersPet = netPetProxies.get(String(ev?.by || ""));
        if (ownersPet?.hp > 0) return ownersPet.id;
      } else if (petTarget === String(netMyId())) {
        if (petLockValid()) return "pet";
      } else {
        const remotePet = netPetProxies.get(petTarget);
        if (remotePet?.hp > 0) return remotePet.id;
      }
    }
    let best = null, bestD2 = range * range;
    const consider = (id, x, y) => {
      const dx = x - tx, dy = y - ty;
      const d2 = dx * dx + dy * dy;
      if (d2 < bestD2) { bestD2 = d2; best = id; }
    };
    for (const c of enemies) {
      if (!c || !(c.hp > 0)) continue;
      consider(c.id, c.x, c.y);
    }
    for (const e of netPlayerProxies.values()) {
      if (!e || !(e.hp > 0)) continue;
      consider(e.id, e.x, e.y);
    }
    for (const e of netPetProxies.values()) {
      if (!e || !(e.hp > 0)) continue;
      consider(e.id, e.x, e.y);
    }
    // Un tir distant sur notre PET doit finir sur le REX, pas etre rattache
    // par proximite a notre vaisseau ou a un NPC.
    if (petLockValid()) consider("pet", petState.x, petState.y);
    if (!player.dead && player.hp > 0) consider("self", player.x, player.y);
    return best;
  } catch { return null; }
}

function netVisualShotOrigin(ev) {
  const fallback = { x: Number(ev?.x), y: Number(ev?.y) };
  try {
    const npc = enemies.find(e => e?.hp > 0 && e._netUid === String(ev?.by || ""));
    if (npc) return { x: npc.x, y: npc.y };
    const remote = getNetplayRemotes().get(String(ev?.by || ""));
    if (!remote) return fallback;
    if (ev?.petClone === 0 || ev?.petClone === 1) {
      const clone = remote.tbrClones?.[ev.petClone];
      return clone ? { x: Number(clone.rx ?? clone.x), y: Number(clone.ry ?? clone.y) } : fallback;
    }
    if (ev?.petSource === true) {
      return { x: Number(remote.petrx ?? remote.petx), y: Number(remote.petry ?? remote.pety) };
    }
    return { x: Number(remote.rx ?? remote.x), y: Number(remote.ry ?? remote.y) };
  } catch { return fallback; }
}

// Une vraie salve reseau porte un identifiant `v`. Les projectiles visuels
// supplementaires reutilisent ce meme identifiant : leur image est jouee,
// mais jamais leur son une seconde fois.
const netVolleySoundsSeen = new Map();
function shouldPlayNetVolleySound(ev) {
  if (!Number.isFinite(Number(ev?.v))) return true;
  const key = `${String(ev?.t || "shot")}:${String(ev?.by || "?")}:${Math.floor(Number(ev.v))}`;
  if (netVolleySoundsSeen.has(key)) return false;
  const now = performance.now();
  netVolleySoundsSeen.set(key, now);
  if (netVolleySoundsSeen.size > 512) {
    for (const [oldKey, at] of netVolleySoundsSeen) {
      if (now - Number(at || 0) > 10_000 || netVolleySoundsSeen.size > 480) netVolleySoundsSeen.delete(oldKey);
      if (netVolleySoundsSeen.size <= 480) break;
    }
  }
  try {
    const rally = getNetGroup()?.rally;
    if (rally && Number(rally.expiresAt) > Date.now() && String(rally.map) === String(window.__CURRENT_MAP_ID__ || "")) {
      petLocatorMarkers.push({ x: Number(rally.x) || 0, y: Number(rally.y) || 0, color: "#ff3b4f", pulse: true, cross: true });
    }
  } catch {}
  return true;
}

function spawnNetShotVisual(ev) {
  // Tir NPC<->JPC partagé : streak rouge téléguidé (aucune collision).
  if (ev && ev.npcShot === true) {
    const from = enemies.find(e => e?.hp > 0 && e._netUid === String(ev.by || ""));
    const target = enemies.find(e => e?.hp > 0 && e._netUid === String(ev.tuid || ""));
    if (!target) return;
    const cfg = NPC_TYPES[from?.type || ev.npcType] || {};
    const sx0 = Number(from?.x ?? ev.x), sy0 = Number(from?.y ?? ev.y);
    if (![sx0, sy0, target.x, target.y].every(Number.isFinite)) return;
    const angle = Math.atan2(target.y - sy0, target.x - sx0);
    const fx = Math.cos(angle), fy = Math.sin(angle);
    const spd = Math.max(120, Number(from?.bulletSpeed ?? cfg.bulletSpeed) || 900);
    const muzzle = (Number(from?.r ?? cfg.r) || 18) + 12;
    const sprite = from?.bulletSprite || cfg.bulletSprite || null;
    if (sprite?.src) loadImage(sprite.src, { priority: true });
    for (const off of Number(ev.n) === 2 ? [-14, 14] : [0]) {
      const sx = sx0 + fx * muzzle - fy * off;
      const sy = sy0 + fy * muzzle + fx * off;
      const dx = target.x - sx, dy = target.y - sy, distance = Math.hypot(dx, dy) || 1;
      addCappedProjectile(enemyBullets, {
        x: sx, y: sy, vx: dx / distance * spd, vy: dy / distance * spd, spd,
        r: from?.bulletR ?? cfg.bulletR ?? 7, life: distance / spd + 0.3,
        dmg: 0, key: from?.ammoKey || cfg.ammoKey || "x1",
        scale: from?.bulletScale ?? cfg.bulletScale ?? 1.5, sprite,
        target: "jpc", targetId: target.id, homing: true,
        ownerId: from?.id ?? null, miss: false, visual: true, _jpcVisual: true,
      }, ENTITY_LIMITS.enemyBullets);
    }
    return;
  }
  const jpcShooter = enemies.find(e => e?.isJpcBot && e.hp > 0 && e._netUid === String(ev?.by || ""));
  if (jpcShooter) {
    const targetUid = String(ev.tuid || "");
    let target = targetUid
      ? enemies.find(e => e?.hp > 0 && (e._netUid === targetUid || e._netPlayer === targetUid))
        || (targetUid === String(netMyId()) ? player : null)
      : null;
    // Le serveur deja en cours peut encore emettre l'ancien format sans
    // tuid. Ces evenements portent le point vise, comme les tirs allies.
    // Le repli est visuel uniquement; un UID explicite garde la priorite.
    if (!targetUid && Number.isFinite(Number(ev.tx)) && Number.isFinite(Number(ev.ty))) {
      let bestD2 = 400 * 400;
      for (const candidate of [...enemies, player]) {
        if (!candidate || candidate === jpcShooter || !(candidate.hp > 0) || candidate.dead) continue;
        const d2 = (candidate.x - Number(ev.tx)) ** 2 + (candidate.y - Number(ev.ty)) ** 2;
        if (d2 < bestD2) { bestD2 = d2; target = candidate; }
      }
    }
    if (!target || !(target.hp > 0)) return;
    const legacyVolley = !targetUid && ev.jpcPart !== true;
    const isPair = legacyVolley ? jpcShooter._netJpcPair === true : Number(ev.n) === 2;
    if (legacyVolley) jpcShooter._netJpcPair = !isPair;
    // Munition réelle du tireur (x4 / salves x6 en riposte, x1 en farm).
    const evKey = String(ev.key || "x1").toLowerCase();
    const jpcAmmo = (typeof PLAYER_BULLET_SPRITES !== "undefined" && PLAYER_BULLET_SPRITES[evKey]) ? evKey : "x1";
    const jpcSprite = (typeof PLAYER_BULLET_SPRITES !== "undefined" && PLAYER_BULLET_SPRITES[jpcAmmo]) || PLAYER_BULLET_SPRITES.x1;
    const angle = Math.atan2(target.y - jpcShooter.y, target.x - jpcShooter.x);
    const fx = Math.cos(angle), fy = Math.sin(angle);
    const spd = 4000 + Math.hypot(target.x - jpcShooter.x, target.y - jpcShooter.y);
    for (const off of isPair ? [-SIDE_OFFSET, SIDE_OFFSET] : [0]) {
      const sx = jpcShooter.x + fx * ((jpcShooter.r || 20) + 10) - fy * off;
      const sy = jpcShooter.y + fy * ((jpcShooter.r || 20) + 10) + fx * off;
      const dx = target.x - sx, dy = target.y - sy, distance = Math.hypot(dx, dy) || 1;
      addCappedProjectile(enemyBullets, {
        x: sx, y: sy, vx: dx / distance * spd, vy: dy / distance * spd, spd,
        r: 6, life: distance / spd + 0.3, dmg: 0, key: jpcAmmo, scale: 1,
        sprite: jpcSprite,
        target: target === player ? "player" : "npc", targetId: target.id,
        homing: true, ownerId: jpcShooter.id, miss: false, visual: true, _jpcVisual: true, _jpcShot: true,
      }, ENTITY_LIMITS.enemyBullets);
    }
    if (legacyVolley) {
      // L'ancien serveur n'envoie que le vrai tir. Completer la salve
      // ici; les serveurs recents signalent chaque eclair par jpcPart.
      const volley = (Number(jpcShooter._netJpcVolley) || 0) + 1;
      jpcShooter._netJpcVolley = volley;
      for (let i = 1; i < 6; i++) {
        const pair = (i % 2 === 0) === isPair;
        for (const off of pair ? [-SIDE_OFFSET, SIDE_OFFSET] : [0]) {
          scheduleNpcFaux(i * 0.2, {
            npcId: jpcShooter.id, jpcVolley: volley, off, dmg: 0,
            spd, life: Math.hypot(target.x - jpcShooter.x, target.y - jpcShooter.y) / spd + 0.3,
            key: jpcAmmo, scale: 1, sprite: jpcSprite, bulletR: 6,
            target: target === player ? "player" : "npc", targetId: target.id,
            homing: true, visualOnly: true,
          });
        }
      }
    }
    return;
  }
  const tx = Number(ev.tx), ty = Number(ev.ty);
  const origin = netVisualShotOrigin(ev);
  const sx0 = Number(origin.x), sy0 = Number(origin.y);
  if (!Number.isFinite(tx) || !Number.isFinite(ty)) return;
  if (!Number.isFinite(sx0) || !Number.isFinite(sy0)) return;
  const spd = Math.max(500, Math.min(20000, Number(ev.spd) || 4000));
  const key = String(ev.key || "x1").toLowerCase();
  const ammo = (typeof PLAYER_BULLET_SPRITES !== "undefined" && PLAYER_BULLET_SPRITES[key]) ? key : "x1";
  const n = Math.max(1, Math.min(2, Math.round(Number(ev.n) || 1)));
  const tgtId = netVisualTarget(tx, ty, ev.station === true ? 1200 : 400, ev);
  if (tgtId == null) return;
  const sab = ev.sab === true;
  const shotSound = sab ? PLAYER_SHOT_SFX.sab : (PLAYER_SHOT_SFX[key] || PLAYER_SHOT_SFX.x1);
  if (shouldPlayNetVolleySound(ev)) {
    playNetSpatialSound(shotSound, sx0, sy0, { cooldown: 0.03, maxVoices: 5 });
  }
  // SAB inverse : part de la cible vers le vaisseau (comme en local),
  // en ligne droite (pas de homing vers nous).
  const ox = sab ? tx : sx0, oy = sab ? ty : sy0;
  const ax = sab ? sx0 : tx, ay = sab ? sy0 : ty;
  const ang = Math.atan2(ay - oy, ax - ox);
  const fx = Math.cos(ang), fy = Math.sin(ang);
  const px = -fy, py = fx;
  const starts = n > 1
    ? [[ox + fx * 28 + px * SIDE_OFFSET, oy + fy * 28 + py * SIDE_OFFSET],
       [ox + fx * 28 - px * SIDE_OFFSET, oy + fy * 28 - py * SIDE_OFFSET]]
    : [[ox + fx * 28, oy + fy * 28]];
  // MISS distant : meme texte que le tireur (volley namespace par expediteur
  // pour ne pas collisionner avec nos propres volleyId).
  const netMiss = ev.miss === true;
  const netVolley = Number.isFinite(Number(ev.v))
    ? `net:${String(ev.by || "?")}:${Math.floor(Number(ev.v))}`
    : `net:${String(ev.by || "?")}:${Math.floor(Math.random() * 1e9)}`;
  for (const [sx, sy] of starts) {
    const mdx = ax - sx, mdy = ay - sy;
    const md = Math.hypot(mdx, mdy) || 1;
    try {
      addCappedProjectile(bullets, {
        x: sx, y: sy,
        vx: (mdx / md) * spd, vy: (mdy / md) * spd,
        r: 6.0, life: md / spd + 0.3,
        dmg: 0, key: ammo, side: "player", targetId: tgtId,
        // SAB allie : comme en local, homing vers le vaisseau du tireur +
        // absorption a l'arrivee (voir tick : branche _netVisual). Sans ca,
        // le tir file droit vers la position figee du tireur et le depasse
        // loin derriere des qu'il bouge.
        homing: true, visual: true, spd, sabReverse: sab,
        sabHomeBy: sab ? String(ev.by || "") : "",
        volleyId: netVolley, volleySize: starts.length,
        miss: netMiss, _netVisual: true,
        // Tir d'un bot JPC (uid map#jpcN) : exempté du cull capteur comme
        // les streaks rouges (le farm a lieu loin du joueur).
        _jpcVisual: /#jpc\d*$/i.test(String(ev.by || "")),
      }, ENTITY_LIMITS.playerBullets);
    } catch { break; }
  }
}

// Vaisseau allie d'ou part un SAB affiche (proxy interpole). Le SAB visuel
// le poursuit et s'y absorbe ; s'il disparait (mort/deco), le tir s'eteint.
function netVisualSabHome(by) {
  try {
    const id = String(by || "");
    if (!id) return null;
    for (const e of netPlayerProxies.values()) {
      if (e && String(e._netPlayer) === id && Number(e.hp) > 0) return e;
    }
  } catch {}
  return null;
}

function spawnNetRocketVisual(ev) {
  const tx = Number(ev.tx), ty = Number(ev.ty);
  const origin = netVisualShotOrigin(ev);
  const sx0 = Number(origin.x), sy0 = Number(origin.y);
  if (!Number.isFinite(tx) || !Number.isFinite(ty)) return;
  if (!Number.isFinite(sx0) || !Number.isFinite(sy0)) return;
  const kind = String(ev.kind || "r310").toLowerCase();
  const rkey = (typeof PLAYER_BULLET_SPRITES !== "undefined" && PLAYER_BULLET_SPRITES[kind]) ? kind : "r310";
  let isLauncher = false;
  try { isLauncher = getRocketType(kind)?.manual === false; } catch {}
  if (shouldPlayNetVolleySound(ev)) {
    playNetSpatialSound(isLauncher ? "sfx_shot_lance_roquettes" : "sfx_shot_roquettes", sx0, sy0, {
      cooldown: isLauncher ? 0.08 : 0.05,
      maxVoices: 5,
    });
  }
  const spd = Math.max(500, Math.min(20000, Number(ev.spd) || 1500));
  const dist = Math.hypot(tx - sx0, ty - sy0);
  if (!(dist > 40) || dist > 5000) return;
  const tgtId = netVisualTarget(tx, ty, ev.station === true ? 1200 : 500, ev);
  if (tgtId == null) return;
  const ang = Math.atan2(ty - sy0, tx - sx0);
  const prange = Math.max(200, Number(ev.prange) || 1000);
  const arcDir = Number(ev.arcDir) < 0 ? -1 : 1;
  const arcScale = Number.isFinite(Number(ev.arcScale)) ? Number(ev.arcScale) : 1;
  const arcBoost = Number.isFinite(Number(ev.arcBoost)) ? Number(ev.arcBoost) : 0;
  // MISS distant (roquette) : meme texte que le tireur.
  const netMissR = ev.miss === true;
  const netVolleyR = Number.isFinite(Number(ev.v))
    ? `net:${String(ev.by || "?")}:${Math.floor(Number(ev.v))}`
    : `net:${String(ev.by || "?")}:${Math.floor(Math.random() * 1e9)}`;
  // Roquette de station : départ vers le haut puis arc (comme un
  // lance-roquettes), fumée rouge au lieu de l'arc-en-ciel.
  const stationShot = ev.station === true;
  try {
    addCappedProjectile(bullets, {
      x: sx0, y: sy0,
      vx: Math.cos(ang) * spd, vy: Math.sin(ang) * spd,
      r: 8.0, life: dist / spd + 1.5,
      dmg: 0, key: rkey, side: "player", targetId: tgtId,
      homing: true, visual: true, spd,
      volleyId: netVolleyR, volleySize: 1,
      miss: netMissR, isSab: false, isRocket: true, isLauncherRocket: isLauncher || stationShot,
      prec: ev.prec === true,
      launcherDepartureX: stationShot ? 0 : Math.cos(ang), launcherDepartureY: stationShot ? -1 : Math.sin(ang), launcherDepartureT: 0,
      arcDist0: dist, arcT: 0,
      arcKick0: arcDir * arcScale * spd * Math.tan((70 + arcBoost - Math.min(1, dist / prange) * 25) * Math.PI / 180),
      smokeT: 0, smokeHue: Math.floor(Math.random() * 360),
      stationSmoke: stationShot || undefined,
      _netVisual: true,
      // Tir d'un bot JPC (uid map#jpcN) : exempté du cull capteur comme
      // les streaks (le farm a lieu loin du joueur).
      _jpcVisual: /#jpc\d*$/i.test(String(ev.by || "")),
    }, ENTITY_LIMITS.playerBullets);
  } catch {}
}

function showRemoteAbilityHeal(ev, remote) {
  if (!remote || remote.dead || remote.cloaked || remote.cloakCpu) return;
  const selected = Target.get();
  if (!selected || String(selected._netPlayer || "") !== String(ev.by)) return;
  const amount = Number(ev.amount);
  if (!Number.isFinite(amount) || amount < 0) return;
  const shield = ev.shield === true;
  addFloatText(Number(remote.rx ?? remote.x) + (Math.random() - 0.5) * 60,
    Number(remote.ry ?? remote.y) - (shield ? 110 : 90) - Math.random() * 20,
    amount, shield ? "rgba(70,180,255,0.98)" : "rgba(80,255,125,0.98)",
    { text: `+${DMG_FMT.format(amount)}`, size: 21, pop: 0.3, shake: 0.6, life: 1, glow: 1, weight: 900, impact: true });
}

function applyNetHeal(ev) {
  const shield = ev.shield === true;
  if (player.dead) return;
  // Tempest Back-up bloque bien le soin de coque, mais Energy Leech doit
  // quand même afficher le +0 confirmé par le serveur.
  const tempestBlocked = !shield && (player.tempestBackupT || 0) > 0;
  if (tempestBlocked && !(ev.skill === "ability_tech_energy_leech" && Math.round(Number(ev.amount) || 0) === 0)) return;
  const key = shield ? "sh" : "hp", maxKey = shield ? "shMax" : "hpMax";
  const aegis = ev.skill.startsWith("ability_aegis_");
  const cap = aegis ? ev.skill === "ability_aegis_repair-pod" ? 18000 : shield ? 25000 : 40000 : 1e9;
  const amount = Math.max(0, Math.min(cap, Math.round(Number(ev.amount) || 0)));
  const before = Number(player[key]) || 0;
  const fresh = !(Number(ev.healSeq) > 0) || Number(ev.healSeq) > Number(player._netAbilityHealSeq || 0);
  if (fresh) {
    if (Number(ev.healSeq) > 0) player._netAbilityHealSeq = ev.healSeq;
    if (ev.skill === "ability_sentinel" && Number.isFinite(ev.shMax)) player.shMax = ev.shMax;
    player[key] = Math.min(Number(player[maxKey]) || 0, Number.isFinite(ev[key]) ? ev[key] : before + amount);
  }
  const gain = amount;
  if (Number(ev.healSeq) > 0) {
    if (Number(ev.healSeq) <= Number(player._netAbilityHealFxSeq || 0)) return;
    player._netAbilityHealFxSeq = Number(ev.healSeq);
  }
  // Les Solace affichent déjà leur réparation instantanée au clic.
  if (String(ev.by) === String(netMyId()) && ev.skill.startsWith("ability_solace")) return;
  addFloatText(Number(player.x) + (Math.random() - 0.5) * 60,
    Number(player.y) - (shield ? 110 : 90) - Math.random() * 20,
    gain, shield ? "rgba(70,180,255,0.98)" : "rgba(80,255,125,0.98)",
    { text: `+${DMG_FMT.format(gain)}`, size: 21, pop: 0.3, shake: 0.6, life: 1, glow: 1, weight: 900, impact: true });
}

function applyTechVisualEvent(ev) {
  const skill = String(ev.skill || "");
  if (!skill.startsWith("ability_tech_")) return;
  const local = String(ev.by) === String(netMyId());
  const actor = local ? player : getNetplayRemotes()?.get(String(ev.by));
  if (!actor) return;
  const field = {
    ability_tech_chain_impulse: "chainImpFx", ability_tech_frost_field: "frostFx",
    ability_tech_npc_bomb: "npcBombFx", ability_tech_energy_leech: "leechFx",
  }[skill];
  if (ev.enabled === false) {
    if (field) actor[field] = null;
    if (local && skill === "ability_tech_energy_leech") player.energyLeechUntil = 0;
    if (local && skill === "ability_tech_precision_targeter") player.precisionUntil = 0;
    if (local && skill === "ability_tech_npc_bomb") techNpcBombFrom = 0;
    return;
  }
  if (ev.phase === "heal") {
    if (skill === "ability_tech_energy_leech" && !actor.dead && !actor.cloaked && !actor.cloakCpu) {
      leechBeams.push({ ax: Number(ev.x) || 0, ay: Number(ev.y) || 0, by: String(ev.by), t0: performance.now() });
    }
    return; // Un soin ne relance jamais l'animation ou la durée de l'aura.
  }
  const at = Number(ev.at) || 0;
  const serverNow = typeof netGameTimeMs === "function" ? netGameTimeMs() : Date.now();
  const startedAt = performance.now() - Math.max(0, serverNow - at);
  if (field && actor[field]?.at !== at) actor[field] = { at, startedAt, chain: ev.chain || [] };
  if (local) {
    if (skill === "ability_tech_energy_leech") {
      player.energyLeechUntil = Date.now() + Math.max(0, Number(ev.until) - serverNow);
      player.energyLeechNeedsResync = false;
    }
    if (skill === "ability_tech_precision_targeter") player.precisionUntil = Date.now() + Math.max(0, Number(ev.until) - serverNow);
    if (skill === "ability_tech_npc_bomb") techNpcBombFrom = actor.npcBombFx.startedAt;
  }
}

function syncTechVisualSnapshot(actor, local = false) {
  if (!actor) return;
  const target = local ? player : actor;
  if (actor.dead) {
    target.leechFx = target.npcBombFx = target.frostFx = target.chainImpFx = null;
    // Le Siphon et la Roquette de précision sont des techs persistantes : la
    // mort masque leur visuel mais ne détruit pas leurs timers. Elles
    // reprennent automatiquement au respawn.
    return;
  }
  for (const entry of actor.afx || []) {
    const skill = abilityIdForFxCode(entry[0]);
    const duration = { ability_tech_energy_leech: 1800000, ability_tech_npc_bomb: 60000,
      ability_tech_precision_targeter: 3600000 }[skill];
    if (!(duration > 0) || !(Number(entry[1]) > 0) || !(Number(entry[5]) > 0)) continue;
    applyTechVisualEvent({ skill, by: local ? netMyId() : actor.id, at: Number(entry[5]), until: Number(entry[5]) + duration });
  }
}

function tickNetplayVisuals(dt) {
  const remotes = getNetplayRemotes();
  for (const actor of remotes?.values() || []) syncTechVisualSnapshot(actor);
  syncTechVisualSnapshot(getNetSelf(), true);
  for (const id of netHoloClonesSeen.keys()) if (!remotes?.has(id)) netHoloClonesSeen.delete(id);
  for (const [id, remote] of remotes || []) {
    if (!(remote.holoClones?.length > 0) && !netHoloClonesSeen.has(id)) continue;
    const current = new Map((remote.holoClones || []).map(c => [c.id, { x: c.rx ?? c.x, y: c.ry ?? c.y }]));
    let exploded = false;
    for (const [cloneId, position] of netHoloClonesSeen.get(id) || []) {
      if (current.has(cloneId) || remote.dead || remote.cloaked || remote.cloakCpu) continue;
      spawnExplosion(position.x, position.y, 1);
      exploded = true;
    }
    if (exploded) playNetSpatialSound("mimesisLaugh", remote.rx ?? remote.x, remote.ry ?? remote.y, { cooldown: 0.1 });
    if (current.size) netHoloClonesSeen.set(id, current);
    else netHoloClonesSeen.delete(id);
  }
  // Refus serveur d'une aptitude mouvement : annule l'effet local pour
  // converger (fini le rubber-band permanent en cas de désaccord :
  // mauvais vaisseau, cooldown, cible, portée, bouclier).
  try {
    for (const denied of drainNetSkillDenied()) {
      try { cancelMovementAbilityByServer(String(denied?.skill || ""), denied.cooldown); } catch {}
    }
  } catch {}
  try {
    for (const ev of drainNetSkillInbox()) {
      if (!ev?.by) continue;
      applyTechVisualEvent(ev);
      if (ev.forced && ev.enabled === false && String(ev.by) === String(netMyId())) {
        cancelMovementAbilityByServer(ev.skill, Number(getAbilityInfo(ev.skill)?.cooldownSec) || 0);
        continue;
      }
      if (ev.phase === "clones") {
        if (String(ev.by) !== String(netMyId())) {
          const remote = getNetplayRemotes()?.get(String(ev.by));
          if (remote) remote.holoBoomStartedAt = performance.now();
          if (String(Target.get()?._netPlayer || "") === String(ev.by)) { Target.clear(); attackActive = false; }
        }
        continue;
      }
      if (ev.phase === "unlink") {
        if (String(ev.by) === String(netMyId())) breakLocalRepairLink(ev.skill, false);
        const caster = getNetplayRemotes()?.get(String(ev.by));
        const code = abilityFxCodeFor(ev.skill);
        if (caster) {
          for (const entry of caster.afx || []) if (Number(entry[0]) === code) entry[4] = "";
          if (Number(caster.fxFlash?.code) === code) caster.fxFlash.target = "";
        }
        continue;
      }
      if (ev.phase === "proc" && ev.skill === "ability_paladin_last-stand") {
        if (String(ev.by) === String(netMyId())) {
          player._netLastStandAt = ev.at;
          const fresh = Number(ev.healSeq) > Number(player._netAbilityHealSeq || 0);
          player._netAbilityHealSeq = Math.max(Number(player._netAbilityHealSeq) || 0, Number(ev.healSeq) || 0);
          if (fresh) player.hp = Math.min(player.hpMax, Number(ev.hp) || player.hpMax);
          addFloatText(player.x, player.y - 90, ev.amount, "rgba(80,255,125,0.98)",
            { text: `+${DMG_FMT.format(ev.amount)}`, size: 21, life: 1, weight: 900, impact: true });
          player.lastStandCd = droneAbilityCooldown(LASTSTAND_COOLDOWN);
          player.lastStandAnimT = LASTSTAND_FRAMES / LASTSTAND_FPS;
          player.lastStandFxOff = true;
          persistCdUntil("lastStand", droneAbilityCooldown(LASTSTAND_COOLDOWN));
        } else {
          const r = getNetplayRemotes()?.get(String(ev.by));
          if (r) r.lastStandT = LASTSTAND_FRAMES / LASTSTAND_FPS;
          showRemoteAbilityHeal(ev, r);
        }
        continue;
      }
      if (ev.phase === "heal" && ev.target) {
        if (String(ev.target) === String(netMyId())) applyNetHeal(ev);
        else showRemoteAbilityHeal({ ...ev, by: ev.target }, getNetplayRemotes()?.get(String(ev.target)));
        continue;
      }
      if (String(ev.by) === String(netMyId())) {
        if (ev.phase !== "heal" && ev.enabled !== false
          && repairTargetField(ev.skill)
          && String(player[repairTargetField(ev.skill)]?._netPlayer || "") !== String(ev.target || "")) {
          breakLocalRepairLink(ev.skill, false);
        }
        continue;
      }
      const remote = getNetplayRemotes()?.get(String(ev.by));
      if (remote && ev.phase === "fire" && (ev.skill === "ability_retiarus_chs" || ev.skill === "ability_retiarus-plus_chsp")) {
        remote.afx = (remote.afx || []).filter(entry => Number(entry[0]) !== abilityFxCodeFor(ev.skill));
        playNetSpatialSound("x4", Number(remote.rx ?? remote.x), Number(remote.ry ?? remote.y), { cooldown: 0.05 });
      }
      if (remote && ev.enabled !== false && (ev.skill === "ability_hyperion_ga" || ev.skill === "ability_hyperion_qa")) {
        const field = ev.skill === "ability_hyperion_ga" ? "gaFx" : "qaFx";
        if (remote[field]?.from !== Number(ev.at)) {
          remote[field] = {
            from: Number(ev.at), startedAt: performance.now(),
            duration: Math.max(0, (Number(ev.until) - Number(ev.at)) / 1000),
            x: Number(ev.x) || 0, y: Number(ev.y) || 0, target: String(ev.target || ""),
          };
        }
      }
      if (remote && ev.skill === "ability_tempest_voltage-link" && ev.chain?.length) {
        remote.voltLinkFx = { at: ev.at, startedAt: performance.now(), chain: ev.chain };
      }
      if (ev.phase === "heal") {
        showRemoteAbilityHeal(ev, remote);
        continue;
      }
      if (ev.enabled === false) {
        if (remote) {
          if (ev.skill === "ability_hyperion_ga") remote.gaFx = null;
          if (ev.skill === "ability_hyperion_qa") remote.qaFx = null;
          if (ev.skill === "ability_zephyr_tbr") { remote.tbrClones = []; remote.tbrUntil = 0; }
          const code = abilityFxCodeFor(ev.skill);
          remote.afx = (Array.isArray(remote.afx) ? remote.afx : []).filter(entry => Number(entry[0]) !== code);
          if (Number(remote.fxFlash?.code) === code) remote.fxFlash = null;
        }
        continue;
      }
      if (remote && (ev.skill === "iem" || ev.skill === "smb" || ev.skill === "ish")) {
        playNetSpatialSound(ev.skill === "iem" ? "pulseIEM" : ev.skill === "smb" ? "smbBomb" : "ishShield", Number(remote.rx ?? remote.x), Number(remote.ry ?? remote.y), {
          cooldown: 0.05,
          maxVoices: 4,
        });
      }
      if (ev.skill === "iem") {
        if (remote) spawnPulseFx(Number(remote.rx ?? remote.x), Number(remote.ry ?? remote.y), 1, String(ev.by));
        // IEM ennemie qui pète à côté : dévoile le CPU CL04K-XL.
        try {
          if (player.cpuCloak === true && !player.dead && remote) {
            const dIem = Math.hypot(Number(remote.rx ?? remote.x) - player.x, Number(remote.ry ?? remote.y) - player.y);
            if (dIem <= CPU_CLOAK_IEM_RADIUS) breakCpuCloak("iem");
          }
        } catch {}
        const locked = Target.get();
        if (locked?._netPlayer != null && String(locked._netPlayer) === String(ev.by)) {
          Target.clear();
          attackActive = false;
        }
      } else if (ev.skill === "smb") {
        // Mine SMB-01 distante : la vraie vidéo smartbomb + son d'explosion.
        // Posée au point de réception : ne suit pas le joueur distant.
        if (remote) spawnSmbFx(Number(remote.rx ?? remote.x), Number(remote.ry ?? remote.y), 1, false);
      } else if (typeof ev.skill === "string" && String(ev.skill).startsWith("ability_")) {
        // Phase 2 : flash d'activation d'aptitude distante (1,8 s).
        // Les auras persistantes arrivent via snapshot afx ; ce flash couvre
        // les casts instantanés (rafales déjà visibles via projectiles, QA,
        // lien Volt, tir chargé...) + le timing des poses de zone.
        // Camouflages : jamais diffusés par le serveur, ignorés par sécurité.
        try {
          const akey = String(ev.skill).toLowerCase();
          if (akey === "ability_admin-ultimate-cloaking"
            || akey === "ability_spearhead_ultimate-cloak"
            || akey === "ability_spearhead-plus_ultimate-cloak") {
            // invisible par design
          } else if (remote && abilityFxCodeFor(akey) > 0) {
            remote.fxFlash = {
              code: abilityFxCodeFor(akey),
              phase: ev.phase,
              until: performance.now() + (ev.phase === "fire" ? 1200 : Math.min(1800, Math.max(100, ev.until - ev.at))),
              startedAt: performance.now(),
              sec: Math.max(0, (Number(ev.until) - Number(ev.at)) / 1000),
              x: Number(ev.x) || 0,
              y: Number(ev.y) || 0,
              target: String(ev.target || ""),
            };
          }
        } catch {}
      }
    }
  } catch {}
  let evs = [];
  try { evs = drainNetShotEvents(); } catch {}
  if (!evs.length) return;
  for (const ev of evs.slice(0, 128)) {
    try {
      if (!ev || (ev.t !== "shot" && ev.t !== "rshot")) continue;
      if (ev.t === "rshot") spawnNetRocketVisual(ev);
      else spawnNetShotVisual(ev);
    } catch {}
  }
}

// ---------------------------------------------------------------------------
// Phase 2 — rendu distant des aptitudes (tout le monde voit les effets).
// Source : r.afx = [[code, secLeft, x, y, target]] (snapshot serveur validé)
// + r.fxFlash (flash d'activation instantanée, voir tickNetplayVisuals).
// Le ctx est déjà translaté sur le distant (0,0 = lanceur). Les zones
// posées (pods...) se dessinent en offset (fxX - rx, fxY - ry).
// Volontairement en primitifs Canvas (pas de nouveaux assets) : encadré,
// lisible, pas de risque de 404. Les camouflages n'arrivent jamais ici.
// ---------------------------------------------------------------------------
// Style par code ABILITY_FX : self = anneau sur le lanceur (couleur),
// zone = anneau au sol (rayon), target = anneau sur la cible (couleur),
// link = trait lanceur->cible (couleur), speed = streaks de vitesse.
