        b.launcherDepartureT = (b.launcherDepartureT || 0) + dt;
        const returnProgress = (b.launcherDepartureT - 0.08) / 0.28;
        const departure = blendVelocityDirection(
          b.launcherDepartureX,
          b.launcherDepartureY,
          guided.vx,
          guided.vy,
          returnProgress,
          chaseSpeed,
        );
