      if (bulletTarget.isJpcBot === true || b.target === "npc" || (b.visual === true && b.dmg === 0)) continue;
      const formationEvasion = bulletTarget === player
        ? Math.max(0, Number(getActiveDroneFormation(account.user).effects?.evasionPct || 0)) / 100
        : 0;
