            e._resetting = false;
            e._minionDespawning = false;
            e._sinceHit = 999;

            e._provoked = false;
            e._aggro = false;
            e._aggroT = 0;
            e._attackedPlayerRecently = false;
            if (e.aiZ) e.aiZ.state = "wander";
